// Function to add a new record to the linked list and update its status flag
void add_record(record_t* rec, bool active) {
    pthread_mutex_lock(&mutex);

    // Check if the linked list is empty
    if (!head) {
        head = rec;
        tail = rec;
        rec->next = NULL;
    } else {
        // Add the new record to the end of the linked list
        tail->next = rec;
        tail = rec;
        rec->next = NULL;
    }

    // Update the status flag of the new record
