    pthread_mutex_unlock(&mutex);
}

// Function to remove a record from the linked list and update its status flag
void remove_record(record_t* rec) {
    pthread_mutex_lock(&mutex);

    // Check if the linked list is empty
    if (!head) {
        head = NULL;
        tail = NULL;
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Find the record in the linked list and remove it
    record_t* current = head;
    while (current != rec) {
        current = current->next;
        if (!current) {
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Update the status flag of the removed record
    rec->active = false;

    // Remove the record from the linked list
    if (rec == head) {
        head = rec->next;
    } else if (rec == tail) {
        tail = current;
    }

    pthread_mutex_unlock(&mutex);
}

// Function to clean up inactive records and update their status flags
void cleanup(bool active) {
