            record_t* next = current->next;
            free(current);
            current = next;

            // Update the status flag of the removed record
            head->active = false;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&mutex);
}

// Function to serialize the linked list to a file and update its status flags
void serialize(FILE* fp) {
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list and write each record to the file
    record_t* current = head;
    while (current != NULL) {
        if (!fwrite(&(current->key), sizeof(int), 1, fp)) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        if (!fwrite(current->metadata, strlen(current->metadata), 1, fp)) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        if (!fwrite(&(current->active), sizeof(bool), 1, fp)) {
            pthread_mutex_unlock(&mutex);
            return;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
}

// Function to deserialize the linked list from a file and update its status flags
void deserialize(FILE* fp) {
    pthread_mutex_lock(&mutex);

    // Read each record from the file and add it to the linked list
    while (!feof(fp)) {
        int key = 0;
        if (fread(&key, sizeof(int), 1, fp) != 1) {
            pthread_mutex_unlock(&mutex);
            return;
