        size_t len = 0;
        getdelim(&metadata, &len, '\0', fp);
        bool active = false;
        if (fread(&active, sizeof(bool), 1, fp) != 1) {
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Add the new record to the linked list
        add_record(key, metadata, active);
    }

    pthread_mutex_unlock(&mutex);
}
