void process_file(char* input_filename, char* output_filename, char* rules_str, int threshold, int compressed) {
    // Open the input file
    FILE* input_file = fopen(input_filename, "rb");
    if (input_file == NULL) {
        printf("Error: unable to open input file '%s'\n", input_filename);
        return;
    }

    // Read the input file
    size_t file_size = 0;
    fseek(input_file, 0, SEEK_END);
    file_size = ftell(input_file);
    rewind(input_file);
    char* buffer = (char*)malloc(file_size * sizeof(char));
    size_t bytes_read = fread(buffer, 1, file_size, input_file);
    if (bytes_read < file_size) {
        printf("Error: unable to read entire input file\n");
        return;
    }

    // Decompress the input file if necessary
    char* decompressed_buffer = NULL;
    size_t decompressed_size = 0;
    if (compressed) {
        int err = uncompress(buffer, &decompressed_size, buffer, bytes_read);
        if (err != Z_OK || decompressed_size == 0) {
            printf("Error: unable to decompress input file\n");
            return;
        }
        decompressed_buffer = (char*)malloc(decompressed_size * sizeof(char));
        memcpy(decompressed_buffer, buffer, decompressed_size);
    } else {
        decompressed_buffer = buffer;
        decompressed_size = bytes_read;
    }

    // Parse the JSON rules string
    json_object* rules = json_tokener_parse(rules_str);
    if (rules == NULL) {
        printf("Error: unable to parse rules JSON\n");
        return;
