    if (output_file == NULL) {
        printf("Error: unable to create output file '%s'\n", output_filename);
        return;
    }

    // Process the input file in chunks
    char* current_pos = decompressed_buffer;
    size_t bytes_remaining = decompressed_size;
    size_t start_time = get_timestamp();
    while (bytes_remaining > 0) {
        // Determine the chunk size based on the performance threshold
        size_t chunk_size = bytes_remaining < threshold ? bytes_remaining : threshold;

        // Process the current chunk
