            // If an interruption is detected, clean up and exit
            printf("Interrupted!\n");
            fclose(input_file);
            free(decompressed_buffer);
            return;
        }
    }

    // Close the output file
    fclose(output_file);

    // Free memory
    json_object_put(rules);
    free(decompressed_buffer);
}

