#include <openssl/evp.h>
#include <openssl/aes.h>

int select_cipher(const unsigned char *iv, const unsigned char *key, int key_len, EVP_CIPHER **ctx) {
    // Select the appropriate AES algorithm and mode of operation based on the key length
    if (key_len == 16) {
        // Use AES-128 in CBC mode
        *ctx = EVP_aes_128_cbc();
    } else if (key_len == 24) {
        // Use AES-192 in CTR mode
        *ctx = EVP_aes_192_ctr();
    } else if (key_len == 32) {
        // Use AES-256 in GCM mode
        *ctx = EVP_aes_256_gcm();
    } else {
        return -1;
    }

    // Set the IV and key for the selected cipher
    if (EVP_CipherInit(*ctx, iv, key, 1) != 1) {
        return -2;
    }

    return 0;
}
```
