    public class Pipeline
    {
        private readonly IRelationalDatabase _database;
        private readonly ICachingService _cache;
        private readonly IEnumerable<IDataSource> _dataSources;

        public Pipeline(IRelationalDatabase database, ICachingService cache, IEnumerable<IDataSource> dataSources)
        {
            _database = database;
            _cache = cache;
            _dataSources = dataSources;
        }

        public async Task<IEnumerable<T>> ProcessDataAsync<T>(string query, params object[] parameters) where T : class
        {
            var cachedResult = await _cache.GetAsync(query, parameters);
            if (cachedResult != null)
            {
                return cachedResult;
            }

            try
            {
                var result = await _database.ExecuteQueryAsync<T>(query, parameters);
                await _cache.SetAsync(query, parameters, result);
                return result;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing data: {ex.Message}");
                throw;
            }
        }

