package com.example;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class StringProcessor {
    private static final int MAX_THREADS = 10; // adjust to your needs
    private static final long MEMORY_LIMIT_BYTES = 1_000_000_000L; // adjust to your needs

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

        while (true) {
            String input = readNextInput(); // method to read next input from the stream

            if (input == null) {
                break; // no more inputs to process, exit loop
            }

            executor.submit(new ProcessStringTask(input));
        }

        executor.shutdown();
    }
}

class ProcessStringTask implements Runnable {
    private String input;

    public ProcessStringTask(String input) {
        this.input = input;
    }

    @Override
    public void run() {
        try {
            processInput(input);
        } catch (Exception e) {
            // handle exception
        }
    }
}

private static class StringProcessorMetrics {
    private long totalBatchesProcessed;
    private long totalTimeTakenToProcessBatch;
    private long fastestOperationTimeInMs;
    private long slowestOperationTimeInMs;

    public void updateMetrics(long batchSize, long processingTime) {
        this.totalBatchesProcessed++;
        this.totalTimeTakenToProcessBatch += processingTime;
        if (processingTime < fastestOperationTimeInMs || fastestOperationTimeInMs == -1) {
            this.fastestOperationTimeInMs = processingTime;
        }
        if (processingTime > slowestOperationTimeInMs) {
            this.slowestOperationTimeInMs = processingTime;
        }
    }

    public long getTotalBatchesProcessed() {
        return totalBatchesProcessed;
    }

    public long getTotalTimeTakenToProcessBatch() {
        return totalTimeTakenToProcessBatch;
    }

    public long getFastestOperationTimeInMs() {
        return fastestOperationTimeInMs;
    }

    public long getSlowestOperationTimeInMs() {
        return slowestOperationTimeInMs;
    }
}
