['```php
function manageUserAccounts($request) {
    $sub_action = $request['sub_action'] ?? null;
    $id = $request['id'] ?? null;
    $name = $request['name'];
    $email = $request['email'];
    $password = $request['password'];

    // Validate input data
    if (strlen($name) > 50) {
        return ['message' => 'error', 'details' => 'Name must be less than 50 characters.'];
    }
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return ['message' => 'error', 'details' => 'Invalid email format.'];
    }
    if (strlen($password) < 8 || !preg_match('#\d+#', $password)) {
        return ['message' => 'error', 'details' => 'Password must be at least 8 characters long and include a digit.'];
    }

    // Check if user account exists
    if ($id !== null) {
        $user = getUserById($id);
        if (!$user) {
            return ['message' => 'error', 'details' => "User account with ID '$id' could not be found."];
        }
    } elseif ($sub_action !== 'delete') {
        // Check for unique email address
        $existingUser = getUserByEmail($email);
        if ($existingUser) {
            return ['message' => 'error', 'details' => "A user account with the same email address already exists."];
        }
    }

    // Handle sub_action requests
    switch ($sub_action) {
        case 'delete':
            if (!$id) {
                return ['message' => 'error', 'details' => "ID parameter is required for delete action"];
            }
            $user = getUserById($id);
            if (!$user) {
                return ['message' => 'error', 'details' => "User account with ID '$id' could not be found."];
            }
            $associatedData = getAssociatedDataByUserId($id);
            if ($associatedData) {
                return ['message' => 'error', 'details' => "Cannot delete user account with associated data. User has posts or comments."];
            }
            deleteUserById($id);
            return ['message' => 'success', 'details' => "User account with ID '$id' deleted successfully"];
        case null:
            // Create new user account
            $user = createUser($name, $email, $password);
            if ($user) {
                return ['message' => 'success', 'details' => "User account created successfully."];
            } else {
                return ['message' => 'error', 'details' => "Failed to create user account."];
            }
        default:
            // Update existing user account
            $user = getUserById($id);
            if (!$user) {
                return ['message' => 'error', 'details' => "User account with ID '$id' could not be found."];
            }
            $updateResult = updateUser($id, $name, $email, $password);
            if ($updateResult) {
                return ['message' => 'success', 'details' => "User account updated successfully."];
            } else {
                return ['message' => 'error', 'details' => "Failed to update user account."];
            }
    }
}

function getUserById($id) {
    // Connect to database and retrieve user by ID
    $dbConnection = connectToDatabase();
    $query = "SELECT * FROM users WHERE id = ?";
    $result = $dbConnection->query($query, [$id]);
    if ($result && $result->num_rows > 0) {
        return $result->fetch_assoc();
    } else {
        return null;
    }
}

function getUserByEmail($email) {
    // Connect to database and retrieve user by email address
    $dbConnection = connectToDatabase();
    $query = "SELECT * FROM users WHERE email = ?";
    $result = $dbConnection->query($query, [$email]);
    if ($result && $result->num_rows > 0) {
        return $result->fetch_assoc();
    } else {
        return null;
    }
}

function getAssociatedDataByUserId($userId) {
    // Connect to database and retrieve associated data for user by ID
    $dbConnection = connectToDatabase();
    $query = "SELECT * FROM associated_data WHERE user_id = ?";
    $result = $dbConnection->query($query, [$userId]);
    if ($result && $result->num_rows > 0) {
        return $result->fetch_all(MYSQLI_ASSOC);
    } else {
        return null;
    }
}

function createUser($name, $email, $password) {
    // Connect to database and create new user account
    $dbConnection = connectToDatabase();
    $query = "INSERT INTO users (name, email, password) VALUES (?, ?, ?)";
    $result = $dbConnection->query($query, [$name, $email, $password]);
    if ($result) {
        return true;
    } else {
        return false;
    }
}

function updateUser($id, $name, $email, $password) {
    // Connect to database and update user account with new data
    $dbConnection = connectToDatabase();
    $query = "UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?";
    $result = $dbConnection->query($query, [$name, $email, $password, $id]);
    if ($result) {
        return true;
    } else {
        return false;
    }
}

function deleteUserById($id) {
    // Connect to database and delete user account by ID
    $dbConnection = connectToDatabase();
    $query = "DELETE FROM users WHERE id = ?";
    $result = $dbConnection->query($query, [$id]);
    if ($result) {
        return true;
    } else {
        return false;
    }
}

function connectToDatabase() {
    // Connect to MySQL database
    $dbHost = "localhost";
    $dbUsername = "root";
    $dbPassword = "";
    $dbName = "mydatabase";
    $dbConnection = new mysqli($dbHost, $dbUsername, $dbPassword, $dbName);
    if ($dbConnection->connect_error) {
        return null;
    } else {
        return $dbConnection;
    }
}']

