import java.io.*;
import java.util.logging.Logger;

public class MoSTStateLoader {
    private static final Logger logger = Logger.getLogger(MoSTStateLoader.class.getName());

    public static MoSTState loadStateFromFile(String filePath) throws IOException {
        FileInputStream inputStream = null;
        ObjectInputStream objectInputStream = null;
        MoSTState state = null;

        try {
            // Open the input stream and verify that it exists
            inputStream = new FileInputStream(filePath);
            if (!inputStream.exists()) {
                logger.warning("Input stream does not exist: " + filePath);
                return null;
            }

            // Create an object input stream for the given file
            objectInputStream = new ObjectInputStream(inputStream);

            // Read the state object from the input stream
            state = (MoSTState) objectInputStream.readObject();
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Error loading state from file: " + filePath);
        } finally {
            // Close the input stream to release resources
            if (inputStream != null) {
                try {
                    inputStream.close();
                } catch (IOException e) {
                    logger.warning("Error closing input stream: " + filePath);
                }
            }

            // Close the object input stream to release resources
            if (objectInputStream != null) {
                try {
                    objectInputStream.close();
                } catch (IOException e) {
                    logger.warning("Error closing object input stream: " + filePath);
                }
            }
        }

        return state;
    }
}
