function processDialogFields(fields, resourceId, url) {
  const fieldNames = ['field1', 'field2', 'field3'];
  const message = {
    type: 'UPDATE_FIELD',
    payload: {
      id: resourceId,
      value: null,
    },
  };
  let updatedFields = fields;

  for (const field of fields) {
    if (fieldNames.includes(field.name)) {
      message.payload.value = getFieldValueFromParentWindow(url);
      const response = await postMessageToParentWindow(message);
      if (response.success) {
        updatedFields = updateFieldValue(updatedFields, field.name, response.value);
      }
    } else {
      continue;
    }
  }

  // Insert new string after first occurrence of specified string
  const insertIndex = fields.findIndex((f) => f.name === 'field4');
  if (insertIndex !== -1) {
    updatedFields.splice(insertIndex + 1, 0, { name: 'newField', value: 'newValue' });
  } else {
    updatedFields.push({ name: 'newField', value: 'newValue' });
  }

  return updatedFields;
}

function updateFieldValue(fields, fieldName, newValue) {
  const index = fields.findIndex((f) => f.name === fieldName);
  if (index !== -1) {
    fields[index].value = newValue;
  }
  return fields;
}

function getFieldValueFromParentWindow(url) {
  return window.parent.postMessage({ type: 'GET_FIELD_VALUE', payload: url }, url);
}

function postMessageToParentWindow(message) {
  return new Promise((resolve, reject) => {
    window.parent.postMessage(message, message.payload.id);
    window.addEventListener('message', (event) => {
      if (event.data.type === 'SUCCESS') {
        resolve(event.data.payload);
      } else {
        reject(new Error('Error updating field value'));
      }
    });
  });
}
