function traverseDOM(selectors, depthLimit) {
  // Create an array to store matched elements
  const matches = [];

  // Function to recursively traverse the DOM tree
  function traverse(node, depth = 0) {
    // Check if the current node matches any of the selectors
    for (const selector of selectors) {
      if (matchesSelector(selector, node)) {
        // Add the matched element to the array
        matches.push(node);
      }
    }

    // Recursively traverse the children nodes if the depth is less than the limit
    if (depth < depthLimit) {
      for (const child of node.children) {
        traverse(child, depth + 1);
      }
    }
  }

  // Start traversing the DOM tree from the root element
  traverse(document.documentElement, 0);

  // Return the array of matched elements
  return matches;
}

// Asynchronous callback for processing each matched element
