import java.util.*;
import java.time.Instant;

public class LogAnalyzer {
    public static void main(String[] args) throws Exception {
        // Sliding window of size 10 seconds
        int windowSize = 10;
        Instant startTime = Instant.now().minusSeconds(windowSize);
        Map<String, List<String>> requestPatterns = new HashMap<>();

        // Read log file line by line and process each request
        BufferedReader reader = new BufferedReader(new FileReader("log.txt"));
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse log entry and extract HTTP method, URI path, and query parameters
            String[] parts = line.split(" ");
            String httpMethod = parts[0];
            String uriPath = parts[1];
            String queryParams = parts[2];

            // Convert time to epoch milliseconds for comparison with window start time
            long requestTime = Instant.parse(parts[3]).toEpochMilli();

            // Ignore malformed log entries and varying character encodings
            if (httpMethod == null || uriPath == null || queryParams == null) {
                continue;
            }

            // Check if request is within window size
            if (requestTime >= startTime.toEpochMilli()) {
                // Add request to sliding window
                String key = httpMethod + " " + uriPath + "?" + queryParams;
                List<String> patterns = requestPatterns.get(key);
                if (patterns == null) {
                    patterns = new ArrayList<>();
                    requestPatterns.put(key, patterns);
                }
                patterns.add(line);
            }
        }

        // Print unique request patterns and their frequency
        for (Map.Entry<String, List<String>> entry : requestPatterns.entrySet()) {
            String key = entry.getKey();
            List<String> values = entry.getValue();
            System.out.println(key + " -> " + values);
        }

        // Measure processing time and print in milliseconds
        long endTime = Instant.now().toEpochMilli();
        System.out.println("Processing time: " + (endTime - startTime.toEpochMilli()) + "ms");
    }
}
