['package com.example;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class LoadBalancer {
    private static final int MAX_CONNECTIONS = 1000;
    private static final int BACKEND_SERVERS = 5;
    private static final String[] SERVER_ADDRESSES = new String[BACKEND_SERVERS];
    private static final AtomicInteger CONNECTION_COUNTER = new AtomicInteger();

    // Map of connection IDs to server addresses
    private static ConcurrentHashMap<String, InetSocketAddress> addressMap;
    // Executor service for managing the backend servers
    private static ExecutorService executorService;
    // Selector for handling incoming connections and requests
    private static Selector selector;

    public static void main(String[] args) throws IOException {
        init();
        while (true) {
            handleIncomingConnections();
            handleIncomingRequests();
        }
    }

    private static void init() throws IOException {
        addressMap = new ConcurrentHashMap<>();
        executorService = Executors.newFixedThreadPool(BACKEND_SERVERS);
        selector = Selector.open();
        ServerSocketChannel serverSocket = ServerSocketChannel.open().bind(new InetSocketAddress("localhost", 8080));
        serverSocket.configureBlocking(false);
        serverSocket.register(selector, SelectionKey.OP_ACCEPT);
    }

    private static void handleIncomingConnections() throws IOException {
        int numKeys = selector.selectNow();
        if (numKeys == 0) {
            return;
        }

        Set<SelectionKey> selectedKeys = selector.selectedKeys();
        Iterator<SelectionKey> keyIterator = selectedKeys.iterator();
        while (keyIterator.hasNext()) {
            SelectionKey key = keyIterator.next();
            if (key.isAcceptable()) {
                ServerSocketChannel serverSocket = (ServerSocketChannel) key.channel();
                SocketChannel clientSocket = serverSocket.accept();
                clientSocket.configureBlocking(false);
                String connectionId = Integer.toString(CONNECTION_COUNTER.incrementAndGet());
                addressMap.put(connectionId, new InetSocketAddress("localhost", 8081 + (connectionId.hashCode() % BACKEND_SERVERS)));
                clientSocket.register(selector, SelectionKey.OP_READ);
            }
            keyIterator.remove();
        }
    }

    private static void handleIncomingRequests() throws IOException {
        int numKeys = selector.selectNow();
        if (numKeys == 0) {
            return;
        }

        Set<SelectionKey> selectedKeys = selector.selectedKeys();
        Iterator<SelectionKey> keyIterator = selectedKeys.iterator();
        while (keyIterator.hasNext()) {
            SelectionKey key = keyIterator.next();
            if (key.isReadable()) {
                SocketChannel clientSocket = (SocketChannel) key.channel();
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                int bytesRead = clientSocket.read(buffer);
                if (bytesRead < 0) {
                    // Connection closed, remove the selection key
                    keyIterator.remove();
                    continue;
                }
                buffer.flip();
                byte[] data = new byte[buffer.remaining()];
                buffer.get(data);
                String request = new String(data);
                System.out.println("Received request: " + request);
                InetSocketAddress serverAddress = addressMap.get((String) key.attachment());
                SocketChannel backendSocket = SocketChannel.open();
                backendSocket.configureBlocking(false);
                backendSocket.connect(serverAddress);
                backendSocket.write(ByteBuffer.wrap(request.getBytes()));
                backendSocket.register(selector, SelectionKey.OP_READ, key.attachment());
            }
            if (key.isWritable()) {
                SocketChannel backendSocket = (SocketChannel) key.channel();
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                int bytesRead = backendSocket.read(buffer);
                if (bytesRead < 0) {
                    // Connection closed, remove the selection key
                    keyIterator.remove();
                    continue;
                }
                buffer.flip();
                byte[] data = new byte[buffer.remaining()];
                buffer.get(data);
                String response = new String(data);
                System.out.println("Sending response: " + response);
                clientSocket.write(ByteBuffer.wrap(response.getBytes()));
            }
        }
    }
}

