function combinedFunction($flag = 'php', $length = 50, $charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    if ($flag === 'php') {
        return generateRandomString($length, $charSet);
    } else {
        try {
            $fileContent = file_get_contents(readFileSync('path/to/file'));
            return $fileContent;
        } catch (Exception $e) {
            // Handle error
        }
    }
}

function generateRandomString($length, $charSet) {
    $randomChars = [];
    for ($i = 0; $i < $length; $i++) {
        $randomChars[] = $charSet[mt_rand(0, strlen($charSet) - 1)];
    }
    return implode('', $randomChars);
}

function readFileSync($path) {
    if (!file_exists($path)) {
        throw new Exception("File not found: {$path}");
    }
    return file_get_contents($path);
}
