typedef struct {
    int *states;
    size_t num_active;
} state_list_t;

state_list_t* manage_states(int *current_states, size_t num_active, fsa_t *fsa, int last_index, int max_size) {
    // Check if the new list exceeds the maximum allowed size
    if (num_active + 1 > max_size) {
        return NULL;
    }

    // Create a new state list with an additional state
    state_list_t *new_states = malloc(sizeof(state_list_t));
    if (!new_states) {
        return NULL;
    }
    new_states->num_active = num_active + 1;
    new_states->states = malloc(new_states->num_active * sizeof(int));
    if (!new_states->states) {
        free(new_states);
        return NULL;
    }

    // Copy the current states to the new list
    memcpy(new_states->states, current_states, num_active * sizeof(int));

    // Add the new state to the end of the list
    new_states->states[num_active] = fsa->starting_state;

    // Update the 'next' pointer of the last state in the list to point to the new state list
    if (last_index >= 0) {
        current_states[last_index]->next = new_states->states;
    } else {
        fsa->starting_state->next = new_states->states;
    }

    // Clean up the previous state list if it was reallocated
    if (current_states != NULL) {
        free(current_states);
    }

    return new_states;
}
