#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define EVENT_SIZE 1024
#define MAX_EVENTS 10000
#define MINUTE 60

struct event {
    char id[10];
    long timestamp;
};

struct event_metadata {
    int priority_score;
    struct event* event;
};

struct event_window {
    int count;
    struct event_metadata events[MAX_EVENTS];
};

// Function to filter events based on their timestamp, frequency of similar events in the last minute, and a dynamically calculated priority score.
struct event_window* process_event(struct event* new_event, struct event_window* current_window) {
    // Check if the event is a duplicate by comparing its ID with the IDs of existing events in the window
    for (int i = 0; i < current_window->count; i++) {
        if (!strcmp(new_event->id, current_window->events[i].event->id)) {
            return current_window; // Return the current window as is if a duplicate event is found
        }
    }

    // Calculate the priority score based on the timestamp and frequency of similar events in the last minute
    int priority = 0;
    long recent_timestamp = new_event->timestamp - MINUTE;
    for (int i = 0; i < current_window->count; i++) {
        if (current_window->events[i].event->timestamp >= recent_timestamp) {
            priority += current_window->events[i].priority_score;
        }
    }
    priority /= MINUTE; // Divide the score by the number of events in the last minute to get an average priority score

    // Update the event metadata and add it to the window
    struct event_metadata new_event_metadata = {priority, new_event};
    current_window->events[current_window->count++] = new_event_metadata;

    return current_window;
}

// Function to maintain a rolling window of processed events and update metrics.
void update_metrics(struct event_window* window) {
    // Calculate the highest priority score in the window
    int highest_priority = 0;
    for (int i = 0; i < window->count; i++) {
        if (highest_priority < window->events[i].priority_score) {
            highest_priority = window->events[i].priority_score;
        }
    }

    // Print the results to stdout
    printf("Highest priority event: %s (%d)\n", window->events[0].event->id, highest_priority);
    printf("Total events in the current window: %d\n", window->count);
}

int main() {
    struct event* new_event;
    struct event_window* current_window = (struct event_window*)malloc(sizeof(struct event_window));
    memset(current_window, 0, sizeof(struct event_window));

    while (1) {
        // Fetch the next event from an external event metadata service
        new_event = fetch_next_event();

        if (!new_event) {
            break;
        }

        current_window = process_event(new_event, current_window);

        update_metrics(current_window);
    }

    free(current_window);

    return 0;
}']

