#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>

// Define the size limit for the theme cache
#define THEME_CACHE_SIZE 1024

// Define the default directory for the theme cache
#define DEFAULT_THEME_DIR "/usr/share/themes"

// Define the maximum number of threads that can access the cache simultaneously
#define MAX_THREADS 8

// Define a structure to hold information about each cached theme
typedef struct {
    char *path; // The path of the cached theme file
    unsigned char *data; // The raw data of the cached theme
    size_t size; // The size of the cached theme in bytes
} ThemeCacheEntry;

// Define a cache to store all the cached themes
ThemeCacheEntry *cache = NULL;
size_t cacheSize = 0;

// Define a function to allocate memory for a new theme cache entry
void allocThemeCacheEntry(char *path, unsigned char *data, size_t size) {
    // Allocate the memory for the cache entry
    ThemeCacheEntry *entry = (ThemeCacheEntry *)malloc(sizeof(ThemeCacheEntry));
    assert(entry != NULL);

    // Initialize the fields of the cache entry
    entry->path = path;
    entry->data = data;
    entry->size = size;

    // Add the new cache entry to the end of the cache
    if (cache == NULL) {
        cache = entry;
    } else {
        ThemeCacheEntry *current = cache;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = entry;
    }

    // Increment the size of the cache
    ++cacheSize;
}

// Define a function to free all the resources allocated for the theme cache
void freeThemeCache() {
    // Free the memory for each cached theme
    ThemeCacheEntry *entry = cache;
    while (entry != NULL) {
        ThemeCacheEntry *next = entry->next;
        free(entry->data);
        free(entry);
        entry = next;
    }

    // Reset the cache size to 0
    cacheSize = 0;
}

// Define a function to load a theme from a file and add it to the cache
void loadThemeFromFile(char *path) {
    // Open the theme file for reading
    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Allocate memory for the raw data of the theme file
    unsigned char *data = (unsigned char *)malloc(sizeof(unsigned char) * 1024);
    assert(data != NULL);

    // Read the contents of the theme file into the raw data
    size_t size = fread(data, sizeof(unsigned char), 1024, file);
    if (size == 0) {
        perror("fread");
        free(data);
        fclose(file);
        return;
    }

    // Close the theme file
    fclose(file);

    // Allocate a new cache entry for the theme and add it to the cache
    allocThemeCacheEntry(path, data, size);
}

// Define a function to parse a PNG file from the cache root directory
void parsePngFile(char *filename) {
    // Open the PNG file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Read the contents of the PNG file into a buffer
    unsigned char *buffer = (unsigned char *)malloc(sizeof(unsigned char) * 1024);
    assert(buffer != NULL);

    size_t size = fread(buffer, sizeof(unsigned char), 1024, file);
    if (size == 0) {
        perror("fread");
