    public static IEnumerable<ImageMetadata> ProcessImages(string directory, int maxFiles = 1000)
    {
        // Check if the input directory exists and is a valid TIFF image format
        if (!Directory.Exists(directory) || !Tiff.Equals(Path.GetExtension(directory)))
        {
            throw new ArgumentException("Invalid directory or file extension.");
        }

        // Get all files in the specified directory that are TIFF images
        var imageFiles = Directory.EnumerateFiles(directory, "*.tiff", SearchOption.TopDirectoryOnly).ToList();
        if (imageFiles.Count == 0)
        {
            throw new ArgumentException("No TIFF images found in the specified directory.");
        }

        // Process up to the maximum number of files concurrently
        var processedImages = new List<ImageMetadata>(maxFiles);
        using (var md5 = MD5.Create())
        {
            Parallel.ForEach(imageFiles, (file) =>
            {
                try
                {
                    // Read the TIFF image and extract its metadata
                    var bitmap = new Bitmap(file);
                    var bitsPerSample = bitmap.BitsPerPixel / bitmap.NumberOfColor;
                    var samplesPerPixel = bitmap.NumberOfColor;
                    var extraSamples = bitmap.ExtraSamples?.Length ?? 0;
                    var hash = md5.ComputeHash(File.ReadAllBytes(file));

                    // Create a new ImageMetadata object and add it to the list of processed images
                    processedImages.Add(new ImageMetadata
                    {
                        FileName = Path.GetFileName(file),
                        BitsPerSample = bitsPerSample,
                        SamplesPerPixel = samplesPerPixel,
                        ExtraSamples = extraSamples,
                        Hash = BitConverter.ToString(hash)
                    });
                }
                catch (Exception ex)
                {
                    // Log any errors that occur while processing images
                    Console.WriteLine($"Error processing image: {file}");
                    Console.WriteLine(ex.Message);
                }
            });
        }

        return processedImages;
    }
}

public class ImageMetadata
{
