    // Check if the algorithm is already added
    for (int i = 0; i < ctx->num_algos; i++) {
        if (ctx->algos[i].type == type) {
            return -1;
        }
    }
    // Reallocate memory for the array of algorithm contexts if necessary
    if (ctx->num_algos >= ctx->algos.length()) {
        ctx->algos = realloc(ctx->algos, (ctx->num_algos + 1) * sizeof(algo_ctx_t));
    }
    // Add the algorithm to the array of algorithm contexts
    ctx->algos[ctx->num_algos].type = type;
    ctx->algos[ctx->num_algos].ctx = ctx;
    ctx->num_algos++;
    return 0;
}

// Define a function to remove an algorithm from the library's context
int lib_remove_algo(library_ctx_t* ctx, int type) {
    // Find the index of the algorithm in the array of algorithm contexts
    for (int i = 0; i < ctx->num_algos; i++) {
        if (ctx->algos[i].type == type) {
            break;
        }
    }
    // If the algorithm was found, remove it from the array of algorithm contexts
    if (i != ctx->num_algos) {
        memmove(&ctx->algos[i], &ctx->algos[i + 1], sizeof(algo_ctx_t));
        ctx->num_algos--;
