        ERR_print_errors_fp(stderr);
        return -1;
    }
    if (EVP_PKEY_sign(pctx, out + in_len, &out_len, out, in_len)) {
        ERR_print_errors_fp(stderr);
        return -1;
    }
    EVP_PKEY_CTX_free(pctx);
    return 0;
}

// Define a function to decrypt data using the library's context
int lib_decrypt(library_ctx_t* ctx, void* in, int in_len, void* out, int out_len) {
