        ERR_print_errors_fp(stderr);
        return -1;
    }
    if (EVP_PKEY_CTX_ctrl(pctx, -1, EVP_PKEY_OP_VERIFY, EVP_PKEY_CTRL_DIGESTINIT, 0, ctx->sha_alg) != 1) {
