### Encrypting a String Using AES and RSA with SHA-256

```java
import java.io.*;
import java.security.*;
import java.security.spec.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class AES_RSA_Encrypt {
    public static void main(String[] args) throws Exception {
        // Generate the keys
        KeyPairGenerator keyGen = KeyPairGenerator.getInstance("RSA");
        keyGen.initialize(2048);
        KeyPair keyPair = keyGen.generateKeyPair();
        PrivateKey privateKey = keyPair.getPrivate();
        PublicKey publicKey = keyPair.getPublic();

        // Create the AES cipher
        Cipher aesCipher = Cipher.getInstance("AES");
        SecretKeySpec secretKeySpec = new SecretKeySpec(privateKey.getEncoded(), "AES");
        aesCipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

        // Create the RSA cipher
        Cipher rsaCipher = Cipher.getInstance("RSA/ECB/OAEPWithSHA-256AndMGF1Padding");
        rsaCipher.init(Cipher.ENCRYPT_MODE, publicKey);

        // Encrypt the message
        String plaintext = "Hello World!";
        byte[] ciphertext = rsaCipher.doFinal(plaintext.getBytes("UTF-8"));
        ciphertext = aesCipher.doFinal(ciphertext);

        // Decrypt the message
        byte[] plaintext2 = aesCipher.doFinal(ciphertext);
        plaintext2 = rsaCipher.doFinal(plaintext2);
        String decrypted = new String(plaintext2, "UTF-8");

        System.out.println("Original: " + plaintext);
        System.out.println("Encrypted: " + ciphertext);
        System.out.println("Decrypted: " + decrypted);
    }
}
```

