        public async Task<bool> AddWebsiteAsync(string websiteName, int port, string binding)
        {
            try
            {
                // Verify read/write permissions for the directory path
                if (!Directory.Exists(_directoryPath))
                    throw new DirectoryNotFoundException($"The directory '{_directoryPath}' does not exist.");
                if (Directory.GetAccessControl(_directoryPath).AreAccessRulesProtected)
                    throw new UnauthorizedAccessException($"Insufficient permissions to access the directory '{_directoryPath}'.");

                // Ensure necessary configuration files are present and valid
                var configFiles = _configurationFiles.Select(f => Path.Combine(_directoryPath, f));
