                        throw new FileNotFoundException($"The configuration file '{file}' does not exist.");
                    var xml = XDocument.Load(file);
                    var portNode = xml.Root?.Element("system.webServer").Element("listenPrefixes");
                    if (portNode == null)
                        throw new XmlException($"The configuration file '{file}' does not contain a 'system.webServer' element.");
                    var ports = portNode.Elements().Select(e => e.Attribute("port"));
                    if (!ports.Any() || !ports.Contains(port))
                        throw new InvalidOperationException($"The configuration file '{file}' does not contain a valid port for the website.");
                }

                // Handle multiple website configurations with varying ports and bindings
                var existingSites = Directory.GetFiles(_directoryPath, "*.config");
                if (existingSites.Any())
                {
                    var bindingNode = _configurationFiles[1].SelectSingleNode("//system.webServer/binding[@port='" + port + "']");
                    if (bindingNode == null)
                        throw new InvalidOperationException($"The configuration file '{_configurationFiles[1]}' does not contain a valid binding for the website.");
                }

                // Implement flexible configuration management through site-config.json
                var configJson = _configurationFiles[1].ReadAllText();
                var jsonObj = JsonSerializer.Deserialize<JObject>(configJson);
                if (jsonObj["site"] != null)
                    jsonObj["site"]["port"] = port;
                else
                    jsonObj.Add("site", new JObject(new JProperty("port", port)));
                configJson = JsonSerializer.Serialize(jsonObj);

                // Maintain a detailed log of all operations, including timestamps, actions, and outcomes
                _loggingService.Log($"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] Website addition attempt for {websiteName} at port {port} with binding {binding}", LogLevel.Information);
                try
                {
                    // Optimize file I/O operations to handle large directories efficiently
                    var dirInfo = new DirectoryInfo(_directoryPath);
                    foreach (var file in configFiles)
                    {
                        using (var streamWriter = new StreamWriter(file))
                        {
                            await streamWriter.WriteAsync(configJson).ConfigureAwait(false);
                        }
                    }

                    // Integrate with an external API service for notifications upon successful additions or failures
                    _apiService.NotifyAdditionSuccess($"{websiteName} was successfully added at port {port} with binding {binding}");
                }
                catch (Exception ex)
                {
                    _loggingService.Log($"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] Website addition failed for {websiteName} at port {port} with binding {binding}", LogLevel.Error);
                    _apiService.NotifyAdditionFailure($"{websiteName} could not be added at port {port} with binding {binding}. Reason: {ex.Message}");
                }
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException($"Failed to add website '{websiteName}' at port {port} with binding {binding}. Reason: {ex.Message}", ex);
            }
        }

