import java.io.*;
import java.util.regex.*;

public class ShellCommandExecutor {
  private static final Pattern ALLOWED_OPERATIONS = Pattern.compile("^ls|pwd$");
  private static final String LOG_FILE_PREFIX = "shell-command-executor";

  public void execute(String command) throws IOException {
    // Validate and sanitize the command
    if (!ALLOWED_OPERATIONS.matcher(command).matches()) {
      throw new IllegalArgumentException("Command not allowed");
    }

    // Create temporary directory for storing logs
    File logDir = new File("/var/log/shell-commands");
    if (!logDir.exists() && !logDir.mkdirs()) {
      throw new IOException("Failed to create log directory");
    }

    // Execute the command and get the output and error streams
    Process process = Runtime.getRuntime().exec(command);
    InputStream inputStream = process.getInputStream();
    InputStream errorStream = process.getErrorStream();

    // Log the standard output and error streams to separate files
    BufferedWriter logOutputWriter = new BufferedWriter(new FileWriter(LOG_FILE_PREFIX + "-output.log"));
    BufferedWriter logErrorWriter = new BufferedWriter(new FileWriter(LOG_FILE_PREFIX + "-error.log"));
    try {
      int byte;
      while ((byte = inputStream.read()) != -1) {
        logOutputWriter.write(byte);
      }
      while ((byte = errorStream.read()) != -1) {
        logErrorWriter.write(byte);
      }
    } finally {
      inputStream.close();
      errorStream.close();
      logOutputWriter.close();
      logErrorWriter.close();
    }

    // Clean up temporary files created during the process
    File tempFile = new File("/tmp/shell-command-executor");
    if (tempFile.exists() && !tempFile.delete()) {
      throw new IOException("Failed to delete temporary file");
    }
  }
}
