#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/des.h>
#include <openssl/aes.h>
#include <openssl/evp.h>

struct CredentialInfo {
    char *password;
    struct ConnectionConfig *connection_config;
    void (*callback)(void *);
};

struct ConnectionConfig {
    char *title;
    int initialized;
};

int processAndDecryptCredential(struct CredentialInfo *credential, const char *base64_message, const char *key, const char *iv) {
    // Validate the credential structure
    if (credential == NULL || credential->password == NULL || credential->connection_config == NULL || credential->callback == NULL) {
        return -1;
    }

    // Validate the connection configuration
    if (credential->connection_config->title == NULL || !credential->connection_config->initialized) {
        return -2;
    }

    // Decrypt the message using Triple DES encryption with the provided key and IV
    char *decrypted_message = NULL;
    int ret = -3;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        goto exit;
    }

    EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, NULL, &decrypted_message, base64_message, strlen(base64_message));
    if (ret != 1) {
        goto exit;
    }

    // Decode the decrypted message into a format suitable for processing by the connected system
    char *processed_message = NULL;
    switch (credential->connection_config->title[0]) {
        case 'A':
            // For connections with title "A", decode the decrypted message as a JSON object
            processed_message = json_decode(decrypted_message);
            break;
        case 'B':
            // For connections with title "B", decode the decrypted message as a CSV file
            processed_message = csv_decode(decrypted_message);
            break;
    }

exit:
    EVP_CIPHER_CTX_free(ctx);
    free(decrypted_message);
    return ret;
}
