#include <jsonwebtoken/jwt.h>
#include <openssl/pkey.h>
#include <openssl/rsa.h>
#include <unistd.h>
#include <iostream>
#include <fstream>
#include <map>

using namespace std;

class JWTValidator {
public:
    JWTValidator(const string& publicKeyFile, const string& privateKeyFile) : publicKeyFile_(publicKeyFile), privateKeyFile_(privateKeyFile) {}

    ~JWTValidator() {
        if (pkeyCtx_) {
            EVP_PKEY_CTX_free(pkeyCtx_);
            pkeyCtx_ = NULL;
        }
    }

    bool validateJWT(const string& jwt, const map<string, string>& requiredClaims) {
        // Load public key from file
        auto pubKey = loadPublicKey(publicKeyFile_);
        if (!pubKey) {
            cerr << "Failed to load public key" << endl;
            return false;
        }

        // Parse JWT and extract claims
        auto jwtClaims = parseJWTClaims(jwt, requiredClaims);
        if (!jwtClaims) {
            cerr << "Failed to parse JWT claims" << endl;
            return false;
        }

        // Verify JWT signature using public key
        auto verifyResult = verifySignature(jwt, *pubKey);
        if (!verifyResult) {
            cerr << "JWT signature verification failed" << endl;
            return false;
        }

        // Validate required claims
        for (const auto& claim : requiredClaims) {
            auto it = jwtClaims->find(claim.first);
            if (it == jwtClaims->end()) {
                cerr << "Missing required claim: " << claim.first << endl;
                return false;
            }
            if (it->second != claim.second) {
                cerr << "Invalid value for claim: " << claim.first << ": expected=" << claim.second << ", actual=" << it->second << endl;
                return false;
            }
        }

        // Success!
        cout << "JWT validation successful" << endl;
        return true;
    }

private:
    string publicKeyFile_;
    string privateKeyFile_;
    EVP_PKEY_CTX* pkeyCtx_ = NULL;

    shared_ptr<EVP_PKEY> loadPublicKey(const string& filename) {
        // Load public key from file
        ifstream ifs(filename, ios::binary);
        if (!ifs.is_open()) {
            cerr << "Failed to open public key file: " << filename << endl;
            return nullptr;
        }

        auto pkey = make_shared<EVP_PKEY>();
        PEM_read_PUBKEY(ifs, &pkey.get(), NULL, NULL);

        // Cache public key for later use
        auto cacheIt = publicKeyCache_.find(filename);
        if (cacheIt == publicKeyCache_.end()) {
            publicKeyCache_.insert({filename, pkey});
        } else {
            cacheIt->second = pkey;
        }

        return pkey;
    }

    shared_ptr<EVP_PKEY> loadPrivateKey(const string& filename) {
        // Load private key from file
        ifstream ifs(filename, ios::binary);
        if (!ifs.is_open()) {
            cerr << "Failed to open private key file: " << filename << endl;
            return nullptr;
        }

        auto pkey = make_shared<EVP_PKEY>();
        PEM_read_PrivateKey(ifs, &pkey.get(), NULL, NULL);

        // Cache private key for later use
        auto cacheIt = privateKeyCache_.find(filename);
        if (cacheIt == privateKeyCache_.end()) {
            privateKeyCache_.insert({filename, pkey});
        } else {
            cacheIt->second = pkey;
        }

        return pkey;
    }

    shared_ptr<map<string, string>> parseJWTClaims(const string& jwt, const map<string, string>& requiredClaims) {
        // Parse JWT claims
        auto claims = make_shared<map<string, string>>();
        try {
            *claims = jsonwebtoken::decode(jwt);
        } catch (const jsonwebtoken::TokenException& e) {
            cerr << "Failed to parse JWT claims: " << e.what() << endl;
            return nullptr;
        }

        // Validate required claims
        for (const auto& claim : requiredClaims) {
            auto it = claims->find(claim.first);
            if (it == claims->end()) {
                cerr << "Missing required claim: " << claim.first << endl;
                return nullptr;
            }
            if (it->second != claim.second) {
                cerr << "Invalid value for claim: " << claim.first << ": expected=" << claim.second << ", actual=" << it->second << endl;
                return nullptr;
            }
        }

        return claims;
    }

    shared_ptr<bool> verifySignature(const string& jwt, const EVP_PKEY& pubKey) {
        // Set up signature verification context
        if (!pkeyCtx_) {
            pkeyCtx_ = EVP_PKEY_CTX_new(pubKey.get(), NULL);
            if (!pkeyCtx_) {
                cerr << "Failed to create signature verification context" << endl;
                return nullptr;
            }
        }

        // Verify JWT signature using public key
        try {
            return jsonwebtoken::verify(jwt, pubKey.get());
        } catch (const jsonwebtoken::TokenException& e) {
            cerr << "JWT signature verification failed: " << e.what() << endl;
            return nullptr;
        }
    }

    map<string, shared_ptr<EVP_PKEY>> publicKeyCache_;
    map<string, shared_ptr<EVP_PKEY>> privateKeyCache_;
};

int main(int argc, char* argv[]) {
    if (argc < 4) {
        cerr << "Usage: ./jwt_validator <public key file> <private key file> <JWT string>" << endl;
        return 1;
    }

    auto publicKeyFile = string(argv[1]);
    auto privateKeyFile = string(argv[2]);
    auto jwt = string(argv[3]);

    // Create JWT validator instance with given public and private key files
    JWTValidator validator(publicKeyFile, privateKeyFile);

    // Validate JWT using the validator instance
    if (!validator.validateJWT(jwt)) {
        cerr << "JWT validation failed" << endl;
        return 1;
    }

    cout << "JWT validation succeeded" << endl;
    return 0;
}']

