public static class FileHasher
{
    public static string HashFile(string filePath, string hashAlgorithm)
    {
        // Open the file and read it into a byte array
        using (var stream = new FileStream(filePath, FileMode.Open))
        {
            var buffer = new byte[stream.Length];
            stream.Read(buffer, 0, buffer.Length);

            // Create a hasher based on the selected algorithm
            HashAlgorithm hasher;
            if (hashAlgorithm == "MD5")
            {
                hasher = MD5.Create();
            }
            else if (hashAlgorithm == "SHA256")
            {
                hasher = SHA256.Create();
            }
            else
            {
                throw new ArgumentException("Invalid hash algorithm");
            }

            // Compute the hash of the file contents
            var hash = hasher.ComputeHash(buffer);

            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
    }
}
```
