    public class AesCbcDecryptionService
    {
        private readonly IConfigurationService _configurationService;
        private readonly ICachingService _cachingService;

        public AesCbcDecryptionService(IConfigurationService configurationService, ICachingService cachingService)
        {
            _configurationService = configurationService;
            _cachingService = cachingService;
        }

        public async Task<byte[]> DecryptAsync(byte[] ciphertext, CancellationToken cancellationToken = default)
        {
            var key = await GetEncryptionKeyAsync();
            var iv = await GetInitializationVectorAsync();
            var paddingScheme = await GetPaddingSchemeAsync();

            using var aesCbcDecryptor = Aes.Create();
            aesCbcDecryptor.Key = key;
            aesCbcDecryptor.IV = iv;
            aesCbcDecryptor.Mode = CipherMode.CBC;
            aesCbcDecryptor.Padding = paddingScheme;

            using var memoryStream = new MemoryStream();
            await aesCbcDecryptor.DecryptAsync(ciphertext, memoryStream, cancellationToken);
            return memoryStream.ToArray();
        }

        private async Task<byte[]> GetEncryptionKeyAsync()
        {
            try
            {
                var encryptionKey = await _configurationService.GetEncryptionKeyAsync();
                if (encryptionKey == null)
                {
                    throw new KeyNotFoundException("Encryption key not found in configuration service.");
                }
                return encryptionKey;
            }
            catch (ServiceUnavailableException ex)
            {
                _cachingService.Add(nameof(GetEncryptionKeyAsync), ex);
                throw;
            }
        }

        private async Task<byte[]> GetInitializationVectorAsync()
        {
            try
            {
                var initializationVector = await _configurationService.GetInitializationVectorAsync();
                if (initializationVector == null)
                {
                    throw new KeyNotFoundException("Initialization vector not found in configuration service.");
                }
                return initializationVector;
            }
            catch (ServiceUnavailableException ex)
            {
                _cachingService.Add(nameof(GetInitializationVectorAsync), ex);
                throw;
            }
        }

        private async Task<PaddingMode> GetPaddingSchemeAsync()
        {
            try
            {
                var paddingScheme = await _configurationService.GetPaddingSchemeAsync();
                if (paddingScheme == null)
                {
                    throw new KeyNotFoundException("Padding scheme not found in configuration service.");
                }
                return Enum.Parse<PaddingMode>(paddingScheme);
            }
            catch (ServiceUnavailableException ex)
            {
                _cachingService.Add(nameof(GetPaddingSchemeAsync), ex);
                throw;
            }
        }
    }
}
