['Here is a C function named `initializeAndUploadFile` that integrates file upload functionality with network interface management in a large-scale distributed infrastructure scenario:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <bluebird/async.h>

typedef struct {
    int id;
    int throughput;
    int latency;
    struct NetworkSession* next;
} NetworkInterfaceStatus;

void initializeAndUploadFile(const char* url) {
    // Initialize the asynchronous library (e.g., Bluebird)
    bluebird_init();

    // Create a dynamically allocated array of NetworkInterfaceStatus structures
    NetworkInterfaceStatus** interfaceStatuses = malloc(sizeof(NetworkInterfaceStatus*) * 10);

    // Iterate over each network interface and populate the status structure
    for (int i = 0; i < 10; i++) {
        interfaceStatuses[i] = malloc(sizeof(NetworkInterfaceStatus));
        interfaceStatuses[i]->id = i;
        interfaceStatuses[i]->throughput = get_throughput();
        interfaceStatuses[i]->latency = get_latency();
        interfaceStatuses[i]->next = NULL;
    }

    // Initialize the network interface management system
    initialize_network_interface_management(interfaceStatuses);

    // Upload the file to a remote server using the asynchronous library
    bluebird_upload_file(url, "file.txt", 0, NULL);

    // Clean up resources
    for (int i = 0; i < 10; i++) {
        free(interfaceStatuses[i]);
    }
    free(interfaceStatuses);
    bluebird_destroy();
}
```
