// Define a structure to hold RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a helper function to print the largest integer in the list
void printLargestInteger(NFAPI_CRC_INDICATION_PDU_T *array, int size) {
    int largest = array[0].RNTI;
    for (int i = 1; i < size; i++) {
        if (array[i].RNTI > largest) {
            largest = array[i].RNTI;
        }
    }
    printf("Largest integer: %d\n", largest);
}

// Define the main function to dynamically read a list of integers from standard input, handle errors and clean up memory
int main() {
    // Dynamically allocate an array for the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG structures
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    // Read a list of integers from standard input, one at a time
    int i = 0;
    while (scanf("%d", &array[i].RNTI) != EOF) {
        array[i].CRCFLAG = rand() % 2; // Set CRCFLAG randomly
        i++;
    }

    // Print the largest integer in the list using the helper function
    printLargestInteger(array, i);

    // Free the dynamically allocated memory
    free(array);

    return 0;
}
