#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/aes.h>
#include <openssl/des.h>
#include <openssl/chacha.h>
#include <openssl/modes.h>
#include <openssl/rand.h>

// Define the supported ciphers and their corresponding modes
typedef enum {
    DES_ECB,
    DES_EDE,
    DES_EDE3,
    AES,
    ChaCha20
} CipherType;

typedef enum {
    ECB,
    CBC,
    CFB,
    OFB
} CipherMode;

// Define the supported key sizes for each cipher
static const uint8_t DES_KEYSIZE[3] = { 64, 128, 192 };
static const uint8_t AES_KEYSIZE[4] = { 128, 192, 256, 384 };
static const uint8_t ChaCha20_KEYSIZE[2] = { 256, 512 };

// Define the supported block sizes for each cipher
static const uint8_t DES_BLOCKSIZE = 64;
static const uint8_t AES_BLOCKSIZE = 128;
static const uint8_t ChaCha20_BLOCKSIZE = 64;

// Define the supported cipher parameters for each mode
typedef struct {
    CipherType type;
    CipherMode mode;
    uint8_t keySize;
    uint8_t blockSize;
} CipherParams;

static const CipherParams CIPHER_PARAMS[5] = {
    { DES_ECB,  ECB,  64,  64 },
    { DES_EDE,  ECB,  128, 64 },
    { DES_EDE3, ECB,  192, 64 },
    { AES,     CBC,  128, 128 },
    { ChaCha20, ChaCha20, 256, 64 }
};

// Define the error codes for the library
typedef enum {
    SUCCESS = 0,
    ERR_UNKNOWN,
    ERR_NOT_SUPPORTED,
    ERR_INVALID_MODE,
    ERR_INVALID_KEYSIZE,
    ERR_INVALID_BLOCKSIZE,
    ERR_MEMORY_ALLOCATION,
    ERR_CIPHER_INITIALIZATION,
    ERR_DATA_ENCRYPTION,
    ERR_DATA_DECRYPTION,
    ERR_CIPHER_SHUTDOWN,
} ErrorCode;

// Define the error strings for each error code
static const char* ERROR_STRINGS[10] = {
    "SUCCESS",
    "UNKNOWN ERROR",
    "NOT SUPPORTED",
    "INVALID MODE",
    "INVALID KEYSIZE",
    "INVALID BLOCKSIZE",
    "MEMORY ALLOCATION ERROR",
    "CIPHER INITIALIZATION ERROR",
    "DATA ENCRYPTION ERROR",
    "DATA DECRYPTION ERROR",
    "CIPHER SHUTDOWN ERROR"
};

// Define the memory management functions for allocating and deallocating memory
static void* (*malloc_func)(size_t size) = malloc;
static void (*free_func)(void* ptr) = free;

// Define the logging function to be used by the library
static void (*log_func)(const char* message, ...) = printf;

// Define the error handling and logging functions for the library
static ErrorCode handle_error(ErrorCode err) {
    log_func("Encryption Library: %s\n", ERROR_STRINGS[err]);
    return err;
}

// Define the function to dynamically determine the cipher parameters based on the environment variables
static CipherParams determine_cipher_params() {
    // Determine the supported cipher type and mode based on the environment variables
    CipherType type = DES_ECB;
    CipherMode mode = ECB;

    if (getenv("CIPHER_TYPE") != NULL) {
        type = (CipherType)atoi(getenv("CIPHER_TYPE"));
    }

    if (getenv("CIPHER_MODE") != NULL) {
        mode = (CipherMode)atoi(getenv("CIPHER_MODE"));
    }

    // Determine the key size and block size based on the cipher type and mode
    uint8_t keySize = 0;
    uint8_t blockSize = 0;

    switch (type) {
        case DES_ECB:
        case DES_EDE:
        case DES_EDE3:
            keySize = DES_KEYSIZE[atoi(getenv("CIPHER_KEYSIZE"))];
            blockSize = DES_BLOCKSIZE;
            break;

        case AES:
            keySize = AES_KEYSIZE[atoi(getenv("CIPHER_KEYSIZE"))];
            blockSize = AES_BLOCKSIZE;
            break;

        case ChaCha20:
            keySize = ChaCha20_KEYSIZE[atoi(getenv("CIPHER_KEYSIZE"))];
            blockSize = ChaCha20_BLOCKSIZE;
            break;
    }

    return (CipherParams){ type, mode, keySize, blockSize };
}

// Define the function to initialize the cipher based on the determined cipher parameters
static ErrorCode init_cipher(EVP_CIPHER_CTX* ctx, CipherParams params) {
    // Initialize the EVP context and set the cipher type and mode
    if (!EVP_CipherInit(ctx, NULL, NULL, 0)) {
        return handle_error(ERR_CIPHER_INITIALIZATION);
    }

    // Set the key size and block size based on the determined cipher parameters
    EVP_CIPHER_CTX_set_key_length(ctx, params.keySize / 8);
    EVP_CIPHER_CTX_set_padding(ctx, 0);

    // Set the encryption or decryption mode based on the determined cipher parameters
    if (params.mode == ECB || params.mode == OFB) {
        if (!EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL)) {
            return handle_error(ERR_CIPHER_INITIALIZATION);
        }
    } else if (params.mode == CBC || params.mode == CFB) {
        if (!EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, NULL)) {
            return handle_error(ERR_CIPHER_INITIALIZATION);
        }
    } else {
        return handle_error(ERR_INVALID_MODE);
    }

    // Set the key based on the determined cipher parameters
    if (!EVP_CipherInit(ctx, NULL, getenv("CIPHER_KEY"), 0)) {
        return handle_error(ERR_CIPHER_INITIALIZATION);
    }

    return SUCCESS;
}

// Define the function to encrypt or decrypt data based on the determined cipher parameters
static ErrorCode encrypt_decrypt(EVP_CIPHER_CTX* ctx, uint8_t* inData, size_t inLen, uint8_t* outData, size_t outLen) {
    // Determine the encryption or decryption mode based on the determined cipher parameters
    int (*cipher)(EVP_CIPHER_CTX*, unsigned char**, size_t*, const unsigned char*, size_t) = NULL;

