struct StateList* createStateList(const int* currentStates, size_t numStates, const struct FSA* fsa, int lastState) {
    struct StateList* newList = malloc(sizeof(struct StateList));
    if (!newList) {
        return NULL;
    }

    // Allocate memory for the state list
    newList->states = malloc(numStates * sizeof(int));
    if (!newList->states) {
        free(newList);
        return NULL;
    }

    // Copy the current states to the new list
    memcpy(newList->states, currentStates, numStates * sizeof(int));

    // Update the 'next' pointer of the last state in the input list
    newList->count = numStates;
    fsa->stateList->next = newList;

    return newList;
}
