public class Event {
    public DateTimeOffset Timestamp { get; set; }
    public string ServiceName { get; set; }
    public string EventType { get; set; }
    public int EventId { get; set; }
    public string Data { get; set; }
}

public class CustomEventDeserializer : JsonConverter<Event> {
    private readonly IDictionary<string, ServiceMetadata> _serviceMetadataMap;

    public CustomEventDeserializer(IDictionary<string, ServiceMetadata> serviceMetadataMap) {
        _serviceMetadataMap = serviceMetadataMap ?? throw new ArgumentNullException(nameof(serviceMetadataMap));
    }

    public override Event ReadJson(JsonReader reader, Type objectType, Event existingValue, bool hasExistingValue, JsonSerializer serializer) {
        var jsonObject = JObject.Load(reader);
        var eventId = Convert.ToInt32(jsonObject["event_id"]);
        var serviceName = jsonObject["service_name"];
        var eventType = jsonObject["event_type"];
        var data = jsonObject["data"];

        // Handle deserialization errors and logging detailed error information for troubleshooting.
        try {
            return new Event {
                Timestamp = DateTimeOffset.Parse(jsonObject["timestamp"]),
                ServiceName = serviceName,
                EventType = eventType,
                EventId = eventId,
                Data = data
            };
        } catch (Exception e) {
            Console.WriteLine($"Failed to deserialize JSON object: {jsonObject}");
            Console.WriteLine(e);
            return null;
        }
    }

    public override void WriteJson(JsonWriter writer, Event value, JsonSerializer serializer) {
        throw new NotImplementedException();
    }
}

public class ServiceMetadata {
    public string Name { get; set; }
    public string Description { get; set; }
    public string Type { get; set; }
}

public class EventProcessor {
    private readonly IDictionary<string, ServiceMetadata> _serviceMetadataMap;
    private readonly List<Event> _eventList = new List<Event>();

    public EventProcessor(IDictionary<string, ServiceMetadata> serviceMetadataMap) {
        _serviceMetadataMap = serviceMetadataMap ?? throw new ArgumentNullException(nameof(serviceMetadataMap));
    }

    public void ProcessLogFile(string logFilePath) {
        using var reader = new StreamReader(logFilePath);
        string line;
        while ((line = reader.ReadLine()) != null) {
            if (string.IsNullOrWhiteSpace(line)) continue;
            try {
                // Deserialize JSON object into Event object and add to list.
                var eventJsonObject = JObject.Parse(line);
                _eventList.Add(new CustomEventDeserializer(_serviceMetadataMap).ReadJson(eventJsonObject));
            } catch (Exception e) {
                Console.WriteLine($"Failed to parse JSON object from line: {line}");
                Console.WriteLine(e);
            }
        }
    }

    public List<Event> GetEvents() {
        return _eventList;
    }
}
```
