#include <cmath>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>

// Define the Union-Find data structure for disjoint sets
class UnionFind {
private:
    std::vector<int> parent; // parent[i] = parent of item i
    std::vector<int> rank;   // rank[i] = rank of item i

public:
    UnionFind(int n) : parent(n), rank(n, 0) {}

    void make_set(int i) {
        parent[i] = i;
    }

    int find_set(int i) {
        if (parent[i] != i) {
            parent[i] = find_set(parent[i]);
        }
        return parent[i];
    }

    void union_sets(int i, int j) {
        int iroot = find_set(i);
        int jroot = find_set(j);
        if (iroot == jroot) {
            return;
        }
        if (rank[iroot] < rank[jroot]) {
            parent[iroot] = jroot;
        } else {
            parent[jroot] = iroot;
            if (rank[iroot] == rank[jroot]) {
                rank[jroot]++;
            }
        }
    }
};

// Define the caching mechanism for repeated computations
class Cache {
private:
    std::unordered_map<std::string, double> cache; // cache[key] = average value of key
    std::mutex mutex;                             // mutex to protect concurrent access
    int max_size;                                 // maximum size of the cache

public:
    Cache(int max_size) : max_size(max_size) {}

    double get(std::string key) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cache.find(key) != cache.end()) {
            return cache[key];
        } else {
            return -1; // key not found in the cache
        }
    }

    void set(std::string key, double value) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cache.size() == max_size) {
            cache.erase(cache.begin()); // evict the least recently used item
        }
        cache[key] = value;
    }
};

int main() {
    std::vector<std::string> files; // list of text files to process
    std::mutex file_mutex;          // mutex to protect concurrent access to the files vector
    std::condition_variable cv;     // condition variable for signaling when a thread finishes processing a file
    int num_threads = 4;           // number of threads to use for concurrent file processing

    // initialize the Union-Find data structure and caching mechanism
    UnionFind uf(1000);            // create a Union-Find data structure with 1000 sets
    Cache cache(10000);            // create a caching mechanism with maximum size of 10,000

    // add text files to the list of files to process
    files.push_back("file1.txt");
    files.push_back("file2.txt");
    files.push_back("file3.txt");

    // create a thread pool for concurrent file processing
    std::vector<std::thread> threads;
    for (int i = 0; i < num_threads; ++i) {
        threads.emplace_back([&]() {
            while (true) {
                std::string file;
                {
                    std::lock_guard<std::mutex> lock(file_mutex);
                    if (!files.empty()) {
                        // get the next file to process from the list of files
                        file = files[0];
                        files.erase(files.begin());
                    } else {
                        break;
                    }
                }
                process_file(file, uf, cache); // process the file concurrently
                cv.notify_all();              // signal that a thread finished processing a file
            }
        });
    }

    // wait for all threads to finish processing files
    while (threads.size() > 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        cv.notify_all();
        std::unique_lock<std::mutex> lock(file_mutex);
        cv.wait(lock, [&]() { return files.empty(); });
    }

    return 0;
}

void process_file(const std::string& file, UnionFind& uf, Cache& cache) {
    // open the file and read each line
    std::ifstream in(file);
    if (!in.is_open()) {
        std::cout << "Error opening file: " << file << "\n";
        return;
    }
    std::string line;
    while (std::getline(in, line)) {
        // transform the line into a comma-separated format
        std::istringstream iss(line);
        std::vector<std::string> tokens;
        std::string token;
        while (std::getline(iss, token, ',')) {
            if (!token.empty()) {
                tokens.push_back(token);
            }
        }
        // calculate the average of the last two numeric values
        double avg = -1;
        if (tokens.size() >= 2) {
            try {
                int n1 = std::stoi(tokens[tokens.size() - 2]);
                int n2 = std::stoi(tokens[tokens.size() - 1]);
                avg = (n1 + n2) / 2;
            } catch (std::invalid_argument& e) {
                // ignore invalid arguments and use the default value of -1
            }
        }

        // create a disjoint set for each line
        uf.make_set(tokens[0]);

        // cache the average value if it is not already cached
        std::string key = file + ":" + tokens[0];
        double cached_avg = cache.get(key);
        if (cached_avg == -1) {
            cache.set(key, avg);
        } else {
            avg = cached_avg;
        }

        // print the transformed line with the average value
        std::cout << tokens[0] << "," << avg << "\n";
    }
}
