#include <sys/wait.h>
#include <sys/types.h>
#include <sys/resource.h>
#include <errno.h>
#include <signal.h>
#include <pthread.h>
#include <json-c/json.h>

#define MAX_PROCESSES 100
#define MAX_LOAD 2.0

typedef struct {
    int id;
    char* command;
    double priority;
} Process;

typedef enum {
    SUCCESS,
    FAILURE,
} Status;

Status executeCommand(Process *process) {
    // Execute the command and get its exit status
    int status = system(process->command);
    if (status == -1) {
        return FAILURE;
    } else if (WIFEXITED(status)) {
        // Command exited normally, check the exit status
        if (WEXITSTATUS(status) != 0) {
            return FAILURE;
        }
    } else {
        // Command terminated abnormally, check the signal number
        int signum = WTERMSIG(status);
        if (signum == SIGKILL || signum == SIGSTOP) {
            return FAILURE;
        }
    }

    return SUCCESS;
}

Status manageProcesses(Process *processes, int num_processes, double load) {
    // Loop through the processes and execute commands based on their priorities
    for (int i = 0; i < num_processes; i++) {
        Process *process = &processes[i];
        Status status = executeCommand(process);
        if (status == FAILURE) {
            // Command failed, remove it from the list of processes to execute
            memmove(&processes[i], &processes[i + 1], num_processes - i - 1);
            num_processes--;
            i--;
        }
    }

    // Check if the load is above the maximum allowed load, and kill processes to reduce it
    if (load > MAX_LOAD) {
        for (int i = 0; i < num_processes; i++) {
            Process *process = &processes[i];
            if (process->priority < MIN_PRIORITY) {
                // Send the process a SIGKILL signal to kill it immediately
                int status = kill(process->id, SIGKILL);
                if (status == -1) {
                    perror("kill");
                    return FAILURE;
                }
            } else {
                break;
            }
        }
    }

    // Return the status and metrics
    Status status = SUCCESS;
    int num_active_processes = 0;
    for (int i = 0; i < num_processes; i++) {
        Process *process = &processes[i];
        if (process->priority >= MIN_PRIORITY) {
            num_active_processes++;
        }
    }
    int num_executed_commands = num_processes - num_active_processes;
    return status;
}

Status startProcess(Process *process) {
    // Create a new process and execute the command inside it
    pid_t pid = fork();
    if (pid == 0) {
        // Child process executes the command
        int status = system(process->command);
        if (status == -1) {
            return FAILURE;
        } else if (WIFEXITED(status)) {
            // Command exited normally, check the exit status
            if (WEXITSTATUS(status) != 0) {
                return FAILURE;
            }
        } else {
            // Command terminated abnormally, check the signal number
            int signum = WTERMSIG(status);
            if (signum == SIGKILL || signum == SIGSTOP) {
                return FAILURE;
            }
        }
    } else if (pid > 0) {
        // Parent process waits for the child to exit
        int status;
        waitpid(pid, &status, 0);
    } else {
        perror("fork");
        return FAILURE;
    }

    return SUCCESS;
}

int main() {
    // Initialize the pool of background processes
    Process *processes = (Process*) malloc(sizeof(Process) * MAX_PROCESSES);
    if (!processes) {
        perror("malloc");
        return 1;
    }
    int num_processes = 0;

    // Load the configuration from a JSON file
    json_object* config = loadConfig();
    if (!config) {
        fprintf(stderr, "Error loading configuration\n");
        return 1;
    }

    // Set up the external logging service
    int logfd = setupLoggingService(config);
    if (logfd == -1) {
        perror("setupLoggingService");
        return 1;
    }

    while (1) {
        // Check if there are any commands to execute
        if (num_processes < MAX_PROCESSES) {
            // Check if there are any commands in the queue
            json_object* command = getNextCommand();
            if (command) {
                // Add the command to the list of processes to execute
                processes[num_processes].id = getpid();
                processes[num_processes].priority = getPriority(command);
                processes[num_processes++].command = getCommand(command);
            }
        }

        // Manage the background processes and execute commands based on their priorities
        manageProcesses(processes, num_processes, 0.0);

        // Check if there are any failed commands and remove them from the list of processes to execute
        for (int i = 0; i < num_processes; i++) {
            Process *process = &processes[i];
            if (process->priority >= MIN_PRIORITY) {
                // Check if the command failed, and remove it from the list of processes to execute
                Status status = checkCommand(process);
                if (status == FAILURE) {
                    memmove(&processes[i], &processes[i + 1], num_processes - i - 1);
                    num_processes--;
                    i--;
                }
            } else {
                break;
            }
        }

        // Check if the load is above the maximum allowed load, and kill processes to reduce it
        if (getLoad() > MAX_LOAD) {
            for (int i = 0; i < num_processes; i++) {
                Process *process = &processes[i];
                if (process->priority < MIN_PRIORITY) {
                    // Send the process a SIGKILL signal to kill it immediately
                    int status = kill(process->id, SIGKILL);
                    if (status == -1) {
                        perror("kill");
                        return 1;
                    }
                } else {
                    break;
                }
            }
        }

        // Sleep for a short period of time to avoid busy-looping
        usleep(10000);
    }
}
```
This code block implements the C function that manages a dynamic pool of background processes. The function uses a JSON file to load the configuration and sets up an external logging service. It then enters a loop that checks if there are any commands to execute, manages the background processes based on their priorities, removes any failed commands from the list of processes to execute, and kills any processes that exceed the maximum allowed load. The function uses `fork()` to create a new process for each command to be executed, and `waitpid()` to wait for the child process to exit before continuing with the next iteration of the loop. The function also includes a short sleep period using `usleep()` to avoid busy-looping.']

