#include <openssl/rand.h>
#include <openssl/err.h>

// Initialize the cryptographic framework and register new algorithms
void init_crypto() {
    // Initialize OpenSSL library
    SSL_library_init();

    // Register AES algorithm
    EVP_add_cipher(EVP_aes_256_cbc());

    // Register Camellia algorithm
    EVP_add_cipher(EVP_camellia_192_cbc());

    // Register SHA256 algorithm
    EVP_add_digest(EVP_sha256());

    // Register RSA with SHA256 algorithm
    EVP_add_signature(EVP_rsa_with_sha256(), NULL);
}

// Generate cryptographic key of specified length and type
int generate_key(uint8_t *key, uint32_t len, enum crypto_type type) {
    // Check if key generation is supported for the given type
    if (!EVP_get_cipherbynid(type)) {
        return -1;
    }

    // Generate a random key using OpenSSL's RAND_bytes function
    if (RAND_bytes(key, len) != 1) {
        return -1;
    }

    return 0;
}

// Destroy cryptographic key securely
void destroy_key(uint8_t *key) {
    // Zeroize the key data to prevent it from being leaked
    memset(key, 0, sizeof(*key));

    // Free the allocated memory for the key
    free(key);
}

// Encrypt data using AES or Camellia algorithm
int encrypt(uint8_t *data, uint32_t len, uint8_t *key) {
    // Check if encryption is supported for the given key type
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher = EVP_get_cipherbynid(key->type);
    if (!cipher) {
        return -1;
    }

    // Create and initialize encryption context
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return -1;
    }

    // Set encryption key and algorithm type
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key->data, iv)) {
        return -1;
    }

    // Encrypt data in chunks
    while (len > 0) {
        // Get maximum chunk size for encryption
        uint32_t chunk_size = EVP_CIPHER_CTX_block_size(ctx);

        // Encrypt chunk of data
        if (EVP_EncryptUpdate(ctx, data, &chunk_size, data, len)) {
            return -1;
        }

        // Update data and remaining length
        data += chunk_size;
        len -= chunk_size;
    }

    // Finalize encryption
    if (EVP_EncryptFinal_ex(ctx, NULL, NULL)) {
        return -1;
    }

    // Clean up encryption context
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Decrypt data using AES or Camellia algorithm
int decrypt(uint8_t *data, uint32_t len, uint8_t *key) {
    // Check if decryption is supported for the given key type
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher = EVP_get_cipherbynid(key->type);
    if (!cipher) {
        return -1;
    }

    // Create and initialize decryption context
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return -1;
    }

    // Set decryption key and algorithm type
    if (EVP_DecryptInit_ex(ctx, cipher, NULL, key->data, iv)) {
        return -1;
    }

    // Decrypt data in chunks
    while (len > 0) {
        // Get maximum chunk size for decryption
        uint32_t chunk_size = EVP_CIPHER_CTX_block_size(ctx);

        // Decrypt chunk of data
        if (EVP_DecryptUpdate(ctx, data, &chunk_size, data, len)) {
            return -1;
        }

        // Update data and remaining length
        data += chunk_size;
        len -= chunk_size;
    }

    // Finalize decryption
    if (EVP_DecryptFinal_ex(ctx, NULL, NULL)) {
        return -1;
    }

    // Clean up decryption context
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Compute hash using SHA256 algorithm
int sha256(uint8_t *data, uint32_t len, uint8_t *hash) {
    // Create and initialize SHA256 context
    EVP_MD_CTX *ctx;
    const EVP_MD *md = EVP_get_digestbynid(NID_sha256);
    if (!md) {
        return -1;
    }

    // Set hash data and algorithm type
    ctx = EVP_MD_CTX_create();
    if (!ctx) {
        return -1;
    }

    // Initialize SHA256 context with data
    if (EVP_DigestInit_ex(ctx, md, NULL)) {
        return -1;
    }

    // Compute hash in chunks
    while (len > 0) {
        // Get maximum chunk size for SHA256
        uint32_t chunk_size = EVP_MAX_MD_SIZE;

        // Update hash with chunk of data
        if (EVP_DigestUpdate(ctx, data, len)) {
            return -1;
        }

        // Update data and remaining length
        data += chunk_size;
        len -= chunk_size;
    }

    // Finalize SHA256 hash computation
    if (EVP_DigestFinal_ex(ctx, hash, NULL)) {
        return -1;
    }

    // Clean up SHA256 context
    EVP_MD_CTX_destroy(ctx);

    return 0;
}

// Sign data using RSA with SHA256 algorithm
int sign(uint8_t *data, uint32_t len, uint8_t *key) {
    // Create and initialize RSA signature context
    EVP_MD_CTX *ctx;
    const EVP_MD *md = EVP_get_digestbynid(NID_sha256);
    if (!md) {
        return -1;
    }

    // Set data and algorithm type for RSA signature context
    ctx = EVP_MD_CTX_create();
    if (!ctx) {
        return -1;
    }

    // Initialize RSA signature context with data
    if (EVP_DigestInit_ex(ctx, md, NULL)) {
        return -1;
    }

    // Sign data in chunks
    while (len > 0) {
        // Get maximum chunk size for RSA signature
        uint32_t chunk_size = EVP_MAX_MD_SIZE;

        // Update hash with chunk of data
        if (EVP_DigestUpdate(ctx, data, len)) {
            return -1;
        }

        // Update data and remaining length
        data += chunk_size;
        len -= chunk_size;
    }

    // Finalize RSA signature computation
    if (EVP_DigestFinal_ex(ctx, NULL, key)) {
        return -1;
    }

    // Clean up RSA signature context
    EVP_MD_CTX_destroy(ctx);

    return 0;
}

// Verify data using RSA with SHA256 algorithm
int verify(uint8_t *data, uint32_t len, uint8_t *key) {
    // Create and initialize RSA verification context
    EVP_MD_CTX *ctx;
    const EVP_MD *md = EVP_get_digestbynid(NID_sha256);
    if (!md) {
        return -1;
    }

    // Set data and algorithm type for RSA verification context
    ctx = EVP_MD_CTX_create();
    if (!ctx) {
        return -1;
    }

    // Initialize RSA verification context with data
    if (EVP_DigestInit_ex(ctx, md, NULL)) {
        return -1;
    }

    // Verify data in chunks
    while (len > 0) {
        // Get maximum chunk size for RSA verification
        uint32_t chunk_size = EVP_MAX_MD_SIZE;

        // Update hash with chunk of data
        if (EVP_DigestUpdate(ctx, data, len)) {
            return -1;
        }

        // Update data and remaining length
        data += chunk_size;
        len -= chunk_size;
    }

    // Finalize RSA verification computation
    if (EVP_DigestFinal_ex(ctx, NULL, key)) {
        return -1;
    }

    // Clean up RSA verification context
    EVP_MD_CTX_destroy(ctx);

    return 0;
}

// Generate a symmetric key using AES-256 algorithm
int generate_key(uint8_t *key) {
    // Create and initialize AES-256 context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return -1;
    }

    // Set encryption algorithm type
    const EVP_CIPHER *cipher = EVP_get_cipherbynid(NID_aes_256_cbc);
    if (!cipher) {
        return -1;
    }

    // Initialize AES-256 context with key generation parameters
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        return -1;
    }

    // Generate symmetric key in chunks
    while (len > 0) {
        // Get maximum chunk size for AES-256 key generation
        uint32_t chunk_size = EVP_MAX_KEY_LENGTH;

        // Update key with chunk of data
        if (EVP_EncryptUpdate(ctx, key, &chunk_size, NULL, len)) {
            return -1;
        }

        // Update data and remaining length
        key += chunk_size;
        len -= chunk_size;
    }

    // Finalize AES-256 key generation computation
    if (EVP_EncryptFinal_ex(ctx, NULL, 0)) {
        return -1;
    }

    // Clean up AES-256 context
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Encrypt data using symmetric key and AES-256 algorithm
int encrypt(uint8_t *data, uint32_t len, uint8_t *key) {
    // Create and initialize AES-256 encryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return -1;
    }

    // Set encryption algorithm type and key
    const EVP_CIPHER *cipher = EVP_get_cipherbynid(NID_aes_256_cbc);
    if (!cipher) {
        return -1;
    }
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL)) {
        return -1;
    }

    // Encrypt data in chunks
    while (len > 0) {
        // Get maximum chunk size for AES-256 encryption
        uint32_t chunk_size = EVP_MAX_BLOCK_LENGTH;

        // Update ciphertext with chunk of plaintext
        if (EVP_EncryptUpdate(ctx, data, &chunk_size, data, len)) {
            return -1;
        }

        // Update plaintext and remaining length
        data += chunk_size;
        len -= chunk_size;
    }

    // Finalize AES-256 encryption computation
    if (EVP_EncryptFinal_ex(ctx, NULL, 0)) {
        return -1;
    }

    // Clean up AES-256 encryption context
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}

// Decrypt data using symmetric key and AES-256 algorithm
int decrypt(uint8_t *data, uint32_t len, uint8_t *key) {
    // Create and initialize AES-256 decryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return -1;
    }

    // Set decryption algorithm type and key
    const EVP_CIPHER *cipher = EVP_get_cipherbynid(NID_aes_256_cbc);
    if (!cipher) {
        return -1;
    }
    if (EVP_DecryptInit_ex(ctx, cipher, NULL, key, NULL)) {
        return -1;
    }

    // Decrypt data in chunks
    while (len > 0) {
        // Get maximum chunk size for AES-256 decryption
        uint32_t chunk_size = EVP_MAX_BLOCK_LENGTH;

        // Update plaintext with chunk of ciphertext
        if (EVP_DecryptUpdate(ctx, data, &chunk_size, data, len)) {
            return -1;
        }

        // Update ciphertext and remaining length
        data += chunk_size;
        len -= chunk_size;
    }

    // Finalize AES-256 decryption computation
    if (EVP_DecryptFinal_ex(ctx, NULL, 0)) {
        return -1;
    }

    // Clean up AES-256 decryption context
    EVP_CIPHER_CTX_free(ctx);

    return 0;
