LinkedList* initialize_network_interfaces(int num_interfaces) {
    // Allocate memory for the linked list of network interfaces
    LinkedList *interface_list = (LinkedList *)malloc(sizeof(LinkedList));
    if (!interface_list) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface list\n");
        return NULL;
    }

    // Initialize the linked list
    initialize_linked_list(interface_list);

    // Iterate over each network interface and create a corresponding structure
    for (int i = 0; i < num_interfaces; i++) {
        NetworkInterfaceStatus *interface = (NetworkInterfaceStatus *)malloc(sizeof(NetworkInterfaceStatus));
        if (!interface) {
            fprintf(stderr, "Error: Failed to allocate memory for network interface structure\n");
            return NULL;
        }

        // Initialize the network interface structure
        interface->id = i;
        interface->throughput = 0.0;
        interface->latency = 0.0;
        initialize_linked_list(interface->active_sessions);

        // Add the network interface to the linked list of interfaces
        add_to_linked_list(interface_list, interface);
    }

    return interface_list;
}

void update_network_interfaces(LinkedList *interface_list) {
    // Iterate over each network interface and update its throughput and latency
    for (int i = 0; i < interface_list->length; i++) {
        NetworkInterfaceStatus *interface = (NetworkInterfaceStatus *)get_from_linked_list(interface_list, i);
        if (!interface) continue;

        // Update the throughput and latency for this network interface
        double throughput = get_throughput_for_network_interface(interface->id);
        double latency = get_latency_for_network_interface(interface->id);

        // Validate the throughput and latency values to ensure they are within typical operational ranges
        if (throughput < 0 || throughput > 1000) {
            fprintf(stderr, "Error: Invalid throughput value for network interface %d\n", interface->id);
            continue;
        }
        if (latency < 0 || latency > 1000) {
            fprintf(stderr, "Error: Invalid latency value for network interface %d\n", interface->id);
            continue;
        }

        // Update the throughput and latency values in the network interface structure
        interface->throughput = throughput;
        interface->latency = latency;
    }
}

void handle_network_interface_updates(LinkedList *interface_list) {
    // Handle potential concurrency issues during updates to the network interfaces
    pthread_mutex_lock(&interface_list->mutex);

    // Update the throughput and latency values for each network interface
    update_network_interfaces(interface_list);

    // Release the mutex to allow other threads to access the linked list of interfaces
    pthread_mutex_unlock(&interface_list->mutex);
}

