#include <openssl/aes.h>
#include <openssl/evp.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

// Hashing algorithm for key derivation
#define HASH_ALGORITHM SHA256

// AES-256-CBC cipher initialization and cleanup functions
void initAES(const char* password, unsigned char** iv, unsigned char** key) {
    *iv = (unsigned char*)malloc(sizeof(uint8_t) * 16); // IV length is 16 bytes
    *key = (unsigned char*)malloc(sizeof(uint8_t) * 32); // Key length is 32 bytes
    if (!EVP_BytesToKey(HASH_ALGORITHM, AES_256_CBC, *iv, password, strlen(password), 1000, *key, NULL)) {
        printf("Error initializing AES-256-CBC cipher with given password\n");
        exit(1);
    }
}

void cleanupAES(unsigned char* iv, unsigned char* key) {
    free(iv);
    free(key);
}

// Function to find and print the largest integer in an array of integers
int findLargestInteger(int* arr, int size) {
    if (size <= 0) return -1; // Invalid input
    int max = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("%d\n", max);
    return max;
}

// Main function to handle AES-256-CBC cipher initialization, input array processing, and cleanup
int main() {
    unsigned char* iv = NULL;
    unsigned char* key = NULL;
    int arr[10] = {0}; // Input array of integers
    int size = sizeof(arr) / sizeof(arr[0]); // Size of input array

    // Initialize AES-256-CBC cipher with given password
    initAES("password", &iv, &key);

    // Read and store integer inputs from standard input
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    // Find and print the largest integer in the input array
    findLargestInteger(arr, size);

    // Clean up AES-256-CBC cipher resources
    cleanupAES(iv, key);

    return 0;
}
