int initialize_configuration(void) {
	// Initialize logger
	if (!logger_init()) {
		return LOGGER_INITIALIZATION_FAILURE;
	}

	// Verify logger performance
	if (!verify_logger_performance()) {
		logger_destroy();
		return LOGGER_PERFORMANCE_FAILURE;
	}

	// Initialize database connection
	if (!database_connect()) {
		logger_destroy();
		return DATABASE_CONNECTION_FAILURE;
	}

	// Verify database performance
	if (!verify_database_performance()) {
		database_disconnect();
		logger_destroy();
		return DATABASE_PERFORMANCE_FAILURE;
	}

	// Load user preferences
	if (!load_user_preferences()) {
		database_disconnect();
		logger_destroy();
		return USER_PREFERENCES_LOAD_FAILURE;
	}

	// Verify user preferences load timeout
	if (!verify_user_preferences_load_timeout()) {
		database_disconnect();
		logger_destroy();
		return USER_PREFERENCES_LOAD_TIMEOUT;
	}

	// Initialize settings updater callback function
	if (!initialize_settings_updater_callback()) {
		database_disconnect();
		logger_destroy();
		return SETTINGS_UPDATER_CALLBACK_INITIALIZATION_FAILURE;
	}

	// Verify settings updater callback performance
	if (!verify_settings_updater_callback_performance()) {
		database_disconnect();
		logger_destroy();
		return SETTINGS_UPDATER_CALLBACK_PERFORMANCE_FAILURE;
	}

	// Attempt to update user preferences using settings updater callback
	if (!update_user_preferences()) {
		database_disconnect();
		logger_destroy();
		return USER_PREFERENCES_UPDATE_FAILURE;
	}

	// Destroy logger and database connection
	logger_destroy();
	database_disconnect();

	return SUCCESS;
}

