	// Initialize logger with default settings
	if (!logger_default_init()) {
		return false;
	}

	// Set log level to INFO
	logger_set_level(INFO);

	// Enable logging of at least 100 messages per second under high load conditions
	logger_enable_high_load_logging();

	return true;
}

