	int64_t start = get_time_in_milliseconds();

	// Log 100 messages per second for at least 5 seconds
	for (int i = 0; i < 5000; i++) {
		logger_log("Test message %d", i);
	}

	int64_t end = get_time_in_milliseconds();

	// Verify that at least 100 messages per second were logged within the last 5 seconds
	if (end - start < 5000) {
		return false;
	}

	return true;
}

