      size_t currentPacketIndex = 0;
      uint8_t* encryptionKey; // Encryption key for ZUC algorithm
      size_t encryptionKeyLength; // Length of encryption key in bytes

    public:
      PacketAssembler(uint8_t* encryptionKey, size_t encryptionKeyLength) :
        encryptionKey(encryptionKey),
        encryptionKeyLength(encryptionKeyLength) {}

      ~PacketAssembler() {
        for (size_t i = 0; i < packetHeaders.size(); i++) {
          delete[] packetHeaders[i].data;
        }
      }

      void assemblePacketList(std::vector<PACKET_HEADER_T>& headers) {
        // Assemble packets from list of PACKET_HEADER_T structures
        for (size_t i = 0; i < headers.size(); i++) {
          std::byte* data = new std::byte[headers[i].dataSize];
          memcpy(data, &headers[i], sizeof(PACKET_HEADER_T));
          // Encrypt data using ZUC algorithm with encryption key
          zuc_encrypt(data, headers[i].dataSize, encryptionKey);
          packetHeaders.push_back({ headers[i].sequenceNumber, headers[i].sourceIp, headers[i].destinationIp, headers[i].dataSize, data });
        }
      }

      void disassemblePacketStream(const std::byte* stream, size_t length, std::vector<PACKET_HEADER_T>& headers) {
        // Disassemble packets from packet stream
        for (size_t i = 0; i < length; i++) {
          std::byte* data = new std::byte[headers[i].dataSize];
          memcpy(data, &stream[i], sizeof(PACKET_HEADER_T));
          // Decrypt data using ZUC algorithm with encryption key
          zuc_decrypt(data, headers[i].dataSize, encryptionKey);
          packetHeaders.push_back({ headers[i].sequenceNumber, headers[i].sourceIp, headers[i].destinationIp, headers[i].dataSize, data });
        }
      }
  };
}
