            pdu->rx_ue_information_tag = 0x80;
            pdu->rnti = rnti;
            pdu->crc_indication_rel8_tag = 0x40;
            pdu->crcflag = (rand() % 2) ? true : false;
            list->list[list->count++] = *pdu;
        }
    }
