// Function to remove a NFAPI_CRC_INDICATION_PDU structure from the list by RNTI value
void remove_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint16_t rnti) {
    // Find the index of the structure to be removed
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->list[i].rnti == rnti) {
            break;
        }
    }

    // Check if the structure was found
    if (i < list->count) {
        // Remove the structure from the list
        memmove(&list->list[i], &list->list[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->count--;
    }
}

// Function to clear the entire list of NFAPI_CRC_INDICATION_PDU structures
void clear_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list) {
