void initEntries(int numEntries, long seed) {
    // Check for invalid input parameters
    if (numEntries <= 0) {
        printf("Invalid number of entries: %d\n", numEntries);
        return;
    }

    // Allocate memory for the collection
    Entry *entries = malloc(sizeof(Entry) * numEntries);
    if (entries == NULL) {
        printf("Failed to allocate memory for the entries\n");
        return;
    }

    // Initialize the collection with random values and timestamps
    srand(seed);
    for (int i = 0; i < numEntries; i++) {
        entries[i].key = i + 1;
        entries[i].timestamp = time(NULL);
        entries[i].value = rand() / (double)RAND_MAX * 10.0 - 5.0;
    }

    // Handle memory reallocation and resizing
    if (numEntries > 2 && numEntries % 2 == 0) {
        // Reallocate the collection to double its size if it exceeds capacity
        entries = realloc(entries, sizeof(Entry) * 2 * numEntries);
        if (entries == NULL) {
            printf("Failed to reallocate memory for the entries\n");
            return;
        }
    } else if (numEntries < 4 && numEntries % 2 != 0) {
        // Resize the collection to half its size if it is too small
        int newNumEntries = numEntries / 2;
        Entry *newEntries = malloc(sizeof(Entry) * newNumEntries);
        if (newEntries == NULL) {
            printf("Failed to allocate memory for the resized entries\n");
            return;
        }
        memcpy(newEntries, entries, sizeof(Entry) * numEntries);
        free(entries);
        entries = newEntries;
    }
}
