    if (profile->contact.phoneNumber.length() > 10 || !isdigit(profile->contact.phoneNumber)) {
        return false;
    }
    if (profile->contact.emailAddress.find('@') == std::string::npos) {
        return false;
    }

    // Check for correct size limit of profile picture
    if (profile->picture.size() > 1024 * 1024) {
        return false;
    }

    // Return true if all validation checks passed successfully
    return true;
}

// Implement logging mechanism to record critical events
void logEvent(struct Log* log, enum EventType eventType, struct User* user) {
