#include <json-c/json.h>

// Define the struct to hold the configuration settings
struct Configuration {
    float *values;
    size_t count;
};

// Define the helper function to calculate the average value of an array
float calculateAverage(const float *array, const size_t length) {
    if (length == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (size_t i = 0; i < length; ++i) {
        sum += array[i];
    }
    return sum / length;
}

// Define the function to read configuration settings from the remote API
void getConfiguration(struct Configuration *config, const char *url) {
    CURL *curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L); // set timeout to 10 seconds
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to get configuration: %s\n", curl_easy_strerror(res));
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code != 200) {
                fprintf(stderr, "Bad HTTP response code: %ld\n", http_code);
            } else {
                // Parse the JSON response
                json_object *response = NULL;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_HEADER, &response);
                if (response) {
                    json_object *values = json_object_array_get_idx(response, 0);
                    config->count = json_object_array_length(values);
                    config->values = malloc(config->count * sizeof(float));
                    for (size_t i = 0; i < config->count; ++i) {
                        const char *value = json_object_get_string(json_object_array_get_idx(values, i));
                        if (!value || sscanf(value, "%f", &config->values[i]) != 1) {
                            fprintf(stderr, "Failed to parse value: %s\n", value);
                        }
                    }
                } else {
                    fprintf(stderr, "Failed to get response header\n");
                }
            }
        }
        curl_easy_cleanup(curl);
    }
}

int main() {
    struct Configuration config;
    const char *url = "https://example.com/configuration";
    getConfiguration(&config, url);
    if (config.values) {
        // Calculate the average value of the configuration settings
        float average = calculateAverage(config.values, config.count);
        printf("Average configuration setting: %f\n", average);
    } else {
        fprintf(stderr, "Failed to get configuration settings\n");
    }
    return 0;
}']

