Here is a sample C function to manage a dynamic array of MAC entity contexts:
```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a MAC entity context
typedef struct {
  char l2_entity_id[32]; // L2 Entity ID
  int num_bearer_contexts; // Number of active bearer contexts
  QoSFlowDescriptor *flow_descriptors; // List of QoS flow descriptors
} MacEntityContext;

// Define the structure for a dynamic array of MAC entity contexts
typedef struct {
  MacEntityContext **contexts; // Array of MAC entity contexts
  int num_contexts; // Number of contexts in the array
  pthread_mutex_t lock; // Mutex for protecting access to the array
} MacEntityContextArray;

// Initialize a dynamic array of MAC entity contexts
MacEntityContextArray *init_mac_entity_context_array() {
  MacEntityContextArray *arr = malloc(sizeof(MacEntityContextArray));
  arr->num_contexts = 0;
  pthread_mutex_init(&arr->lock, NULL);
  return arr;
}

// Add a new MAC entity context to the dynamic array
void add_mac_entity_context(MacEntityContextArray *arr, char *l2_entity_id, int num_bearer_contexts) {
  MacEntityContext *ctx = malloc(sizeof(MacEntityContext));
  ctx->l2_entity_id[31] = '\0';
  strncpy(ctx->l2_entity_id, l2_entity_id, 31);
  ctx->num_bearer_contexts = num_bearer_contexts;
  pthread_mutex_lock(&arr->lock);
  arr->num_contexts++;
  arr->contexts = realloc(arr->contexts, sizeof(MacEntityContext *) * arr->num_contexts);
  arr->contexts[arr->num_contexts - 1] = ctx;
  pthread_mutex_unlock(&arr->lock);
}

// Update an existing MAC entity context in the dynamic array
void update_mac_entity_context(MacEntityContextArray *arr, char *l2_entity_id, int num_bearer_contexts) {
  pthread_mutex_lock(&arr->lock);
  for (int i = 0; i < arr->num_contexts; i++) {
    if (!strcmp(arr->contexts[i]->l2_entity_id, l2_entity_id)) {
      arr->contexts[i]->num_bearer_contexts = num_bearer_contexts;
      break;
    }
  }
  pthread_mutex_unlock(&arr->lock);
}

// Retrieve a MAC entity context from the dynamic array by its L2 Entity ID
MacEntityContext *get_mac_entity_context(MacEntityContextArray *arr, char *l2_entity_id) {
  pthread_mutex_lock(&arr->lock);
  for (int i = 0; i < arr->num_contexts; i++) {
    if (!strcmp(arr->contexts[i]->l2_entity_id, l2_entity_id)) {
      pthread_mutex_unlock(&arr->lock);
      return arr->contexts[i];
    }
  }
  pthread_mutex_unlock(&arr->lock);
  return NULL;
}
```
