#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

struct record {
    long offset;
    int key;
    char *metadata;
    bool active;
};

struct record_list {
    struct record **records;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cv;
    struct record *head, *tail;
    int cache[];
};

void init_record_list(struct record_list *list) {
    list->records = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cv, NULL);
    list->head = NULL;
    list->tail = NULL;
}

void destroy_record_list(struct record_list *list) {
    free(list->records);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cv);
}

bool insert_record(struct record_list *list, struct record *r) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == 0) {
        list->head = r;
        list->tail = r;
    } else {
        r->next = list->head;
        list->head->prev = r;
        list->head = r;
    }
    list->records[list->count] = r;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

bool delete_record(struct record_list *list, struct record *r) {
    pthread_mutex_lock(&list->mutex);
    if (r == list->head) {
        list->head = r->next;
    }
    if (r == list->tail) {
        list->tail = r->prev;
    }
    if (r->prev != NULL) {
        r->prev->next = r->next;
    }
    if (r->next != NULL) {
        r->next->prev = r->prev;
    }
    list->records[list->count] = r;
    list->count--;
    pthread_mutex_unlock(&list->mutex);
}

struct record *get_record(struct record_list *list, int key) {
    struct record *r = NULL;
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->records[i]->key == key) {
            r = list->records[i];
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return r;
}

void set_record_status(struct record_list *list, struct record *r, bool active) {
    pthread_mutex_lock(&list->mutex);
    if (active) {
        r->next = list->head;
        list->head->prev = r;
        list->head = r;
    } else {
        r->next = NULL;
        r->prev = NULL;
    }
    pthread_mutex_unlock(&list->mutex);
}

void cache_record(struct record_list *list, struct record *r) {
    list->cache[list->count] = r;
    list->count++;
}

struct record *get_cached_record(struct record_list *list, int index) {
    return list->cache[index];
}

void invalidate_cached_record(struct record_list *list, struct record *r) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->cache[i] == r) {
            list->cache[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void cleanup_inactive_records(struct record_list *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (!list->cache[i]->active) {
            free(list->cache[i]);
            list->cache[i] = NULL;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void serialize_record_list(struct record_list *list, FILE *f) {
    fwrite(&list->count, sizeof(int), 1, f);
    for (int i = 0; i < list->count; i++) {
        struct record *r = list->records[i];
        fwrite(&r->offset, sizeof(long), 1, f);
        fwrite(&r->key, sizeof(int), 1, f);
        fwrite(r->metadata, strlen(r->metadata) + 1, 1, f);
    }
}

void deserialize_record_list(struct record_list *list, FILE *f) {
    int count;
    fread(&count, sizeof(int), 1, f);
    for (int i = 0; i < count; i++) {
        struct record r;
        fread(&r.offset, sizeof(long), 1, f);
        fread(&r.key, sizeof(int), 1, f);
        r.metadata = malloc(strlen(f) + 1);
        fread(r.metadata, strlen(r.metadata) + 1, 1, f);
        insert_record(list, &r);
    }
}
```
This implementation includes a doubly linked list data structure to maintain records in a thread-safe manner. The linked list is protected by a mutex and condition variable for concurrent access. A cache of recently accessed records is also implemented to minimize the need for frequent record lookups. Additionally, this implementation includes functions for serializing and deserializing the record list to file, which allows the program to persist its state across runs.']

