        if (interfaces[i].throughput < min_throughput || interfaces[i].latency > max_latency) {
            free(interfaces);
            fprintf(stderr, "Failed to validate throughput and latency values for interface %d\n", i + 1);
            return -3;
        }
    }

    // Filter the interfaces based on minimum throughput and maximum latency criteria provided by the user
    int filtered_interfaces = 0;
    for (int i = 0; i < num_interfaces; i++) {
