            filtered_interfaces++;
        } else {
            free(interfaces[i].sessions);
        }
    }

    // Reallocate the memory for the filtered interfaces
    NetworkInterfaceStatus *filtered_interfaces = realloc(interfaces, sizeof(NetworkInterfaceStatus) * filtered_interfaces);
    if (!filtered_interfaces) {
