// Function to process CSV file containing floating-point numbers
void processCSVFile(const char *filepath) {
  // Open the CSV file for reading
  FILE *fp = fopen(filepath, "r");
  if (fp == NULL) {
    printf("Error opening file %s\n", filepath);
    return;
  }

  // Initialize variables to track valid numbers and average
  int numValidNumbers = 0;
  long totalSum = 0;

  // Read the CSV file line by line
  char *line = NULL;
  size_t len = 0;
  ssize_t read;
  while ((read = getline(&line, &len, fp)) != -1) {
    // Trim newline character from end of line
    int lineLen = strlen(line);
    if (line[lineLen-1] == '\n') {
      line[lineLen-1] = '\0';
    }

    // Split the line into separate fields using comma as delimiter
    char **fields = str_split(line, ',');

    // Iterate over each field and check for valid numbers
    int numFields = sizeof(fields) / sizeof(fields[0]);
    for (int i = 0; i < numFields; i++) {
      char *field = fields[i];
      if (!isNumericString(field)) {
        // Skip invalid entries and continue with next field
        continue;
      }

      // Convert string to float and add to total sum
      float value = atof(field);
      totalSum += (long)value;

      // Increment valid numbers count
      numValidNumbers++;
    }
  }

  // Calculate average of valid numbers
  if (numValidNumbers > 0) {
    double average = (double)totalSum / (double)numValidNumbers;
    printf("Average: %lf\n", average);
  } else {
    printf("No valid numbers found in file\n");
  }

  // Clean up memory allocated for fields and line buffer
  for (int i = 0; i < numFields; i++) {
    free(fields[i]);
  }
  free(line);
  fclose(fp);
}

// Split a string into an array of substrings using a specified delimiter
char **str_split(char *str, char delim) {
  int len = strlen(str);
  char **fields = (char **)malloc(len * sizeof(char *));
  if (fields == NULL) {
    return NULL;
  }

  // Initialize array with empty strings
  for (int i = 0; i < len; i++) {
    fields[i] = "";
  }

  int fieldIndex = 0;
  char *token = strtok(str, delim);
  while (token != NULL) {
    fields[fieldIndex++] = token;
    token = strtok(NULL, delim);
  }

  return fields;
}

// Check if a string is a valid floating-point number
int isNumericString(char *str) {
  char *end;
  double value = strtod(str, &end);
  if (end == NULL || *end != '\0') {
    return 0;
  }
  return 1;
}
