// Initialize the pool with a fixed capacity
static void init_pool(PHY_RX_BUFFER_T *pool) {
    pool->count = 0;
    pool->capacity = 50000;
}

// Allocate memory for a new RX buffer
static RX_FRAME_INFO *alloc_rx_buffer(PHY_RX_BUFFER_T *pool) {
    if (pool->count < pool->capacity) {
        return &(pool->rx_buffers[pool->count++]);
    } else {
        return NULL;
    }
}

// Free memory for an RX buffer
static void free_rx_buffer(PHY_RX_BUFFER_T *pool, RX_FRAME_INFO *buffer) {
    if (buffer != NULL) {
        pool->count--;
    }
}

// Add a new RX buffer to the pool
static void add_rx_buffer(PHY_RX_BUFFER_T *pool, RX_FRAME_INFO *buffer) {
    if (pool->count < pool->capacity) {
        pool->rx_buffers[pool->count++] = buffer;
    } else {
        free_rx_buffer(pool, buffer);
    }
}

// Remove an RX buffer from the pool
