    }

    return array;
}

// Helper function to generate a random string of specified length using given character set
char* generateRandomString(int length, const char* charset) {
    int len = strlen(charset);
    char* result = malloc((length + 1) * sizeof(char));

    // Generate a random number between 0 and the length of the charset
    int randomIndex = rand() % len;

    // Iteratively generate a string of specified length using the given character set
    for (int i = 0; i < length; ++i) {
        result[i] = charset[randomIndex];
        randomIndex = (randomIndex + 1) % len;
    }
    result[length] = '\0';

    return result;
}

// Helper function to calculate a checksum for a given message
uint8_t calculateChecksum(char* msg) {
    int len = strlen(msg);
    uint8_t sum = 0;

    // Calculate the checksum by iterating over each character in the message
    for (int i = 0; i < len; ++i) {
        sum += msg[i];
    }

    return sum % 256;
}
