// Function to initialize hash table
void hashTableInit(struct HashTable* ht) {
    ht->capacity = 1000; // Initial capacity of hash table
    ht->table = (MacEntityContext**) malloc(ht->capacity * sizeof(MacEntityContext*));
    memset(ht->table, NULL, ht->capacity * sizeof(MacEntityContext*));
}

// Function to hash L2 Entity ID into index of hash table
int hashL2EntityId(uint32_t l2EntityId) {
    return l2EntityId % ht->capacity;
}

// Function to add new MAC entity context to hash table
void addContext(uint32_t l2EntityId, uint32_t numActiveBearers, QosFlowDescriptor* qosFlowDescriptors) {
    // Create new MAC entity context
