        idx++;
        if (idx == ht->capacity) {
            // Resize hash table if necessary
            struct HashTable* newHt = (struct HashTable*) malloc(sizeof(struct HashTable));
            newHt->capacity *= 2;
            newHt->table = (MacEntityContext**) malloc(newHt->capacity * sizeof(MacEntityContext*));
            memset(newHt->table, NULL, newHt->capacity * sizeof(MacEntityContext*));
            for (int i = 0; i < ht->capacity; i++) {
