                if (ctx != NULL) {
                    int newIdx = hashL2EntityId(ctx->l2EntityId);
                    while (newHt->table[newIdx] != NULL) {
                        newIdx++;
                        if (newIdx == newHt->capacity) {
                            // Resize hash table again if necessary
                            struct HashTable* tmpHt = newHt;
                            newHt = (struct HashTable*) malloc(sizeof(struct HashTable));
                            newHt->capacity *= 2;
                            newHt->table = (MacEntityContext**) malloc(newHt->capacity * sizeof(MacEntityContext*));
                            memset(newHt->table, NULL, newHt->capacity * sizeof(MacEntityContext*));
                            for (int j = 0; j < tmpHt->capacity; j++) {
