                                if (ctx != NULL) {
                                    int newIdx = hashL2EntityId(ctx->l2EntityId);
                                    while (newHt->table[newIdx] != NULL) {
                                        newIdx++;
                                        assert(newIdx < newHt->capacity);
                                    }
                                    newHt->table[newIdx] = ctx;
                                }
                            }
                            free(tmpHt->table);
                            free(tmpHt);
                        }
                    }
                    assert(newIdx < newHt->capacity);
                    newHt->table[newIdx] = ctx;
                }
            }
            free(ht->table);
            ht = newHt;
        }
    }
    ht->table[idx] = ctx;
}

// Function to update existing MAC entity context in hash table
void updateContext(uint32_t l2EntityId, uint32_t numActiveBearers) {
    int idx = hashL2EntityId(l2EntityId);
    while (ht->table[idx] == NULL || ht->table[idx]->l2EntityId != l2EntityId) {
