                }
            }
            free(ht->table);
            ht = newHt;
        }
    }
    MacEntityContext* ctx = ht->table[idx];
    ctx->numActiveBearers = numActiveBearers;
}

// Function to remove existing MAC entity context from hash table
void deleteContext(uint32_t l2EntityId) {
    int idx = hashL2EntityId(l2EntityId);
    while (ht->table[idx] == NULL || ht->table[idx]->l2EntityId != l2EntityId) {
        idx++;
        if (idx == ht->capacity) {
            return; // Context not found
        }
    }
    MacEntityContext* ctx = ht->table[idx];
    free(ctx);
    ht->table[idx] = NULL;
}

// Function to retrieve MAC entity context from hash table
MacEntityContext* getContext(uint32_t l2EntityId) {
    int idx = hashL2EntityId(l2EntityId);
    while (ht->table[idx] == NULL || ht->table[idx]->l2EntityId != l2EntityId) {
        idx++;
        if (idx == ht->capacity) {
            return NULL; // Context not found
        }
    }
    return ht->table[idx];
}

// Function to retrieve all MAC entity contexts from hash table
MacEntityContext* getAllContexts(void) {
