void *processIntegerList(void *input) {
    // Get the input list from the thread argument
    int *list = (int *)input;

    // Loop through the list and update the largest integer
    for (size_t i = 0; i < input_size; i++) {
        if (list[i] > largest_integer) {
            largest_integer = list[i];
        }
    }
