// Function to read a list of integers from standard input
void readIntegerList(int *list, size_t size) {
    // Check the input size is within the maximum limit
    if (size > 10000) {
        printf("Input size exceeds maximum limit\n");
        exit(1);
    }

    // Read each integer from standard input and add to list
    for (size_t i = 0; i < size; i++) {
        scanf("%d", &list[i]);
    }
}

// Main function that processes multiple input lists concurrently
int main() {
    // Create a thread pool with 4 threads
    pthread_t threads[4];

    // Initialize the list of integers and the input size
    int *list = (int *)malloc(sizeof(int) * 10000);
    readIntegerList(list, 10000);

    // Create a barrier to synchronize threads
    pthread_barrier_t barrier;
    pthread_barrier_init(&barrier, NULL, 4);

    // Launch the threads to process the input lists
    for (int i = 0; i < 4; i++) {
        int status = pthread_create(&threads[i], NULL, processIntegerList, list + (i * 2500));
        if (status != 0) {
            printf("Error creating thread %d\n", i);
            exit(1);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print the largest integer in the list
    printf("Largest integer: %d\n", largest_integer);

    // Clean up resources
    free(list);
    pthread_barrier_destroy(&barrier);

    return 0;
}
