        // Periodically select a video game character attack to use from a predefined set of attacks
        if (!isCooldownActive || std::chrono::steady_clock::now() - lastCooldownEndTime >= std::chrono::seconds(9)) {
            currentAttackIndex = (currentAttackIndex + 1) % availableAttacks.size();
            isCooldownActive = true;
            lastCooldownEndTime = std::chrono::steady_clock::now() + std::chrono::seconds(9);
