#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the maximum number of packets that can be stored in the list
#define MAX_PACKETS 1000

// Define the maximum payload length for each packet
#define MAX_PAYLOAD_LENGTH 1024

// Define the predefined limit for memory usage
#define MEMORY_LIMIT (MAX_PACKETS * sizeof(NFAPI_UL_TxPacket_t))

typedef struct NFAPI_UL_TxPacket {
    TX_RRC_CONNECTION_RECONFIGURATION msg;
    uint16_t pci;
    uint32_t payload_length;
    NFAPI_UL_TxPdu_t* payload;
} NFAPI_UL_TxPacket_t;

typedef struct {
    // Array of pointers to the dynamically allocated packets
    NFAPI_UL_TxPacket_t** packets;
    // Number of packets currently stored in the list
    size_t num_packets;
    // Total memory usage of the list (in bytes)
    size_t total_memory_usage;
} NFAPI_UL_TxPacketList_t;

// Function to initialize and manage a dynamically allocated list of NFAPI_UL_TxPacket_t structures
NFAPI_UL_TxPacketList_t* nfapi_ul_tx_packet_list_init(void) {
    // Allocate memory for the list structure
    NFAPI_UL_TxPacketList_t* list = (NFAPI_UL_TxPacketList_t*) malloc(sizeof(NFAPI_UL_TxPacketList_t));
    if (!list) {
        return NULL;
    }
    // Initialize the list structure
    list->packets = (NFAPI_UL_TxPacket_t**) calloc(MAX_PACKETS, sizeof(NFAPI_UL_TxPacket_t*));
    if (!list->packets) {
        free(list);
        return NULL;
    }
    list->num_packets = 0;
    list->total_memory_usage = 0;
    // Return the initialized list structure
    return list;
}

// Function to add a new packet to the list
void nfapi_ul_tx_packet_list_add(NFAPI_UL_TxPacketList_t* list, TX_RRC_CONNECTION_RECONFIGURATION msg, uint16_t pci) {
    // Check if the list is full
    if (list->num_packets == MAX_PACKETS) {
        return;
    }
    // Allocate memory for the new packet
    NFAPI_UL_TxPacket_t* packet = (NFAPI_UL_TxPacket_t*) malloc(sizeof(NFAPI_UL_TxPacket_t));
    if (!packet) {
        return;
    }
    // Initialize the new packet structure
    packet->msg = msg;
    packet->pci = pci;
    // Generate a random payload length for the new packet
    int min = 10, max = MAX_PAYLOAD_LENGTH - MIN_PAYLOAD_LENGTH + 1;
    packet->payload_length = (rand() % (max - min)) + min;
    // Allocate memory for the payload
    packet->payload = (NFAPI_UL_TxPdu_t*) malloc(packet->payload_length);
    if (!packet->payload) {
        free(packet);
        return;
    }
    // Add the new packet to the list
    list->packets[list->num_packets++] = packet;
    // Update the total memory usage of the list
    list->total_memory_usage += sizeof(NFAPI_UL_TxPacket_t) + packet->payload_length;
    if (list->total_memory_usage > MEMORY_LIMIT) {
        // Prioritize discarding older packets to maintain stability
        for (int i = 0; i < list->num_packets - 1; i++) {
            NFAPI_UL_TxPacket_t* current_packet = list->packets[i];
            if (current_packet) {
                free(current_packet->payload);
                free(current_packet);
                current_packet = NULL;
                list->packets[i] = NULL;
            }
        }
    }
}

// Function to remove a packet from the list by its index
void nfapi_ul_tx_packet_list_remove(NFAPI_UL_TxPacketList_t* list, int index) {
    // Check if the index is valid
    if (index < 0 || index >= list->num_packets) {
        return;
    }
    // Remove the packet from the list by its index
    NFAPI_UL_TxPacket_t* current_packet = list->packets[index];
    if (current_packet) {
        free(current_packet->payload);
        free(current_packet);
        current_packet = NULL;
        list->packets[index] = NULL;
        // Update the total memory usage of the list
        list->total_memory_usage -= sizeof(NFAPI_UL_TxPacket_t) + current_packet->payload_length;
    }
}

// Function to handle a new packet from the network, including processing and logging
void nfapi_ul_tx_packet_handle(NFAPI_UL_TxPacketList_t* list, TX_RRC_Connection_Reestablishment msg) {
    // Check if the list is full
    if (list->num_packets == MAX_PACKETS) {
        return;
    }
    // Add the new packet to the list
    nfapi_ul_tx_packet_list_add(list, msg);
}

// Function to update the memory usage of the list, including checking for leaks
void nfapi_ul_tx_packet_list_update_memory_usage(NFAPI_UL_TxPacketList_t* list) {
    // Check if there are any leaked packets in the list
    for (int i = 0; i < list->num_packets; i++) {
        NFAPI_UL_TxPacket_t* current_packet = list->packets[i];
        if (current_packet) {
            // Update the total memory usage of the list
            list->total_memory_usage -= sizeof(NFAPI_UL_TxPacket_t) + current_packet->payload_length;
            // Remove the leaked packet from the list
            nfapi_ul_tx_packet_list_remove(list, i);
        }
    }
}
```

