void setEnvironmentVariablesFromConfigurationFile(const char *config_file) {
    // Parse configuration file for seed and log level values, if specified
    struct Configuration config = parseConfigurationFile(config_file);
    if (config.seed == 0 && config.log_level == NULL) {
        return;
    }
    // Set environment variables for seed and log level as needed
    if (config.seed != 0) {
        setenv("CRC_INDICATION_SEED", config.seed, 1);
    }
    if (config.log_level != NULL) {
        setenv("LOGGING_LEVEL", config.log_level, 1);
    }
}

uint32_t generateRandomValueForCRCFlag(void) {
    // Generate random value for CRCFLAG based on seed value
    srand(time(NULL));
    uint32_t seed = getenv("CRC_INDICATION_SEED");
    if (seed == NULL) {
        return rand() & 0x1;
    } else {
        return seed % 2;
    }
