    srand(time(NULL));
    uint32_t seed = getenv("CRC_INDICATION_SEED");
    if (seed == NULL) {
        return rand() & 0xFFFF;
    } else {
        return seed % 65536;
    }
}

struct NFARPC_PDU *allocateNfarpcPdu(void) {
