#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/des.h>
#include <openssl/rand.h>
#include <openssl/err.h>

// Define the NFAPI_INDICATION_PDU_T structure
struct NFAPI_INDICATION_PDU_T {
  unsigned char *rx_ue_information_tag;
  unsigned int rnti;
  unsigned char *crc_indication_rel8_tag;
  unsigned char crcflag;
};

// Define the connection settings structure
struct CONNECTION_SETTINGS {
  char *title;
  int initialization_status;
  void (*callback1)(void);
  void (*callback2)(void);
};

// Define the decryption key and IV for Triple DES
static const unsigned char des_key[8] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
static const unsigned char iv[8] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};

// Define the error codes for the function
#define PROCESS_NFAPI_INDICATIONS_SUCCESS 0
#define PROCESS_NFAPI_INDICATIONS_ERROR -1
#define VALIDATION_ERROR 2
#define DECRYPTION_ERROR 3

// Function to initialize and populate the list of NFAPI_INDICATION_PDU_T structures
int processNFAPIIndications(struct CONNECTION_SETTINGS *connection_settings, struct NFAPI_INDICATION_PDU_T **indication_list) {
  // Validate the connection settings and callback functions
  if (connection_settings->initialization_status != 1 || connection_settings->callback1 == NULL || connection_settings->callback2 == NULL) {
    printf("Error: Connection settings or callback functions are not valid\n");
    return VALIDATION_ERROR;
  }

  // Initialize the list of NFAPI_INDICATION_PDU_T structures
  *indication_list = malloc(sizeof(struct NFAPI_INDICATION_PDU_T) * connection_settings->initialization_status);
  if (*indication_list == NULL) {
    printf("Error: Failed to allocate memory for the indication list\n");
    return PROCESS_NFAPI_INDICATIONS_ERROR;
  }

  // Populate the list of NFAPI_INDICATION_PDU_T structures with data from an external source
  for (int i = 0; i < connection_settings->initialization_status; i++) {
    (*indication_list)[i].rx_ue_information_tag = malloc(sizeof(unsigned char) * 8);
    (*indication_list)[i].rnti = rand() % 1024;
    (*indication_list)[i].crc_indication_rel8_tag = malloc(sizeof(unsigned char) * 8);
    (*indication_list)[i].crcflag = 1;
  }

  // Validate each structure and decrypt the Base64-encoded message associated with each credential using Triple DES encryption
  for (int i = 0; i < connection_settings->initialization_status; i++) {
    if ((*indication_list)[i].rx_ue_information_tag == NULL || (*indication_list)[i].crc_indication_rel8_tag == NULL) {
      printf("Error: Structure %d is not valid\n", i);
      return VALIDATION_ERROR;
    }

    // Determine the appropriate decryption algorithm and format based on the connection type and expected message format
    switch (connection_settings->title[i]) {
      case 'A':
        if ((*indication_list)[i].rx_ue_information_tag[0] != 0x12 || (*indication_list)[i].crc_indication_rel8_tag[0] != 0x34) {
          printf("Error: Message format is not valid\n");
          return DECRYPTION_ERROR;
        }
      case 'B':
        if ((*indication_list)[i].rx_ue_information_tag[0] != 0x13 || (*indication_list)[i].crc_indication_rel8_tag[0] != 0x35) {
          printf("Error: Message format is not valid\n");
          return DECRYPTION_ERROR;
        }
    }

    // Decrypt the Base64-encoded message associated with each credential using Triple DES encryption
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen = 0;
    if (EVP_DecryptInit(ctx, EVP_des_cbc(), des_key, iv) <= 0 ||
        EVP_DecryptUpdate(ctx, NULL, &outlen, (*indication_list)[i].rx_ue_information_tag, strlen((char *)(*indication_list)[i].rx_ue_information_tag)) <= 0 ||
        EVP_DecryptFinal(ctx, NULL, &outlen) <= 0) {
      printf("Error: Failed to decrypt the message\n");
      return DECRYPTION_ERROR;
    }
    free(ctx);
  }

  // Return an error code indicating the outcome of the operation and the processed and decrypted message if successful
  return PROCESS_NFAPI_INDICATIONS_SUCCESS;
}
