        log_entries[i].ue_id = i + 1;
        log_entries[i].level = INFO;
    }

    // Set the global variable to track the number of log entries
    num_log_entries = max_num_entries;
}

// Define a function to add a new log entry to the list
void add_log_entry(ModemLogEntry *new_entry) {
    // Acquire the lock on the shared log file
    pthread_mutex_lock(&log_file_mutex);

    // Check if the maximum number of log entries has been reached
    if (num_log_entries == 0) {
        // If so, initialize and populate the list of ModemLogEntry structures
        init_log(max_num_entries);
    }

    // Add the new log entry to the end of the list
    log_entries[num_log_entries++] = *new_entry;

    // Release the lock on the shared log file
    pthread_mutex_unlock(&log_file_mutex);
}

