    // Check if the maximum number of retries has been reached
    if (num_retries == max_num_retries) {
        // If so, return without writing the log entry to the shared log file
        pthread_mutex_unlock(&log_file_mutex);
        return;
    }

    // Attempt to write the log entry to the shared log file
    if (fprintf(stderr, "%d:%s\n", log_entry->timestamp, log_entry->ue_id, log_entry->level) == EOF) {
        // If unsuccessful, increment the number of retries and try again
        num_retries++;
    } else {
        // If successful, reset the number of retries to 0
        num_retries = 0;
    }

    // Release the lock on the shared log file
    pthread_mutex_unlock(&log_file_mutex);
}
