#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the ModemLogEntry structure to hold log data
typedef struct {
    time_t timestamp;
    int ue_id;
    char *log_level;
} ModemLogEntry;

// Create a list of ModemLogEntry structures to store log data
static List *log_list = NULL;

// Define the logging interface for the function
void modem_log(const char *format, ...) {
    // Get the current time
    struct tm now;
    time_t timestamp = time(NULL);
    localtime_r(&timestamp, &now);

    // Create a new ModemLogEntry structure
    ModemLogEntry *entry = malloc(sizeof(ModemLogEntry));
    entry->timestamp = timestamp;
    entry->ue_id = -1;
    entry->log_level = "INFO";

    // Format the log message using the given format string and arguments
    va_list args;
    va_start(args, format);
    vsnprintf(entry->message, sizeof(entry->message), format, args);
    va_end(args);

    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&log_list_mutex);

    // Add the new log entry to the end of the list
    if (log_list == NULL) {
        log_list = list_create();
    }
    list_add(log_list, entry);

    // Unlock the list and return
    pthread_mutex_unlock(&log_list_mutex);
}

// Function to initialize the logging system
void modem_logging_init() {
    log_list = list_create();
}

// Function to write the log data to a file in a thread-safe manner
void modem_logging_write(const char *filename) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&log_list_mutex);

    // Open the file for writing
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Iterate through the log entries and write them to the file
    ListNode *node = list_get_first(log_list);
    while (node != NULL) {
        ModemLogEntry *entry = node->data;
        fprintf(file, "%s %d %s\n", ctime(&entry->timestamp), entry->ue_id, entry->log_level);
        node = list_get_next(node);
    }

    // Close the file and unlock the list
    fclose(file);
    pthread_mutex_unlock(&log_list_mutex);
}

// Function to rotate the log file when it reaches a specified size threshold
void modem_logging_rotate(const char *filename, int size) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&log_list_mutex);

    // Open the current log file for reading and truncation
    FILE *file = fopen(filename, "r+");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Create a new log file with the same name as the original one, but with a timestamp appended to it
    char new_filename[256];
    strcpy(new_filename, filename);
    strcat(new_filename, "_");
    struct tm now;
    time_t timestamp = time(NULL);
    localtime_r(&timestamp, &now);
    sprintf(new_filename + strlen(new_filename), "%d%02d%02d_%02d%02d%02d", now.tm_year + 1900, now.tm_mon + 1, now.tm_mday, now.tm_hour, now.tm_min, now.tm_sec);
    FILE *new_file = fopen(new_filename, "a");
    if (new_file == NULL) {
        perror("fopen");
        return;
    }

    // Copy the contents of the original file to the new one, until it reaches the size threshold
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        fprintf(new_file, "%s", line);
        if (ftell(new_file) > size * 1024) {
            break;
        }
    }

    // Close both files and unlock the list
    fclose(file);
    fclose(new_file);
    pthread_mutex_unlock(&log_list_mutex);
}

// Function to handle log data efficiently, considering large volumes of log data
void modem_logging_handle_data() {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&log_list_mutex);

    // Create a new buffer to store the log entries
    char *buffer = malloc(sizeof(ModemLogEntry) * 1024);

    // Iterate through the log entries and write them to the buffer
    ListNode *node = list_get_first(log_list);
    int index = 0;
    while (node != NULL && index < sizeof(buffer)) {
        ModemLogEntry *entry = node->data;
        memcpy(buffer + index, entry, sizeof(ModemLogEntry));
        index += sizeof(ModemLogEntry);
        node = list_get_next(node);
    }

    // Unlock the list and return the buffer
    pthread_mutex_unlock(&log_list_mutex);
}
