int num_measurements = 0;

// Function to add a new measurement
void add_measurement(int measurement_id, int band, float frequency_range, char* channel_quality_indicator) {
    // Allocate memory for the new measurement
    Measurement* new_measurement = malloc(sizeof(Measurement));
    if (new_measurement == NULL) {
        printf("Error: Failed to allocate memory for a new measurement!\n");
        return;
    }

    // Initialize the new measurement
    new_measurement->measurement_id = measurement_id;
    new_measurement->band = band;
    new_measurement->frequency_range = frequency_range;
    new_measurement->channel_quality_indicator = strdup(channel_quality_indicator);

    // Add the new measurement to the list
    measurements = realloc(measurements, (num_measurements + 1) * sizeof(Measurement));
    if (measurements == NULL) {
        printf("Error: Failed to allocate memory for the updated measurements list!\n");
        return;
    }
    measurements[num_measurements++] = new_measurement;
}

// Function to remove a measurement by its ID
void remove_measurement(int measurement_id) {
    // Find the index of the measurement with the given ID
    int index = -1;
    for (int i = 0; i < num_measurements; i++) {
        if (measurements[i]->measurement_id == measurement_id) {
            index = i;
            break;
        }
    }

    // If the measurement was found, remove it from the list and free its memory
    if (index >= 0) {
        free(measurements[index]);
        measurements = realloc(measurements, (num_measurements - 1) * sizeof(Measurement));
        if (measurements == NULL) {
            printf("Error: Failed to allocate memory for the updated measurements list!\n");
            return;
        }
        num_measurements--;
    } else {
        printf("Error: Measurement with ID %d not found in the list!\n", measurement_id);
    }
}

// Function to update a measurement by its ID
void update_measurement(int measurement_id, int band, float frequency_range, char* channel_quality_indicator) {
    // Find the index of the measurement with the given ID
    int index = -1;
    for (int i = 0; i < num_measurements; i++) {
        if (measurements[i]->measurement_id == measurement_id) {
            index = i;
            break;
        }
    }

    // If the measurement was found, update its values
    if (index >= 0) {
        measurements[index]->band = band;
        measurements[index]->frequency_range = frequency_range;
        free(measurements[index]->channel_quality_indicator);
        measurements[index]->channel_quality_indicator = strdup(channel_quality_indicator);
    } else {
        printf("Error: Measurement with ID %d not found in the list!\n", measurement_id);
    }
}

// Function to print all measurements in the list
void print_measurements() {
    for (int i = 0; i < num_measurements; i++) {
        printf("Measurement %d: Band %d, Frequency Range %.2f, CQI %s\n",
               measurements[i]->measurement_id, measurements[i]->band,
               measurements[i]->frequency_range, measurements[i]->channel_quality_indicator);
