    // Check if the filename is valid and the format is supported
    assert(filename != NULL && strcmp(format, "xml") == 0 || strcmp(format, "json") == 0);

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (pdu_list == NULL) {
        printf("Error: Could not allocate memory for the list of structures\n");
        return -1;
    }

    // Initialize the structures with default values
    for (int i = 0; i < count; i++) {
        pdu_list[i].rx_ue_information.valid = false;
        pdu_list[i].crc_indication.crc_flag = false;
    }

    // Load the configuration from the file
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Could not open the configuration file\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Check if the line contains a valid configuration parameter
        int len = strlen(line);
        if (line[len-1] == '\n') line[--len] = 0;
        char *param = strtok(line, "=");
        if (param == NULL) continue;

        // Check if the parameter is a valid RX_UE_INFORMATION_TAG or CRC_INDICATION_REL8_TAG
        if (strcmp(param, "RX_UE_INFORMATION_TAG") == 0 || strcmp(param, "CRC_INDICATION_REL8_TAG") == 0) {
            // Read the value of the parameter from the file
            char *value = strtok(NULL, "=");
            if (value == NULL) continue;

            // Check if the value is a valid RNTI
            int rnti = atoi(value);
            if (rnti < 0 || rnti > 65535) {
                printf("Warning: Invalid RNTI value '%s' found in configuration file\n", value);
                continue;
            }

            // Set the corresponding parameter in the structure
            if (strcmp(param, "RX_UE_INFORMATION_TAG") == 0) {
                pdu_list[i].rx_ue_information.valid = true;
                pdu_list[i].rx_ue_information.rnti = rnti;
            } else if (strcmp(param, "CRC_INDICATION_REL8_TAG") == 0) {
                pdu_list[i].crc_indication.crc_flag = true;
            }
        }
    }

    fclose(file);
    return count;
}
