int add_entry(LTE_UESearchResults *entry) {
    // Allocate memory for the new entry
    LTE_UESearchResults *new_entry = malloc(sizeof(LTE_UESearchResults));
    if (new_entry == NULL) {
        return 1; // Error allocating memory
    }

