    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Add the new entry to the end of the array
    if (array == NULL) {
        array = malloc(sizeof(LTE_UESearchResults *) * 10);
        if (array == NULL) {
            free(new_entry);
            return 1; // Error allocating memory for the array
        }
    } else {
        LTE_UESearchResults **new_array = realloc(array, sizeof(LTE_UESearchResults *) * (num_entries + 1));
        if (new_array == NULL) {
            free(new_entry);
            return 1; // Error reallocating memory for the array
        }
        array = new_array;
    }

    array[num_entries++] = new_entry;

    // Unlock the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);

    return 0; // Success
}

// Function to update an existing entry in the dynamic array
int update_entry(uint32_t UE_ID, LTE_UESearchResults *new_info) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the index of the entry to be updated
    int i;
    for (i = 0; i < num_entries; i++) {
        if (array[i]->UE_ID == UE_ID) {
            break;
        }
    }

    // If the entry was not found, return an error
    if (i == num_entries) {
        pthread_mutex_unlock(&mutex);
        return 1; // Error: Entry not found
    }

    // Update the RACH and CELL_MEASUREMENTS fields of the entry
    memcpy(array[i]->rach_info, new_info->rach_info, sizeof(RACH_INFO));
    memcpy(array[i]->cell_measurements, new_info->cell_measurements, sizeof(CELL_MEASUREMENTS));

    // Unlock the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);

    return 0; // Success
}

// Function to remove an entry from the dynamic array
int remove_entry(uint32_t UE_ID) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the index of the entry to be removed
    int i;
    for (i = 0; i < num_entries; i++) {
        if (array[i]->UE_ID == UE_ID) {
            break;
        }
    }

    // If the entry was not found, return an error
    if (i == num_entries) {
        pthread_mutex_unlock(&mutex);
        return 1; // Error: Entry not found
    }

    // Remove the entry from the array by shifting all subsequent entries back one index
    for (int j = i; j < num_entries - 1; j++) {
        array[j] = array[j + 1];
    }

    num_entries--;

    // Reallocate memory for the reduced size of the array
    LTE_UESearchResults **new_array = realloc(array, sizeof(LTE_UESearchResults *) * (num_entries));
    if (new_array == NULL) {
        pthread_mutex_unlock(&mutex);
        return 1; // Error reallocating memory for the array
    }
    array = new_array;

    // Unlock the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);

    return 0; // Success
}
