#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Define struct for storing CRC indication data
typedef struct {
  unsigned int rx_ue_information_tag;
  unsigned int rnti;
  unsigned int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define function for reading configuration settings from XML file and creating list of structures
NFAPI_CRC_INDICATION_PDU_T* read_config(const char *xml_file, unsigned int count) {
  // Check if XML file exists
  FILE *fp = fopen(xml_file, "r");
  if (fp == NULL) {
    printf("Error: cannot open XML file '%s'\n", xml_file);
    return NULL;
  }

  // Initialize list of structures
  NFAPI_CRC_INDICATION_PDU_T *list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (list == NULL) {
    printf("Error: cannot allocate memory for structure list\n");
    fclose(fp);
    return NULL;
  }

  // Initialize XML parser and read configuration data from file
  xmlDocPtr doc = xmlReadFile(xml_file, NULL, 0);
  if (doc == NULL) {
    printf("Error: cannot parse XML file '%s'\n", xml_file);
    free(list);
    fclose(fp);
    return NULL;
  }

  // Loop through all RX UE information tags in the configuration data
  for (int i = 0; i < count; i++) {
    // Retrieve RX UE information tag from XML file
    xmlNodePtr node = xmlDocGetRootElement(doc);
    if (node == NULL) {
      printf("Error: cannot find root element in XML file '%s'\n", xml_file);
      free(list);
      fclose(fp);
      return NULL;
    }

    // Extract RX UE information tag and RNTI from XML node
    const char *rx_ue_info_tag = (const char *)xmlGetProp(node, "RX_UE_INFORMATION_TAG");
    const char *rnti = (const char *)xmlGetProp(node, "RNTI");

    // Check if RX UE information tag and RNTI are valid
    if (rx_ue_info_tag == NULL || rnti == NULL) {
      printf("Error: invalid RX UE information tag or RNTI in XML file '%s'\n", xml_file);
      free(list);
      fclose(fp);
      return NULL;
    }

    // Extract CRC indication REL8 tag from XML node
    const char *crc_indication_rel8_tag = (const char *)xmlGetProp(node, "CRC_INDICATION_REL8_TAG");

    // Check if CRC indication REL8 tag is valid
    if (crc_indication_rel8_tag == NULL) {
      printf("Error: invalid CRC indication REL8 tag in XML file '%s'\n", xml_file);
      free(list);
      fclose(fp);
      return NULL;
    }

    // Initialize structure for storing CRC indication data
    NFAPI_CRC_INDICATION_PDU_T *crc_indication = &list[i];

    // Set RX UE information tag, RNTI, and CRC indication REL8 tag in structure
    crc_indication->rx_ue_information_tag = atoi(rx_ue_info_tag);
    crc_indication->rnti = atoi(rnti);
    crc_indication->crc_indication_rel8_tag = atoi(crc_indication_rel8_tag);

    // Check if CRC indication REL8 tag is valid and set CRCFLAG randomly
    bool crcflag = rand() % 2;
    crc_indication->crc_indication_rel8_tag |= (crcflag << 1);

    // Log failure if CRC indication REL8 tag is invalid
    if (!crcflag) {
      printf("Error: invalid CRC indication REL8 tag in XML file '%s'\n", xml_file);
      free(list);
      fclose(fp);
      return NULL;
    }

    // Move to next XML node for retrieving RX UE information tag and RNTI
    node = node->next;
  }

  // Close XML file and return list of structures
  fclose(fp);
  return list;
}

// Define function for serializing list of structures back to XML file
int serialize_config(const char *xml_file, NFAPI_CRC_INDICATION_PDU_T *list) {
  // Check if XML file exists and if list is not NULL
  FILE *fp = fopen(xml_file, "w");
  if (fp == NULL || list == NULL) {
    printf("Error: cannot open or write to XML file '%s'\n", xml_file);
    return -1;
  }

  // Initialize XML writer and add root element
  xmlTextWriterPtr writer = xmlNewTextWriterFilename(xml_file, 0);
  if (writer == NULL) {
    printf("Error: cannot create XML writer for file '%s'\n", xml_file);
    fclose(fp);
    return -1;
  }

  // Loop through all structures in list and add RX UE information tag, RNTI, and CRC indication REL8 tag to XML file
  for (int i = 0; i < count; i++) {
    NFAPI_CRC_INDICATION_PDU_T *crc_indication = &list[i];

    // Add RX UE information tag, RNTI, and CRC indication REL8 tag to XML file
    xmlTextWriterWriteFormat(writer, "<RX_UE_INFORMATION_TAG>%d</RX_UE_INFORMATION_TAG>", crc_indication->rx_ue_information_tag);
    xmlTextWriterWriteFormat(writer, "<RNTI>%d</RNTI>", crc_indication->rnti);
    xmlTextWriterWriteFormat(writer, "<CRC_INDICATION_REL8_TAG>%d</CRC_INDICATION_REL8_TAG>", crc_indication->crc_indication_rel8_tag);
  }

  // Close XML writer and return success
  xmlFreeTextWriter(writer);
  fclose(fp);
  return 0;
}
