// UserAccount structure to store user account information
typedef struct UserAccount {
    char* username;
    char* email;
    time_t creation_timestamp;
    int status; // 0 for active, 1 for inactive
} UserAccount;

// Read and process user account information from a structured data source (e.g., CSV or binary file)
void read_and_process_user_accounts(const char* filename, size_t count, UserAccount** user_accounts) {
    // Check if the file exists
    if (access(filename, F_OK) == -1) {
        fprintf(stderr, "File not found: %s\n", filename);
        return;
    }

    // Open the file in read mode
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return;
    }

    // Allocate memory for the linked list of UserAccount structures
    *user_accounts = malloc(sizeof(UserAccount) * count);
    if (*user_accounts == NULL) {
        fprintf(stderr, "Failed to allocate memory for user accounts\n");
        return;
    }

    // Read and process each record in the file
    size_t i = 0;
    while (fscanf(file, "%ms,%*s,%*d,%*s", &(*user_accounts)[i].username) == 1 && i < count) {
        (*user_accounts)[i].status = 0; // Set default status to active

        // Read email and creation timestamp if available
        if (fscanf(file, ",%*s,%lld", &(*user_accounts)[i].creation_timestamp) == 1) {
            (*user_accounts)[i].email = NULL; // Set default email to null
        } else {
            fprintf(stderr, "Failed to read creation timestamp for user %s\n", (*user_accounts)[i].username);
        }

        i++;
    }

    // Close the file
    fclose(file);

    // Deduplicate accounts and handle malformed records
    deduplicate_accounts(*user_accounts, count);

    // Update linked list size to match actual number of user accounts
    *user_accounts = realloc(*user_accounts, sizeof(UserAccount) * i);
}

// Deduplicate accounts and handle malformed records
void deduplicate_accounts(UserAccount* user_accounts, size_t count) {
    // Build a map of username to email addresses for fast lookups
    char** usernames = malloc(sizeof(char*) * count);
    if (usernames == NULL) {
        fprintf(stderr, "Failed to allocate memory for usernames\n");
        return;
    }

    // Populate the map with unique usernames and their corresponding email addresses
    size_t i = 0;
    for (size_t j = 0; j < count; j++) {
        if (usernames[j] == NULL) {
            usernames[i++] = user_accounts[j].username;
        } else {
            // Handle duplicate usernames and malformed records by ignoring them
            fprintf(stderr, "Ignoring duplicate username %s or malformed record\n", user_accounts[j].username);
        }
    }

    // Update the linked list size to match actual number of unique usernames
    count = i;
    *user_accounts = realloc(*user_accounts, sizeof(UserAccount) * count);
}

// Configuration parsing mechanism that supports easy updates and extensions without requiring code changes
void parse_config(const char* config_file, struct Config** config) {
    // Open the configuration file in read mode
    FILE* file = fopen(config_file, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open configuration file: %s\n", config_file);
        return;
    }

    // Allocate memory for the Config structure
    *config = malloc(sizeof(struct Config));
    if (*config == NULL) {
        fprintf(stderr, "Failed to allocate memory for configuration\n");
        return;
    }

    // Read and parse each line in the file
    while (fscanf(file, "%ms", &(*config)->data_source) != EOF) {
        // Handle malformed records by ignoring them
        if ((*config)->data_source == NULL) {
            fprintf(stderr, "Ignoring malformed record\n");
        } else {
            break;
        }
    }

    // Close the file
    fclose(file);
}

// Robust date parsing mechanism that accurately interprets timestamps across various time zones and formats
void parse_date(const char* date_string, struct tm* result) {
    // Check if the date string is in a valid format
    if (strptime(date_string, "%Y-%m-%dT%H:%M:%SZ", result) == NULL) {
        fprintf(stderr, "Invalid date format: %s\n", date_string);
        return;
    }
}
