    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct linked_list {
    pthread_mutex_t lock; // mutex for concurrent access
    size_t size; // current number of elements in the list
    size_t capacity; // maximum number of elements that can be stored in the list
    NFAPI_CRC_INDICATION_PDU_T* data; // array of pointers to NFAPI_CRC_INDICATION_PDU_T structures
} linked_list;

void init_linked_list(linked_list* l) {
    assert(l != NULL);
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_ERRORCHECK);
    pthread_mutex_init(&l->lock, &attr);
    l->size = 0;
    l->capacity = 16;
    l->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * l->capacity);
    assert(l->data != NULL);
}

void free_linked_list(linked_list* l) {
    assert(l != NULL);
    pthread_mutex_destroy(&l->lock);
    free(l->data);
}

void insert_at_end(linked_list* l, NFAPI_CRC_INDICATION_PDU_T* p) {
    assert(l != NULL && p != NULL);
    pthread_mutex_lock(&l->lock);
    if (l->size == l->capacity) { // resize the array if necessary
        size_t new_capacity = 2 * l->capacity;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(l->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_data == NULL) {
            pthread_mutex_unlock(&l->lock);
            return;
        }
        l->data = new_data;
        l->capacity = new_capacity;
    }
    l->data[l->size] = *p;
    l->size++;
    pthread_mutex_unlock(&l->lock);
}

void insert_at_front(linked_list* l, NFAPI_CRC_INDICATION_PDU_T* p) {
    assert(l != NULL && p != NULL);
    pthread_mutex_lock(&l->lock);
    if (l->size == l->capacity) { // resize the array if necessary
        size_t new_capacity = 2 * l->capacity;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(l->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_data == NULL) {
            pthread_mutex_unlock(&l->lock);
            return;
        }
        l->data = new_data;
        l->capacity = new_capacity;
    }
    for (size_t i = l->size; i > 0; i--) {
        l->data[i] = l->data[i - 1];
    }
    l->data[0] = *p;
    l->size++;
    pthread_mutex_unlock(&l->lock);
}

void delete(linked_list* l, int rnti) {
    assert(l != NULL);
    bool found = false;
    size_t index = 0;
    pthread_mutex_lock(&l->lock);
    for (size_t i = 0; i < l->size; i++) {
        if (l->data[i].RNTI == rnti) {
            found = true;
            index = i;
            break;
        }
    }
    if (!found) { // element not found
        pthread_mutex_unlock(&l->lock);
        return;
    }
    for (size_t i = index; i < l->size - 1; i++) {
        l->data[i] = l->data[i + 1];
    }
    l->size--;
    pthread_mutex_unlock(&l->lock);
}
