  for (uint32_t i = 0; i < num_users; ++i) {
    // Allocate memory for the new object
    NFAPI_CRC_INDICATION_PDU_T *new_object = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_object == NULL) {
      // If allocation fails, free any previously allocated objects and return an error code
      for (uint32_t j = 0; j < list_size; ++j) {
        free(list[j]);
      }
      return -1;
    }

