      if (list == NULL) {
        free(new_object);
        return -1;
      }
    }
    list[list_size - 1] = new_object;

    // If the list size exceeds the maximum limit, remove objects from the front of the list to maintain a balanced distribution of CRCFLAG values
    if (list_size > max_list_size) {
      for (uint32_t j = 0; j < list_size - max_list_size; ++j) {
        free(list[j]);
        memmove(&list[j], &list[j + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (list_size - j));
      }
    }
  }

  // Return the list of NFAPI_CRC_INDICATION_PDU_T objects
  return list;
}
