// Define the function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *allocate_crc_indication_pdu(int num_elems) {
    // Lock the semaphore to prevent concurrent access to the memory pool
    if (sem_wait(&mem_pool_sem)) {
        printf("Error: Failed to acquire semaphore for allocating CRC indication PDUs\n");
        return NULL;
    }

    // Check if the requested number of elements is greater than the current size of the memory pool
    if (num_elems > mem_pool_size) {
        // Reallocate the memory pool to fit the new number of elements
        NFAPI_CRC_INDICATION_PDU_T *new_mem_pool = realloc(crc_indication_pdu_arr, num_elems * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_mem_pool) {
            // Failed to reallocate the memory pool due to insufficient memory
            printf("Error: Failed to allocate CRC indication PDUs (insufficient memory)\n");
            return NULL;
        }

        crc_indication_pdu_arr = new_mem_pool;
        mem_pool_size = num_elems * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // Initialize the newly allocated memory with random values
    for (int i = 0; i < num_elems; ++i) {
        crc_indication_pdu_arr[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        crc_indication_pdu_arr[i].rnti = rand();
        crc_indication_pdu_arr[i].crc_indication_rel8.crflag = rand() & 0x1;
    }

    // Unlock the semaphore to allow other threads to access the memory pool
    if (sem_post(&mem_pool_sem)) {
        printf("Error: Failed to release semaphore after allocating CRC indication PDUs\n");
    }

    return crc_indication_pdu_arr;
}

// Define the function to deallocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
void deallocate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *ptr) {
    // Lock the semaphore to prevent concurrent access to the memory pool
    if (sem_wait(&mem_pool_sem)) {
        printf("Error: Failed to acquire semaphore for deallocating CRC indication PDUs\n");
        return;
    }

    // Free the memory pool and set the pointer to NULL
    free(ptr);
    ptr = NULL;
    mem_pool_size = 0;

    // Unlock the semaphore to allow other threads to access the memory pool
    if (sem_post(&mem_pool_sem)) {
        printf("Error: Failed to release semaphore after deallocating CRC indication PDUs\n");
    }
}
