// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures for UE-specific CRC indication
NFAPI_CRC_INDICATION_PDU_T* alloc_crc_indication_pdu(int num_ues) {
    // Check for valid input
    if (num_ues <= 0) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indication_pdu) {
        LOG_ERROR("Failed to allocate memory for CRC indication PDU");
        return NULL;
    }

    // Initialize each structure in the array
    for (int i = 0; i < num_ues; i++) {
        NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = &crc_indication_pdu[i];
        memset(crc_indication_pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Validate the initialization of each structure
    for (int i = 0; i < num_ues; i++) {
        NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = &crc_indication_pdu[i];
        if (!validate_crc_indication_pdu(crc_indication_pdu)) {
            LOG_ERROR("Failed to validate CRC indication PDU");
            free(crc_indication_pdu);
            return NULL;
        }
    }

    // Handle potential overflow conditions
    if (num_ues > INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        LOG_ERROR("Too many UEs for CRC indication PDU array");
        free(crc_indication_pdu);
        return NULL;
    }

    // Integrate with external logging library to record allocation failures and initialization errors
    if (!LOG_SUCCESS) {
        LOG_ERROR("Failed to allocate or initialize CRC indication PDU");
        free(crc_indication_pdu);
        return NULL;
    }

    // Return the allocated and initialized array of structures
    return crc_indication_pdu;
}

// Function to validate each NFAPI_CRC_INDICATION_PDU_T structure in an array
bool validate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu) {
    // Check for valid input
    if (!crc_indication_pdu) {
        return false;
    }

    // Validate each field in the structure
    bool is_valid = true;
    is_valid &= validate_field(&crc_indication_pdu->rnti, sizeof(int), "RNTI");
    is_valid &= validate_field(&crc_indication_pdu->timing_advance, sizeof(int), "Timing advance");
    is_valid &= validate_field(&crc_indication_pdu->measured_frequency_offset, sizeof(int), "Measured frequency offset");
    return is_valid;
}

// Function to validate a single field in an NFAPI_CRC_INDICATION_PDU_T structure
bool validate_field(void* field, size_t field_size, const char* field_name) {
    // Check for valid input
    if (!field || !field_name) {
        return false;
    }

    // Validate the field value based on its type
    switch (field_size) {
        case sizeof(int): {
            int* int_field = field;
            if (*int_field < 0) {
                LOG_ERROR("Invalid %s: %d", field_name, *int_field);
                return false;
            }
            break;
        }
        default: {
            LOG_WARN("Unsupported field type for %s", field_name);
            break;
        }
    }

    // Return success if the validation passed
    return true;
}
