#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

// Structure to store PHY RX stats information
typedef struct {
    uint16_t tag; // PHY_RX_STATS_REL15_TAG
    uint8_t sfn; // SFN
    uint8_t srb_id; // SRB_ID
    int8_t rx_power; // RX_POWER
} NR_PHY_RX_STATS_PDU_T;

// Structure to store regression parameters and historical data
typedef struct {
    double a; // Slope of the regression line
    double b; // Intercept of the regression line
    uint8_t sfn; // SFN for which the regression was calculated
    int8_t rx_power; // RX_POWER value corresponding to the regression line
} NR_PHY_RX_STATS_REGESSION_PARAMS_T;

// Global variable to store the current regression parameters and historical data
NR_PHY_RX_STATS_REGESSION_PARAMS_T regression_params = {0};

// Function to fetch regression parameters and historical data from an external service
int fetch_regression_data(void) {
    int ret;

    // Connect to the external data service using a socket
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(struct sockaddr_in));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Change to the actual port number
    server_addr.sin_addr.s_addr = inet_addr("192.168.0.1"); // Change to the actual IP address

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        return -1;
    }

    ret = connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (ret < 0) {
        perror("connect failed");
        close(sock);
        return -1;
    }

    // Send a request to the external data service for the current regression parameters and historical data
    char *request = "GET /regression_data/current HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n";
    send(sock, request, strlen(request), 0);

    // Receive the response from the external data service
    char buffer[4096];
    memset(buffer, 0, sizeof(buffer));
    ret = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (ret <= 0) {
        perror("recv failed");
        close(sock);
        return -1;
    }

    // Parse the response and extract the regression parameters and historical data
    char *token = strtok(buffer, "\r\n");
    while (token != NULL && ret > 0) {
        if (strcmp(token, "a:") == 0) {
            token = strtok(NULL, ",");
            regression_params.a = atof(token);
        } else if (strcmp(token, "b:") == 0) {
            token = strtok(NULL, "\r\n");
            regression_params.b = atof(token);
        } else if (strcmp(token, "sfn:") == 0) {
            token = strtok(NULL, ",");
            regression_params.sfn = atoi(token);
        } else if (strcmp(token, "rx_power:") == 0) {
            token = strtok(NULL, "\r\n");
            regression_params.rx_power = atoi(token);
        }
        ret--;
    }

    // Close the socket and return success
    close(sock);
    return 0;
}

// Function to calculate RX_POWER based on a linear regression model using historical data
int calc_rx_power(NR_PHY_RX_STATS_PDU_T *pdu) {
    // Check if the regression parameters have been fetched from the external service
    if (regression_params.a == 0 || regression_params.b == 0) {
        fetch_regression_data();
    }

    // Calculate RX_POWER using the linear regression model
    pdu->rx_power = regression_params.a * (double)pdu->sfn + regression_params.b;

    return 0;
}

// Function to allocate memory for an array of NR_PHY_RX_STATS_PDU_T structures with a maximum size of MAX_NR_OF_ELEMENTS
void *allocate_memory(int max_nr_of_elements) {
    void *mem = NULL;

    // Allocate memory for the array of NR_PHY_RX_STATS_PDU_T structures
    mem = calloc(max_nr_of_elements, sizeof(NR_PHY_RX_STATS_PDU_T));
    if (mem == NULL) {
        perror("calloc failed");
        return NULL;
    }

    // Initialize the memory pool for managing memory allocations and deallocations
    struct mempool_t *mempool = create_mempool(MAX_NR_OF_ELEMENTS);
    if (mempool == NULL) {
        perror("create_mempool failed");
        free(mem);
        return NULL;
    }

    // Set the memory pool for managing memory allocations and deallocations
    memset_s(mem, sizeof(NR_PHY_RX_STATS_PDU_T) * max_nr_of_elements, 0);
    set_mempool(mem, mempool);

    return mem;
}

// Function to release memory for an array of NR_PHY_RX_STATS_PDU_T structures with a maximum size of MAX_NR_OF_ELEMENTS
void release_memory(void *mem) {
    // Check if the memory pool has been set
    if (get_mempool(mem) == NULL) {
        return;
    }

    // Release the memory pool for managing memory allocations and deallocations
    free(get_mempool(mem));

    // Free the memory allocated for the array of NR_PHY_RX_STATS_PDU_T structures
    free(mem);
}

// Function to create a mempool for managing memory allocations and deallocations
struct mempool_t *create_mempool(int max_nr_of_elements) {
    struct mempool_t *mempool = (struct mempool_t *)malloc(sizeof(struct mempool_t));
    if (mempool == NULL) {
        perror("malloc failed");
        return NULL;
    }

    // Initialize the mempool structure
    memset_s(mempool, sizeof(struct mempool_t), 0);

    // Allocate memory for the array of NR_PHY_RX_STATS_PDU_T structures
    mempool->mem = (void **)calloc(max_nr_of_elements, sizeof(NR_PHY_RX_STATS_PDU_T));
    if (mempool->mem == NULL) {
        perror("calloc failed");
        free(mempool);
        return NULL;
    }

    // Set the maximum number of elements in the mempool
    mempool->max_nr_of_elements = max_nr_of_elements;

    return mempool;
}

// Function to set the memory pool for managing memory allocations and deallocations
void set_mempool(void *mem, struct mempool_t *mempool) {
    // Check if the memory address is valid
    if (mem == NULL || mempool == NULL) {
        return;
    }

    // Set the memory pool for managing memory allocations and deallocations
    *((struct mempool_t **)mem) = mempool;
}

// Function to get the memory pool for managing memory allocations and deallocations
struct mempool_t *get_mempool(void *mem) {
    // Check if the memory address is valid
    if (mem == NULL) {
        return NULL;
    }

    // Get the memory pool for managing memory allocations and deallocations
    return *((struct mempool_t **)mem);
}

// Function to free a single element from the mempool
void free_element(void *mem, struct mempool_t *mempool, int index) {
    // Check if the memory address is valid and the memory pool has been set
    if (mem == NULL || mempool == NULL) {
        return;
    }

    // Free the memory allocated for the element
    free(mem);

    // Set the memory address to NULL in the mempool
    mempool->mem[index] = NULL;
}
