// Define the structure for storing frame information
typedef struct {
    LTE_RRC_CU下行NAS_TRANSPORT_TAG nas;
    UE_ID ue_id;
    LTF_DEMODULATION_RESULT_TAG *ltf;
} FrameInfo;

// Define the dynamic array for storing frame information
FrameInfo **frames;
int num_frames = 0;
pthread_mutex_t lock;

// Function to add a new entry to the dynamic array
void add_frame(LTE_RRC_CU下行NAS_TRANSPORT_TAG nas, UE_ID ue_id, LTF_DEMODULATION_RESULT_TAG *ltf) {
    pthread_mutex_lock(&lock);
    // Check if there is enough memory to allocate a new frame
    if (num_frames >= 1024) {
        // Reallocate the memory for the dynamic array if necessary
        frames = realloc(frames, sizeof(FrameInfo *) * (num_frames + 1));
    }
    // Initialize the new frame and add it to the dynamic array
    FrameInfo *frame = malloc(sizeof(FrameInfo));
    frame->nas = nas;
    frame->ue_id = ue_id;
    frame->ltf = ltf;
    frames[num_frames] = frame;
    num_frames++;
    pthread_mutex_unlock(&lock);
}

// Function to update an existing entry in the dynamic array
void update_frame(int index, LTE_RRC_CU下行NAS_TRANSPORT_TAG nas, UE_ID ue_id, LTF_DEMODULATION_RESULT_TAG *ltf) {
    pthread_mutex_lock(&lock);
    // Check if the index is valid
    if (index >= num_frames || index < 0) {
        return;
    }
    // Update the frame information
    frames[index]->nas = nas;
    frames[index]->ue_id = ue_id;
    frames[index]->ltf = ltf;
    pthread_mutex_unlock(&lock);
}

// Function to retrieve an entry from the dynamic array by index
FrameInfo *get_frame(int index) {
    pthread_mutex_lock(&lock);
    // Check if the index is valid
    if (index >= num_frames || index < 0) {
        return NULL;
    }
    FrameInfo *frame = frames[index];
    pthread_mutex_unlock(&lock);
    return frame;
}

// Function to deallocate memory for the dynamic array
void deallocate() {
    pthread_mutex_lock(&lock);
    // Loop through the dynamic array and free each frame
    for (int i = 0; i < num_frames; i++) {
        FrameInfo *frame = frames[i];
        if (frame->ltf) {
            free(frame->ltf);
        }
        free(frame);
    }
    // Free the memory for the dynamic array
    free(frames);
    num_frames = 0;
    pthread_mutex_unlock(&lock);
}
