    uint8_t crcflag;
    struct nfapi_crc_indication_node *next;
} nfapi_crc_indication_node_t;

// Define a linked list structure for storing NFAPI_CRC_INDICATION_PDU_T data
typedef struct nfapi_crc_indication_list {
    nfapi_crc_indication_node_t *head;
    nfapi_crc_indication_node_t *tail;
} nfapi_crc_indication_list_t;

// Define a mutex for protecting concurrent access to the linked list
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for a scalable linked list of NFAPI_CRC_INDICATION_PDU_T structures
nfapi_crc_indication_list_t* nfapi_crc_indication_alloc(size_t num_elements) {
    // Check if the number of elements is valid
    if (num_elements > 10000) {
        return NULL;
    }

    // Allocate memory for the linked list structure
    nfapi_crc_indication_list_t *list = malloc(sizeof(nfapi_crc_indication_list_t));
    if (!list) {
        return NULL;
    }

    // Initialize the linked list structure
    list->head = NULL;
    list->tail = NULL;

    // Allocate memory for each node and initialize its data
    nfapi_crc_indication_node_t *node = malloc(sizeof(nfapi_crc_indication_node_t));
    if (!node) {
        free(list);
        return NULL;
    }
    node->rx_ue_information_tag = 0;
    node->rnti = 0;
    node->crc_indication_rel8_tag = 0;
    node->crcflag = 0;
    node->next = NULL;

    // Insert the first node into the linked list
    list->head = node;
    list->tail = node;

    // Allocate memory for each subsequent node and insert it into the linked list
    for (size_t i = 1; i < num_elements; i++) {
        node = malloc(sizeof(nfapi_crc_indication_node_t));
        if (!node) {
            free(list->head);
            free(list);
            return NULL;
        }
        node->rx_ue_information_tag = 0;
        node->rnti = 0;
        node->crc_indication_rel8_tag = 0;
        node->crcflag = 0;
        node->next = NULL;
        list->tail->next = node;
        list->tail = node;
    }

    return list;
}

// Function to free all allocated memory when the linked list is no longer needed
void nfapi_crc_indication_free(nfapi_crc_indication_list_t *list) {
    // Check if the input parameter is valid
    if (!list) {
        return;
    }

    // Acquire the mutex for protecting concurrent access to the linked list
    pthread_mutex_lock(&mutex);

    // Free each node in the linked list and its data
    nfapi_crc_indication_node_t *current = list->head;
    while (current) {
        nfapi_crc_indication_node_t *next = current->next;
        free(current);
        current = next;
    }

    // Release the mutex for protecting concurrent access to the linked list
    pthread_mutex_unlock(&mutex);

    // Free the memory allocated for the linked list structure
    free(list);
}

// Function to insert a new node into the linked list in a thread-safe manner
void nfapi_crc_indication_insert(nfapi_crc_indication_list_t *list, uint16_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag, uint8_t crcflag) {
    // Check if the input parameter is valid
    if (!list) {
        return;
    }

    // Acquire the mutex for protecting concurrent access to the linked list
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new node and initialize its data
    nfapi_crc_indication_node_t *node = malloc(sizeof(nfapi_crc_indication_node_t));
    if (!node) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    node->rx_ue_information_tag = rx_ue_information_tag;
    node->rnti = rnti;
    node->crc_indication_rel8_tag = crc_indication_rel8_tag;
    node->crcflag = crcflag;
    node->next = NULL;

    // Insert the new node into the linked list
    list->tail->next = node;
    list->tail = node;

    // Release the mutex for protecting concurrent access to the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over the elements in the linked list in a thread-safe manner
void nfapi_crc_indication_iterate(nfapi_crc_indication_list_t *list, void (*callback)(uint16_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag, uint8_t crcflag)) {
    // Check if the input parameter is valid
    if (!list || !callback) {
        return;
    }

    // Acquire the mutex for protecting concurrent access to the linked list
    pthread_mutex_lock(&mutex);

    // Iterate over each node in the linked list and call the callback function on each node
    nfapi_crc_indication_node_t *current = list->head;
    while (current) {
        (*callback)(current->rx_ue_information_tag, current->rnti, current->crc_indication_rel8_tag, current->crcflag);
        current = current->next;
    }

    // Release the mutex for protecting concurrent access to the linked list
    pthread_mutex_unlock(&mutex);
}
