NFAPI_STATUS remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
  // Check if memory allocation failed
  if (pdu == NULL) {
    return NFAPI_MEMORY_ALLOCATION_ERROR;
  }

  // Remove CRC indication from array
  return NFAPI_SUCCESS;
}

NFAPI_STATUS validate_crc(NFAPI_CRC_INDICATION_PDU_T *pdu) {
  // Check if memory allocation failed
  if (pdu == NULL) {
    return NFAPI_MEMORY_ALLOCATION_ERROR;
  }

  // Calculate CRC checksum using a specified algorithm
  uint32_t crc = calculate_crc(pdu->tag, pdu->rnti);

  // Compare calculated CRC with stored value
  if (pdu->crc_tag.crflag != crc) {
    // Mark CRC indication as invalid and update status accordingly
    pdu->crc_tag.valid = false;
    return NFAPI_ERROR;
  } else {
    // Mark CRC indication as valid and update status accordingly
    pdu->crc_tag.valid = true;
    return NFAPI_SUCCESS;
  }
}

void log_invalid_crc(NFAPI_CRC_INDICATION_PDU_T *pdu) {
  // Check if memory allocation failed
