    return;
  }

  // Log the invalid CRC indication to a file or system log
  fprintf(stderr, "Invalid CRC indication: tag=%d, rnti=%d, crcflag=0x%08X\n", pdu->tag, pdu->rnti, pdu->crc_tag.crflag);
}

void compact_array(NFAPI_CRC_INDICATION_PDU_T *pdu) {
  // Check if memory allocation failed
  if (pdu == NULL) {
    return;
  }

  // Reorganize valid structures into a contiguous block of memory, preserving their order and minimizing fragmentation
  NFAPI_CRC_INDICATION_PDU_T *compacted = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * pdu->count);
  if (compacted == NULL) {
    return;
  }

  // Copy valid structures to compacted array
  int index = 0;
  for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU; i++) {
    if (pdu[i].crc_tag.valid) {
      memcpy(&compacted[index], &pdu[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
      index++;
    }
  }

  // Update array size and pointer
  pdu->count = index;
  pdu->data = compacted;
