        available_pdus[num_available_pdus] = NULL;
        pthread_mutex_unlock(&pdu_mutex);
        return pdu;
    } else {
        // Check if the maximum number of PDUs has been reached
        if (num_allocated_pdus >= MAX_NUM_PDUS) {
            pthread_mutex_unlock(&pdu_mutex);
            return NULL;
        }

        // Increment the total number of allocated PDUs
        num_allocated_pdus++;

        // Allocate memory for a new PDU and initialize it
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(SIZEOF_PDU);
        memset(pdu, 0, SIZEOF_PDU);

        // Unlock the mutex and return the allocated PDU
        pthread_mutex_unlock(&pdu_mutex);
        return pdu;
    }
}

// Function to deallocate memory for a single PDU
void deallocate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Lock the mutex to prevent concurrent access to the list of available PDUs
    pthread_mutex_lock(&pdu_mutex);

    // Check if there is space in the pool for this PDU
    if (num_available_pdus < MAX_NUM_PDUS) {
        // Increment the number of available PDUs and store the deallocated PDU at the end of the list
        num_available_pdus++;
        available_pdus[num_available_pdus - 1] = pdu;
    } else {
        // Decrement the total number of allocated PDUs
        num_allocated_pdus--;

        // Free the memory for this PDU
        free(pdu);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&pdu_mutex);
}

// Function to update the list of PDUs based on user-provided input N
void update_pdus(uint32_t N) {
    // Check if the provided value is within a reasonable range
    if (N < 1 || N > MAX_NUM_PDUS) {
