    // Lock the mutex to prevent concurrent access to the list of PDUs
    pthread_mutex_lock(&pdu_mutex);

    // Check if there are any available PDUs in the pool
    if (num_available_pdus > 0) {
        // Decrement the number of available PDUs and update the list of PDUs based on the provided value N
        num_available_pdus = MIN(num_available_pdus, N);
        for (uint32_t i = 0; i < num_available_pdus; i++) {
            available_pdus[i]->RX_UE_INFORMATION_TAG = rand();
            available_pdus[i]->RNTI = rand();
            available_pdus[i]->CRCFLAG = (rand() & 1) == 0 ? 0 : 1;
