class HtmlElementUpdater {
    private static final int MAX_CONTENT_LENGTH = 10000; // Maximum allowed content length (in characters)

    public void updateHtmlElement(String pageSectionId, String elementId, String newContent) throws ContentTruncatedException {
        if (newContent.length() > MAX_CONTENT_LENGTH) {
            throw new ContentTruncatedException("Content exceeds maximum allowed length of " + MAX_CONTENT_LENGTH + " characters");
        }

        // Update HTML content using a database connection pool
        try (Connection conn = getDbConnection()) {
            String sql = "UPDATE html_elements SET content=? WHERE page_section_id=? AND element_id=?";
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setString(1, newContent);
            stmt.setString(2, pageSectionId);
            stmt.setString(3, elementId);
            int rowsAffected = stmt.executeUpdate();
            if (rowsAffected == 0) {
                // No rows were updated, so throw an exception
                throw new RuntimeException("No HTML element found with ID " + elementId + " in page section " + pageSectionId);
            }
        } catch (SQLException e) {
            throw new RuntimeException("Error updating HTML element content", e);
        }
    }
}

// Exception for when the updated content exceeds the maximum allowed length
class ContentTruncatedException extends RuntimeException {
    public ContentTruncatedException(String message) {
        super(message);
    }
}

// Function to handle HTTP POST requests for updating HTML elements
public void updateHtmlElement(HttpServletRequest request, HttpServletResponse response) throws IOException {
    // Parse the request parameters
    String pageSectionId = request.getParameter("page_section_id");
    String elementId = request.getParameter("element_id");
    String newContent = request.getParameter("new_content");

    try {
        // Update the HTML element using the service class
        HtmlElementUpdater.updateHtmlElement(pageSectionId, elementId, newContent);
    } catch (ContentTruncatedException e) {
        // Handle exception by logging a warning message and returning an error response
        log.warn("Content exceeds maximum allowed length for HTML element " + elementId + " in page section " + pageSectionId);
        response.sendError(HttpServletResponse.SC_BAD_REQUEST, e.getMessage());
    } catch (RuntimeException e) {
        // Handle exception by logging an error message and returning an error response
        log.error("Error updating HTML element", e);
        response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Failed to update HTML element");
    }
}

// Integrate functionality into existing web framework
public class MyWebFramework {
    private HtmlElementUpdater htmlElementUpdater;

    public MyWebFramework() {
        this.htmlElementUpdater = new HtmlElementUpdater();
    }

    // Handle HTTP POST requests for updating HTML elements
    @PostMapping("/update-element")
    public void updateHtmlElement(HttpServletRequest request, HttpServletResponse response) throws IOException {
        htmlElementUpdater.updateHtmlElement(request, response);
    }
}']

