// C function to process floating-point numbers read from standard input
void process_floating_numbers(float *arr, int arr_size) {
  // Array to store valid entries
  float *valid_entries = (float *)malloc(sizeof(float) * arr_size);

  // Index for valid entries array
  int valid_index = 0;

  // Loop through each entry in the input array
  for (int i = 0; i < arr_size; i++) {
    float entry = arr[i];

    // Check if entry is valid (not NaN or infinite)
    if (!isnan(entry) && !isinf(entry)) {
      // If valid, add to the valid entries array
      valid_entries[valid_index++] = entry;
    }
  }

  // Calculate average of valid entries
  float average = calculate_average(valid_entries, valid_index);

  // Print average to standard output
  printf("Average: %f\n", average);

  // Free dynamically allocated memory for valid entries array
  free(valid_entries);
}

// Helper function to calculate the average of an array
float calculate_average(float *arr, int arr_size) {
  float sum = 0;

  // Calculate sum of all elements in the array
  for (int i = 0; i < arr_size; i++) {
    sum += arr[i];
  }

  // Return average of sum and array size
  return sum / arr_size;
}']

