// Source file: nfapi_crc_indication_list.c
#include "nfapi_crc_indication_list.h"

#include <stdlib.h>
#include <time.h>
#include <string.h>

void init_nfapi_crc_indication_list(NFAPI_CRC_INDICATION_T **list, uint16_t num_elements) {
    // Allocate memory for the list
    *list = (NFAPI_CRC_INDICATION_T *)malloc(sizeof(NFAPI_CRC_INDICATION_T) * num_elements);
    if (*list == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize each structure with a unique RNTI and a randomly set CRCFLAG within the specified range
    for (uint16_t i = 0; i < num_elements; i++) {
        (*list)[i].rx_ue_information_tag = i + 1; // Start at 1 to avoid conflict with reserved values
        (*list)[i].rnti = rand() % (UINT16_MAX - UINT16_C(2)) + UINT16_C(2); // Randomly set RNTI within the specified range
        (*list)[i].crc_indication_rel8_tag = rand() % UINT8_MAX; // Randomly set CRCFLAG within the specified range
    }
}

bool add_nfapi_crc_indication(NFAPI_CRC_INDICATION_T **list, uint16_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag) {
    // Check if the list is already full
    if (*list == NULL || (*list)[0].rx_ue_information_tag == 0) {
        return false;
    }

    // Find an empty slot in the list
    for (uint16_t i = 0; i < UINT16_MAX - 1; i++) {
        if ((*list)[i].rx_ue_information_tag == 0) {
            (*list)[i].rx_ue_information_tag = rx_ue_information_tag;
            (*list)[i].rnti = rnti;
            (*list)[i].crc_indication_rel8_tag = crc_indication_rel8_tag;
            return true;
        }
    }

    // If no empty slot is found, the list is already full
    return false;
}

bool remove_nfapi_crc_indication(NFAPI_CRC_INDICATION_T **list, uint16_t rx_ue_information_tag, uint16_t rnti) {
    // Check if the list is empty or if the specified RNTI does not exist in the list
    if (*list == NULL || (*list)[0].rx_ue_information_tag == 0) {
        return false;
    }

    // Find the specified RNTI in the list
    for (uint16_t i = 0; i < UINT16_MAX - 1; i++) {
        if ((*list)[i].rx_ue_information_tag == rx_ue_information_tag && (*list)[i].rnti == rnti) {
            // Found the specified RNTI, mark it as empty
            memset(&(*list)[i], 0, sizeof(NFAPI_CRC_INDICATION_T));
            return true;
        }
    }

    // If no matching RNTI is found, the list does not contain the specified RNTI
    return false;
}

void print_nfapi_crc_indication_list(NFAPI_CRC_INDICATION_T *list) {
    printf("NFAPI CRC Indication List: \n");
    if (list == NULL || list[0].rx_ue_information_tag == 0) {
        printf("The list is empty\n");
    } else {
        for (uint16_t i = 0; i < UINT16_MAX - 1; i++) {
            if (list[i].rx_ue_information_tag != 0) {
                printf("RX UE Information Tag: %d, RNTI: %d, CRCFLAG: %d\n", list[i].rx_ue_information_tag, list[i].rnti, list[i].crc_indication_rel8_tag);
            }
        }
    }
}

void destroy_nfapi_crc_indication_list(NFAPI_CRC_INDICATION_T **list) {
    if (*list != NULL) {
        free(*list);
        *list = NULL;
    }
}

// Main function for testing
int main() {
    // Initialize the list with 10,000 structures
    NFAPI_CRC_INDICATION_T *list = NULL;
    init_nfapi_crc_indication_list(&list);
    print_nfapi_crc_indication_list(list);

    // Add a new entry to the list
