#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define structure for LTE_EPC_UE_CONTEXT_T
typedef struct {
    char *guti;  // Globally Unique Temporary Identifier
    char *imsi;  // International Mobile Subscriber Identity
    int state;   // UE state (e.g., connected, disconnected)
} LTE_EPC_UE_CONTEXT_T;

// Define list of LTE_EPC_UE_CONTEXT_T structures
typedef struct {
    LTE_EPC_UE_CONTEXT_T *ue_contexts;  // List of UE contexts
    size_t count;                       // Number of UE contexts in list
    size_t capacity;                   // Capacity of list (number of slots)
} UE_CONTEXT_LIST_T;

// Initialize list with given seed and capacity
void init_ue_context_list(UE_CONTEXT_LIST_T *list, int seed, size_t capacity) {
    // Allocate memory for UE contexts in list
    list->ue_contexts = (LTE_EPC_UE_CONTEXT_T *)malloc(sizeof(LTE_EPC_UE_CONTEXT_T) * capacity);
    assert(list->ue_contexts != NULL);

    // Initialize UE contexts in list
    for (size_t i = 0; i < capacity; ++i) {
        list->ue_contexts[i].guti = generate_unique_guti(seed, i);
        list->ue_contexts[i].imsi = generate_unique_imsi(seed, i);
        list->ue_contexts[i].state = UE_STATE_INIT;
    }

    // Set list properties
    list->count = 0;
    list->capacity = capacity;
}

// Generate unique GUTI based on seed and index
char *generate_unique_guti(int seed, size_t index) {
    char guti[12];  // Globally Unique Temporary Identifier (e.g., IMSIxxxxxxxxx)
    sprintf(guti, "IMSI%09d", seed + index);
    return strdup(guti);
}

// Generate unique IMSI based on seed and index
char *generate_unique_imsi(int seed, size_t index) {
    char imsi[14];  // International Mobile Subscriber Identity (e.g., 123456789012345)
    sprintf(imsi, "%013d", seed + index);
    return strdup(imsi);
}

// Add new UE context to list
void add_ue_context(UE_CONTEXT_LIST_T *list, LTE_EPC_UE_CONTEXT_T *ue) {
    // Check if list is full
    if (list->count == list->capacity) {
        // Reallocate memory for UE contexts in list
        list->ue_contexts = realloc(list->ue_contexts, 2 * list->capacity);
        assert(list->ue_contexts != NULL);

        // Update capacity of list
        list->capacity *= 2;
    }

    // Add new UE context to list
    list->ue_contexts[list->count++] = *ue;
}

// Remove UE context from list by index
void remove_ue_context(UE_CONTEXT_LIST_T *list, size_t index) {
    // Check if index is valid
    if (index >= list->count) return;

    // Shift elements after index to fill gap
    for (size_t i = index + 1; i < list->count; ++i) {
        list->ue_contexts[i - 1] = list->ue_contexts[i];
    }

    // Decrement count of UE contexts in list
    --list->count;
}

// Update UE context state by index
void update_ue_state(UE_CONTEXT_LIST_T *list, size_t index, int state) {
    // Check if index is valid
    if (index >= list->count) return;

    // Set new state for UE context at index
    list->ue_contexts[index].state = state;
}

// Release memory allocated for UE contexts in list
void release_ue_context_list(UE_CONTEXT_LIST_T *list) {
    free(list->ue_contexts);
}
