int manage_crc_indication_pdu_list(char *hostname, int port, char *interface, NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    // DNS resolution variables
    struct addrinfo hints, *res;
    int err = 0;

    // rate limiting variable
    static int64_t last_request_time = 0;
    int64_t current_time = get_current_time();

    if (current_time - last_request_time < DSCP_RATE_LIMIT) { // rate limiting
        return -1;
    } else {
        last_request_time = current_time;
    }

    // initialize PDU list and DNS resolution variables
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_PDU, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_flags = AI_PASSIVE;

    // perform DNS resolution for hostname
    err = getaddrinfo(hostname, NULL, &hints, &res);
    if (err != 0) {
        printf("DNS resolution failed: %s\n", gai_strerror(err));
        return -1;
    }

    // create socket and connect to host
    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (connect(sock, res->ai_addr, res->ai_addrlen) == -1) {
        printf("Socket connection failed: %s\n", strerror(errno));
        return -1;
    }

    // send message to host and receive response
    char buffer[4096];
    ssize_t bytes_received = recvfrom(sock, buffer, 4096, 0, res->ai_addr, &res->ai_addrlen);
    if (bytes_received == -1) {
        printf("Socket receive failed: %s\n", strerror(errno));
        return -1;
    }

    // parse response message and populate PDU list
    int i = 0;
    while (i < MAX_PDU && bytes_received > 0) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*pdu_list)[i];
        pdu->valid = true;
        // extract RNTI and CRC_INDICATION_REL8 from response message
        pdu->rnti = 0x1234; // example value
        memcpy(pdu->crc_indication_rel8, buffer + i * 6, 6);
        // set CRCFLAG based on input parameters
        if (some_condition) {
            pdu->crcflag = true;
        } else {
            pdu->crcflag = false;
        }
        bytes_received -= 6;
        i++;
    }

    // free DNS resolution resources
    freeaddrinfo(res);

    // return populated PDU list and IP address
    u_char ip[4];
    res->ai_addr->sa_family = AF_INET;
    memcpy(ip, &((struct sockaddr_in *)res->ai_addr)->sin_addr.s_addr, 4);
    return i;
}
