void logError(const char* file, const int line, const char* message);
void logInfo(const char* file, const int line, const char* message);

// Function definitions
void* allocateMemory(size_t size) {
    // Memory pool implementation using a fixed-size array
    static uint8_t memoryPool[1024 * 1024]; // 1 MB pool
    static int nextFreeIndex = 0;

    if (nextFreeIndex + size <= sizeof(memoryPool)) {
        void* ptr = &memoryPool[nextFreeIndex];
        nextFreeIndex += size;
        return ptr;
    } else {
        logError(__FILE__, __LINE__, "Memory allocation failed");
        return NULL;
    }
}

void deallocateMemory(void* ptr, size_t size) {
    // Memory pool implementation using a fixed-size array
    static uint8_t memoryPool[1024 * 1024]; // 1 MB pool

    if (ptr && nextFreeIndex - size >= 0) {
        memcpy(&memoryPool[nextFreeIndex], ptr, size);
        nextFreeIndex -= size;
    } else {
        logError(__FILE__, __LINE__, "Memory deallocation failed");
    }
}

NFAPI_CRC_INDICATION_PDU_T* createPDU(uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
