        logError(__FILE__, __LINE__, "Failed to allocate memory for PDU");
        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRCFLAG = generateRandomCRC();

    return pdu;
}

int generateRandomCRC(void) {
    // Random number generation using a fixed seed for reproducibility
    const uint32_t SEED = 1234567890;
    static bool isSeeded = false;

    if (!isSeeded) {
        srand(SEED);
        isSeeded = true;
    }

    return rand() % 2; // Return 1 or 0 randomly
}

