} HashTable;

// Initialize the hash table with an empty linked list
HashTable* init_hash_table() {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->size = 10000; // maximum size of the hash table
    ht->count = 0; // number of nodes in the linked list
    ht->buckets = calloc(ht->size, sizeof(Node*));
    return ht;
}

// Insert a new structure into the linked list and the hash table
void insert_node(HashTable* ht, NFAPI_CRC_INDICATION_PDU_T data) {
    // Generate a random RNTI value if not provided
    if (data.RNTI == 0) {
        data.RNTI = rand() % 10000;
    }

    // Check if the RNTI already exists in the hash table
    int index = ht->size * (data.RNTI % 10000);
    Node* node = ht->buckets[index];
    while (node != NULL && node->data.RNTI == data.RNTI) {
        node = node->next;
    }

    // If the RNTI is new, insert a new node into the linked list and hash table
    if (node == NULL) {
        Node* new_node = malloc(sizeof(Node));
        new_node->data = data;
        new_node->next = ht->buckets[index];
        ht->buckets[index] = new_node;
        ht->count++;
    } else { // If the RNTI already exists, update the node in the linked list and hash table
        Node* current = node;
        while (current != NULL && current->next != NULL) {
            if (current->next->data.RNTI == data.RNTI) {
                current->next->data = data;
                break;
            }
            current = current->next;
        }
    }
}

// Delete a structure from the linked list and hash table
void delete_node(HashTable* ht, int RNTI) {
    // Check if the RNTI exists in the hash table
    int index = ht->size * (RNTI % 10000);
    Node* node = ht->buckets[index];
    while (node != NULL && node->data.RNTI == RNTI) {
        if (node->next != NULL && node->next->data.RNTI == RNTI) {
            // If the RNTI is found, delete the node from the linked list and hash table
            Node* tmp = node->next;
            node->next = node->next->next;
            free(tmp);
            ht->count--;
        } else {
            // If the RNTI is not found, break the loop
            break;
        }
    }
}

// Update a structure in the linked list and hash table
void update_node(HashTable* ht, int RNTI, NFAPI_CRC_INDICATION_PDU_T data) {
    // Check if the RNTI exists in the hash table
    int index = ht->size * (RNTI % 10000);
    Node* node = ht->buckets[index];
    while (node != NULL && node->data.RNTI == RNTI) {
        if (node->next != NULL && node->next->data.RNTI == RNTI) {
            // If the RNTI is found, update the node in the linked list and hash table
            Node* current = node;
            while (current != NULL && current->next != NULL) {
                if (current->next->data.RNTI == RNTI) {
                    current->next->data = data;
                    break;
                }
                current = current->next;
            }
        } else {
            // If the RNTI is not found, insert a new node into the linked list and hash table
            insert_node(ht, data);
        }
    }
}

// Search for a structure in the linked list and hash table
NFAPI_CRC_INDICATION_PDU_T* search_node(HashTable* ht, int RNTI) {
    // Check if the RNTI exists in the hash table
    int index = ht->size * (RNTI % 10000);
    Node* node = ht->buckets[index];
    while (node != NULL && node->data.RNTI == RNTI) {
        return &(node->data);
    }
    return NULL;
}

// Free the memory allocated to the hash table and linked list
void free_hash_table(HashTable* ht) {
    for (int i = 0; i < ht->size; i++) {
        Node* current = ht->buckets[i];
        while (current != NULL) {
            Node* tmp = current;
            current = current->next;
            free(tmp);
        }
    }
    free(ht->buckets);
    free(ht);
}
