<?php

function authenticateUser($username, $password) {
    // Initialize the Guzzle HTTP client
    $client = new GuzzleHttp\Client();

    // Set the URL for the OAuth 2.0 authorization endpoint
    $url = 'https://oauth2.example.com/authorize';

    // Set the headers for the POST request to the authorization endpoint
    $headers = [
        'Content-Type' => 'application/x-www-form-urlencoded',
    ];

    // Set the form data for the POST request to the authorization endpoint
    $formData = [
        'grant_type' => 'password',
        'username' => $username,
        'password' => $password,
    ];

    // Make a POST request to the authorization endpoint with the form data
    $response = $client->post($url, ['headers' => $headers, 'form_params' => $formData]);

    // Check if the response is successful
    if ($response->getStatusCode() != 200) {
        throw new Exception('Failed to authenticate user');
    }

    // Extract the access token from the response body
    $body = json_decode($response->getBody());
    $accessToken = $body->access_token;

    // Set the session variable for the access token
    $_SESSION['accessToken'] = $accessToken;
}

