static pthread_mutex_t crc_indication_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage the list of CRC indications
NFAPI_CRC_INDICATION_LIST *crc_indication_list = NULL;

void add_crc_indication(RX_UE_INFORMATION_TAG rx_ue_information, RNTI crc_indication_rel8_tag, CRCFLAG crcflag) {
    // Lock the mutex to prevent concurrent access to the data structures
    pthread_mutex_lock(&crc_indication_mutex);

    // Create a new structure to store the CRC indication information
    NFAPI_CRC_INDICATION_PDU *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_entry) {
        pthread_mutex_unlock(&crc_indication_mutex);
        return;
    }

    // Initialize the structure with the given information
    new_entry->rx_ue_information = rx_ue_information;
    new_entry->crc_indication_rel8_tag = crc_indication_rel8_tag;
    new_entry->crcflag = crcflag;

    // Check if the list is empty
    if (!crc_indication_list) {
        // Initialize the list and add the new entry
        crc_indication_list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
        if (!crc_indication_list) {
            pthread_mutex_unlock(&crc_indication_mutex);
            return;
        }

        crc_indication_list->head = new_entry;
        crc_indication_list->tail = new_entry;
    } else {
        // Add the new entry to the end of the list
        NFAPI_CRC_INDICATION_PDU *current_entry = crc_indication_list->tail;
        while (current_entry) {
            if (current_entry->crc_indication_rel8_tag == new_entry->crc_indication_rel8_tag) {
                // If the list already contains an entry with the same RNTI, skip it
                pthread_mutex_unlock(&crc_indication_mutex);
                return;
            }

            if (!current_entry->next) {
                break;
            }

            current_entry = current_entry->next;
        }

        // Add the new entry to the end of the list
        current_entry->next = new_entry;
        crc_indication_list->tail = new_entry;
    }

    pthread_mutex_unlock(&crc_indication_mutex);
}

void delete_crc_indication(RNTI crc_indication_rel8_tag) {
    // Lock the mutex to prevent concurrent access to the data structures
    pthread_mutex_lock(&crc_indication_mutex);

    // Find the entry with the given RNTI in the list
    NFAPI_CRC_INDICATION_PDU *current_entry = crc_indication_list->head;
    while (current_entry) {
        if (current_entry->crc_indication_rel8_tag == crc_indication_rel8_tag) {
            // If the entry is found, delete it from the list
            NFAPI_CRC_INDICATION_PDU *previous_entry = current_entry->previous;
            if (previous_entry) {
                previous_entry->next = current_entry->next;
            } else {
                crc_indication_list->head = current_entry->next;
            }

            // Free the memory allocated for the entry
            free(current_entry);

            pthread_mutex_unlock(&crc_indication_mutex);
            return;
        }

        if (!current_entry->next) {
            break;
        }

        current_entry = current_entry->next;
    }

    pthread_mutex_unlock(&crc_indication_mutex);
}

void clear_crc_indications() {
    // Lock the mutex to prevent concurrent access to the data structures
    pthread_mutex_lock(&crc_indication_mutex);

    // Free the memory allocated for the list and set it to NULL
    NFAPI_CRC_INDICATION_PDU *current_entry = crc_indication_list->head;
    while (current_entry) {
        free(current_entry);

        current_entry = current_entry->next;
    }

    free(crc_indication_list);
    crc_indication_list = NULL;

    pthread_mutex_unlock(&crc_indication_mutex);
}

