NFAPI_CRC_INDICATION_PDU_T* createAndPopulateNFAPDUList(char* resourceBundleFilePath) {
    // Open the resource bundle file for reading
    int fd = open(resourceBundleFilePath, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open resource bundle file");
        return NULL;
    }

    // Read the number of items in the bundle from the first line
    int numItems = readLine(fd, BUNDLE_FILE_NAME);
    if (numItems < 0) {
        close(fd);
        return NULL;
    }

    // Dynamically allocate memory for the list and its items
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numItems);
    if (!pduList) {
        perror("Failed to allocate memory for PDU list");
        close(fd);
        return NULL;
    }

    // Loop through each item in the bundle and parse its data
    for (int i = 0; i < numItems; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pduList[i];
        char line[128];

        // Read the RX_UE_INFORMATION_TAG from the file
        if (readLine(fd, BUNDLE_FILE_NAME, line) < 0) {
            free(pduList);
            close(fd);
            return NULL;
        }
        pdu->rxUeInformationTag = atoi(line);

        // Read the RNTI from the file
        if (readLine(fd, BUNDLE_FILE_NAME, line) < 0) {
            free(pduList);
            close(fd);
            return NULL;
        }
        pdu->rnti = atoi(line);

        // Read the CRC_INDICATION_REL8_TAG from the file
        if (readLine(fd, BUNDLE_FILE_NAME, line) < 0) {
            free(pduList);
            close(fd);
            return NULL;
        }
        pdu->crcIndicationRel8Tag = atoi(line);

        // Generate a random value for the CRCFLAG
        pdu->crcFlag = rand() % 2;
    }

    close(fd);
    return pduList;
}

// Reads a line from a file and stores it in the provided buffer
int readLine(int fd, char* fileName, char* buffer) {
    int bytesRead = read(fd, buffer, 128);
    if (bytesRead < 0) {
        perror("Failed to read line from resource bundle file");
        return -1;
    } else if (bytesRead == 0) {
        fprintf(stderr, "Unexpected end of file for resource bundle '%s'\n", fileName);
        return -2;
    }
    buffer[bytesRead] = '\0';
    return bytesRead;
}
