typedef struct NFAPI_L2_PDU_T {
    L2_PDU_TYPE type;
    L2_HEADER header;
    BYTE payload[MAX_PAYLOAD_SIZE];
} NFAPI_L2_PDU_T;

// Dynamically allocated array of L2 PDUs
NFAPI_L2_PDU_T* pdus = NULL;
size_t total_elements = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addElement(NFAPI_L2_PDU_T* pdu) {
    // Acquire lock on mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if memory has been allocated for the array
    if (pdus == NULL) {
        // Allocate memory for the array
        pdus = malloc(sizeof(NFAPI_L2_PDU_T) * INITIAL_ELEMENTS);
        total_elements = INITIAL_ELEMENTS;
    }

    // Check if there is space in the array to add a new element
    if (total_elements >= pdus->size()) {
        // Reallocate memory for the array with doubled size
        NFAPI_L2_PDU_T* new_pdus = realloc(pdus, sizeof(NFAPI_L2_PDU_T) * total_elements * 2);
        if (new_pdus == NULL) {
            // Memory allocation failed, handle error
        } else {
            pdus = new_pdus;
            total_elements *= 2;
        }
    }

    // Add the new element to the array
    pdus[total_elements++] = *pdu;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

void removeElement(size_t index) {
    // Acquire lock on mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the array is empty or the index is out of bounds
    if (total_elements == 0 || index >= total_elements) {
        // Release lock on mutex and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Shift elements to the left over the deleted element
    for (size_t i = index + 1; i < total_elements; i++) {
        pdus[i - 1] = pdus[i];
    }

    // Decrement the number of elements in the array
    total_elements--;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

NFAPI_L2_PDU_T* getElement(size_t index) {
    // Acquire lock on mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the array is empty or the index is out of bounds
    if (total_elements == 0 || index >= total_elements) {
        // Release lock on mutex and return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    NFAPI_L2_PDU_T* element = &pdus[index];

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);

    return element;
}
