#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include "nfapi_interface.h"

typedef struct nfapi_crc_indication_pdu_s {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t cf[4];
} nfapi_crc_indication_pdu_t;

typedef struct nfapi_crc_indication_node_s {
    nfapi_crc_indication_pdu_t *data;
    struct nfapi_crc_indication_node_s *next;
} nfapi_crc_indication_node_t;

nfapi_crc_indication_node_t* construct_crc_indication_list(int n) {
    // dynamically allocate memory for the linked list
    nfapi_crc_indication_node_t *head = malloc(sizeof(nfapi_crc_indication_node_t));
    if (!head) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return NULL;
    }
    head->data = malloc(sizeof(nfapi_crc_indication_pdu_t));
    if (!head->data) {
        printf("Error: Failed to allocate memory for CRC indication PDU\n");
        free(head);
        return NULL;
    }
    head->next = NULL;

    // initialize the first node
    nfapi_crc_indication_pdu_t *data = head->data;
    data->rx_ue_information_tag = rand() % 100000;
    data->rnti = rand() % 65536;
    data->crc_indication_rel8_tag = rand() % 256;
    for (int i = 0; i < 4; i++) {
        data->cf[i] = rand() % 256;
    }

    // construct the remaining nodes
    nfapi_crc_indication_node_t *current = head;
    for (int i = 1; i < n; i++) {
        current->next = malloc(sizeof(nfapi_crc_indication_node_t));
        if (!current->next) {
            printf("Error: Failed to allocate memory for CRC indication node\n");
            free_crc_indication_list(head);
            return NULL;
        }
        current = current->next;
        current->data = malloc(sizeof(nfapi_crc_indication_pdu_t));
        if (!current->data) {
            printf("Error: Failed to allocate memory for CRC indication PDU\n");
            free_crc_indication_list(head);
            return NULL;
        }
        current->next = NULL;
        data = current->data;
        data->rx_ue_information_tag = rand() % 100000;
        data->rnti = rand() % 65536;
        data->crc_indication_rel8_tag = rand() % 256;
        for (int j = 0; j < 4; j++) {
            data->cf[j] = rand() % 256;
        }
    }

    return head;
}

void free_crc_indication_list(nfapi_crc_indication_node_t *head) {
    nfapi_crc_indication_node_t *current = head;
    while (current != NULL) {
        nfapi_crc_indication_node_t *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}
