void populateList(struct NFAPI_CRC_INDICATION_PDU_T **list, size_t *size) {
    // Create a semaphore to manage concurrent access to the list
    sem_t *sem = sem_open("list_sem", O_CREAT | O_EXCL, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(EXIT_FAILURE);
    }

    // Initialize the list with a size of zero
    *list = NULL;
    *size = 0;

    while (true) {
        // Acquire the semaphore before accessing the list
        if (sem_wait(sem)) {
            perror("Failed to acquire semaphore");
            exit(EXIT_FAILURE);
        }

        // Generate a random integer within the valid range
        int rx_ue_information = rand() % 2000 - 1000;
        int rnti = rand() % 2000 - 1000;
        int crc_indication_rel8_tag = rand() % 2000 - 1000;
        bool crcflag = (rand() % 2) == 0 ? true : false;

        // Validate the integer to fall within the valid range
        if (rx_ue_information >= -1000 && rx_ue_information <= 1000 &&
            rnti >= -1000 && rnti <= 1000 &&
            crc_indication_rel8_tag >= -1000 && crc_indication_rel8_tag <= 1000) {
            // Allocate memory for the new structure
            struct NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
            if (new_element == NULL) {
                perror("Failed to allocate memory for new element");
                exit(EXIT_FAILURE);
            }

            // Initialize the structure with the generated values
            new_element->RX_UE_INFORMATION_TAG = rx_ue_information;
            new_element->RNTI = rnti;
            new_element->CRC_INDICATION_REL8_TAG = crc_indication_rel8_tag;
            new_element->CRCFLAG = crcflag;

            // Add the new structure to the list
            *list = realloc(*list, (*size + 1) * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
            if (*list == NULL) {
                perror("Failed to allocate memory for list");
                exit(EXIT_FAILURE);
            }
            (*list)[*size] = new_element;
            *size += 1;
        }

        // Release the semaphore after accessing the list
        if (sem_post(sem)) {
            perror("Failed to release semaphore");
            exit(EXIT_FAILURE);
        }
    }
}

void printLargestInteger(struct NFAPI_CRC_INDICATION_PDU_T **list, size_t *size) {
    // Create a semaphore to manage concurrent access to the list
    sem_t *sem = sem_open("list_sem", O_CREAT | O_EXCL, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(EXIT_FAILURE);
    }

    // Initialize the largest integer to a minimum value
    int largest = -2000;

    while (true) {
        // Acquire the semaphore before accessing the list
        if (sem_wait(sem)) {
            perror("Failed to acquire semaphore");
            exit(EXIT_FAILURE);
        }

        // Loop through each element in the list
        for (size_t i = 0; i < *size; i++) {
            struct NFAPI_CRC_INDICATION_PDU_T *element = (*list)[i];

            // Compare the current element to the largest integer found so far
            if (element->RX_UE_INFORMATION_TAG > largest) {
                largest = element->RX_UE_INFORMATION_TAG;
            }
        }

        // Release the semaphore after accessing the list
        if (sem_post(sem)) {
            perror("Failed to release semaphore");
            exit(EXIT_FAILURE);
        }
    }
}
