    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CACHE {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu;
    size_t capacity;
    size_t count;
} CACHE;

// Function to add new elements to the cache
void cache_add(CACHE *cache, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->count == cache->capacity) {
        // Cache is full, increase capacity by 50%
        cache->capacity += cache->capacity / 2;
        cache->crc_indication_pdu = realloc(cache->crc_indication_pdu, cache->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    // Add new element to the end of the list
    cache->crc_indication_pdu[cache->count++] = *crc_indication_pdu;
    pthread_mutex_unlock(&cache->mutex);
}

// Function to remove elements from the cache
void cache_remove(CACHE *cache, size_t index) {
    if (index < cache->count && index >= 0) {
        pthread_mutex_lock(&cache->mutex);
        memmove(&cache->crc_indication_pdu[index], &cache->crc_indication_pdu[index + 1], (cache->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        cache->count--;
        pthread_mutex_unlock(&cache->mutex);
    }
}

// Function to retrieve elements from the cache by index
NFAPI_CRC_INDICATION_PDU_T *cache_get(CACHE *cache, size_t index) {
    if (index < cache->count && index >= 0) {
        return &cache->crc_indication_pdu[index];
    } else {
        return NULL;
    }
}

// Function to update the cache with new data from an external source
void cache_update(CACHE *cache, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    pthread_mutex_lock(&cache->mutex);
    size_t index = 0;
    while (index < cache->count && crc_indication_pdu->RX_UE_INFORMATION_TAG != cache->crc_indication_pdu[index].RX_UE_INFORMATION_TAG) {
        index++;
    }
    if (index == cache->count) {
        // New element, add it to the end of the list
        cache_add(cache, crc_indication_pdu);
    } else {
        // Update existing element
        memcpy(&cache->crc_indication_pdu[index], crc_indication_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Function to handle edge cases gracefully
bool cache_handle_edge_cases(CACHE *cache, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    if (crc_indication_pdu->RX_UE_INFORMATION_TAG > cache->capacity || crc_indication_pdu->RNTI > cache->capacity) {
        return false;
    } else if (crc_indication_pdu->RX_UE_INFORMATION_TAG < 0 || crc_indication_pdu->RNTI < 0) {
        return false;
    } else {
        return true;
    }
}

// Function to synchronize access from multiple threads
void cache_synchronize(CACHE *cache, pthread_mutex_t mutex) {
    pthread_mutex_lock(&mutex);
    pthread_mutex_unlock(&mutex);
}

// Function to evaluate trade-offs between memory overhead and cache efficiency
void cache_trade_off(CACHE *cache, size_t capacity) {
    if (capacity > 0 && capacity <= cache->capacity) {
        cache->capacity = capacity;
        cache->crc_indication_pdu = realloc(cache->crc_indication_pdu, cache->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
