            exit(EXIT_FAILURE);
        }
        strcpy(data->PDCP_SDU, "MOCK_SDU");

        // Add each entry to linked list
        if (head == NULL) {
            head = current = malloc(sizeof(node));
        } else {
            current->next = malloc(sizeof(node));
            current = current->next;
        }
        current->data = *data;
    }

    // Log initialization status for debugging purposes
    printf("[DEBUG] Initialized and populated PDCP list with %d entries\n", num_entries);
}

// Function to handle memory allocation failure gracefully
