#define CHUNK_SIZE 1024 * 1024 // 1 MB

// Define a struct to hold the data for each entry in the list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    bool valid;
} Entry;

// Function to read and process data from a binary file, ensuring efficient deserialization and population of a list of NFAPI_CRC_INDICATION_PDU_T structures
void read_and_process(const char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    // Define a list to hold all the valid entries
    Entry* entries = malloc(sizeof(Entry) * FILE_SIZE_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (entries == NULL) {
        printf("Error allocating memory for the entry list\n");
        fclose(fp);
        return;
    }

    // Initialize the number of valid entries to 0
    int num_valid = 0;

    // Read and process the file in chunks if necessary
    while (!feof(fp)) {
        // Define a temporary buffer for reading from the file
        char buf[CHUNK_SIZE];

        // Read from the file into the temporary buffer
        size_t bytes_read = fread(buf, 1, CHUNK_SIZE, fp);

        // If an error occurred while reading, break out of the loop
        if (ferror(fp)) {
            printf("Error reading from file %s\n", filename);
            free(entries);
            fclose(fp);
            return;
        }

        // Iterate over each entry in the chunk
        for (size_t i = 0; i < bytes_read / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
            // Define a pointer to the current entry
            NFAPI_CRC_INDICATION_PDU_T* pdu = &entries[num_valid].pdu;

            // Attempt to deserialize the entry from the buffer
            if (deserialize_nfapi_crc_indication_pdu(buf + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), pdu)) {
                // If the deserialization was successful, validate the integrity of the entry
                bool valid = true;
                if (!validate_nfapi_crc_indication_pdu(pdu)) {
                    printf("Invalid entry at index %zu\n", i);
                    valid = false;
                }

                // If the entry is valid, add it to the list
                if (valid) {
                    entries[num_valid++].valid = true;
                } else {
                    num_valid++;
                }
            } else {
                printf("Error deserializing NFAPI_CRC_INDICATION_PDU_T entry at index %zu\n", i);
            }
        }
    }

    // Close the file
    fclose(fp);

    // Export the data to a CSV file
    export_csv(entries, num_valid);

    // Free the memory allocated for the entry list
    free(entries);
}

// Function to validate the integrity of an NFAPI_CRC_INDICATION_PDU_T structure
bool validate_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Check that all required fields are present and correctly formatted
    if (pdu->rx_ue_information.rx_ue_information_rel8.rnti == 0 ||
            pdu->rx_ue_information.rx_ue_information_rel8.crc_flag == 0) {
        return false;
    }
    if (pdu->rx_ue_information.rx_ue_information_rel8.rnti > 65535 ||
            pdu->rx_ue_information.rx_ue_information_rel8.crc_flag > 1) {
        return false;
    }

    // Check that the RX_UE_INFORMATION_TAG is valid
    if (pdu->rx_ue_information.rx_ue_information_rel8.rnti != NFAPI_RNTI_VALUE_NONE &&
            pdu->rx_ue_information.rx_ue_information_rel8.rnti != NFAPI_RNTI_VALUE_NOT_A_VALUE) {
        return false;
    }

    // Check that the CRC_INDICATION_REL8_TAG is valid
    if (pdu->rx_ue_information.rx_ue_information_rel8.crc_flag != NFAPI_CRC_FLAG_NO &&
            pdu->rx_ue_information.rx_ue_information_rel8.crc_flag != NFAPI_CRC_FLAG_YES) {
        return false;
    }

    // If all checks passed, the entry is valid
    return true;
}

// Function to deserialize an NFAPI_CRC_INDICATION_PDU_T structure from a buffer
bool deserialize_nfapi_crc_indication_pdu(const char* buf, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Check that the buffer is large enough to hold an NFAPI_CRC_INDICATION_PDU_T structure
    if (strlen(buf) < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return false;
    }

    // Deserialize the RX_UE_INFORMATION_TAG
    memcpy(&pdu->rx_ue_information.rx_ue_information_rel8, buf, sizeof(NFAPI_RX_UE_INFORMATION_REL8_T));
