    // Construct a SQL command to query the database based on the populated CRC indication data
    StringBuilder sqlBuilder = new StringBuilder("SELECT * FROM crc_indications WHERE ");
    for (NFAPI_CRC_INDICATION_PDU_T pdu : crcIndicationList) {
        // Use parameterized SQL to avoid SQL injection attacks
        sqlBuilder.append("rnti = ? AND ");
