#define NFAPI_CRC_INDICATION_PDU_T struct { \
    unsigned int rx_ue_information_tag; \
    unsigned int rnti; \
    unsigned int crc_indication_rel8_tag; \
    unsigned char crcflag; \
}

#define MAX_CRC_INDICATIONS 1000

struct CrcIndicationList {
    NFAPI_CRC_INDICATION_PDU_T *crc_indications[MAX_CRC_INDICATIONS];
    int num_crc_indications;
    pthread_mutex_t lock;
};

struct CrcIndicationList crc_list = {
    .num_crc_indications = 0,
};

void initCrcIndications(NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    pthread_mutex_lock(&crc_list.lock);
    crc_list.num_crc_indications++;
    if (crc_list.num_crc_indications > MAX_CRC_INDICATIONS) {
        printf("ERROR: CRC indication list is full\n");
        pthread_mutex_unlock(&crc_list.lock);
        return;
    }
    crc_list.crc_indications[crc_list.num_crc_indications - 1] = crc_indication;
    pthread_mutex_unlock(&crc_list.lock);
}

void freeCrcIndications() {
    pthread_mutex_lock(&crc_list.lock);
    for (int i = 0; i < crc_list.num_crc_indications; i++) {
        if (crc_list.crc_indications[i] != NULL) {
            free(crc_list.crc_indications[i]);
        }
    }
    crc_list.num_crc_indications = 0;
    pthread_mutex_unlock(&crc_list.lock);
}

