        token = strtok(NULL, " ");
        int rnti = atoi(token);
        token = strtok(NULL, " ");
        int crc_indication_rel8_tag = atoi(token);
        token = strtok(NULL, " ");
        int crcflag = atoi(token);

        NFAPI_CRC_INDICATION_PDU_T *crc_indication = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crc_indication->rx_ue_information_tag = rx_ue_information_tag;
        crc_indication->rnti = rnti;
        crc_indication->crc_indication_rel8_tag = crc_indication_rel8_tag;
        crc_indication->crcflag = crcflag;

        initCrcIndications(crc_indication);
    }
}

