void updateListWithNewCrcs() {
    NFAPI_CRC_INDICATION_PDU_T *new_crc_list[MAX_CRC_INDICATIONS];
    int num_new_crcs = 0;

    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_crc = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_crc->rx_ue_information_tag = 0;
        new_crc->rnti = 0;
        new_crc->crc_indication_rel8_tag = 0;
        new_crc->crcflag = 0;

        new_crc_list[i] = new_crc;
    }

    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *old_crc = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        old_crc->rx_ue_information_tag = 0;
        old_crc->rnti = 0;
        old_crc->crc_indication_rel8_tag = 0;
        old_crc->crcflag = 0;

        int index = i % new_crc_list[i]->rx_ue_information_tag;

        if (index > num_new_crcs) {
            break;
        } else {
            new_crc_list[i] = old_crc;
            num_new_crcs++;
        }
    }
}

void freeList() {
    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        if (new_crc_list[i] != NULL) {
            free(new_crc_list[i]);
        }
    }
}

