    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        if (new_crc_list[i] != NULL) {
            printf("%d %d %d %d\n", new_crc_list[i]->rx_ue_information_tag, new_crc_list[i]->rnti, new_crc_list[i]->crc_indication_rel8_tag, new_crc_list[i]->crcflag);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <input file> <output file>\n", argv[0]);
        return 1;
    }

    populateListFromXmlFile(argv[1]);
    updateListWithNewCrcs();
    printList();
    freeList();

    return 0;
}
