// Initialize the custom memory pool with a predefined capacity
void init_memory_pool(size_t capacity) {
    pool.capacity = capacity;
    pool.used = 0;
    pool.free = capacity;
    pool.elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
}

// Allocate a new element in the custom memory pool, or return NULL if allocation fails
NFAPI_CRC_INDICATION_PDU_T* allocate_element() {
    if (pool.free == 0) {
        // No more elements available, return NULL
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* element = pool.elements[pool.used++];
    --pool.free;

    // Initialize the allocated element with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
