    }

    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * n);
    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* element = allocate_element();
        if (!element) {
            // Allocation failed, free previously allocated elements and return NULL
            for (size_t j = 0; j < i; ++j) {
