#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>

// Custom memory pool allocator
struct MemoryPool {
    struct MemoryBlock* head;
    struct MemoryBlock* tail;
};

struct MemoryBlock {
    void* data;
    size_t size;
    bool used;
    struct MemoryBlock* next;
};

void initMemoryPool(struct MemoryPool* pool) {
    pool->head = NULL;
    pool->tail = NULL;
}

void* allocFromPool(struct MemoryPool* pool, size_t size) {
    if (!pool || !size) return NULL;

    struct MemoryBlock* block = (struct MemoryBlock*)malloc(sizeof(struct MemoryBlock));
    block->data = malloc(size);
    block->size = size;
    block->used = false;
    block->next = NULL;

    if (!pool->head) {
        pool->head = block;
        pool->tail = block;
    } else {
        pool->tail->next = block;
        pool->tail = block;
    }

    return block->data;
}

void freeFromPool(struct MemoryPool* pool, void* data) {
    if (!pool || !data) return;

    struct MemoryBlock* block = (struct MemoryBlock*)data - 1;
    block->used = false;
}

// Custom logger
#define LOG_BUF_SIZE 256

struct Logger {
    char buf[LOG_BUF_SIZE];
    size_t pos;
};

void initLogger(struct Logger* logger) {
    memset(logger, 0, sizeof(struct Logger));
}

void logAllocationEvent(struct Logger* logger, void* data, size_t size) {
    if (!logger || !data || !size) return;

    snprintf(logger->buf, LOG_BUF_SIZE, "ALLOC: %p (%zu bytes)", data, size);
    logger->pos = strlen(logger->buf);
}

void logDeallocationEvent(struct Logger* logger, void* data) {
    if (!logger || !data) return;

    snprintf(logger->buf + logger->pos, LOG_BUF_SIZE - logger->pos, "DEALLOC: %p", data);
}

