int srb1_max_buffer_size = 0;
pthread_mutex_t srb1_buffer_lock = PTHREAD_MUTEX_INITIALIZER;

void init_srb1_buffers(int max_buffer_size) {
    pthread_mutex_lock(&srb1_buffer_lock);
    srb1_max_buffer_size = max_buffer_size;
    srb1_buffers = calloc(max_buffer_size, sizeof(LTE_ENB_SRB1_BUFFER_T));
    for (int i = 0; i < max_buffer_size; i++) {
        srb1_buffers[i].valid = 0;
        srb1_buffers[i].size = 0;
        srb1_buffers[i].data = NULL;
    }
    pthread_mutex_unlock(&srb1_buffer_lock);
}

void add_srb1_buffer(int size, char *data) {
    pthread_mutex_lock(&srb1_buffer_lock);
    if (size > srb1_max_buffer_size || srb1_buffer_count >= srb1_max_buffer_size) {
        // handle buffer overflow gracefully by reallocating memory
        int new_max_buffer_size = size + 1024; // or any other suitable strategy
        LTE_ENB_SRB1_BUFFER_T *new_buffers = realloc(srb1_buffers, new_max_buffer_size * sizeof(LTE_ENB_SRB1_BUFFER_T));
        if (new_buffers == NULL) {
            // handle allocation failure gracefully
            pthread_mutex_unlock(&srb1_buffer_lock);
            return;
        }
        srb1_max_buffer_size = new_max_buffer_size;
        srb1_buffers = new_buffers;
    }
    int buffer_index = 0;
    while (srb1_buffers[buffer_index].valid == 1) {
        buffer_index++;
    }
    srb1_buffers[buffer_index].valid = 1;
    srb1_buffers[buffer_index].size = size;
    srb1_buffers[buffer_index].data = data;
    srb1_buffer_count++;
    pthread_mutex_unlock(&srb1_buffer_lock);
}

void delete_srb1_buffer(int buffer_index) {
    pthread_mutex_lock(&srb1_buffer_lock);
    if (buffer_index >= srb1_max_buffer_size || buffer_index < 0) {
        // handle invalid buffer index gracefully
        pthread_mutex_unlock(&srb1_buffer_lock);
        return;
    }
    LTE_ENB_SRB1_BUFFER_T *temp = malloc(sizeof(LTE_ENB_SRB1_BUFFER_T));
    if (temp == NULL) {
        // handle allocation failure gracefully
        pthread_mutex_unlock(&srb1_buffer_lock);
        return;
    }
    memcpy(temp, &srb1_buffers[buffer_index], sizeof(LTE_ENB_SRB1_BUFFER_T));
    srb1_buffers[buffer_index].valid = 0;
    srb1_buffers[buffer_index].size = 0;
    srb1_buffers[buffer_index].data = NULL;
    free(temp);
    srb1_buffer_count--;
    pthread_mutex_unlock(&srb1_buffer_lock);
}

