            crc_count++;
        } else {
            list[i].crcflag = false;
        }
    }

    // Update the CRCFLAG values based on predefined conditions
    for (int i = 0; i < N; i++) {
        if (i % UPDATE_INTERVAL == 0 && crc_count > CRC_THRESHOLD) {
            list[i].crcflag = true;
            crc_count--;
        }
    }

    // Log the number of structures with CRCFLAG set to true and the total number of structures
    printf("Number of structures with CRCFLAG set to true: %d\n", crc_count);
    printf("Total number of structures: %d\n", N);

    // Check if the list reaches its capacity before all required structures are added
