        int num_structures_secondary = 0;
        for (int i = 0; i < SECONDARY_BUFFER_SIZE; i++) {
            if (secondary_buffer[i].crcflag == true) {
                num_structures_secondary++;
            }
        }
        printf("Number of structures added to the secondary buffer: %d\n", num_structures_secondary);
    }

    // Free the memory allocated for the list and secondary buffer
    free(list);
    free(secondary_buffer);
}
