["```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

#define MAX_PACKETS 1024 // maximum number of packets to store

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned char *data; // CRC indication data
    size_t len; // length of the CRC indication data
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PacketListNode {
    struct PacketListNode *next; // pointer to the next node in the list
    struct PacketListNode *prev; // pointer to the previous node in the list
    NFAPI_CRC_INDICATION_PDU_T packet; // the packet data
} PacketListNode;

typedef struct PacketList {
    PacketListNode *head; // head of the linked list
    PacketListNode *tail; // tail of the linked list
    size_t numPackets; // number of packets in the list
} PacketList;

void initPacketList(PacketList *list) {
    list->head = NULL;
    list->tail = NULL;
    list->numPackets = 0;
}

void addPacketToList(PacketList *list, NFAPI_CRC_INDICATION_PDU_T packet) {
    PacketListNode *node = (PacketListNode *)malloc(sizeof(PacketListNode));
    assert(node != NULL);
    node->packet = packet;
    node->next = NULL;
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    list->numPackets++;
}

void removePacketFromList(PacketList *list, NFAPI_CRC_INDICATION_PDU_T packet) {
    PacketListNode *node = list->head;
    while (node != NULL) {
        if (memcmp(packet.data, node->packet.data, packet.len) == 0 && node->packet.len == packet.len) {
            // remove the node from the list
            if (node->prev != NULL) {
                node->prev->next = node->next;
            } else {
                list->head = node->next;
            }
            if (node->next != NULL) {
                node->next->prev = node->prev;
            } else {
                list->tail = node->prev;
            }
            list->numPackets--;
        }
    }
}

void freePacketList(PacketList *list) {
    PacketListNode *node = list->head;
    while (node != NULL) {
        // free the memory for the node's packet data
        free(node->packet.data);
        // move to the next node in the list
        node = node->next;
    }
}

void iterateOverPackets(PacketList *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    PacketListNode *node = list->head;
    while (node != NULL) {
        callback(node->packet);
        node = node->next;
    }
}
```
