#define MAX_FRAMES 1024

typedef struct NFAPI_RX_FRAME {
    int frameNumber;
    int subFrameNumber;
    char* payload;
} NFAPI_RX_FRAME_T;

struct FrameList {
    size_t size;
    size_t capacity;
    NFAPI_RX_FRAME_T** frames;
};

void initializeFrameList(struct FrameList* list) {
    list->size = 0;
    list->capacity = MAX_FRAMES;
    list->frames = malloc(list->capacity * sizeof(NFAPI_RX_FRAME_T*));
}

void addFrameToList(struct FrameList* list, NFAPI_RX_FRAME_T* frame) {
    if (list->size == list->capacity) {
        // Reallocate memory for the list to make room for a new frame
        size_t newCapacity = 2 * list->capacity;
        NFAPI_RX_FRAME_T** newFrames = realloc(list->frames, newCapacity * sizeof(NFAPI_RX_FRAME_T*));
        if (newFrames == NULL) {
            // Handle memory allocation failure
            return;
        }
        list->capacity = newCapacity;
        list->frames = newFrames;
    }
    list->frames[list->size++] = frame;
}

void removeFrameFromList(struct FrameList* list, size_t index) {
    if (index >= list->size) {
        // Handle invalid index
        return;
    }
    NFAPI_RX_FRAME_T* frame = list->frames[index];
    for (size_t i = index + 1; i < list->size - 1; i++) {
        list->frames[i - 1] = list->frames[i];
    }
    list->size--;
}

void clearFrameList(struct FrameList* list) {
    for (size_t i = 0; i < list->size; i++) {
        NFAPI_RX_FRAME_T* frame = list->frames[i];
        free(frame);
    }
    list->size = 0;
}

void logFrameDetails(struct FrameList* list, size_t index) {
    if (index >= list->size) {
        // Handle invalid index
        return;
    }
    NFAPI_RX_FRAME_T* frame = list->frames[index];
    printf("Frame %zu: Number %d, Subframe number %d\n", index, frame->frameNumber, frame->subFrameNumber);
}
