static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new structure with random CRCFLAG
NFAPI_CRC_INDICATION_PDU_T *create_structure(void) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_data->rx_ue_information_tag = rand();
    new_data->rnti = rand();
    new_data->crc_indication_rel8_tag = (uint8_t)rand() % 2;
    return new_data;
}

// Function to add a new structure to the list
void add_structure(NFAPI_CRC_INDICATION_PDU_T *new_data) {
    pthread_mutex_lock(&list_lock);
    if (list.data == NULL) {
        // List is empty, create a new node and insert it at the head
        list.prev = list.next = NULL;
        list.data = new_data;
    } else {
        // Insert the new node at the end of the list
        list.next->prev = new_data;
        new_data->next = list.next;
        list.next = new_data;
    }
    pthread_mutex_unlock(&list_lock);
}

// Function to remove a structure from the list
void remove_structure(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list_lock);
    if (data == list.data) {
        // Remove head node
        list.data = data->next;
        if (list.next != NULL) {
            list.next->prev = NULL;
        }
    } else {
        NFAPI_CRC_INDICATION_PDU_T *curr = list.data;
        while (curr != NULL && curr->next != data) {
            curr = curr->next;
        }
        if (curr == NULL) {
            // Not found, ignore
            return;
        }
        // Remove the node from the list
        curr->next = data->next;
        if (data->next != NULL) {
            data->next->prev = curr;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

// Function to validate the integrity of the list
void validate_list(void) {
    NFAPI_CRC_INDICATION_PDU_T *curr = list.data;
    while (curr != NULL) {
        if (curr->next == NULL && curr->prev != NULL) {
            // Error, invalid next pointer
            return;
        }
        curr = curr->next;
    }
}

// Main function to demonstrate usage of the list
int main(void) {
    pthread_t thread[10];
    for (int i = 0; i < 10; i++) {
        // Create a new structure and add it to the list
        NFAPI_CRC_INDICATION_PDU_T *new_data = create_structure();
        add_structure(new_data);

        // Create a new thread for adding/removing structures from the list
