    }

    // Validate the integrity of the list and print the contents
    validate_list();
    NFAPI_CRC_INDICATION_PDU_T *curr = list.data;
    while (curr != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %u\n", curr->rx_ue_information_tag, curr->rnti, curr->crc_indication_rel8_tag);
        curr = curr->next;
    }

    return 0;
}

// Function to add/remove structures from the list concurrently
void *add_remove_structures(void *arg) {
