}

// Define a function to serialize the dynamic array to a file in binary format
void serialize(DYNAMIC_ARRAY *array, FILE *file) {
    // Check if the array is empty or the file is not open for writing
    if (array->capacity <= 0 || file == NULL) {
        return;
