}

// Define a function to deserialize the dynamic array from a file in binary format
void deserialize(DYNAMIC_ARRAY *array, FILE *file) {
    // Check if the file is not open for reading or does not exist
    if (file == NULL || !fseek(file, 0, SEEK_END)) {
        return;
    }
    long file_size = ftell(file);
    rewind(file);
    // Read the size of the array from the file
    fread(&(array->capacity), sizeof(size_t), 1, file);
    // Allocate memory for the array and read each element from the file
    array->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * array->capacity);
    for (int i = 0; i < array->capacity; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fread(element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        array->elements[i] = element;
    }
}

// Define a function to free the memory allocated for the dynamic array
void free_dynamic_array(DYNAMIC_ARRAY *array) {
    // Free each structure in the array and the array itself
    for (int i = 0; i < array->capacity; i++) {
