// Define the memory pool size and alignment
#define POOL_SIZE 1024*1024
#define ALIGNMENT 64

// Define the lock for synchronizing access to the memory pool
pthread_mutex_t mem_lock;

// Define the memory pool structure
struct mem_pool {
    char *mem;
    int size;
};

// Define the memory pool instance
static struct mem_pool mem_pool;

// Initialize the memory pool
void init_mem_pool() {
    // Allocate a large block of memory for the pool
    mem_pool.mem = (char *)malloc(POOL_SIZE);
    if (!mem_pool.mem) {
        LOG_ERROR("Failed to allocate memory for memory pool");
        return;
    }

    // Set the size of the pool
    mem_pool.size = POOL_SIZE;

    // Initialize the lock for synchronizing access to the pool
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    if (pthread_mutex_init(&mem_lock, &attr) != 0) {
        LOG_ERROR("Failed to initialize memory lock");
        return;
    }
}

// Deinitialize the memory pool
void deinit_mem_pool() {
    // Destroy the lock for synchronizing access to the pool
    pthread_mutex_destroy(&mem_lock);

    // Free the memory block allocated for the pool
    free(mem_pool.mem);
}

// Allocate a new structure from the memory pool
NFAPI_CRC_INDICATION_PDU_T *alloc_crc_ind_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    // Acquire the lock for synchronizing access to the pool
    pthread_mutex_lock(&mem_lock);

    // Check if there is enough memory in the pool for a new structure
    int size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (size > mem_pool.size) {
        LOG_ERROR("Not enough memory in pool");
        pthread_mutex_unlock(&mem_lock);
        return NULL;
    }

    // Find the first available slot in the pool and allocate it for the new structure
    char *slot = memchr(mem_pool.mem, 0, POOL_SIZE - size);
    if (!slot) {
        LOG_ERROR("No free slots in memory pool");
        pthread_mutex_unlock(&mem_lock);
        return NULL;
    }

    // Allocate the structure in the slot and update the memory pool size
    pdu = (NFAPI_CRC_INDICATION_PDU_T *)slot;
    *(int *)pdu = size;
    mem_pool.size -= size;

    // Release the lock for synchronizing access to the pool
    pthread_mutex_unlock(&mem_lock);

    return pdu;
}

// Free a structure allocated from the memory pool
void free_crc_ind_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the lock for synchronizing access to the pool
    pthread_mutex_lock(&mem_lock);

    // Check if the structure is valid and has not been freed already
    int size = *(int *)pdu;
    if (size <= 0 || memcmp(pdu, pdu + size, ALIGNMENT - 1) != 0) {
        LOG_ERROR("Invalid structure or double free detected");
        pthread_mutex_unlock(&mem_lock);
        return;
    }

    // Update the memory pool size and mark the slot as available
    mem_pool.size += size;
    *(int *)pdu = 0;

    // Release the lock for synchronizing access to the pool
    pthread_mutex_unlock(&mem_lock);
}

// Populate an allocated structure with valid data
void populate_crc_ind_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Generate a random value for the RX_UE_INFORMATION_TAG
