    mac_context_t *data;
    struct mac_context_node *next;
} mac_context_node_t;

// Function to dynamically allocate and manage the linked list of MAC context structures
void *mac_context_list_alloc(uint32_t n) {
    // Check if the number of entries is zero
    if (n == 0) {
        // Allocate a dummy node with a NULL pointer to data
        mac_context_node_t *dummy = malloc(sizeof(mac_context_node_t));
        dummy->data = NULL;
        dummy->next = NULL;

        return dummy;
    }

    // Allocate an array of pointers to MAC context structures
    mac_context_t **data_array = malloc(n * sizeof(mac_context_t *));

    // Initialize the head and tail pointers of the linked list
    mac_context_node_t *head = NULL;
    mac_context_node_t *tail = NULL;

    // Allocate a node for each entry in the array and add it to the linked list
    for (uint32_t i = 0; i < n; i++) {
        mac_context_node_t *new_node = malloc(sizeof(mac_context_node_t));
        new_node->data = data_array[i];
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }

    // Free the array of pointers to MAC context structures
    free(data_array);

    return head;
}

// Function to dynamically allocate and manage a single MAC context structure
mac_context_t *mac_context_alloc() {
    // Allocate memory for the MAC context structure
    mac_context_t *data = malloc(sizeof(mac_context_t));

    if (data == NULL) {
        fprintf(stderr, "Failed to allocate memory for MAC context\n");
        exit(1);
    }

    return data;
}

// Function to dynamically deallocate and manage a linked list of MAC context structures
void mac_context_list_dealloc(mac_context_node_t *head) {
    // Check if the head node is NULL
    if (head == NULL) {
        return;
    }

    // Traverse the linked list and deallocate each node
    while (head != NULL) {
        mac_context_node_t *current = head;
        head = head->next;

        free(current);
    }
}

// Function to dynamically deallocate and manage a single MAC context structure
void mac_context_dealloc(mac_context_t *data) {
    // Check if the data pointer is NULL
    if (data == NULL) {
        return;
    }

    free(data);
}
