    NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
    if (newArray == NULL) {
