      printf("Error: Failed to reallocate memory for CRC indication array\n");
      return;
    } else {
      // Reallocation succeeded, update the dynamic array with the new pointer
      array->pdu = newArray;
      array->capacity = newCapacity;
    }
  }
  // Add the new element to the end of the dynamic array
  NFAPI_CRC_INDICATION_PDU_T *newPdu = &(array->pdu[array->size]);
  newPdu->rxUETag = rxUETag;
  newPdu->rnti = rnti;
  newPdu->crcFlag = crcFlag;
  array->size++;
}

// Removes the last element from the dynamic array
void crcIndicationArrayPopBack(CRC_INDICATION_ARRAY *array) {
  if (array->size > 0) {
    array->size--;
  } else {
    // Attempted to pop back from an empty dynamic array, exit the function and return an error
    printf("Error: Tried to pop back from an empty CRC indication array\n");
  }
}

// Frees the memory allocated for the dynamic array
void crcIndicationArrayFree(CRC_INDICATION_ARRAY *array) {
  free(array->pdu);
  array->size = 0;
  array->capacity = 0;
}
