    my_vector.push_back(1);
    my_vector.push_back(2);
    my_vector.push_back(3);

    // Print out the size and contents of the vector
    std::cout << "Size: " << my_vector.size() << std::endl;
    for (int i = 0; i < my_vector.size(); i++) {
