// Log entry structure
typedef struct {
    int transaction_id;
    long timestamp;
    char* event_type;
    char* payload_data;
} log_entry;

// Linked list node for storing log entries
typedef struct log_list_node {
    log_entry entry;
    struct log_list_node* next;
} log_list_node;

// Log list head
static log_list_node* log_head = NULL;

// Lock for synchronizing access to the log list
static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new log entry to the list
void add_log_entry(int transaction_id, long timestamp, char* event_type, char* payload_data) {
    // Allocate memory for the new log entry
    log_entry* new_entry = malloc(sizeof(log_entry));
    if (!new_entry) {
        printf("Error: could not allocate memory for log entry\n");
        return;
    }

    // Fill in the fields of the new log entry
    new_entry->transaction_id = transaction_id;
    new_entry->timestamp = timestamp;
    new_entry->event_type = event_type;
    new_entry->payload_data = payload_data;

    // Lock the log list and add the new entry to the end of the list
    pthread_mutex_lock(&log_lock);
    log_list_node* current = log_head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_entry;
    log_head = new_entry;
    pthread_mutex_unlock(&log_lock);
}

// Function to filter and categorize logs based on predefined criteria
void process_logs(int M, int* transaction_ids, char** event_types) {
    // Lock the log list for read access
    pthread_mutex_lock(&log_lock);
    log_list_node* current = log_head;

    // Iterate through the log entries and filter/categorize them based on the input parameters
    while (current != NULL) {
        // Check if the transaction ID is in the list of IDs to filter by
        int found = 0;
        for (int i = 0; i < M && !found; i++) {
            if (transaction_ids[i] == current->entry.transaction_id) {
                found = 1;
            }
        }
        // If the transaction ID is not in the list, skip this log entry
        if (!found) {
            current = current->next;
            continue;
        }

        // Check if the event type is in the list of types to filter by
        found = 0;
        for (int i = 0; i < M && !found; i++) {
            if (strcmp(event_types[i], current->entry.event_type) == 0) {
                found = 1;
            }
        }
        // If the event type is not in the list, skip this log entry
        if (!found) {
            current = current->next;
            continue;
        }

        // Print the filtered/categorized log entry to the console
        printf("%d %ld %s %s\n", current->entry.transaction_id, current->entry.timestamp, current->entry.event_type, current->entry.payload_data);

        // Move on to the next log entry
        current = current->next;
    }

    pthread_mutex_unlock(&log_lock);
}
