// Define a struct to represent a session context
struct SessionContext {
    int ue_id; // UE identifier
    int pdu_session_id; // PDU session ID
    unsigned long teids[4]; // Array of GTP-U TEID values
};

// Define a linked list node to represent a session context in the list
struct SessionContextNode {
    struct SessionContext *context; // Pointer to the session context
    struct SessionContextNode *next; // Pointer to the next node in the list
};

// Define a linked list to store all session contexts
struct SessionContextList {
    struct SessionContextNode *head; // Pointer to the first node in the list
    struct SessionContextNode *tail; // Pointer to the last node in the list
    size_t size; // Number of nodes in the list
};

// Define a mutex for synchronizing access to the linked list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

/**
 * Initialize a session context list with an initial size.
 *
 * @param list The pointer to the session context list to initialize
 * @param size The initial size of the linked list
 */
void initSessionContextList(struct SessionContextList *list, size_t size) {
    pthread_mutex_lock(&lock);
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&lock);
}

/**
 * Add a session context to the linked list.
 *
 * @param list The pointer to the session context list
 * @param ue_id The UE identifier of the session context
 * @param pdu_session_id The PDU session ID of the session context
 * @param teids The array of GTP-U TEID values for the session context
 */
void addSessionContext(struct SessionContextList *list, int ue_id, int pdu_session_id, unsigned long teids[]) {
    struct SessionContextNode *new_node = malloc(sizeof(struct SessionContextNode));
    new_node->context = malloc(sizeof(struct SessionContext));
    new_node->context->ue_id = ue_id;
    new_node->context->pdu_session_id = pdu_session_id;
    memcpy(new_node->context->teids, teids, sizeof(unsigned long) * 4);

    pthread_mutex_lock(&lock);
    if (list->size == 0) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&lock);
}

/**
 * Remove a session context from the linked list.
 *
 * @param list The pointer to the session context list
 * @param ue_id The UE identifier of the session context to remove
 * @param pdu_session_id The PDU session ID of the session context to remove
 */
void removeSessionContext(struct SessionContextList *list, int ue_id, int pdu_session_id) {
    struct SessionContextNode *node = list->head;
    while (node != NULL) {
        if (node->context->ue_id == ue_id && node->context->pdu_session_id == pdu_session_id) {
            break;
        }
        node = node->next;
    }

    if (node != NULL) {
        pthread_mutex_lock(&lock);
        list->size--;
        struct SessionContextNode *prev = node->prev;
        struct SessionContextNode *next = node->next;
        free(node->context);
        free(node);
        if (prev != NULL) {
            prev->next = next;
        } else {
            list->head = next;
        }
        if (next != NULL) {
            next->prev = prev;
        } else {
            list->tail = prev;
        }
        pthread_mutex_unlock(&lock);
    }
}

/**
 * Find a session context in the linked list.
 *
 * @param list The pointer to the session context list
 * @param ue_id The UE identifier of the session context to find
 * @param pdu_session_id The PDU session ID of the session context to find
 * @return The pointer to the found session context, or NULL if not found
 */
struct SessionContext* findSessionContext(struct SessionContextList *list, int ue_id, int pdu_session_id) {
    struct SessionContextNode *node = list->head;
    while (node != NULL) {
        if (node->context->ue_id == ue_id && node->context->pdu_session_id == pdu_session_id) {
            return node->context;
        }
        node = node->next;
    }
    return NULL;
}

/**
 * Update a session context in the linked list.
 *
 * @param list The pointer to the session context list
 * @param ue_id The UE identifier of the session context to update
