 */
void updateSessionContext(struct SessionContextList *list, int ue_id, int pdu_session_id, unsigned long teids[]) {
    struct SessionContextNode *node = list->head;
    while (node != NULL) {
        if (node->context->ue_id == ue_id && node->context->pdu_session_id == pdu_session_id) {
            break;
        }
        node = node->next;
    }

    if (node != NULL) {
        memcpy(node->context->teids, teids, sizeof(unsigned long) * 4);
    }
}

/**
