typedef struct {
    MAC_PDU *pdu;
    pthread_mutex_t mutex;
} mac_pdu_list;

mac_pdu_list *mac_pdu_list_create() {
    mac_pdu_list *list = malloc(sizeof(mac_pdu_list));
    list->pdu = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void mac_pdu_list_add(mac_pdu_list *list, MAC_PDU *pdu) {
    pthread_mutex_lock(&list->mutex);
    list->pdu = realloc(list->pdu, (list->len + 1) * sizeof(MAC_PDU));
    memcpy(&list->pdu[list->len++], pdu, sizeof(MAC_PDU));
    pthread_mutex_unlock(&list->mutex);
}

void mac_pdu_list_update(mac_pdu_list *list, MAC_PDU *pdu) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->len; i++) {
        if (memcmp(&list->pdu[i], pdu, sizeof(MAC_PDU)) == 0) {
            memcpy(&list->pdu[i], pdu, sizeof(MAC_PDU));
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void mac_pdu_list_free(mac_pdu_list *list) {
    for (int i = 0; i < list->len; i++) {
        free(list->pdu[i].l3_header);
        free(list->pdu[i].pdusessionid);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list->pdu);
}

void nfapi_crci_update(nfapi_crci_t *self, mac_pdu_list *list) {
    pthread_mutex_lock(&self->mutex);
    for (int i = 0; i < list->len; i++) {
        nfapi_crci_add(self, &list->pdu[i].l3_header, &list->pdu[i].pdusessionid);
    }
    pthread_mutex_unlock(&self->mutex);
}

void nfapi_crci_crc_indication(nfapi_crci_t *self, CRC_INDICATION_REL8_TAG *crc_ind) {
    pthread_mutex_lock(&self->mutex);
    for (int i = 0; i < self->len; i++) {
        if (self->pdu[i].l3_header == crc_ind->l3_header && self->pdu[i].pdusessionid == crc_ind->pdusessionid) {
            self->pdu[i].crc_indication = *crc_ind;
        }
    }
