            // Shift all subsequent contexts to fill the gap
            for (int j = i; j < MAX_SESSIONS - 1; j++) {
                session_list[j] = session_list[j + 1];
            }
            // Decrement the number of sessions by one
            MAX_SESSIONS--;
            break;
        }
    }

    // Unlock the mutex and return the result of the deallocation
