} MAC_PDU;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct MAC_ARRAY {
    size_t capacity;
    size_t size;
    MAC_PDU *pdu_array;
};

// Function to add a new element to the array
static void mac_add(struct MAC_ARRAY *arr, L3_HEADER *l3_header, PDCP_SN pdcp_sn, PDUSessionID pdusessionid) {
    // Check if the array is full
    if (arr->size >= arr->capacity) {
        // Double the capacity of the array
        arr->capacity *= 2;
        // Reallocate memory for the array
        arr->pdu_array = realloc(arr->pdu_array, arr->capacity * sizeof(MAC_PDU));
    }
    // Add a new element to the array
    arr->pdu_array[arr->size].l3_header = l3_header;
    arr->pdu_array[arr->size].pdcp_sn = pdcp_sn;
    arr->pdu_array[arr->size].pdusessionid = pdusessionid;
    // Increment the size of the array
    ++(arr->size);
}

// Function to update an existing element in the array
static void mac_update(struct MAC_ARRAY *arr, L3_HEADER *l3_header, PDCP_SN pdcp_sn, PDUSessionID pdusessionid) {
    // Find the index of the element to be updated
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->pdu_array[i].l3_header == l3_header &&
            arr->pdu_array[i].pdcp_sn == pdcp_sn &&
            arr->pdu_array[i].pdusessionid == pdusessionid) {
            // Update the element at the found index
            arr->pdu_array[i].l3_header = l3_header;
            arr->pdu_array[i].pdcp_sn = pdcp_sn;
            arr->pdu_array[i].pdusessionid = pdusessionid;
        }
    }
}

// Function to randomly set the CRCFLAG in the NFAPI_CRC_INDICATION_PDU_T structure
static void mac_crc_indication(struct MAC_ARRAY *arr, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Generate a random value for the CRCFLAG
    double random_value = (double)rand() / (double)RAND_MAX;
    // Set the CRCFLAG based on the generated value
    if (random_value < CRCFLAG_RANDOM_FACTOR) {
        pdu->crc_indication_rel8_tag.crcflag = 1;
    } else {
        pdu->crc_indication_rel8_tag.crcflag = 0;
    }
}

// Function to populate a list of NFAPI_CRC_INDICATION_PDU_T structures with random values
static void mac_populate(struct MAC_ARRAY *arr) {
    // Allocate memory for the list of PDUs
    size_t n_pdu = arr->size;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Initialize the list of PDUs
    for (size_t i = 0; i < n_pdu; ++i) {
        pdus[i].rx_ue_information_tag.present = 1;
        pdus[i].rnti = arr->pdu_array[i].rnti;
        mac_crc_indication(arr, &pdus[i]);
    }
}

// Function to handle concurrent access by multiple threads
static void mac_lock(struct MAC_ARRAY *arr) {
    // Acquire a lock on the array
    pthread_mutex_lock(&(arr->lock));
}

// Function to release the lock on the array
static void mac_unlock(struct MAC_ARRAY *arr) {
    // Release the lock on the array
    pthread_mutex_unlock(&(arr->lock));
}

// Function to handle network failures gracefully
static void mac_failover(struct MAC_ARRAY *arr) {
    // Check if any element in the array has a failed connection
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->pdu_array[i].l3_header == NULL) {
            // Replace the failed connection with a new one
            L3_HEADER *new_header = malloc(sizeof(L3_HEADER));
            PDCP_SN new_sn = 0;
            PDUSessionID new_sessionid = 0;
            mac_add(arr, new_header, new_sn, new_sessionid);
        }
    }
}

// Function to handle periodic updates from the data sources
static void mac_update_data_sources(struct MAC_ARRAY *arr) {
    // Check if any update is available from the data sources
    for (size_t i = 0; i < arr->size; ++i) {
        L3_HEADER *new_header = NULL;
        PDCP_SN new_sn = 0;
        PDUSessionID new_sessionid = 0;
        // Check if the update is available from the data source
        if (mac_update_data_source(arr->pdu_array[i].l3_header, &new_header, &new_sn, &new_sessionid)) {
            // Update the element in the array
            mac_update(arr, new_header, new_sn, new_sessionid);
        }
    }
}

// Function to handle log messages for debugging purposes
static void mac_log(struct MAC_ARRAY *arr) {
    // Log the contents of the array
    printf("MAC ARRAY: ");
    for (size_t i = 0; i < arr->size; ++i) {
        printf("%d, %d, %d ", arr->pdu_array[i].l3_header, arr->pdu_array[i].pdcp_sn, arr->pdu_array[i].pdusessionid);
    }
    printf("\n");
}

// Entry point for the MAC module
void mac(struct MAC_ARRAY *arr) {
    // Initialize the array with a default value
    mac_init(arr);
    // Handle concurrent access by multiple threads
    while (1) {
        mac_lock(arr);
        // Handle network failures gracefully
        if (mac_failover(arr)) {
            printf("MAC FAILOVER\n");
        }
        // Update the data sources
        mac_update_data_sources(arr);
        // Populate the list of PDUs with random values
        mac_populate(arr);
        // Release the lock on the array
        mac_unlock(arr);
    }
}']

