      transmission_timestamp += timestamp_min_diff;
    }
    // Add the MED structure to the list
    med_list[med_list_size++] = (med_t){.pdcp_sn = pdcp_sn, .transmission_timestamp = transmission_timestamp};
  }
}

// Function to check for consecutive timestamps within a predefined time window
bool consecutive_timestamps(uint64_t timestamp1, uint64_t timestamp2) {
