// Function to update the MED list with new data points and handle potential data loss
void update_med_list(uint32_t pdcp_sn) {
  // Check if the received PDCP SN value is already in the MED list
  for (size_t i = 0; i < med_list_size; i++) {
    if (med_list[i].pdcp_sn == pdcp_sn) {
      return; // Ignore the received data point if it's already in the MED list
    }
  }
  // Handle missing data points and update the MED list with new data points
  handle_missing_data(pdcp_sn);
}

// Function to detect and compensate for network packet loss or disruptions
void handle_disruption() {
  // Check if there are any consecutive timestamps within a predefined time window
  for (size_t i = 0; i < med_list_size - 1; i++) {
    if (consecutive_timestamps(med_list[i].transmission_timestamp, med_list[i + 1].transmission_timestamp)) {
