import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public class DisjointPairs {
    private static final int MAX_ARRAY_SIZE = 1000000; // maximum array size
    private static final int MAX_ELEMENT_VALUE = (int)Math.pow(2, 31) - 1; // maximum element value

    public static PairResult findDisjointPairs(int[] arr) {
        if (arr == null || arr.length == 0) {
            return new PairResult(0L, "Empty array");
        } else if (arr.length > MAX_ARRAY_SIZE) {
            return new PairResult(null, "Array size exceeds maximum allowed value");
        }

        // initialize Union-Find data structure with one component for each element
        Map<Integer, List<Integer>> unionFind = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            if (!unionFind.containsKey(i)) {
                unionFind.put(i, new ArrayList<>());
                unionFind.get(i).add(i);
            }
        }

        long startTime = System.nanoTime(); // start time for performance optimization

        // process each element and perform Union-Find operations
        for (int i = 0; i < arr.length; i++) {
            int currentElement = arr[i];
            if (currentElement <= 0 || currentElement > MAX_ELEMENT_VALUE) {
                return new PairResult(null, "Invalid element value");
            }

            // find the root of the component containing the current element
            while (!unionFind.get(i).contains(i)) {
                i = unionFind.get(i).get(0);
            }

            // perform Union-Find operations on the elements in the current component
            for (int j = i + 1; j < arr.length; j++) {
                if (arr[j] != 0 && Math.abs(arr[j]) <= MAX_ELEMENT_VALUE) {
                    // find the root of the component containing the other element
                    while (!unionFind.get(j).contains(j)) {
                        j = unionFind.get(j).get(0);
                    }

                    if (i != j) {
                        int root1 = findRoot(unionFind, i);
                        int root2 = findRoot(unionFind, j);
                        if (root1 == root2) { // if the elements are in the same component
                            unionFind.get(i).addAll(unionFind.get(j));
                            unionFind.remove(j);
                        } else { // if the elements are in different components
                            int min = Math.min(root1, root2);
                            int max = Math.max(root1, root2);
                            unionFind.get(min).addAll(unionFind.get(max));
                            unionFind.remove(max);
                        }
                    }
                }
            }
        }

        long endTime = System.nanoTime(); // end time for performance optimization
        long totalTime = (endTime - startTime) / 1000; // convert nanoseconds to milliseconds

        int disjointPairs = 0;
        for (int i = 0; i < arr.length; i++) {
            if (unionFind.get(i).size() > 1) {
                disjointPairs++;
            }
        }

        return new PairResult(disjointPairs, totalTime);
    }

    private static int findRoot(Map<Integer, List<Integer>> unionFind, int element) {
        while (!unionFind.get(element).contains(element)) {
            element = unionFind.get(element).get(0);
        }
        return element;
    }
}
