  std::lock_guard<std::mutex> lock(transactionQueueMutex);
  transactionQueue.push(tx);
}

// thread-safe wrapper around the transaction queue
Transaction dequeue() {
  std::lock_guard<std::mutex> lock(transactionQueueMutex);
  if (transactionQueue.size() == 0) {
    return nullptr;
  }
  Transaction tx = transactionQueue.front();
  transactionQueue.pop();
  return tx;
}

// filter and process transactions
void processTransactions() {
  while (true) {
    // acquire semaphore to protect the critical section
    if (sem_wait(&semaphore) != 0) {
      perror("Failed to acquire semaphore");
    }

    // check if there are any transactions in the queue
    Transaction tx = dequeue();
    if (tx == nullptr) {
      break;
    }

    // filter transaction based on age and sliding window mechanism
    if ((time(NULL) - tx.timestamp) > WINDOW_SIZE || rollingAverages.size() >= MAX_TRANSACTIONS) {
      continue;
    }

    // calculate weighted sum of amounts
    double weight = 1 / (tx.timestamp + 5);
    rollingAverages[tx.id].sum += tx.amount * weight;
    rollingAverages[tx.id].count++;

    // release semaphore to allow other threads to access the queue
    if (sem_post(&semaphore) != 0) {
      perror("Failed to release semaphore");
    }
  }
}

// maintain rolling averages
void updateRollingAverages() {
  while (true) {
    // acquire semaphore to protect the critical section
    if (sem_wait(&semaphore) != 0) {
      perror("Failed to acquire semaphore");
    }

    // check if there are any transactions in the queue
    Transaction tx = dequeue();
    if (tx == nullptr) {
      break;
    }

    // update rolling averages
    double weight = 1 / (tx.timestamp + 5);
    rollingAverages[tx.id].sum += tx.amount * weight;
    rollingAverages[tx.id].count++;

    // release semaphore to allow other threads to access the queue
    if (sem_post(&semaphore) != 0) {
      perror("Failed to release semaphore");
    }
  }
}

// log maximum weighted sum and corresponding transaction ID
void logMaximumWeightedSum() {
  while (true) {
    // acquire semaphore to protect the critical section
    if (sem_wait(&semaphore) != 0) {
      perror("Failed to acquire semaphore");
    }

    // check if there are any transactions in the queue
    Transaction tx = dequeue();
    if (tx == nullptr) {
      break;
    }

    // log maximum weighted sum and corresponding transaction ID
    printf("Maximum weighted sum: %f\n", rollingAverages[tx.id].sum);
    printf("Corresponding transaction ID: %s\n", tx.id);

    // release semaphore to allow other threads to access the queue
    if (sem_post(&semaphore) != 0) {
      perror("Failed to release semaphore");
    }
  }
}

// integrate with external systems
void integrateWithExternalSystems() {
  while (true) {
    // acquire semaphore to protect the critical section
    if (sem_wait(&semaphore) != 0) {
      perror("Failed to acquire semaphore");
    }

    // check if there are any transactions in the queue
    Transaction tx = dequeue();
    if (tx == nullptr) {
      break;
    }

    // integrate with external systems
    printf("Integrating with external systems...\n");

    // release semaphore to allow other threads to access the queue
    if (sem_post(&semaphore) != 0) {
      perror("Failed to release semaphore");
    }
  }
}

int main() {
  init();

  // start thread for processing transactions
  pthread_t processTransactionsThread;
  if (pthread_create(&processTransactionsThread, NULL, processTransactions, NULL) != 0) {
    perror("Failed to create thread");
  }

  // start thread for updating rolling averages
  pthread_t updateRollingAveragesThread;
  if (pthread_create(&updateRollingAveragesThread, NULL, updateRollingAverages, NULL) != 0) {
    perror("Failed to create thread");
  }

  // start thread for logging maximum weighted sum and corresponding transaction ID
  pthread_t logMaximumWeightedSumThread;
  if (pthread_create(&logMaximumWeightedSumThread, NULL, logMaximumWeightedSum, NULL) != 0) {
    perror("Failed to create thread");
  }

  // start thread for integrating with external systems
  pthread_t integrateWithExternalSystemsThread;
  if (pthread_create(&integrateWithExternalSystemsThread, NULL, integrateWithExternalSystems, NULL) != 0) {
