    new_node->rx_ue_info = rand() % 10;
    new_node->crci = rand();
    new_node->crcflag = (rand() % 2) ? CRCFLAG_PRESENT : CRCFLAG_NOT_PRESENT;
    if (head == NULL) {
        head = tail = new_node;
