#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Data structure for the LTE MME context
typedef struct {
    EPS_BEARER_ID bearer_id;
    UE_ID ue_id;
    S1AP_MESSAGE message;
} LTE_MME_CONTEXT;

// Doubly linked list of LTE MME contexts
typedef struct {
    pthread_mutex_t mutex; // Mutex for thread-safe access and modification of the list
    LTE_MME_CONTEXT* head; // Head node of the doubly linked list
    LTE_MME_CONTEXT* tail; // Tail node of the doubly linked list
} LTE_MME_LIST;

// Function to create a new LTE MME context and add it to the list
int lte_mme_add(LTE_MME_LIST* list, EPS_BEARER_ID bearer_id, UE_ID ue_id, S1AP_MESSAGE message) {
    // Check if the LTE MME context already exists in the list
    LTE_MME_CONTEXT* current = list->head;
    while (current != NULL) {
        if (current->bearer_id == bearer_id && current->ue_id == ue_id) {
            return 0; // Already exists, don't add it again
        }
        current = current->next;
    }

    // Create a new LTE MME context and add it to the list
    LTE_MME_CONTEXT* node = malloc(sizeof(LTE_MME_CONTEXT));
    if (node == NULL) {
        return -1; // Memory allocation failure, return error code
    }
    node->bearer_id = bearer_id;
    node->ue_id = ue_id;
    node->message = message;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) { // List is empty, add the new node as head and tail
        list->head = node;
        list->tail = node;
    } else { // Add the new node to the end of the list
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->mutex);

    return 1; // Successfully added the LTE MME context to the list
}

// Function to remove a LTE MME context from the list
int lte_mme_remove(LTE_MME_LIST* list, EPS_BEARER_ID bearer_id, UE_ID ue_id) {
    // Check if the LTE MME context exists in the list
    LTE_MME_CONTEXT* current = list->head;
    while (current != NULL) {
        if (current->bearer_id == bearer_id && current->ue_id == ue_id) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) { // LTE MME context doesn't exist in the list, return error code
        return -1;
    }

    // Remove the LTE MME context from the list
    pthread_mutex_lock(&list->mutex);
    if (current == list->head) { // Node is the head of the list, update the head and tail pointers
        list->head = current->next;
        if (list->head == NULL) {
            list->tail = NULL;
        } else {
            list->tail = current->next;
        }
    } else { // Node is not the head of the list, update the next pointer of the previous node
        LTE_MME_CONTEXT* previous = current->previous;
        previous->next = current->next;
        if (previous->next == NULL) {
            list->tail = previous;
        }
    }
    pthread_mutex_unlock(&list->mutex);

    free(current); // Free the memory of the LTE MME context

    return 1; // Successfully removed the LTE MME context from the list
}

// Function to process a S1AP message and add/remove LTE MME contexts as needed
int lte_mme_process(LTE_MME_LIST* list, S1AP_MESSAGE* message) {
    // Check if the S1AP message is a UE association response or a UE disassociation request
    if (message->type == S1AP_UE_ASSOCIATION_RESPONSE || message->type == S1AP_UE_DISASSOCIATION_REQUEST) {
        // Get the EPS bearer ID and UE ID from the S1AP message
        EPS_BEARER_ID bearer_id = message->bearer_id;
        UE_ID ue_id = message->ue_id;

        // Check if the LTE MME context already exists in the list
        LTE_MME_CONTEXT* current = list->head;
        while (current != NULL) {
            if (current->bearer_id == bearer_id && current->ue_id == ue_id) {
                break;
            }
            current = current->next;
        }
        if (current == NULL) { // LTE MME context doesn't exist in the list, add it
            lte_mme_add(list, bearer_id, ue_id, message);
        } else { // LTE MME context already exists in the list, remove it
            lte_mme_remove(list, bearer_id, ue_id);
        }
    }

    return 1; // Successfully processed the S1AP message and added/removed LTE MME contexts as needed
}
