uint64_t num_successful_receptions = 0;

// Number of dropped packets
uint64_t num_dropped_packets = 0;

// Mutex for protecting concurrent access to rx_buffer and counters
pthread_mutex_t mutex;

// Function to manage the dynamic array of MAC_RX_BUFFER_T structures
void manage_rx_buffer(const LAYER2_PDU_HEADER *header, const PHY_STATISTICS *stats, const RX_TIMESTAMP *timestamp) {
    // Acquire mutex for protecting concurrent access to rx_buffer and counters
    pthread_mutex_lock(&mutex);

    // Check if the dynamic array is NULL or not yet allocated
    if (rx_buffer == NULL) {
        // Allocate memory for the dynamic array of MAC_RX_BUFFER_T structures
        rx_buffer = malloc(sizeof(MAC_RX_BUFFER_T));
        if (rx_buffer == NULL) {
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Check if the dynamic array is full or not yet allocated
    if (rx_buffer->size < rx_buffer->capacity) {
        // Add new packet to the dynamic array of MAC_RX_BUFFER_T structures
        rx_buffer[rx_buffer->size].header = *header;
        rx_buffer[rx_buffer->size].stats = *stats;
        rx_buffer[rx_buffer->size].timestamp = *timestamp;
        rx_buffer->size++;
    } else {
        // Drop oldest packet if the dynamic array is full
        rx_buffer[rx_buffer->start].header.valid = 0;
        rx_buffer->start++;
        num_dropped_packets++;
    }

    // Increment number of successful packet receptions
    num_successful_receptions++;

    // Release mutex for protecting concurrent access to rx_buffer and counters
    pthread_mutex_unlock(&mutex);
}

// Function to evaluate the performance metrics of the dynamic array of MAC_RX_BUFFER_T structures
void evaluate_performance() {
    // Acquire mutex for protecting concurrent access to rx_buffer and counters
    pthread_mutex_lock(&mutex);

    // Evaluate number of successful packet receptions
    float num_successful_receptions_ratio = (float)num_successful_receptions / (float)rx_buffer->size;
    if (num_successful_receptions_ratio > 0.5) {
        // If number of successful packet receptions is higher than 50%,
        // adjust the capacity of the dynamic array to a larger size
        rx_buffer->capacity *= 2;
    } else if (num_successful_receptions_ratio < 0.3) {
        // If number of successful packet receptions is lower than 30%,
        // adjust the capacity of the dynamic array to a smaller size
        rx_buffer->capacity /= 2;
    }

    // Evaluate number of dropped packets
    float num_dropped_packets_ratio = (float)num_dropped_packets / (float)rx_buffer->size;
    if (num_dropped_packets_ratio > 0.1) {
        // If number of dropped packets is higher than 10%,
        // adjust the capacity of the dynamic array to a larger size
        rx_buffer->capacity *= 2;
    } else if (num_dropped_packets_ratio < 0.05) {
        // If number of dropped packets is lower than 5%,
        // adjust the capacity of the dynamic array to a smaller size
        rx_buffer->capacity /= 2;
    }

    // Release mutex for protecting concurrent access to rx_buffer and counters
    pthread_mutex_unlock(&mutex);
}
