// Function to initialize and populate dynamic array of CellMeasurementReport structures
bool initAndPopulateCellMeasurementReports(struct CellMeasurementReport **reports, unsigned int numReports) {
    // Check if numReports is greater than 0
    if (numReports == 0) {
        return false;
    }

    // Dynamically allocate memory for reports array
    *reports = malloc(sizeof(struct CellMeasurementReport) * numReports);
    if (*reports == NULL) {
        // Handle allocation failure gracefully by logging a message and continuing with degraded performance
        fprintf(stderr, "Error: Failed to allocate memory for reports array\n");
        return false;
    }

    // Initialize each report structure in the reports array
    for (int i = 0; i < numReports; i++) {
        (*reports)[i].cellIdentity = 0;
        (*reports)[i].rssi = 0;
        (*reports)[i].cqi = 'X';
        (*reports)[i].snr = 0.0f;
    }

    // Fetch expected noise floor value from external data source
    float noiseFloorValue = getNoiseFloorValue();

    // Calculate SNR for each report structure in the reports array
    for (int i = 0; i < numReports; i++) {
        (*reports)[i].snr = calculateSnr((*reports)[i].rssi, noiseFloorValue);
    }

    return true;
}

// Function to get expected noise floor value from external data source
float getNoiseFloorValue() {
    // Implement mechanism to handle intermittent connectivity issues and potential delays in fetching the noise floor value
    float noiseFloorValue = 0.0f;
    bool success = false;
    while (!success) {
        // Attempt to fetch the noise floor value from an external data source
        try {
            noiseFloorValue = getNoiseFloorValueFromExternalSource();
            success = true;
        } catch (const std::exception &e) {
            // Handle potential connectivity issues or other errors gracefully by logging a message and retrying
            fprintf(stderr, "Error: Failed to fetch noise floor value from external data source\n");
            sleep(1);  // Sleep for 1 second before retrying
        }
    }

    return noiseFloorValue;
}

// Function to calculate SNR based on RSSI and expected noise floor value
float calculateSnr(short rssi, float noiseFloorValue) {
    if (rssi == 0 || noiseFloorValue == 0.0f) {
        return 0.0f;
    }

    return (float)(rssi - noiseFloorValue) / (float)rssi;
}
