['package com.example;

import java.net.*;
import java.util.concurrent.*;

public class ConnectionManager {
    private static final int DEFAULT_CONNECTION_TIMEOUT = 10 * 1000; // 10 seconds
    private static final int MAX_RETRY_COUNT = 3;

    public static Socket establishConnection(String host, int port, boolean useTCP) throws IOException {
        Socket socket = null;
        for (int i = 0; i < MAX_RETRY_COUNT; i++) {
            try {
                if (useTCP) {
                    socket = new Socket(host, port);
                } else {
                    socket = new DatagramSocket();
                }

                return socket;
            } catch (IOException e) {
                // ignore and retry
            }
        }

        throw new IOException("Failed to establish connection after " + MAX_RETRY_COUNT + " retries.");
    }

    public static Socket establishConnection(String host, int port, boolean useTCP, long timeout) throws IOException {
        if (timeout <= 0) {
            return establishConnection(host, port, useTCP);
        }

        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<Socket> future = executor.submit(() -> establishConnection(host, port, useTCP));

        try {
            Socket socket = future.get(timeout, TimeUnit.MILLISECONDS);
            return socket;
        } catch (TimeoutException e) {
            future.cancel(true);
            throw new IOException("Connection timeout after " + timeout + " milliseconds.");
        } finally {
            executor.shutdown();
        }
    }
}']

