// Function definitions
void init_network_interfaces(const int max_packets) {
    for (int i = 0; i < MAX_INTERFACES; i++) {
        interface_stats[i] = malloc(sizeof(NetworkInterfaceStats));
        if (interface_stats[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
}

void add_packet(const int interfaceID, const size_t packet_size, const timestamp_t timestamp) {
    if (num_interfaces > MAX_INTERFACES || interfaceID < 0 || interfaceID >= num_interfaces) {
        return;
    }
    NetworkInterfaceStats *stats = interface_stats[interfaceID];
    int packet_idx = stats->rx_stats.len;
    if (packet_idx >= MAX_PACKETS) {
        return;
    }
    stats->rx_stats[packet_idx].packet_size = packet_size;
    stats->rx_stats[packet_idx].timestamp = timestamp;
}

void update_link_status(const int interfaceID, const LinkLayerStatus status) {
    if (num_interfaces > MAX_INTERFACES || interfaceID < 0 || interfaceID >= num_interfaces) {
        return;
    }
    NetworkInterfaceStats *stats = interface_stats[interfaceID];
    stats->link_status = status;
}

void clear_rx_packets(const int interfaceID) {
    if (num_interfaces > MAX_INTERFACES || interfaceID < 0 || interfaceID >= num_interfaces) {
        return;
    }
    NetworkInterfaceStats *stats = interface_stats[interfaceID];
    stats->rx_stats.len = 0;
}

void print_network_interfaces() {
    for (int i = 0; i < num_interfaces; i++) {
        printf("Interface %d: ", i);
        NetworkInterfaceStats *stats = interface_stats[i];
        for (int j = 0; j < stats->rx_stats.len; j++) {
            printf("%luB, ", stats->rx_stats[j].packet_size);
        }
        switch (stats->link_status) {
            case UP:
                printf("Link is up\n");
                break;
            case DOWN:
                printf("Link is down\n");
                break;
            default:
                printf("Link status unknown\n");
        }
    }
}
