// Function to add a new TCP connection record to the dynamic array
void add_tcp_connection(const char *client_ip, const char *server_ip, time_t timestamp, int status) {
    // Check if the dynamic array is full and needs to be resized
    if (tcp_connection_count == tcp_connection_capacity) {
        // Double the size of the dynamic array
        tcp_connection_capacity *= 2;
        TCP_CONNECTION_RECORD *tmp = realloc(tcp_connection_array, tcp_connection_capacity * sizeof(TCP_CONNECTION_RECORD));
        if (tmp == NULL) {
            // Reallocation failed, exit the function with an error
            printf("Failed to add TCP connection record: out of memory\n");
            return;
        } else {
            tcp_connection_array = tmp;
        }
    }

    // Add the new TCP connection record to the dynamic array
    strncpy(tcp_connection_array[tcp_connection_count].client_ip, client_ip, 15);
    strncpy(tcp_connection_array[tcp_connection_count].server_ip, server_ip, 15);
    tcp_connection_array[tcp_connection_count].timestamp = timestamp;
    tcp_connection_array[tcp_connection_count].status = status;
    tcp_connection_count++;
}

