// Doubly linked list to store the NFAPI_CRC_INDICATION_PDU structures
struct NFAPI_CRC_INDICATION_PDU_LIST {
    struct NFAPI_CRC_INDICATION_PDU *prev;
    struct NFAPI_CRC_INDICATION_PDU *next;
};

// Custom memory pool to optimize memory usage and reduce overhead
struct MEMORY_POOL {
    struct NFAPI_CRC_INDICATION_PDU *pool;
    size_t currentSize;
    size_t maxSize;
};

// Function to dynamically manage the array of NFAPI_CRC_INDICATION_PDU structures
void nfapi_crc_indication_pdu_list(struct NFAPI_CRC_INDICATION_PDU_LIST **list, unsigned int rxUeInformationTag, unsigned int rnti) {
    // Check if the current list is empty and allocate a new memory pool if necessary
    if (*list == NULL) {
        *list = (struct NFAPI_CRC_INDICATION_PDU_LIST *) malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_LIST));
        (*list)->prev = NULL;
        (*list)->next = NULL;
    }

    // Allocate a new structure and assign the provided values
    struct NFAPI_CRC_INDICATION_PDU *newStruct = (struct NFAPI_CRC_INDICATION_PDU *) malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU));
    newStruct->rxUeInformationTag = rxUeInformationTag;
    newStruct->rnti = rnti;

    // Add the new structure to the end of the list
    struct NFAPI_CRC_INDICATION_PDU_LIST *current = *list;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = newStruct;
    newStruct->prev = current;

    // Update the memory pool size if necessary
    if ((*list)->currentSize >= (*list)->maxSize) {
        struct NFAPI_CRC_INDICATION_PDU_LIST *newPool = (struct NFAPI_CRC_INDICATION_PDU_LIST *) malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_LIST));
        newPool->prev = (*list)->prev;
        newPool->next = NULL;
        (*list)->prev->next = newPool;
        (*list)->prev = newPool;
        (*list)->maxSize *= 2;
    }

    // Increment the current size of the list
    (*list)->currentSize++;
}

// Function to periodically clean up unused structures and free memory
void nfapi_crc_indication_pdu_cleanup(struct NFAPI_CRC_INDICATION_PDU_LIST **list) {
    struct NFAPI_CRC_INDICATION_PDU_LIST *current = *list;

    // Iterate through the list and free unused structures
    while (current != NULL) {
        if (current->next == NULL) {
            break;
        } else if (current->next->prev == current && current->next->crcFlag == 0) {
            struct NFAPI_CRC_INDICATION_PDU_LIST *toFree = current->next;
            current->next = toFree->next;
            free(toFree);
        } else {
            current = current->next;
        }
    }

    // Update the memory pool size if necessary
    if ((*list)->currentSize < (*list)->maxSize / 2) {
        struct NFAPI_CRC_INDICATION_PDU_LIST *toFree = (*list)->prev;
        (*list)->prev->next = NULL;
        free(toFree);
        (*list)->maxSize /= 2;
    }
}

// Function to retrieve the most recently used active structure efficiently
struct NFAPI_CRC_INDICATION_PDU *nfapi_crc_indication_pdu_get_most_recent(struct NFAPI_CRC_INDICATION_PDU_LIST **list) {
    struct NFAPI_CRC_INDICATION_PDU_LIST *current = *list;

    // Iterate through the list and find the most recently used active structure
    while (current != NULL) {
        if (current->next == NULL || current->crcFlag != 0) {
            break;
        } else {
            current = current->next;
        }
    }

    return current;
}

