use std::time::Duration;
use reqwest::blocking::{Client, RequestBuilder};
use futures::StreamExt;
use tokio::time::sleep;

pub struct HttpClient {
    client: Client,
}

impl HttpClient {
    pub fn new(timeout: Duration) -> Self {
        let mut headers = reqwest::header::HeaderMap::new();
        headers.insert("Authorization", "Bearer <API_KEY>");

        let client = Client::builder()
            .timeout(timeout)
            .default_headers(headers)
            .build()?;

        Self { client }
    }

    pub fn get(&self, url: &str) -> RequestBuilder {
        self.client.get(url).header("X-Custom-Header", "custom value")
    }

    pub fn post(&self, url: &str) -> RequestBuilder {
        self.client.post(url).header("X-Custom-Header", "custom value")
    }

    pub fn put(&self, url: &str) -> RequestBuilder {
        self.client.put(url).header("X-Custom-Header", "custom value")
    }

    pub fn patch(&self, url: &str) -> RequestBuilder {
        self.client.patch(url).header("X-Custom-Header", "custom value")
    }

    pub fn delete(&self, url: &str) -> RequestBuilder {
        self.client.delete(url).header("X-Custom-Header", "custom value")
    }

    pub fn stream<T>(&self, url: &str, timeout: Duration, f: T) -> anyhow::Result<()>
    where
        T: Fn(serde_json::Value) + Send + 'static,
    {
        let mut response = self.client.stream(url)?;
        while let Some(result) = response.next().await {
            if let Ok(value) = result {
                f(value);
            } else {
                break;
            }
        }
        Ok(())
    }

    pub fn execute<T>(&self, url: &str, timeout: Duration, f: T) -> anyhow::Result<()>
    where
        T: Fn(serde_json::Value) + Send + 'static,
    {
        let mut response = self.client.execute(url)?;
        if let Ok(value) = response.text().await? {
            f(value);
        }
        Ok(())
    }
}
