    char *metadata;
    int status; // active or inactive
    struct record *next;
} record;

// Define the function that manages the array of PDUs and the linked list of records
void manage_array(int num_pdu, int max_num_records) {
    // Initialize the arrays for the PDUs and the records
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdu);
    if (!pdu) {
        // Handle memory allocation failure
        return;
    }
    int *long_offset = (int *)malloc(sizeof(int) * max_num_records);
    if (!long_offset) {
        free(pdu);
        return;
    }
    int *keys = (int *)malloc(sizeof(int) * max_num_records);
    if (!keys) {
        free(pdu);
        free(long_offset);
        return;
    }
    record *head = NULL, *tail = NULL;

    // Populate the PDUs and the linked list of records
    for (int i = 0; i < num_pdu; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = rand() % 1000000 + 1;
        pdu[i].RNTI = rand() % 65535 + 1;
        pdu[i].CRCFLAG = (rand() % 2 == 0) ? 1 : 0;
        pdu[i].CRC_INDICATION_REL8_TAG = rand() % 1000000 + 1;

