        int value = rand() % 10000 + 1;
        char metadata[256];
        sprintf(metadata, "Record %d", i);
        record *new_record = (record *)malloc(sizeof(record));
        if (!new_record) {
            free(pdu);
            free(long_offset);
            free(keys);
            return;
        }
        new_record->value = value;
        new_record->metadata = strdup(metadata);
        new_record->status = 1;
        new_record->next = NULL;
        if (head == NULL) {
            head = tail = new_record;
        } else {
            tail->next = new_record;
            tail = new_record;
        }
    }

    // Periodically clean up inactive records to free up memory
    while (head != NULL && head->status == 0) {
        record *temp = head;
        head = head->next;
        free(temp);
    }

    // Serialize and deserialize the linked list of records to persist state across application restarts
    FILE *file = fopen("record_list.bin", "wb");
    if (!file) {
        free(pdu);
        free(long_offset);
        free(keys);
        return;
    }
    fwrite(&head, sizeof(record), 1, file);
    fclose(file);
    file = fopen("record_list.bin", "rb");
    if (!file) {
        free(pdu);
        free(long_offset);
        free(keys);
        return;
    }
    fread(&head, sizeof(record), 1, file);
    fclose(file);
}
