void add_vlan_id(NICP *nicp, uint16_t vlan_id) {
    // Allocate memory for the new VLAN ID and Ethernet Frame
    uint16_t *new_vlan_ids = malloc(sizeof(uint16_t) * (nicp->num_vlan_ids + 1));
    EthernetFrame *new_frames = malloc(sizeof(EthernetFrame) * (nicp->num_frames + 1));

    // Copy the existing VLAN IDs and Ethernet Frames to the new arrays
