    new_frames[nicp->num_frames] = create_ethernet_frame(nicp->mac_header, vlan_id);

    // Free the old arrays and replace them with the new ones
    free(nicp->vlan_ids);
    free(nicp->frames);
    nicp->vlan_ids = new_vlan_ids;
    nicp->frames = new_frames;

    // Increment the number of VLAN IDs and Ethernet Frames
    nicp->num_vlan_ids++;
    nicp->num_frames++;
}

// Function to dynamically delete a VLAN ID from an existing NICP structure
void del_vlan_id(NICP *nicp, uint16_t vlan_id) {
    // Find the index of the VLAN ID in the array
    size_t i = 0;
    while (i < nicp->num_vlan_ids && nicp->vlan_ids[i] != vlan_id) {
        i++;
    }

    // If the VLAN ID is found, remove it from the array and free its associated Ethernet Frame
    if (i < nicp->num_vlan_ids) {
        uint16_t *new_vlan_ids = malloc(sizeof(uint16_t) * (nicp->num_vlan_ids - 1));
        EthernetFrame *new_frames = malloc(sizeof(EthernetFrame) * (nicp->num_frames - 1));

        // Copy the existing VLAN IDs and Ethernet Frames to the new arrays, excluding the one being deleted
        for (size_t j = 0; j < i; j++) {
            new_vlan_ids[j] = nicp->vlan_ids[j];
            new_frames[j] = nicp->frames[j];
        }
        for (size_t j = i + 1; j < nicp->num_vlan_ids; j++) {
            new_vlan_ids[j - 1] = nicp->vlan_ids[j];
            new_frames[j - 1] = nicp->frames[j];
        }

        // Free the old arrays and replace them with the new ones
        free(nicp->vlan_ids);
        free(nicp->frames);
        nicp->vlan_ids = new_vlan_ids;
        nicp->frames = new_frames;

        // Decrement the number of VLAN IDs and Ethernet Frames
        nicp->num_vlan_ids--;
        nicp->num_frames--;
    }
}

