<?php

function updateClinicStatuses($clinicIds, $statusUpdates) {
    // Ensure that the clinic IDs and status updates are valid
    if (!is_array($clinicIds) || !is_array($statusUpdates)) {
        return false;
    }

    // Iterate over each clinic ID and associated status update
    foreach ($clinicIds as $key => $clinicId) {
        $statusUpdate = $statusUpdates[$key];

        // Ensure that the clinic ID is a valid integer
        if (!is_int($clinicId)) {
            return false;
        }

        // Ensure that the status update is a valid string
        if (!is_string($statusUpdate) || !in_array($statusUpdate, ['active', 'inactive'])) {
            return false;
        }
    }

    // Prepare the database connection and query
    $pdo = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
    $query = 'UPDATE clinics SET status = :status, last_modified_ip = :last_modified_ip, last_updated = NOW() WHERE id IN (:clinicIds)';

    // Bind the clinic IDs and status updates to the query parameters
    $statement = $pdo->prepare($query);
    foreach ($clinicIds as $key => $clinicId) {
        $statusUpdate = $statusUpdates[$key];
        $statement->bindValue(':clinicIds', $clinicId, PDO::PARAM_INT);
        $statement->bindValue(':status', $statusUpdate, PDO::PARAM_STR);
        $statement->bindValue(':last_modified_ip', $_SERVER['REMOTE_ADDR'], PDO::PARAM_STR);
    }

    // Execute the query and handle potential failures
    try {
        $statement->execute();
        return true;
    } catch (PDOException $e) {
        // Retry mechanism for failed updates
        if ($statement->errorCode() === '08S01') {
            sleep(pow(2, $retries)); // Exponential backoff
            return updateClinicStatuses($clinicIds, $statusUpdates, $retries + 1);
        } else {
            return false;
        }
    } finally {
        $statement->closeCursor();
    }
}
```
