    int payload_size;
    bool processed;
} data_packet_t;

typedef struct {
    data_packet_t* packets;
    size_t num_packets;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} packet_manager_t;

// Function to initialize the packet manager
void init_packet_manager(packet_manager_t* pm) {
    // Initialize the packet array with a fixed size
    pm->packets = malloc(sizeof(data_packet_t) * 1024);
    pm->num_packets = 0;

    // Initialize the mutex and semaphore for synchronization
    pthread_mutex_init(&pm->mutex, NULL);
    semaphore_init(&pm->semaphore, 0);
}

// Function to add a new DataPacket to the manager
void add_packet(packet_manager_t* pm, long timestamp, int payload_size) {
    pthread_mutex_lock(&pm->mutex);

    // Check if there is enough space in the array for the new packet
    if (pm->num_packets >= 1024) {
        // Reallocate the array to accommodate more packets
        pm->packets = realloc(pm->packets, sizeof(data_packet_t) * 2 * pm->num_packets);
    }

    // Add the new packet to the array and update the count
    pm->packets[pm->num_packets].timestamp = timestamp;
    pm->packets[pm->num_packets].payload_size = payload_size;
    pm->packets[pm->num_packets].processed = false;
    pm->num_packets++;

    pthread_mutex_unlock(&pm->mutex);
}

// Function to update the processing status of a DataPacket
void update_packet(packet_manager_t* pm, int index, bool processed) {
    pthread_mutex_lock(&pm->mutex);

    // Update the packet's processing status
    pm->packets[index].processed = processed;

    pthread_mutex_unlock(&pm->mutex);
}

// Function to retrieve a DataPacket from the manager
void get_packet(packet_manager_t* pm, int index, data_packet_t* packet) {
    pthread_mutex_lock(&pm->mutex);

    // Copy the requested packet into the output parameter
    memcpy(packet, &pm->packets[index], sizeof(data_packet_t));

    pthread_mutex_unlock(&pm->mutex);
}

// Function to retrieve all DataPackets from the manager
void get_all_packets(packet_manager_t* pm, data_packet_t** packets) {
    pthread_mutex_lock(&pm->mutex);

    // Copy all packets into the output parameter
    memcpy(packets, pm->packets, sizeof(data_packet_t) * pm->num_packets);

    pthread_mutex_unlock(&pm->mutex);
}
