    char *random_string = malloc(MAX_INPUT_LENGTH * sizeof(char));
    if (random_string == NULL) {
        perror("Failed to allocate memory for random string");
        exit(1);
    }

    // hash a password using a secure default hash function
    char *password = malloc(PASSWORD_LENGTH * sizeof(char));
    if (password == NULL) {
        perror("Failed to allocate memory for password");
        exit(1);
    }

    // initialize the logging mechanism
    FILE *log_file = fopen("log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    // process the inputs and generate the necessary data structures
    for (int i = 0; i < num_inputs; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = 1; // set to a valid value
        pdu.RNTI = inputs[i];
        pdu.CRC_INDICATION_REL8_TAG = 0; // set to a random value
        rand_string(random_string, MAX_INPUT_LENGTH, CHARACTER_SET);
        hash_password(password, PASSWORD_LENGTH, random_string);
        log_error("Input %d: max value = %d, random string = %s, password = %s\n", i, max_value, random_string, password);
        pdu_list[i] = pdu;
    }

    // manage the semaphore with thread-safe operations
    sem_wait(semaphore); // decrement the semaphore value
    log_error("Semaphore value after waiting: %d\n", semaphore->sem_value);
    sem_post(semaphore); // increment the semaphore value
    log_error("Semaphore value after posting: %d\n", semaphore->sem_value);

    // free memory allocated for the data structures
    free(inputs);
    free(pdu_list);
    free(random_string);
    free(password);
    log_error("Memory deallocated successfully");
}

// generate a random string of the specified length using the given character set
void rand_string(char *str, size_t size, const char *character_set) {
    if (size == 0 || str == NULL || character_set == NULL) {
        return;
    }

    for (int i = 0; i < size; i++) {
        str[i] = character_set[rand() % (strlen(character_set))];
    }

    str[size - 1] = '\0'; // null terminate the string
}

// hash a password using a secure default hash function
void hash_password(char *password, size_t length, const char *salt) {
    if (length == 0 || password == NULL || salt == NULL) {
        return;
    }

    EVP_MD_CTX *mdctx = EVP_MD_CTX_create();
    const EVP_MD *md = EVP_get_digestbyname("SHA256"); // use SHA-256 as the hash function

    if (!EVP_DigestInit(mdctx, md)) {
        return;
    }

    EVP_DigestUpdate(mdctx, password, strlen(password)); // update the message digest with the password
    EVP_DigestUpdate(mdctx, salt, strlen(salt)); // update the message digest with the salt

    unsigned char hash[EVP_MAX_MD_SIZE];
    unsigned int hash_size = sizeof(hash);

    if (!EVP_DigestFinal(mdctx, hash, &hash_size)) {
        return;
    }

    for (int i = 0; i < hash_size; i++) {
        password[i] = hash[i]; // copy the hashed password to the original variable
    }
}

// log an error message with a specified format and arguments
void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
}
