} queue_t;

// Initialize a queue with the given capacity
queue_t* queue_init(int capacity) {
    queue_t* q = (queue_t*)malloc(sizeof(queue_t));
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
    q->size = 0;
    q->capacity = capacity;
    q->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    return q;
}

// Add an element to the queue, blocking until there is room available
void queue_put(queue_t* q, NFAPI_CRC_INDICATION_PDU_T elem) {
    pthread_mutex_lock(&q->mutex);
    while (q->size == q->capacity) {
        // Wait for space to become available
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    q->data[q->size++] = elem;
    pthread_mutex_unlock(&q->mutex);
}

// Remove an element from the queue, blocking until there is an element available
NFAPI_CRC_INDICATION_PDU_T queue_get(queue_t* q) {
    NFAPI_CRC_INDICATION_PDU_T elem;
    pthread_mutex_lock(&q->mutex);
    while (q->size == 0) {
        // Wait for an element to become available
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    elem = q->data[--q->size];
    pthread_mutex_unlock(&q->mutex);
    return elem;
}

// Serialize the queue to a binary file
void queue_serialize(queue_t* q, const char* filename) {
    FILE* f = fopen(filename, "wb");
    if (f == NULL) {
        printf("Failed to open file: %s\n", strerror(errno));
        return;
