        fwrite(elem, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, f);
    }
    // Close the file and return
    fclose(f);
}

// Deserialize the queue from a binary file
void queue_deserialize(queue_t* q, const char* filename) {
    FILE* f = fopen(filename, "rb");
    if (f == NULL) {
        printf("Failed to open file: %s\n", strerror(errno));
        return;
    }
    // Read the size of the queue from the beginning of the file
    int size = 0;
    fread(&size, sizeof(int), 1, f);
    if (size > q->capacity) {
        printf("File size exceeds capacity: %d > %d\n", size, q->capacity);
        return;
