    // Read each element from the file and add it to the queue
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T elem;
        fread(&elem, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, f);
        queue_put(q, elem);
    }
    // Close the file and return
    fclose(f);
}

// Free a queue's memory
