    pthread_mutex_lock(&mutex);

    // Check if the array is already initialized
    if (array != NULL) {
        free(array);
        array = NULL;
    }

    // Allocate memory for the array of NFAPI_MESSAGE_PDU_T structures
    array = malloc(sizeof(NFAPI_MESSAGE_PDU_T) * num_messages);
    if (array == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error: failed to allocate memory for the array
    }

    // Initialize each structure in the array with a valid message identifier, sequence number, and payload length
    for (size_t i = 0; i < num_messages; i++) {
        NFAPI_MESSAGE_PDU_T *structure = &array[i];
        structure->message_id = i + 1;
        structure->sequence_number = i + 1;
        structure->payload_length = 0;
    }

