int add_message(int message_id, int sequence_number, size_t payload_length, char *payload) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the array is already initialized
    if (array == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error: array not initialized
    }

    // Check if there is enough memory to add a new message
    size_t current_size = sizeof(NFAPI_MESSAGE_PDU_T) * (array_length + 1);
    char *new_memory = realloc(array, current_size);
    if (new_memory == NULL) {
        pthread_mutex_unlock(&mutex);
        return -2; // Error: failed to allocate memory for the new message
    }
    array = new_memory;

    // Add the new message to the end of the array
    NFAPI_MESSAGE_PDU_T *structure = &array[array_length];
    structure->message_id = message_id;
    structure->sequence_number = sequence_number;
    structure->payload_length = payload_length;
    structure->payload = malloc(payload_length);
    if (structure->payload == NULL) {
        pthread_mutex_unlock(&mutex);
        return -3; // Error: failed to allocate memory for the message payload
    }
    memcpy(structure->payload, payload, payload_length);

    array_length++;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
    return 0; // Success: added a new message to the array of NFAPI_MESSAGE_PDU_T structures
}

// Function to remove a message from the array of NFAPI_MESSAGE_PDU_T structures
int remove_message(size_t index) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the array is already initialized and the index is valid
    if (array == NULL || index >= array_length) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error: invalid index or array not initialized
    }

    // Get a pointer to the message structure to be removed
    NFAPI_MESSAGE_PDU_T *structure = &array[index];

    // Free the memory allocated for the payload
    free(structure->payload);

    // Shift all subsequent messages in the array to fill the gap
    size_t remaining_messages = array_length - index - 1;
    if (remaining_messages > 0) {
        memmove(&array[index], &array[index + 1], remaining_messages * sizeof(NFAPI_MESSAGE_PDU_T));
    }

    // Decrement the length of the array
    array_length--;

    // Reallocate memory for the array if necessary
    size_t current_size = sizeof(NFAPI_MESSAGE_PDU_T) * array_length;
    char *new_memory = realloc(array, current_size);
    if (new_memory == NULL) {
        pthread_mutex_unlock(&mutex);
        return -2; // Error: failed to reallocate memory for the array
    }
    array = new_memory;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
    return 0; // Success: removed a message from the array of NFAPI_MESSAGE_PDU_T structures
}

