NFAPI_MESSAGE_PDU_T *get_message(size_t index) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the array is already initialized and the index is valid
    if (array == NULL || index >= array_length) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Error: invalid index or array not initialized
    }

    // Get a pointer to the message structure at the specified index
    NFAPI_MESSAGE_PDU_T *structure = &array[index];

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
