    pthread_mutex_lock(&array1->mutex);

    // Check if both arrays have the same number of elements
    if (array1->num_entries != array2->num_entries) {
        printf("Error: Number of elements not equal\n");
        pthread_mutex_unlock(&array1->mutex);
        return;
    }

    // Iterate over each element in the arrays and compare the CRCFLAG values
