  // Remove the element from the list
  NFAPI_CRC_INDICATION_PDU_T* pdu = list->pdu[index];
  free(pdu);
  memmove(&list->pdu[index], &list->pdu[index + 1], (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  list->size--;

  return true;
}

bool nfapi_crc_indication_list_remove_all(NFAPI_CRC_INDICATION_LIST* list) {
  // Remove all elements from the list
  for (int i = 0; i < list->size; i++) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = list->pdu[i];
    free(pdu);
  }
  list->size = 0;

  return true;
}

bool nfapi_crc_indication_list_resize(NFAPI_CRC_INDICATION_LIST* list, size_t capacity) {
  // Check if the new capacity is valid
  if (capacity == 0 || capacity > MAX_LIST_SIZE) {
    return false;
  }

  // Allocate memory for the new array of elements
  NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
  if (pdu == NULL) {
    return false;
  }

  // Copy the elements from the old array to the new one
  for (int i = 0; i < list->size; i++) {
    pdu[i] = list->pdu[i];
  }

  // Free the memory of the old array
  free(list->pdu);

  // Update the list properties
  list->capacity = capacity;
  list->pdu = pdu;

  return true;
}

void nfapi_crc_indication_list_cleanup(NFAPI_CRC_INDICATION_LIST* list) {
  // Clean up the elements of the list
  for (int i = 0; i < list->size; i++) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = list->pdu[i];
    free(pdu);
  }
}

void nfapi_crc_indication_list_print(NFAPI_CRC_INDICATION_LIST* list) {
  // Print the elements of the list
  printf("NFAPI CRC Indication List (%lu elements):\n", list->size);
  for (int i = 0; i < list->size; i++) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = list->pdu[i];
    printf("  %d: %s, %s\n", pdu->rnti, pdu->rxUeInformation, pdu->crcIndicationRel8);
  }
}

void nfapi_crc_indication_list_check_stale(NFAPI_CRC_INDICATION_LIST* list) {
  // Check the elements of the list for stale entries older than `T` seconds
  time_t current_time = time(NULL);
  int threshold = CLEANUP_INTERVAL * 10; // `T` seconds in milliseconds
  for (int i = 0; i < list->size; i++) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = list->pdu[i];
    if (difftime(current_time, pdu->crcIndicationRel8) > threshold) {
      nfapi_crc_indication_list_remove(list, i--);
    }
  }
}

