    // Open the file for reading
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        return -1;
    }

    // Read the size of the array from the file
    size_t read = fread(&config_array->size, sizeof(size_t), 1, fp);
    if (read != 1) {
        fclose(fp);
        return -2;
    }

    // Allocate memory for the array
    config_array->capacity = config_array->size;
    LTE_PHY_TEST_CONFIG_T* new_configs = malloc(config_array->capacity * sizeof(LTE_PHY_TEST_CONFIG_T));
    if (new_configs == NULL) {
        fclose(fp);
        return -3;
    }
    config_array->configs = new_configs;

    // Read each configuration from the file
    for (size_t i = 0; i < config_array->size; i++) {
        read = fread(&config_array->configs[i], sizeof(LTE_PHY_TEST_CONFIG_T), 1, fp);
        if (read != 1) {
            fclose(fp);
            return -4;
        }
    }

    // Close the file
    fclose(fp);

    return 0;
}
