#include <pthread.h>

// Macros for randomization bounds and cache size
#define RX_UE_INFORMATION_TAG_MIN 0
#define RX_UE_INFORMATION_TAG_MAX 1000
#define RNTI_MIN 0
#define RNTI_MAX 1000
#define CACHE_SIZE 128

// Structures and typedefs
typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    bool initialized;
    size_t count;
    size_t cache_hits;
    size_t cache_misses;
    NFAPI_CRC_INDICATION_PDU_T *cache[CACHE_SIZE];
} CRC_LIST_T;

// Function to populate the list with input parameters
void populate_crc_list(CRC_LIST_T *list, const uint32_t rx_ue_information_tag, const uint16_t rnti) {
    // Check if the list is initialized
    if (!list->initialized) {
        pthread_mutex_init(&list->mutex, NULL);
        list->initialized = true;
    }

    // Acquire mutex lock
    pthread_mutex_lock(&list->mutex);

    // Compute CRCFLAG using a hash of the structure's contents
    uint64_t crcflag = (uint64_t)rx_ue_information_tag ^ (uint64_t)rnti;

    // Check if the list contains the entry
    NFAPI_CRC_INDICATION_PDU_T *entry = NULL;
    for (size_t i = 0; i < list->count; i++) {
        if (list->cache[i]->rx_ue_information_tag == rx_ue_information_tag && list->cache[i]->rnti == rnti) {
            entry = list->cache[i];
            break;
        }
    }

    // If the entry is not found, add it to the list
    if (entry == NULL) {
        NFAPI_CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_entry->rx_ue_information_tag = rx_ue_information_tag;
        new_entry->rnti = rnti;
        list->cache[list->count++] = new_entry;
    }

    // Release mutex lock
    pthread_mutex_unlock(&list->mutex);
}

// Function to get the next entry from the list based on CRCFLAG
NFAPI_CRC_INDICATION_PDU_T *get_next_crc_indication(CRC_LIST_T *list, uint64_t crcflag) {
    // Acquire mutex lock
    pthread_mutex_lock(&list->mutex);

    // Check if the list is empty
    if (list->count == 0) {
        // Release mutex lock
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    // Find the entry with the matching CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T *entry = NULL;
    for (size_t i = 0; i < list->count; i++) {
        if (list->cache[i]->crcflag == crcflag) {
            entry = list->cache[i];
            break;
        }
    }

    // If the entry is not found, return NULL
    if (entry == NULL) {
        // Release mutex lock
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    // Increment cache hit counter
    list->cache_hits++;

    // Remove the entry from the list
    NFAPI_CRC_INDICATION_PDU_T *tmp = entry;
    memmove(&list->cache[i], &list->cache[i+1], (list->count-i-1)*sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count--;

    // Release mutex lock
    pthread_mutex_unlock(&list->mutex);

    return tmp;
}

// Function to randomize RX_UE_INFORMATION_TAG and RNTI values within specified bounds
void randomize_crc_indication(CRC_LIST_T *list, int randomization_level) {
    // Acquire mutex lock
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; i++) {
        uint32_t rx_ue_information_tag = RX_UE_INFORMATION_TAG_MIN + (rand() % randomization_level) * (RX_UE_INFORMATION_TAG_MAX - RX_UE_INFORMATION_TAG_MIN);
        uint16_t rnti = RNTI_MIN + (rand() % randomization_level) * (RNTI_MAX - RNTI_MIN);

        list->cache[i]->rx_ue_information_tag = rx_ue_information_tag;
        list->cache[i]->rnti = rnti;
    }

    // Release mutex lock
    pthread_mutex_unlock(&list->mutex);
}

// Function to handle memory allocation efficiently to avoid exceeding a predefined maximum limit
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed. Exiting...\n");
        exit(1);
    }
    return ptr;
}

// Function to handle memory deallocation efficiently to avoid memory leaks
void safe_free(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

// Function to track the number of allocated structures and manage them within the specified limits
void manage_allocated_structures(CRC_LIST_T *list, size_t max_size) {
    // Acquire mutex lock
    pthread_mutex_lock(&list->mutex);

    if (list->count > max_size) {
        for (size_t i = 0; i < list->count - max_size; i++) {
            safe_free(list->cache[i]);
        }
        memmove(list->cache, &list->cache[max_size], (list->count-max_size)*sizeof(NFAPI_CRC_INDICATION_PDU));
        list->count = max_size;
    }

    // Release mutex lock
    pthread_mutex_unlock(&list->mutex);
}
```

In this implementation, we use a `struct` to store the data for each CRC indication. We also use a linked list to store the entries in the cache. The `populate_cache()` function is responsible for populating the cache with the initial CRC indications received from the UE. The `get_next_crc_indication()` function is used to retrieve the next entry from the cache based on its CRCFLAG. The `randomize_crc_indication()` function is used to randomize the RX_UE_INFORMATION_TAG and RNTI values within specified bounds. The `safe_malloc()` and `safe_free()` functions are used to handle memory allocation and deallocation efficiently. Finally, we use a mutex lock to ensure thread-safety in the cache management operations.

### Protocol Description Section (PDS)

The PDS is used to describe the messages that are exchanged between the SCHEDULER and the UE over the RRC connection. The PDS is divided into two parts: the Sender Message Descriptors (SMDs) and the Receiver Message Descriptors (RMDs).

#### Sender Message Descriptors (SMDs)

The SMDs describe the messages that are sent from the SCHEDULER to the UE. The SMDs contain information about the message type, the content of the message, and the format of the message.

Example:
```yaml
sender_message_descriptors:
  - id: 1
    message_type: SR_CONFIG
    content_type: SR_CONTENT
    format: JSON
  - id: 2
    message_type: CRC_INDICATION
    content_type: CRC_CONTENT
    format: JSON
```
In this example, we have two SMDs. The first one describes a message with ID 1 and type SR_CONFIG. It contains the content of the message in SR_CONTENT and is encoded in JSON format. The second one describes a message with ID 2 and type CRC_INDICATION. It contains the content of the message in CRC_CONTENT and is also encoded in JSON format.

#### Receiver Message Descriptors (RMDs)

The RMDs describe the messages that are received by the SCHEDULER from the UE over the RRC connection. The RMDs contain information about the message type, the content of the message, and the format of the message.

Example:
```yaml
receiver_message_descriptors:
  - id: 1
    message_type: SR_RESPONSE
    content_type: SR_CONTENT
    format: JSON
```
In this example, we have one RMD. The first one describes a message with ID 1 and type SR_RESPONSE. It contains the content of the message in SR_CONTENT and is encoded in JSON format.

### Scheduler Configuration Section (SCS)

The SCS is used to configure the behavior of the SCHEDULER. The SCS contains information about the scheduling algorithm, the scheduling parameters, and other configuration options.

Example:
```yaml
scheduler_configuration:
  algorithm: round_robin
  parameters:
    - name: t_nominal
      value: 10
```
In this example, we have one parameter named `t_nominal` with a value of `10`. The `algorithm` field specifies the scheduling algorithm to be used (in this case, round robin).

### Monitoring and Logging Section (MLS)

The MLS is used to configure the monitoring and logging behavior of the SCHEDULER. The MLS contains information about the metrics that need to be monitored and logged.

Example:
```yaml
monitoring_logging_section:
  - metric: srs_successful_percentage
    log_level: info
  - metric: srs_failed_percentage
    log_level: error
```
In this example, we have two metrics to be monitored and logged: `srs_successful_percentage` with a logging level of `info`, and `srs_failed_percentage` with a logging level of `error`.']

