```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>

// Structure definitions
typedef struct {
    int imsi;
    int radioState;
} UEContext;

typedef struct {
    long timestamp;
    char *channelFrequency;
    int signalStrength;
} RadioFrame;

typedef struct {
    char *imsi;
    int radioState;
    struct RadioFrameNode *radioFrames;
} UEContextNode;

struct RadioFrameNode {
    long timestamp;
    char *channelFrequency;
    int signalStrength;
    struct RadioFrameNode *next;
};

// Function declarations
void addUEContext(UEContextNode **head, int imsi, int radioState);
int updateUEContext(UEContextNode **head, int imsi, int radioState);
void printUEContext(UEContextNode **head);
int getLatestRadioState(UEContextNode **head, int imsi);
void freeUEContextNodes(UEContextNode *head);

// Function definitions
void addUEContext(UEContextNode **head, int imsi, int radioState) {
    UEContextNode *node = malloc(sizeof(UEContextNode));
    node->imsi = imsi;
    node->radioState = radioState;
    node->next = NULL;
    if (*head == NULL) {
        *head = node;
    } else {
        UEContextNode *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

int updateUEContext(UEContextNode **head, int imsi, int radioState) {
    UEContextNode *node = *head;
    while (node != NULL && node->imsi != imsi) {
        node = node->next;
    }
    if (node == NULL) {
        return 0; // no such IMSI found
    } else {
        node->radioState = radioState;
        return 1; // success
    }
}

void printUEContext(UEContextNode **head) {
    UEContextNode *node = *head;
    while (node != NULL) {
        printf("IMSI: %d\n", node->imsi);
        printf("Radio State: %d\n", node->radioState);
        if (node->radioFrames != NULL) {
            RadioFrameNode *current = node->radioFrames;
            while (current != NULL) {
                printf("Timestamp: %ld\n", current->timestamp);
                printf("Channel Frequency: %s\n", current->channelFrequency);
                printf("Signal Strength: %d\n", current->signalStrength);
                current = current->next;
            }
        }
        node = node->next;
    }
}

int getLatestRadioState(UEContextNode **head, int imsi) {
    UEContextNode *node = *head;
    while (node != NULL && node->imsi != imsi) {
        node = node->next;
    }
    if (node == NULL) {
        return -1; // no such IMSI found
    } else {
        return node->radioState;
    }
}

void freeUEContextNodes(UEContextNode *head) {
    UEContextNode *current = head;
    while (current != NULL) {
        UEContextNode *next = current->next;
        free(current);
        current = next;
    }
}
```
