NFAPI_CRC_INDICATION_ARRAY* nfapi_crc_indication_array_create(size_t initial_capacity) {
  NFAPI_CRC_INDICATION_ARRAY *array = (NFAPI_CRC_INDICATION_ARRAY*)malloc(sizeof(NFAPI_CRC_INDICATION_ARRAY));
  if (!array) return NULL;

  array->size = 0;
  array->capacity = initial_capacity;
  array->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
  if (!array->elements) {
    free(array);
    return NULL;
  }

  return array;
}

int nfapi_crc_indication_array_add(NFAPI_CRC_INDICATION_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T *element) {
