    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_elements) {
      free(array->elements);
      array->size = 0;
      return -3; // error: realloc failed
    }
    array->elements = new_elements;
    array->capacity = new_capacity;
  }

  // insert the element at the correct position in the sorted array
  size_t i = 0;
  while (i < array->size && array->elements[i].rnti <= element->rnti) {
    i++;
  }
  memcpy(&array->elements[i], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
  array->size++;

  return 0; // success
}

void nfapi_crc_indication_array_destroy(NFAPI_CRC_INDICATION_ARRAY *array) {
  if (!array) return;
  free(array->elements);
  free(array);
}
