// Define a structure to represent an LTE UE context
struct LTE_UE_context {
    // Valid RRC state of the UE
    uint8_t rrc_state;

    // TAI and S-TMSI of the UE
    struct {
        int32_t mcc;
        int16_t mnc;
        int16_t tac;
        int32_t sid;
    } tai;

    // MAC PDU array for uplink data transmission
    uint8_t *mac_pdu[];
};

// Define a pool of UE contexts to manage concurrent access from multiple threads
struct LTE_UE_context_pool {
    struct LTE_UE_context *contexts;
    size_t num_contexts;
    pthread_mutex_t mutex;
};

// Function to initialize and configure a series of LTE UE context structures
void init_LTE_UE_context(struct LTE_UE_context_pool *context_pool) {
    // Allocate memory for the UE context pool
    struct LTE_UE_context *contexts = (struct LTE_UE_context *)malloc(sizeof(struct LTE_UE_context) * 10);
    if (!contexts) {
        // Handle error: memory allocation failed
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize each UE context with a valid RRC state, TAI, and S-TMSI
    for (size_t i = 0; i < 10; i++) {
        struct LTE_UE_context *context = &(contexts[i]);

        // Initialize RRC state
        context->rrc_state = RRC_STATE_CONNECTED;

        // Initialize TAI and S-TMSI
        context->tai.mcc = 1234;
        context->tai.mnc = 56789;
        context->tai.tac = 0x1234;
        context->tai.sid = 0x12345678;

        // Dynamically allocate memory for the MAC PDU array
        context->mac_pdu = (uint8_t **)malloc(sizeof(uint8_t *) * 10);
        if (!context->mac_pdu) {
            // Handle error: memory allocation failed
            printf("Memory allocation failed\n");
            return;
        }

        // Initialize each MAC PDU array with a size of 10 elements
        for (size_t j = 0; j < 10; j++) {
            context->mac_pdu[j] = (uint8_t *)malloc(sizeof(uint8_t) * 10);
            if (!context->mac_pdu[j]) {
                // Handle error: memory allocation failed
                printf("Memory allocation failed\n");
                return;
            }
        }
    }

    // Set the number of UE contexts in the pool
    context_pool->num_contexts = 10;

    // Set the mutex for concurrent access from multiple threads
    pthread_mutex_init(&(context_pool->mutex), NULL);
}

// Function to add a new UE context to the pool and dynamically allocate memory for its MAC PDU array
void add_LTE_UE_context(struct LTE_UE_context_pool *context_pool) {
    // Acquire mutex for concurrent access from multiple threads
    pthread_mutex_lock(&(context_pool->mutex));

    // Check if there is enough space in the pool to add a new context
    if (context_pool->num_contexts < 10) {
        // Dynamically allocate memory for the new UE context
        struct LTE_UE_context *new_context = (struct LTE_UE_context *)malloc(sizeof(struct LTE_UE_context));
        if (!new_context) {
            // Handle error: memory allocation failed
            printf("Memory allocation failed\n");
            return;
        }

        // Initialize the new UE context with a valid RRC state, TAI, and S-TMSI
        new_context->rrc_state = RRC_STATE_CONNECTED;
        new_context->tai.mcc = 1234;
        new_context->tai.mnc = 56789;
        new_context->tai.tac = 0x1234;
        new_context->tai.sid = 0x12345678;

        // Dynamically allocate memory for the MAC PDU array
        new_context->mac_pdu = (uint8_t **)malloc(sizeof(uint8_t *) * 10);
        if (!new_context->mac_pdu) {
            // Handle error: memory allocation failed
            printf("Memory allocation failed\n");
            return;
        }

        // Initialize each MAC PDU array with a size of 10 elements
        for (size_t j = 0; j < 10; j++) {
            new_context->mac_pdu[j] = (uint8_t *)malloc(sizeof(uint8_t) * 10);
            if (!new_context->mac_pdu[j]) {
                // Handle error: memory allocation failed
                printf("Memory allocation failed\n");
                return;
            }
        }

        // Add the new UE context to the pool
        context_pool->contexts[context_pool->num_contexts] = new_context;
        context_pool->num_contexts++;
    } else {
        // Handle error: pool is full
        printf("Pool is full\n");
    }

    // Release mutex for concurrent access from multiple threads
    pthread_mutex_unlock(&(context_pool->mutex));
}

// Function to remove a UE context from the pool and dynamically free its memory
void remove_LTE_UE_context(struct LTE_UE_context_pool *context_pool, size_t index) {
    // Acquire mutex for concurrent access from multiple threads
    pthread_mutex_lock(&(context_pool->mutex));

    // Check if the specified index is within the range of the pool
    if (index < context_pool->num_contexts) {
        struct LTE_UE_context *context = &(context_pool->contexts[index]);

        // Dynamically free the memory allocated for the MAC PDU array
        for (size_t j = 0; j < 10; j++) {
            free(context->mac_pdu[j]);
        }
        free(context->mac_pdu);

        // Dynamically free the memory allocated for the UE context
        free(context);

        // Shift the remaining UE contexts to fill the gap in the pool
        memmove(&(context_pool->contexts[index]), &(context_pool->contexts[index + 1]), (context_pool->num_contexts - index - 1) * sizeof(struct LTE_UE_context));

        // Decrement the number of UE contexts in the pool
        context_pool->num_contexts--;
    } else {
        // Handle error: invalid index
        printf("Invalid index\n");
    }

    // Release mutex for concurrent access from multiple threads
    pthread_mutex_unlock(&(context_pool->mutex));
}

// Function to update the TAI of a UE context in the pool
void update_LTE_UE_TAI(struct LTE_UE_context *context, struct LTE_tai *tai) {
    // Check if the specified context is within the range of the pool
    if (context < &(context_pool->contexts[0]) || context > &(context_pool->contexts[context_pool->num_contexts - 1])) {
        // Handle error: invalid context
        printf("Invalid context\n");
        return;
    }

    // Update the TAI of the UE context
    context->tai.mcc = tai->mcc;
    context->tai.mnc = tai->mnc;
    context->tai.tac = tai->tac;
}

// Function to update the RRC state of a UE context in the pool
void update_LTE_UE_RRCState(struct LTE_UE_context *context, enum LTE_rrc_state state) {
    // Check if the specified context is within the range of the pool
    if (context < &(context_pool->contexts[0]) || context > &(context_pool->contexts[context_pool->num_contexts - 1])) {
        // Handle error: invalid context
        printf("Invalid context\n");
        return;
    }

    // Update the RRC state of the UE context
    context->rrc_state = state;
