typedef struct NFAPI_CRC_INDICATION_LIST {
  pthread_mutex_t lock; // mutex for thread safety
  size_t count; // number of elements in the list
  NFAPI_CRC_INDICATION_PDU_T *elements; // array of elements
} NFAPI_CRC_INDICATION_LIST;

NFAPI_CRC_INDICATION_LIST *createList() {
  NFAPI_CRC_INDICATION_LIST *list = (NFAPI_CRC_INDICATION_LIST *)malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
  if (list == NULL) {
    return NULL;
  }
  list->count = 0;
  list->elements = NULL;
  pthread_mutex_init(&list->lock, NULL);
  return list;
}

void insertElement(NFAPI_CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T element) {
  // validate input parameters
  if (list == NULL || !isValidRxUeInformationTag(element.rxUeInformationTag) || !isValidRnti(element.rnti)) {
    return;
  }

  // allocate memory for the new element
  NFAPI_CRC_INDICATION_PDU_T *newElement = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (newElement == NULL) {
    return;
  }

  // copy the element data
  newElement->rxUeInformationTag = element.rxUeInformationTag;
  newElement->rnti = element.rnti;
  newElement->crcIndicationRel8Tag = element.crcIndicationRel8Tag;
  newElement->crcFlag = element.crcFlag;

  // acquire the lock for thread safety
  pthread_mutex_lock(&list->lock);

  // allocate memory for the array of elements if necessary
  if (list->elements == NULL) {
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count + 1));
    if (list->elements == NULL) {
      free(newElement);
      pthread_mutex_unlock(&list->lock);
      return;
    }
  }

  // insert the new element into the array of elements
  list->elements[list->count] = *newElement;
  list->count++;

  // release the lock for thread safety
  pthread_mutex_unlock(&list->lock);
}

void destroyList(NFAPI_CRC_INDICATION_LIST *list) {
  if (list == NULL) {
    return;
  }

  // acquire the lock for thread safety
  pthread_mutex_lock(&list->lock);

  // free the array of elements
  free(list->elements);
  list->count = 0;
  list->elements = NULL;

  // release the lock for thread safety
  pthread_mutex_unlock(&list->lock);
}
