struct UEContext {
    int rrc_state;
    struct TAI tai;
    uint64_t s_tmsi;
    size_t max_num_logical_channels;
    size_t num_logical_channels;
    struct MACPDU **uplink_pdu_array;
    pthread_mutex_t mutex;
};

struct UEContextPool {
    size_t capacity;
    size_t num_ue_contexts;
    struct UEContext *ue_contexts;
    pthread_mutex_t pool_mutex;
};

void initUEContext(struct UEContext *ue_context) {
    ue_context->rrc_state = RRC_IDLE;
    memset(&ue_context->tai, 0, sizeof(struct TAI));
    ue_context->s_tmsi = 0;
    ue_context->max_num_logical_channels = 1;
    ue_context->num_logical_channels = 0;
    ue_context->uplink_pdu_array = malloc(sizeof(struct MACPDU *) * ue_context->max_num_logical_channels);
    memset(ue_context->uplink_pdu_array, 0, sizeof(struct MACPDU *) * ue_context->max_num_logical_channels);
    pthread_mutex_init(&ue_context->mutex, NULL);
}

void destroyUEContext(struct UEContext *ue_context) {
    free(ue_context->uplink_pdu_array);
    pthread_mutex_destroy(&ue_context->mutex);
}

int createUEContext(struct UEContextPool *pool, struct UEContext *ue_context) {
    int ret = 0;
    if (pool->num_ue_contexts < pool->capacity) {
        initUEContext(ue_context);
        ue_context->id = pool->num_ue_contexts++;
        pool->ue_contexts[ue_context->id] = ue_context;
    } else {
        ret = -1;
    }
    return ret;
}

void deleteUEContext(struct UEContextPool *pool, struct UEContext *ue_context) {
    destroyUEContext(ue_context);
    pool->num_ue_contexts--;
    pool->ue_contexts[ue_context->id] = NULL;
}

