    int ret = 0;
    if (ue_context->num_logical_channels < ue_context->max_num_logical_channels) {
        uplink_pdu_array[ue_context->num_logical_channels] = malloc(sizeof(struct MACPDU));
        memset(uplink_pdu_array[ue_context->num_logical_channels], 0, sizeof(struct MACPDU));
        ue_context->num_logical_channels++;
    } else {
        ret = -1;
    }
    return ret;
}

void deleteLogicalChannel(struct UEContext *ue_context, struct MACPDU **uplink_pdu_array) {
    ue_context->num_logical_channels--;
    free(uplink_pdu_array[ue_context->num_logical_channels]);
}

void updateUEContext(struct UEContext *ue_context, struct TAI tai, uint64_t s_tmsi) {
