CRC_INDICATION_LIST_T* crc_indication_list_create(size_t initial_capacity) {
    CRC_INDICATION_LIST_T* list = malloc(sizeof(CRC_INDICATION_LIST_T));
    if (!list) {
        return NULL;
    }

    list->entries = calloc(initial_capacity, sizeof(CRC_INDICATION_LIST_ENTRY_T));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->num_entries = 0;
    list->capacity = initial_capacity;

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    if (pthread_mutex_init(&list->lock, &attr) != 0) {
        free(list->entries);
        free(list);
        return NULL;
    }

    return list;
}

void crc_indication_list_destroy(CRC_INDICATION_LIST_T* list) {
    if (!list) {
        return;
    }

    pthread_mutex_destroy(&list->lock);
    free(list->entries);
    free(list);
}

int crc_indication_list_insert(CRC_INDICATION_LIST_T* list, size_t index, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) {
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (index > list->num_entries) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Check if the RNTI is already in use
    for (size_t i = 0; i < index; i++) {
        if (list->entries[i].is_used && list->entries[i].pdu->rnti == pdu->rnti) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    // Insert the new structure into the list
    if (index == list->num_entries) {
        list->entries = realloc(list->entries, (list->num_entries + 1) * sizeof(CRC_INDICATION_LIST_ENTRY_T));
        if (!list->entries) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    } else {
        memmove(&list->entries[index + 1], &list->entries[index], (list->num_entries - index) * sizeof(CRC_INDICATION_LIST_ENTRY_T));
    }

    list->entries[index].pdu = pdu;
    list->entries[index].is_used = true;
    list->num_entries++;

    // Set the CRC flag randomly
    bool crcflag = rand() % 2;
    list->entries[index].pdu->crc.crcflag = crcflag;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int crc_indication_list_remove(CRC_INDICATION_LIST_T* list, size_t index) {
    if (!list || index >= list->num_entries) {
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    // Remove the structure from the list
    memmove(&list->entries[index], &list->entries[index + 1], (list->num_entries - index) * sizeof(CRC_INDICATION_LIST_ENTRY_T));
    list->num_entries--;

    // Free the memory of the structure
    free(list->entries[index].pdu);
    list->entries[index].pdu = NULL;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int crc_indication_list_remove_rnti(CRC_INDICATION_LIST_T* list, uint16_t rnti) {
