    pthread_mutex_lock(&list->lock);

    // Find the index of the structure with the given RNTI
    size_t index = 0;
    while (index < list->num_entries && list->entries[index].pdu->rnti != rnti) {
        index++;
    }

    if (index == list->num_entries) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    // Remove the structure from the list
    crc_indication_list_remove(list, index);

    pthread_mutex_unlock(&list->lock);

    return 0;
}
