#include <stdlib.h>
#include <time.h>
#include "nfapi_interface.h" // NFAPI interface definitions
#include "signal_processing_library.h" // Signal processing library

struct crc_indication_pdu {
  uint16_t rx_ue_information_tag;
  uint16_t rnti;
  uint8_t crcflag;
};

struct rx_pdu {
  uint16_t rx_ue_information_tag;
  uint16_t rnti;
  float snr;
  float rssi;
};

int populate_crc_indication_pdus(const int N, const int max_concurrency) {
  // Check if N is negative or zero and return an error if it is
  if (N < 0 || N == 0) {
    fprintf(stderr, "Error: Invalid value of N\n");
    return -1;
  }

  // Initialize variables for tracking concurrent access to shared resources
  int num_concurrent_accesses = 0;
  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

  // Allocate memory for the list of CRC indication PDUs and initialize it
  struct crc_indication_pdu *pdu_list = (struct crc_indication_pdu *)malloc(N * sizeof(struct crc_indication_pdu));
  if (!pdu_list) {
    fprintf(stderr, "Error: Failed to allocate memory for CRC indication PDU list\n");
    return -1;
  }

  // Allocate memory for the list of RX PDUs and initialize it
  struct rx_pdu *rx_pdu_list = (struct rx_pdu *)malloc(N * sizeof(struct rx_pdu));
  if (!rx_pdu_list) {
    fprintf(stderr, "Error: Failed to allocate memory for RX PDU list\n");
    free(pdu_list);
    return -1;
  }

  // Populate the CRC indication PDUs and RX PDUs with valid data
  int i = 0;
  while (i < N) {
    // Acquire a lock to prevent concurrent access to shared resources
    pthread_mutex_lock(&mutex);

    // Generate a new RNTI and CRCFlag for the CRC indication PDU
    uint16_t rnti = (uint16_t)rand() % 65536;
    uint8_t crcflag = (uint8_t)(rand() & 0xff);

    // Fill in the CRC indication PDU with valid data
    pdu_list[i].rx_ue_information_tag = 0;
    pdu_list[i].rnti = rnti;
    pdu_list[i].crcflag = crcflag;

    // Fill in the RX PDU with valid data derived from the received RF signals
    rx_pdu_list[i].rx_ue_information_tag = 0;
    rx_pdu_list[i].rnti = rnti;
    float snr = signal_processing_library_get_snr();
    rx_pdu_list[i].snr = snr;
    float rssi = signal_processing_library_get_rssi(rx_pdu_list[i].snr);
    rx_pdu_list[i].rssi = rssi;

    // Release the lock and increment the counter for concurrent accesses
    pthread_mutex_unlock(&mutex);
    num_concurrent_accesses++;

    i++;
  }

  // Handle edge cases where N is zero or negative
  if (N < 0) {
    fprintf(stderr, "Error: Invalid value of N\n");
    free(pdu_list);
    free(rx_pdu_list);
    return -1;
  } else if (N == 0) {
    // If N is zero, just return an empty list
    return 0;
  }

  return num_concurrent_accesses;
}
