        perror("Error opening configuration file");
        return NULL;
    }

    // Load frequency bands and bandwidths from the external data source
    int num_frequency_bands = 0;
    fscanf(fp, "%d", &num_frequency_bands);

    int* frequency_bands = (int*)malloc(sizeof(int) * num_frequency_bands);
    for (int i = 0; i < num_frequency_bands; i++) {
        fscanf(fp, "%d", &frequency_bands[i]);
    }

    int* bandwidths = (int*)malloc(sizeof(int) * num_frequency_bands);
    for (int i = 0; i < num_frequency_bands; i++) {
        fscanf(fp, "%d", &bandwidths[i]);
    }

    // Initialize and populate the linked list of LTE_PHY_RX_CONFIG_T structures
    LTE_PHY_RX_CONFIG_T* head = NULL;
    LTE_PHY_RX_CONFIG_T* current = NULL;

    for (int i = 0; i < num_frequency_bands; i++) {
        // Allocate memory for a new structure
        LTE_PHY_RX_CONFIG_T* temp = (LTE_PHY_RX_CONFIG_T*)malloc(sizeof(LTE_PHY_RX_CONFIG_T));
        if (temp == NULL) {
            perror("Error allocating memory for LTE_PHY_RX_CONFIG_T structure");
            return NULL;
        }

        // Initialize the structure fields
        temp->ANTENNA_PORT_ID = i;
        temp->rx_tx_config.center_frequency = frequency_bands[i];
        temp->rx_tx_config.bandwidth = bandwidths[i];

        if (head == NULL) {
            head = current = temp;
        } else {
            current->next = temp;
            current = temp;
        }
    }

    fclose(fp);

    return head;
}

void free_linked_list(LTE_PHY_RX_CONFIG_T* head) {
    LTE_PHY_RX_CONFIG_T* current = head;
    while (current != NULL) {
        LTE_PHY_RX_CONFIG_T* next = current->next;
        free(current);
        current = next;
    }
}
