// Function to handle a burst of updates and optimize for both throughput and latency
void nfapi_crc_indication_burst_handler(NFAPI_CRC_INDICATION_LIST_T *list, const NFAPI_CRC_INDICATION_PDU_T *pdus, size_t num_pdus) {
