// Define the structure for UserAccounts
typedef struct {
    char username[32];
    char email[64];
    time_t creation_timestamp;
    bool status_flag;
} UserAccount;

// Define the dynamic linked list of UserAccount structures
typedef struct node {
    UserAccount data;
    struct node* next;
} Node;

// Function to populate the dynamic linked list from an external data source (CSV or binary)
void populate_list(Node** head, const char* filepath, int format) {
    // Open the file at filepath in read mode and check for errors
    FILE* fp = fopen(filepath, "r");
    if (!fp) {
        perror("Error opening file");
        return;
    }

    // Read the data from the file and parse it into UserAccount structures
    while (1) {
        UserAccount account;
        char line[256];
        int read = fscanf(fp, "%s", line);
        if (read == EOF) break;
        else if (read == 4) {
            strcpy(account.username, line);
            read = fscanf(fp, "%s", line);
            if (read != 1) continue;
            strcpy(account.email, line);
            read = fscanf(fp, "%d", &account.creation_timestamp);
            if (read != 1) continue;
            read = fscanf(fp, "%d", &account.status_flag);
            if (read != 1) continue;
            Node* node = malloc(sizeof(Node));
            node->data = account;
            node->next = NULL;
            // Insert the new node at the head of the list
            Node** current = head;
            while (*current) {
                current = &(*current)->next;
            }
            *current = node;
        }
    }

    // Close the file and return
    fclose(fp);
}

// Function to handle concurrent read and write access from multiple threads without data corruption
void acquire_lock(pthread_mutex_t* lock) {
    int rc = pthread_mutex_lock(lock);
    if (rc != 0) {
        perror("Error acquiring lock");
        exit(-1);
    }
}

void release_lock(pthread_mutex_t* lock) {
    int rc = pthread_mutex_unlock(lock);
    if (rc != 0) {
        perror("Error releasing lock");
        exit(-1);
    }
}

// Function to handle potential malformed records or missing fields gracefully
void handle_missing_fields(UserAccount* account, const char* filepath) {
    if (account->username[0] == '\0' || account->email[0] == '\0') {
        perror("Error: Missing username or email field in record");
        exit(-1);
    }
}

// Function to handle potential malformed records or missing fields gracefully
void handle_malformed_records(UserAccount* account, const char* filepath) {
    if (account->creation_timestamp == 0 || account->status_flag == false) {
        perror("Error: Malformed record in file");
        exit(-1);
    }
}

