    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    acquire_lock(&lock);
    // Write the list to the external data source (CSV or binary)
    while (*head) {
        printf("UserAccount: %s %s %ld %d\n", head->data.username, head->data.email, head->data.creation_timestamp, head->data.status_flag);
        head = &(*head)->next;
    }
