    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
struct NFAPI_CRC_INDICATION_PDU_LIST {
    struct NFAPI_CRC_INDICATION_PDU_T *head;
    struct NFAPI_CRC_INDICATION_PDU_T *tail;
    int size;
};

// Define the function to manage the dynamically sized list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_list(struct NFAPI_CRC_INDICATION_PDU_LIST *list) {
    // Initialize the list if it is not already initialized
    if (list->head == NULL) {
        list->head = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        list->tail = list->head;
        list->size = 1;
    }

    // Add a new structure to the end of the list if it is full
    if (list->size == 10000) {
        struct NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        list->tail->next = new_node;
        list->tail = new_node;
        list->size++;
    }

    // Initialize the structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    struct NFAPI_CRC_INDICATION_PDU_T *new_node = list->tail;
    new_node->RX_UE_INFORMATION_TAG = 1;
    new_node->RNTI = 2;
    new_node->CRC_INDICATION_REL8_TAG = 3;
    new_node->CRCFLAG = 4;

