    printf("%s\n", log_msg);

    // Dynamic resizing of the list with minimal allocation overhead
    if (list->size > 1000) {
        struct NFAPI_CRC_INDICATION_PDU_T *old_node = list->head;
        while (old_node != NULL && old_node->next != NULL) {
            old_node = old_node->next;
        }
        if (old_node != NULL) {
            struct NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
            old_node->next = new_node;
            list->tail = new_node;
            list->size++;
        }
    }

    // Memory compaction mechanism that moves active structures to the front of the list and discards inactive ones
    struct NFAPI_CRC_INDICATION_PDU_T *active_node = list->head;
    while (active_node != NULL) {
        if (active_node->CRCFLAG == 0) {
            struct NFAPI_CRC_INDICATION_PDU_T *inactive_node = active_node;
            active_node = inactive_node->next;
            free(inactive_node);
        } else {
            active_node = active_node->next;
        }
    }

    // Serialization of the list to a binary file
    FILE *fptr = fopen("crc_indication_list.bin", "wb");
    if (fptr == NULL) {
        perror("Error opening file");
        return;
    }
    for (int i = 0; i < list->size; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *node = list->head;
        fwrite(&(node->RX_UE_INFORMATION_TAG), sizeof(unsigned int), 1, fptr);
        fwrite(&(node->RNTI), sizeof(unsigned int), 1, fptr);
        fwrite(&(node->CRC_INDICATION_REL8_TAG), sizeof(unsigned int), 1, fptr);
        fwrite(&(node->CRCFLAG), sizeof(unsigned char), 1, fptr);
        node = node->next;
    }
    fclose(fptr);
}

