#include <stdlib.h>
#include <pthread.h>

// Define structure for CRC indication PDU
typedef struct {
    uint16_t rxUeInformationTag;
    uint16_t rnti;
    uint8_t crcIndicationRel8Tag;
    bool crcflag;
} nfapi_crc_indication_pdu_t;

// Define structure for iterator
typedef struct {
    int index;
    pthread_mutex_t *lock;
} list_iterator_t;

// Define the list
struct list {
    nfapi_crc_indication_pdu_t *elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

// Function to dynamically manage the list of CRC indication PDUs
int list_manage(struct list *list, int opcode, void *args) {
    // Lock the list
    pthread_mutex_lock(&list->lock);

    // Switch on operation code
    switch (opcode) {
        case LIST_CREATE: {
            // Allocate memory for the list elements
            list->elements = (nfapi_crc_indication_pdu_t *)malloc(sizeof(nfapi_crc_indication_pdu_t) * INITIAL_CAPACITY);
            if (!list->elements) {
                pthread_mutex_unlock(&list->lock);
                return -1; // Error: unable to allocate memory for list elements
            }
            list->capacity = INITIAL_CAPACITY;
            list->size = 0;
        } break;
        case LIST_INSERT: {
            // Check if the list is full
            if (list->size == list->capacity) {
                // Resize the list if it is full
                size_t new_capacity = list->capacity * 2;
                nfapi_crc_indication_pdu_t *new_elements = (nfapi_crc_indication_pdu_t *)realloc(list->elements, sizeof(nfapi_crc_indication_pdu_t) * new_capacity);
                if (!new_elements) {
                    pthread_mutex_unlock(&list->lock);
                    return -1; // Error: unable to reallocate memory for list elements
                }
                list->elements = new_elements;
                list->capacity = new_capacity;
            }

            // Insert the element into the list
            nfapi_crc_indication_pdu_t *element = (nfapi_crc_indication_pdu_t *)args;
            list->elements[list->size++] = *element;
        } break;
        case LIST_ITERATE: {
            // Check if the iterator is null
            if (!(list_iterator_t *)args) {
                pthread_mutex_unlock(&list->lock);
                return -1; // Error: invalid iterator provided
            }

            // Initialize the iterator with the list's lock and current size
            list_iterator_t *iterator = (list_iterator_t *)args;
            iterator->index = 0;
            iterator->lock = &list->lock;
            iterator->size = list->size;
        } break;
        case LIST_NEXT: {
            // Check if the iterator is null or past the end of the list
            if (!(list_iterator_t *)args || ((list_iterator_t *)args)->index >= list->size) {
                pthread_mutex_unlock(&list->lock);
                return -1; // Error: invalid iterator provided or iterator is past the end of the list
            }

            // Increment the iterator and return the current element
            list_iterator_t *iterator = (list_iterator_t *)args;
            pthread_mutex_unlock(iterator->lock);
            return &list->elements[iterator->index++];
        } break;
        default: {
            // Return an error if the operation code is invalid
            pthread_mutex_unlock(&list->lock);
            return -1; // Error: invalid operation code provided
        } break;
    }

    // Unlock the list
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Function to create a new list
int list_create(struct list **list) {
    *list = (struct list *)malloc(sizeof(struct list));
    if (!*list) {
        return -1; // Error: unable to allocate memory for list
    }
    (*list)->elements = NULL;
    (*list)->capacity = 0;
    (*list)->size = 0;
    pthread_mutex_init(&(*list)->lock, NULL);
    return 0; // Success
}

// Function to insert an element into the list
int list_insert(struct list *list, nfapi_crc_indication_pdu_t *element) {
    return list_manage(list, LIST_INSERT, element);
}

// Function to iterate over the elements of the list
int list_iterate(struct list *list, list_iterator_t *iterator) {
    return list_manage(list, LIST_ITERATE, iterator);
}

// Function to retrieve the next element from the list
nfapi_crc_indication_pdu_t *list_next(struct list *list, list_iterator_t *iterator) {
    return (nfapi_crc_indication_pdu_t *)list_manage(list, LIST_NEXT, iterator);
}
