            }
        }
    }
}

// Define function to deallocate memory for dynamic array of LTE_MME_APP_CONTEXT_T structures
void deallocateLTEMMEAppContexts(LTE_MME_APP_CONTEXT_T **contexts, int num_contexts) {
    free(*contexts);
}

// Define function to add new message to LTE_MME_APP_CONTEXT_T structure
void addNewMessageToLTEMMEAppContext(LTE_MME_APP_CONTEXT_T *context, char *content) {
    // Check if there is still space for a new message in the context
    if (context->num_messages < MAX_NUM_MESSAGES) {
        // Add new message to end of list
        context->messages[context->num_messages].timestamp = time(NULL);
        strcpy(context->messages[context->num_messages].content, content);
        // Increment number of messages in the context
        context->num_messages++;
    } else {
        // If there is no space for a new message, discard oldest message and add new one
        context->messages[0].timestamp = time(NULL);
        strcpy(context->messages[0].content, content);
    }
}

// Define function to get last message from LTE_MME_APP_CONTEXT_T structure
char *getLastMessageFromLTEMMEAppContext(LTE_MME_APP_CONTEXT_T *context) {
    // Check if there are any messages in the context
    if (context->num_messages == 0) {
        return NULL;
    } else {
        return context->messages[context->num_messages - 1].content;
    }
}

// Define function to get all messages from LTE_MME_APP_CONTEXT_T structure as a string
char *getAllMessagesFromLTEMMEAppContext(LTE_MME_APP_CONTEXT_T *context) {
    // Check if there are any messages in the context
    if (context->num_messages == 0) {
        return NULL;
    } else {
        char *result = malloc(MAX_NUM_MESSAGES * 50 + 1);
        result[0] = '\0';
        for (int i = 0; i < context->num_messages; i++) {
            strcat(result, context->messages[i].content);
        }
        return result;
    }
}
