// Custom data structure for session information
struct USER_SESSION_INFO {
    int SessionID;
    int UserIdentifier;
    struct NetworkPacket *NetworkPackets; // list of network packets
};

// Custom data structure for network packets
struct NetworkPacket {
    char Content[1024];
    unsigned long Timestamp;
};

// Function to initialize a dynamic hash table of USER_SESSION_INFO structures
USER_SESSION_INFO *initializeSessionTable(int numSessions) {
    // Allocate memory for the session table and all network packets
    USER_SESSION_INFO *sessionTable = malloc(sizeof(USER_SESSION_INFO) * numSessions);
    struct NetworkPacket **networkPackets = malloc(sizeof(struct NetworkPacket *) * numSessions);

    // Initialize each session with a unique SessionID and UserIdentifier
    for (int i = 0; i < numSessions; i++) {
        sessionTable[i].SessionID = i + 1;
        sessionTable[i].UserIdentifier = i % 10;
        networkPackets[i] = malloc(sizeof(struct NetworkPacket));
    }

    // Add random content and timestamps to each network packet
    for (int i = 0; i < numSessions; i++) {
        char *content = "Hello, World!";
        unsigned long timestamp = time(NULL);
        memcpy(networkPackets[i]->Content, content, strlen(content));
        networkPackets[i]->Timestamp = timestamp;
    }

    // Add each network packet to the corresponding session
    for (int i = 0; i < numSessions; i++) {
        sessionTable[i].NetworkPackets = networkPackets[i];
    }

    return sessionTable;
}

// Function to clean up memory allocated by initializeSessionTable()
void freeSessionTable(USER_SESSION_INFO *sessionTable) {
    for (int i = 0; i < numSessions; i++) {
        free(sessionTable[i].NetworkPackets);
    }
    free(sessionTable);
}
