#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sqlite3.h>

struct LTE_UEContext {
    int ueId;
    int rnti;
    struct phyLayerStats {
        // Comprehensive statistics for uplink and downlink
    };
};

typedef struct {
    pthread_mutex_t mutex;
    sqlite3* db;
    struct LTE_UEContext** list;
    int size;
} ContextManager;

void initContextManager(ContextManager* manager) {
    // Initialize the context manager's mutex and database connection
    pthread_mutex_init(&manager->mutex, NULL);
    manager->db = sqlite3_open("database.sqlite", &err);
    if (err != SQLITE_OK) {
        fprintf(stderr, "Failed to open database: %s\n", sqlite3_errmsg(manager->db));
        exit(1);
    }
    manager->list = NULL;
    manager->size = 0;
}

void addContext(ContextManager* manager, int ueId, int rnti, struct phyLayerStats stats) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Allocate memory for the new context
    struct LTE_UEContext* context = malloc(sizeof(struct LTE_UEContext));
    if (context == NULL) {
        fprintf(stderr, "Failed to allocate memory for new context\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Initialize the new context with the given ueId, rnti, and stats
    context->ueId = ueId;
    context->rnti = rnti;
    memcpy(&context->phyLayerStats, &stats, sizeof(struct phyLayerStats));

    // Insert the new context into the list
    manager->list = realloc(manager->list, (manager->size + 1) * sizeof(struct LTE_UEContext*));
    if (manager->list == NULL) {
        fprintf(stderr, "Failed to allocate memory for new context\n");
        pthread_mutex_unlock(&manager->mutex);
        free(context);
        return;
    }
    manager->list[manager->size] = context;
    manager->size++;

    // Release the mutex and return
    pthread_mutex_unlock(&manager->mutex);
}

void updateContext(ContextManager* manager, int ueId, struct phyLayerStats stats) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Find the context with the given ueId in the list
    int i;
    for (i = 0; i < manager->size; i++) {
        if (manager->list[i]->ueId == ueId) {
            break;
        }
    }
    if (i == manager->size) {
        fprintf(stderr, "No context with given ueId found\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Update the stats for the found context
    memcpy(&manager->list[i]->phyLayerStats, &stats, sizeof(struct phyLayerStats));

    // Release the mutex and return
    pthread_mutex_unlock(&manager->mutex);
}

void deleteContext(ContextManager* manager, int ueId) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Find the context with the given ueId in the list
    int i;
    for (i = 0; i < manager->size; i++) {
        if (manager->list[i]->ueId == ueId) {
            break;
        }
    }
    if (i == manager->size) {
        fprintf(stderr, "No context with given ueId found\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    // Remove the found context from the list and free its memory
    manager->list[i] = manager->list[--manager->size];
    free(manager->list[manager->size]);
    manager->list = realloc(manager->list, manager->size * sizeof(struct LTE_UEContext*));

    // Release the mutex and return
    pthread_mutex_unlock(&manager->mutex);
}

void printContexts(ContextManager* manager) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);

    // Print all contexts in the list
    int i;
    for (i = 0; i < manager->size; i++) {
        printf("Context %d: UEId=%d, RNTI=%d\n", i, manager->list[i]->ueId, manager->list[i]->rnti);
        printf("PhyLayerStats:\n");
        printf("\tUplink: ");
        printPhyLayerStats(&manager->list[i]->phyLayerStats.uplink);
        printf("\n\tDownlink: ");
        printPhyLayerStats(&manager->list[i]->phyLayerStats.downlink);
        printf("\n");
    }

    // Release the mutex and return
    pthread_mutex_unlock(&manager->mutex);
}

void printPhyLayerStats(struct phyLayerStats* stats) {
    // Print all statistics in the given PhyLayerStats struct
    printf("RSSI=%d, RSRP=%d, RSRQ=%d\n", stats->rssi, stats->rsrp, stats->rsrq);
}

void closeContextManager(ContextManager* manager) {
    // Release the mutex and close the database connection
    pthread_mutex_unlock(&manager->mutex);
    sqlite3_close(manager->db);
}
```
