    int max_size; // maximum allowed number of UEs in the array
    NFAPI_CRC_INDICATION_PDU_T *ues[MAX_UES]; // array of UEs
} CRC_INDICATION_ARRAY_T;

void init_array(CRC_INDICATION_ARRAY_T *arr) {
    arr->size = 0;
    arr->max_size = MAX_UES;
    pthread_mutex_init(&arr->mutex, NULL);
}

int alloc_ue(CRC_INDICATION_ARRAY_T *arr, NFAPI_CRC_INDICATION_PDU_T *ue) {
    int ret = 0;
    pthread_mutex_lock(&arr->mutex);
    if (arr->size < arr->max_size) {
        // allocate memory for the UE
        NFAPI_CRC_INDICATION_PDU_T *new_ue = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_ue == NULL) {
            ret = -1; // allocation failed
        } else {
            memcpy(new_ue, ue, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            arr->ues[arr->size++] = new_ue;
        }
    } else {
        ret = -2; // maximum number of UEs exceeded
    }
    pthread_mutex_unlock(&arr->mutex);
    return ret;
}

int free_ue(CRC_INDICATION_ARRAY_T *arr, int index) {
    int ret = 0;
    pthread_mutex_lock(&arr->mutex);
    if (index < arr->size && index >= 0) {
        // deallocate memory for the UE
        NFAPI_CRC_INDICATION_PDU_T *ue = arr->ues[index];
        free(ue);
        memmove(&arr->ues[index], &arr->ues[index + 1], (arr->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        arr->size--;
    } else {
        ret = -1; // invalid index
    }
    pthread_mutex_unlock(&arr->mutex);
    return ret;
}

int get_ue(CRC_INDICATION_ARRAY_T *arr, int index) {
    NFAPI_CRC_INDICATION_PDU_T *ret = NULL;
    pthread_mutex_lock(&arr->mutex);
    if (index < arr->size && index >= 0) {
        ret = arr->ues[index];
    } else {
        ret = NULL; // invalid index
