// Define the structure to store user data
typedef struct {
    int user_id;
    char session_start_time[20];
    char last_activity_timestamp[20];
} USER_DATA_RECORD;

#define MAX_USERS 10000

// Define a linked list to store the user data records
typedef struct {
    USER_DATA_RECORD* head;
    int size;
} LINKED_LIST;

// Function to allocate memory for a new record and return its address
USER_DATA_RECORD* alloc_record(int user_id, char* session_start_time, char* last_activity_timestamp) {
    // Allocate memory for the record
    USER_DATA_RECORD* record = (USER_DATA_RECORD*)malloc(sizeof(USER_DATA_RECORD));
    if (record == NULL) {
        printf("Failed to allocate memory for the new user record\n");
        return NULL;
    }

    // Initialize the record with the given data
    record->user_id = user_id;
    strcpy(record->session_start_time, session_start_time);
    strcpy(record->last_activity_timestamp, last_activity_timestamp);

    return record;
}

// Function to add a new record to the linked list
void add_to_list(LINKED_LIST* list, USER_DATA_RECORD* record) {
    // Check if the list is full
    if (list->size >= MAX_USERS) {
        printf("The list is full\n");
        return;
    }

    // Add the new record to the end of the list
    if (list->head == NULL) {
        list->head = record;
        list->size++;
    } else {
        USER_DATA_RECORD* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
        list->size++;
    }
}

// Function to remove a record from the linked list
void remove_from_list(LINKED_LIST* list, int user_id) {
    // Check if the list is empty
    if (list->head == NULL) {
        printf("The list is empty\n");
        return;
    }

    // Find the record to be removed and update the linked list accordingly
    USER_DATA_RECORD* current = list->head;
    USER_DATA_RECORD* previous = NULL;
    while (current != NULL && current->user_id != user_id) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        printf("The record with the given ID was not found\n");
        return;
    }
    // Remove the record from the linked list
    if (previous != NULL) {
        previous->next = current->next;
    } else {
        list->head = current->next;
    }
    // Free the memory allocated for the record
    free(current);
}

// Function to update a record in the linked list
void update_record(LINKED_LIST* list, int user_id, char* session_start_time, char* last_activity_timestamp) {
    // Find the record to be updated and update its fields accordingly
    USER_DATA_RECORD* current = list->head;
    while (current != NULL && current->user_id != user_id) {
        current = current->next;
    }
    if (current == NULL) {
        printf("The record with the given ID was not found\n");
        return;
    }
    strcpy(current->session_start_time, session_start_time);
    strcpy(current->last_activity_timestamp, last_activity_timestamp);
}

// Function to search for a record in the linked list by user ID
USER_DATA_RECORD* find_record(LINKED_LIST* list, int user_id) {
    // Find the record with the given ID
    USER_DATA_RECORD* current = list->head;
    while (current != NULL && current->user_id != user_id) {
        current = current->next;
    }
    if (current == NULL) {
        printf("The record with the given ID was not found\n");
        return NULL;
    }
    return current;
}

// Main function to manage the linked list of user data records
int main() {
    // Initialize a linked list for storing the user data records
    LINKED_LIST* list = (LINKED_LIST*)malloc(sizeof(LINKED_LIST));
    list->head = NULL;
    list->size = 0;

    // Add some records to the linked list
    USER_DATA_RECORD* record1 = alloc_record(1, "2022-01-01T10:30:00", "2022-01-01T11:30:00");
    add_to_list(list, record1);
    USER_DATA_RECORD* record2 = alloc_record(2, "2022-01-01T11:30:00", "2022-01-01T12:30:00");
    add_to_list(list, record2);
    USER_DATA_RECORD* record3 = alloc_record(3, "2022-01-01T12:30:00", "2022-01-01T13:30:00");
    add_to_list(list, record3);

    // Search for a record in the linked list by user ID
    USER_DATA_RECORD* found = find_record(list, 2);
    if (found != NULL) {
        printf("Found record with ID %d\n", found->user_id);
    }

    // Update a record in the linked list
    update_record(list, 2, "2022-01-01T13:30:00", "2022-01-01T14:30:00");

    // Remove a record from the linked list
    remove_from_list(list, 1);

    return 0;
}
