// Function to create a new list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *create_list() {
    // Allocate memory for the list struct
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        return NULL;
    }
    list->capacity = 10000; // initial capacity of the list
    list->size = 0; // initial size of the list
    list->mutex = PTHREAD_MUTEX_INITIALIZER; // initialize mutex for thread safety
    list->semaphore = semaphore_create(); // create semaphore for memory allocation failures
    if (list->semaphore == NULL) {
        free(list);
        return NULL;
    }
    // Allocate memory for the array of structures
    list->entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    if (list->entries == NULL) {
        free(list);
        return NULL;
    }
    // Initialize each structure in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < list->capacity; i++) {
        list->entries[i].RX_UE_INFORMATION_TAG = 0;
        list->entries[i].RNTI = 0;
        list->entries[i].CRC_INDICATION_REL8_TAG = 0;
    }
    return list;
}

// Function to add a new entry to the list
int add_entry(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    // Check if the list is full
    if (list->size == list->capacity) {
        return -1;
    }
    // Lock the mutex to prevent concurrent access to the list
    pthread_mutex_lock(&(list->mutex));
    // Increase the size of the list by 1
    list->size++;
    // Copy the new entry into the last position in the array
    memcpy(&(list->entries[list->size - 1]), &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Unlock the mutex to allow other threads to access the list
    pthread_mutex_unlock(&(list->mutex));
    return 0;
}

// Function to iterate over the list and perform specific actions
void iterate_list(NFAPI_CRC_INDICATION_LIST_T *list, void (*action)(NFAPI_CRC_INDICATION_PDU_T *entry)) {
    // Lock the mutex to prevent concurrent access to the list
    pthread_mutex_lock(&(list->mutex));
    // Iterate over each entry in the array
    for (size_t i = 0; i < list->size; i++) {
        action(&(list->entries[i]));
    }
    // Unlock the mutex to allow other threads to access the list
    pthread_mutex_unlock(&(list->mutex));
}

// Function to clean up obsolete entries in the list
void cleanup_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Lock the mutex to prevent concurrent access to the list
    pthread_mutex_lock(&(list->mutex));
    // Iterate over each entry in the array and check if it is obsolete
    for (size_t i = 0; i < list->size; i++) {
        if (list->entries[i].CRC_INDICATION_REL8_TAG == 0) {
            // Remove the obsolete entry from the array and decrement the size of the list by 1
            memmove(&(list->entries[i]), &(list->entries[i + 1]), (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
