#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Custom memory pool allocator for managing heap memory
struct MemoryPool {
    void* buffer;
    size_t capacity;
    size_t free_head;
};

void* mempool_alloc(struct MemoryPool* pool, size_t size) {
    // Check if there is enough space in the pool
    if (size > pool->capacity - pool->free_head) {
        return NULL;
    }

    // Allocate memory from the pool
    void* ptr = pool->buffer + pool->free_head;
    pool->free_head += size;

    // Return the allocated memory
    return ptr;
}

void mempool_free(struct MemoryPool* pool, void* ptr) {
    // Check if the pointer is within the pool's range
    if (ptr < pool->buffer || ptr > pool->buffer + pool->capacity) {
        return;
    }

    // Return the memory to the free list
    size_t offset = ptr - pool->buffer;
    pool->free_head += offset;
}

