static void memory_pool_init(void *pool, size_t size) {
    memset(pool, 0x0, size);
}

static void* memory_pool_alloc(void *pool, size_t size) {
    char *mem = (char *) pool;
    mem += size;
    return mem;
}

static void memory_pool_free(void *pool, void *mem) {
    char *mem_ptr = (char *) mem;
    mem_ptr -= size;
}

