    struct S1_MESSAGE_T *S1_Messages;
} LTE_MME_APP_CONTEXT_T;

typedef struct S1_MESSAGE_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} S1_MESSAGE_T;

typedef struct LTE_MME_APP_CONTEXT_LIST {
    pthread_mutex_t mutex;
    int size;
    int capacity;
    LTE_MME_APP_CONTEXT_T *array[];
} LTE_MME_APP_CONTEXT_LIST;

LTE_MME_APP_CONTEXT_LIST *create_context_list() {
    LTE_MME_APP_CONTEXT_LIST *list = malloc(sizeof(LTE_MME_APP_CONTEXT_LIST));
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    list->array = malloc(sizeof(LTE_MME_APP_CONTEXT_T) * INITIAL_CAPACITY);
    return list;
}

void destroy_context_list(LTE_MME_APP_CONTEXT_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        free(list->array[i].S1_Messages);
    }
    free(list->array);
    pthread_mutex_unlock(&list->mutex);
}

void add_context(LTE_MME_APP_CONTEXT_LIST *list, int MME_EPS_MOBILITY_ID, int UE_IDENTIFIER) {
    S1_MESSAGE_T *S1_Messages = malloc(sizeof(S1_MESSAGE_T));
    memset(S1_Messages, 0, sizeof(S1_MESSAGE_T));
    S1_Messages->RX_UE_INFORMATION_TAG = (int)rand();
    S1_Messages->RNTI = (int)rand();
    S1_Messages->CRC_INDICATION_REL8_TAG = (int)rand();
    S1_Messages->CRCFLAG = true;
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->array = realloc(list->array, sizeof(LTE_MME_APP_CONTEXT_T) * list->capacity);
    }
    list->array[list->size].MME_EPS_MOBILITY_ID = MME_EPS_MOBILITY_ID;
    list->array[list->size].UE_IDENTIFIER = UE_IDENTIFIER;
    list->array[list->size].S1_Messages = S1_Messages;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void remove_context(LTE_MME_APP_CONTEXT_LIST *list, int MME_EPS_MOBILITY_ID, int UE_IDENTIFIER) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->array[i].MME_EPS_MOBILITY_ID == MME_EPS_MOBILITY_ID && list->array[i].UE_IDENTIFIER == UE_IDENTIFIER) {
            free(list->array[i].S1_Messages);
            for (int j = i; j < list->size - 1; j++) {
                list->array[j] = list->array[j + 1];
            }
            list->size--;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

int get_context(LTE_MME_APP_CONTEXT_LIST *list, int MME_EPS_MOBILITY_ID, int UE_IDENTIFIER) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->array[i].MME_EPS_MOBILITY_ID == MME_EPS_MOBILITY_ID && list->array[i].UE_IDENTIFIER == UE_IDENTIFIER) {
            pthread_mutex_unlock(&list->mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

void update_s1_message(LTE_MME_APP_CONTEXT_LIST *list, int MME_EPS_MOBILITY_ID, int UE_IDENTIFIER, S1_MESSAGE_T *S1_Message) {
    pthread_mutex_lock(&list->mutex);
    int index = get_context(list, MME_EPS_MOBILITY_ID, UE_IDENTIFIER);
    if (index >= 0) {
        list->array[index].S1_Messages = S1_Message;
    }
    pthread_mutex_unlock(&list->mutex);
}

void clear_s1_message(LTE_MME_APP_CONTEXT_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        free(list->array[i].S1_Messages);
        list->array[i].S1_Messages = NULL;
    }
    pthread_mutex_unlock(&list->mutex);
}
```

The above code is a simple implementation of a context list data structure using mutex to handle concurrent access. The `add_context` function adds a new context entry to the list, and the `remove_context` function removes an existing context entry from the list. The `get_context` function retrieves the index of a given context entry in the list, and the `update_s1_message` function updates the S1 message field of a given context entry. The `clear_s1_message` function clears all S1 message fields in the list.

The `LTE_MME_APP_CONTEXT` structure contains the following fields:

* `MME_EPS_MOBILITY_ID`: the MME EPS mobility identity of the context entry
* `UE_IDENTIFIER`: the UE identifier of the context entry
* `S1_Messages`: a pointer to the S1 message field of the context entry, which is used to store the S1 message sent by the UE to the MME.

The `LTE_MME_APP_CONTEXT_LIST` structure contains the following fields:

* `mutex`: a mutex to handle concurrent access to the list
* `size`: the number of context entries in the list
* `capacity`: the capacity of the list
* `array`: an array of `LTE_MME_APP_CONTEXT` structures that stores all the context entries in the list.']

