NFAPI_CRC_INDICATION_PDU_T* alloc_array(size_t n) {
  // Check if the input size is valid
  if (n <= 0) {
    return NULL;
  }

  // Allocate memory for the array of structures
  NFAPI_CRC_INDICATION_PDU_T* arr = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (arr == NULL) {
