  for (size_t i = 0; i < n; ++i) {
    arr[i].rx_information_tag = rand() % 1000;
    arr[i].rnti = rand() % 65536;
    arr[i].crc_indication_rel8_tag = rand() % 256;
  }

  // Initialize the array elements with unique timestamps derived from the current system time
  for (size_t i = 0; i < n; ++i) {
    arr[i].timestamp = time(NULL);
  }

  return arr;
}

// Define a function to free memory allocated by the alloc_array function
void free_array(NFAPI_CRC_INDICATION_PDU_T* arr, size_t n) {
  if (arr == NULL || n <= 0) {
    return;
  }

  for (size_t i = 0; i < n; ++i) {
