// Structure to represent a UE context
struct UEContext {
    int macEntityConfiguration; // valid MAC Entity Configuration for the UE
    struct BWPConfig *bwpList; // list of configured Downlink BWP settings
};

// Structure to represent a Downlink BWP (Bandwidth Part) configuration
struct BWPConfig {
    int bwpId; // ID of the Downlink BWP
    int bandwidth; // bandwidth of the Downlink BWP in MHz
    int subcarrierSpacing; // subcarrier spacing of the Downlink BWP (e.g., 15 or 20)
};

// Function to initialize and configure a set of LTE UE Contexts
void initUEContexts(struct UEContext *ueList, size_t numUes) {
    // Initialize the MAC Entity Configuration for each UE context
    for (size_t i = 0; i < numUes; i++) {
        ueList[i].macEntityConfiguration = i + 1;
    }

    // Create a list of BWP configurations for each UE context
    for (size_t i = 0; i < numUes; i++) {
        ueList[i].bwpList = malloc(sizeof(struct BWPConfig) * numBWPs);
        size_t bwpIdx = 0;
        while (bwpIdx < numBWPs) {
            ueList[i].bwpList[bwpIdx].bwpId = i + bwpIdx + 1;
            ueList[i].bwpList[bwpIdx].bandwidth = bandwidths[bwpIdx];
            ueList[i].bwpList[bwpIdx].subcarrierSpacing = subcarrierSpacings[bwpIdx];
            bwpIdx++;
        }
    }
}

// Function to add a new Downlink BWP (Bandwidth Part) configuration for a UE context
void addBWPConfig(struct UEContext *ue, int bwpId, int bandwidth, int subcarrierSpacing) {
    // Check if the BWP configuration is already present in the list
    for (size_t i = 0; i < ue->numBWPs; i++) {
        if (ue->bwpList[i].bwpId == bwpId) {
            return; // BWP configuration is already present, nothing to do
        }
    }

    // Add the new BWP configuration to the list
    ue->bwpList = realloc(ue->bwpList, sizeof(struct BWPConfig) * (ue->numBWPs + 1));
    ue->bwpList[ue->numBWPs].bwpId = bwpId;
    ue->bwpList[ue->numBWPs].bandwidth = bandwidth;
    ue->bwpList[ue->numBWPs].subcarrierSpacing = subcarrierSpacing;
    ue->numBWPs++;
}

// Function to remove a Downlink BWP (Bandwidth Part) configuration from a UE context
void removeBWPConfig(struct UEContext *ue, int bwpId) {
    // Find the index of the BWP configuration in the list
    size_t bwpIdx = 0;
    while (bwpIdx < ue->numBWPs && ue->bwpList[bwpIdx].bwpId != bwpId) {
        bwpIdx++;
    }

    // Remove the BWP configuration from the list
    if (bwpIdx < ue->numBWPs) {
        for (size_t i = bwpIdx; i < ue->numBWPs - 1; i++) {
            memcpy(&ue->bwpList[i], &ue->bwpList[i + 1], sizeof(struct BWPConfig));
        }
        ue->numBWPs--;
    }
