    MeasurementNode* newNode = (MeasurementNode*) malloc(sizeof(MeasurementNode));
    if (newNode == NULL) {
        printf("Error: unable to allocate memory for new measurement\n");
        return;
    }
    // Set the report in the new node
    newNode->report = report;
    // Add the new node to the end of the linked list
    measurementListTail->next = newNode;
    measurementListTail = newNode;
}

