    LTE_RRC_CU_TRANSPORT_PDU* pdu; // Pointer to the first PDU in the pool
};

// Function to allocate a new PDU from the memory pool
LTE_RRC_CU_TRANSPORT_PDU* alloc_pdu(size_t length) {
    // Check if there is enough space in the current memory pool to fit the PDU
    if (length > POOL_SIZE - sizeof(struct MemoryPool)) {
        // If not, allocate a new memory pool with twice the size of the current one and add it to the linked list
        struct MemoryPool* new_pool = malloc(POOL_SIZE * 2);
        new_pool->next = mem_pool;
        mem_pool = new_pool;
    }

    // Get a pointer to the first available PDU in the current memory pool
    LTE_RRC_CU_TRANSPORT_PDU* pdu = mem_pool->pdu;
    mem_pool->pdu += sizeof(struct MemoryPool);

    // Initialize the PDU and return a pointer to it
    pdu->valid = 0;
    pdu->buffer = malloc(length);
    pdu->length = length;
    return pdu;
}

// Function to deallocate a PDU from the memory pool
void free_pdu(LTE_RRC_CU_TRANSPORT_PDU* pdu) {
    // Check if the PDU is valid and has a buffer allocated
    if (pdu->valid && pdu->buffer != NULL) {
