        // If so, allocate a new memory pool with twice the size of the current one and add it to the linked list
        struct MemoryPool* new_pool = malloc(POOL_SIZE * 2);
        new_pool->next = mem_pool;
        mem_pool = new_pool;

        // Add the PDU to the array of PDUs
        pdu->valid = 0;
        pdu->buffer = malloc(pdu->length);
        pdu->index = array_size;
        pdu_array[array_size++] = pdu;
    }
}

// Define a function to update a PDU in the array of PDUs
void update_pdu(LTE_RRC_CU_TRANSPORT_PDU* pdu) {
    // Check if the PDU is valid and has a buffer allocated
    if (pdu->valid && pdu->buffer != NULL) {
        // If so, update the PDU in the array of PDUs
        pdu->valid = 0;
        pdu->buffer = malloc(pdu->length);
        pdu_array[pdu->index] = pdu;
    }
}

// Define a function to iterate over all PDUs in the array of PDUs and perform checksum validation on their content
void iterate_pdus() {
    // Iterate over all PDUs in the array of PDUs
    for (int i = 0; i < array_size; i++) {
        LTE_RRC_CU_TRANSPORT_PDU* pdu = pdu_array[i];

        // Check if the PDU is valid and has a buffer allocated
        if (pdu->valid && pdu->buffer != NULL) {
            // If so, perform checksum validation on the PDU content
            unsigned char* buffer = pdu->buffer;
            int length = pdu->length;
            unsigned int checksum = 0;
            for (int j = 0; j < length; j++) {
                checksum += buffer[j];
            }
            if (checksum == pdu->checksum) {
                // If the checksum is valid, set the PDU as valid and return it
                pdu->valid = 1;
                return pdu;
            } else {
                // If the checksum is not valid, set the PDU as invalid and continue iterating over the remaining PDUs
                pdu->valid = 0;
            }
        }
    }
