```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Struct for cellular network event information
struct CellularEvent {
    int type;
    time_t timestamp;
    char* payload;
    void* metadata;
};

// Array of structures to store cellular network events
struct CellularEvent* events;
size_t numEvents = 0;

// Function to add a new event to the array
void addEvent(int type, time_t timestamp, char* payload, void* metadata) {
    // Reallocate memory for the events array if necessary
    if (numEvents == 0 || numEvents == SIZE_MAX) {
        size_t newSize = numEvents ? 2 * numEvents : 16;
        struct CellularEvent* newEvents = realloc(events, newSize * sizeof(struct CellularEvent));
        if (newEvents) {
            events = newEvents;
        } else {
            printf("Failed to allocate memory for events array.\n");
            return;
        }
    }

    // Add the new event to the array
    struct CellularEvent* event = &events[numEvents++];
    event->type = type;
    event->timestamp = timestamp;
    event->payload = payload;
    event->metadata = metadata;
}

// Function to update an existing event in the array by event type
void updateEvent(int type, time_t timestamp, char* payload, void* metadata) {
    // Find the index of the event with the matching type
    size_t i;
    for (i = 0; i < numEvents; ++i) {
        if (events[i].type == type) {
            break;
        }
    }

    // Update the existing event if found, otherwise add a new one
    if (i < numEvents) {
        events[i].timestamp = timestamp;
        events[i].payload = payload;
        events[i].metadata = metadata;
    } else {
        addEvent(type, timestamp, payload, metadata);
    }
}

// Function to retrieve events within a specified time window
struct CellularEvent* getEvents(time_t startTime, time_t endTime) {
    size_t i;
    struct CellularEvent* eventsInRange = malloc(sizeof(struct CellularEvent) * (endTime - startTime));
    for (i = 0; i < numEvents && events[i].timestamp < startTime; ++i);
    for (size_t j = 0; i < numEvents && events[i].timestamp <= endTime; ++i, ++j) {
        struct CellularEvent* event = &eventsInRange[j];
        event->type = events[i].type;
        event->timestamp = events[i].timestamp;
        event->payload = events[i].payload;
        event->metadata = events[i].metadata;
    }
    return eventsInRange;
}

// Function to aggregate statistics for events within a specified time window
void aggregateStats(time_t startTime, time_t endTime) {
    size_t i;
    int numEventsInRange = 0;
    long totalPayloadSize = 0;
    for (i = 0; i < numEvents && events[i].timestamp < startTime; ++i);
    for (size_t j = 0; i < numEvents && events[i].timestamp <= endTime; ++i, ++j) {
        numEventsInRange++;
        totalPayloadSize += strlen(events[i].payload);
    }
    printf("Number of events in range: %d\n", numEventsInRange);
    printf("Average payload size: %.2f bytes\n", (float)totalPayloadSize / numEventsInRange);
}

// Function to periodically clean up inactive events older than a specified duration
void cleanup(time_t maxAge) {
    size_t i;
    for (i = 0; i < numEvents && events[i].timestamp + maxAge <= time(NULL); ++i) {}
    if (i > 0) {
        struct CellularEvent* newEvents = realloc(events, i * sizeof(struct CellularEvent));
        if (newEvents) {
            events = newEvents;
            numEvents = i;
        } else {
            printf("Failed to allocate memory for cleaned up events array.\n");
        }
    }
}
