#define MAX_NFAPI_CRC_INDICATION_PDU_T 10000000
#define MAX_RNTI 10000000
#define MAX_DUPLICATE_RNTI 10000000
#define MIN_CRCFLAG 0
#define MAX_CRCFLAG 1

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t rx_ue_information_tag;
    uint32_t rnti;
    uint32_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_ARRAY {
    uint32_t size;
    NFAPI_CRC_INDICATION_PDU_T* pdu[MAX_NFAPI_CRC_INDICATION_PDU_T];
} NFAPI_CRC_INDICATION_PDU_ARRAY;

typedef struct RNTI_COUNT {
    uint32_t rnti;
    uint32_t count;
} RNTI_COUNT;

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_ARRAY* create_nfapi_crc_indication_pdu_array(uint32_t num_pdu, uint32_t num_rnti) {
    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_ARRAY* pdu_array = (NFAPI_CRC_INDICATION_PDU_ARRAY*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_ARRAY));
    if (!pdu_array) {
        // Memory allocation failed, return NULL
        printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_ARRAY\n");
        return NULL;
    }

    // Initialize the array size and RNTI counts
    pdu_array->size = 0;
    RNTI_COUNT* rnti_counts = (RNTI_COUNT*)malloc(sizeof(RNTI_COUNT) * num_rnti);
    if (!rnti_counts) {
        // Memory allocation failed, return NULL
        printf("Error: Failed to allocate memory for RNTI counts\n");
        free(pdu_array);
        return NULL;
    }
    memset(rnti_counts, 0, sizeof(RNTI_COUNT) * num_rnti);

    // Populate the array with random values
    uint32_t i = 0;
    while (i < num_pdu && pdu_array->size < MAX_NFAPI_CRC_INDICATION_PDU_T) {
        // Generate a random RX_UE_INFORMATION_TAG and RNTI value
        uint32_t rx_ue_information_tag = rand() % 1000;
        uint32_t rnti = rand() % MAX_RNTI;

        // Check if the RNTI is already present in the array
        bool duplicate = false;
        for (uint32_t j = 0; j < pdu_array->size; j++) {
            if (pdu_array->pdu[j]->rnti == rnti) {
                duplicate = true;
                break;
            }
        }

        // If the RNTI is not a duplicate, add it to the array and increment the count
        if (!duplicate) {
            pdu_array->pdu[pdu_array->size] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu_array->pdu[pdu_array->size]) {
                // Memory allocation failed, return NULL
                printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T\n");
                free(rnti_counts);
                free(pdu_array);
                return NULL;
            }

            pdu_array->pdu[pdu_array->size]->rx_ue_information_tag = rx_ue_information_tag;
            pdu_array->pdu[pdu_array->size]->rnti = rnti;
            pdu_array->pdu[pdu_array->size]->crc_indication_rel8_tag = rand() % 1000;
            pdu_array->pdu[pdu_array->size]->crcflag = (rand() % MAX_CRCFLAG) ? true : false;

            // Increment the RNTI count
            rnti_counts[rnti].count++;

            // Increment the array size
            pdu_array->size++;
        } else {
            // If the RNTI is a duplicate, check if it has exceeded the maximum allowable number of duplicates
            uint32_t duplicate_count = rnti_counts[rnti].count;
            if (duplicate_count > MAX_DUPLICATE_RNTI) {
                // If so, return an error
                printf("Error: Exceeded maximum allowable number of duplicates for RNTI %u\n", rnti);
                free(rnti_counts);
                free(pdu_array);
                return NULL;
            }
        }

        i++;
    }

    // Free the RNTI counts if we did not reach the end of the array
    if (i < num_pdu) {
        free(rnti_counts);
    }

    return pdu_array;
}

// Function to destroy an NFAPI CRC Indication PDU array
void destroy_nfapi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_ARRAY* pdu_array) {
    // Free the memory allocated for the RNTI counts
    if (pdu_array->size > 0) {
        free(pdu_array->rnti_counts);
    }

    // Free the memory allocated for the array of structures
    free(pdu_array);
}

