// Define the struct for NFIT_EVENT_RECORD
struct NFIT_EVENT_RECORD {
    int UE_IDENTIFIER;
    time_t timestamp;
    char* event_type;
    char* event_data;
};

// Define the helper function to calculate the event frequency distribution over a sliding window of time
void calculate_event_frequency(struct NFIT_EVENT_RECORD** records, int num_records, int num_events) {
    // Initialize the event frequency map
    int* event_freq = (int*)calloc(num_events, sizeof(int));

    for (int i = 0; i < num_records; i++) {
        struct NFIT_EVENT_RECORD* record = records[i];

        // Increment the event frequency count for each event type in the record
        for (int j = 0; j < record->num_events; j++) {
            int event_type = record->event_types[j];
            event_freq[event_type]++;
        }
    }
}

// Define the function to dynamically create and populate an array of NFIT_EVENT_RECORD structures
struct NFIT_EVENT_RECORD** generate_event_records(int num_records, int num_events) {
    // Create a dynamic array of NFIT_EVENT_RECORD structures
    struct NFIT_EVENT_RECORD** records = (struct NFIT_EVENT_RECORD**)calloc(num_records, sizeof(struct NFIT_EVENT_RECORD));

    // Initialize the timestamp for each record
    time_t current_timestamp = time(NULL);

    // Loop through the number of records to create and populate
    for (int i = 0; i < num_records; i++) {
        struct NFIT_EVENT_RECORD* record = (struct NFIT_EVENT_RECORD*)calloc(1, sizeof(struct NFIT_EVENT_RECORD));
        record->UE_IDENTIFIER = i + 1;
        record->timestamp = current_timestamp++;

        // Generate a random number of events for the record
        int num_events = rand() % 5 + 1;

        // Create an array to store the event types and data
        char* event_types[num_events];
        char* event_data[num_events];

        // Loop through each event and generate a random event type and data
        for (int j = 0; j < num_events; j++) {
            int event_type = rand() % 10 + 1;
            char* event_type_str = malloc(sizeof(char) * 2);
            sprintf(event_type_str, "%d", event_type);
            record->event_types[j] = event_type_str;

            int event_data_length = rand() % 10 + 1;
            char* event_data_str = malloc(sizeof(char) * (event_data_length + 1));
            for (int k = 0; k < event_data_length; k++) {
                event_data_str[k] = 'a' + rand() % 26;
            }
            event_data_str[event_data_length] = '\0';
            record->event_data[j] = event_data_str;
        }

        // Add the record to the array of records
        records[i] = record;
    }

    return records;
}

int main() {
    int num_records = 1000;
    int num_events = 50;

    struct NFIT_EVENT_RECORD** records = generate_event_records(num_records, num_events);

    calculate_event_frequency(records, num_records, num_events);

    // Print the event frequency distribution
    for (int i = 0; i < num_events; i++) {
        printf("Event type %d: %d\n", i + 1, event_freq[i]);
    }

    return 0;
}
