// Structure to represent a node in the linked list
typedef struct {
    nfapi_crc_indication_pdu_t pdu;
    struct node *next;
} node_t;

// Global variables
static node_t *head = NULL;
static int ttl = 300; // default TTL value (5 minutes)

// Function to insert a new element in the linked list
void insert(nfapi_crc_indication_pdu_t pdu) {
    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        // handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return;
    }
    new_node->pdu = pdu;
    new_node->next = head;
    head = new_node;
}

// Function to remove an element from the linked list based on RNTI
void remove(int rnti) {
    node_t *curr = head, *prev = NULL;
    while (curr != NULL && curr->pdu.rnti != rnti) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL) {
        // handle case where RNTI is not found in the linked list
        printf("RNTI not found\n");
        return;
    }
    if (prev == NULL) {
        head = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(curr);
}

// Function to update the CRC flag for a given RNTI
void update_crcflag(int rnti, int new_crcflag) {
    node_t *curr = head;
    while (curr != NULL && curr->pdu.rnti != rnti) {
        curr = curr->next;
    }
    if (curr == NULL) {
        // handle case where RNTI is not found in the linked list
        printf("RNTI not found\n");
        return;
    }
    curr->pdu.crcflag = new_crcflag;
}

