int get_crcflag(int rnti) {
    node_t *curr = head;
    while (curr != NULL && curr->pdu.rnti != rnti) {
        curr = curr->next;
    }
    if (curr == NULL) {
        // handle case where RNTI is not found in the linked list
        printf("RNTI not found\n");
        return -1;
    }
    return curr->pdu.crcflag;
}

// Function to clean up expired elements based on TTL value
void clean_up() {
    node_t *curr = head, *prev = NULL;
    time_t current_time = time(NULL);
    while (curr != NULL && curr->pdu.rx_ue_information_tag + ttl < current_time) {
        prev = curr;
        curr = curr->next;
    }
    if (prev == NULL) {
        head = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(curr);
}

// Function to set the TTL value
