void addPacket(DataPacket* packet) {
    // Check if the array is initialized and has enough capacity for another packet
    if (array == NULL || array->capacity <= array->length) {
        // Reallocate the array with double the current capacity
        size_t newCapacity = array->capacity * 2;
        DataPacket* newPackets = realloc(array->packets, newCapacity * sizeof(DataPacket));
