// Dynamic array class definition
class DynamicArray {
public:
    // Constructor
    DynamicArray() {
        this->arr = NULL;
        this->size = 0;
    }

    // Destructor
    ~DynamicArray() {
        if (this->arr != NULL) {
            free(this->arr);
        }
    }

    // Add packet to the array
    void addPacket(uint64_t timestamp, int id, bool status) {
        this->arr = realloc(this->arr, (this->size + 1) * sizeof(struct DataPacket));
        this->arr[this->size].timestamp = timestamp;
        this->arr[this->size].id = id;
        this->arr[this->size].status = status;
        this->size++;
    }

    // Remove outdated packets from the array based on retention period
    void removeOutdatedPackets(uint64_t retentionPeriod) {
        int i = 0;
        while (i < this->size) {
            if (this->arr[i].timestamp + retentionPeriod <= getCurrentTime()) {
                // Remove outdated packet
                free(this->arr[i]);
                this->arr[i] = NULL;
                this->size--;
            } else {
                i++;
            }
        }
    }

private:
    struct DataPacket* arr;
    int size;
};
