typedef struct {
    int ue_id;
    time_t creation_timestamp;
    time_t last_update_time;
} ue_context_info_t;

list_t* ue_contexts = NULL;
pthread_mutex_t lock;

void init_ue_contexts() {
    ue_contexts = malloc(sizeof(list_t));
    list_init(ue_contexts);
}

int add_ue_context(int ue_id, char* mac_layer_stats) {
    pthread_mutex_lock(&lock);
    if (list_size(ue_contexts) >= MAX_UE_CONTEXT) {
        printf("Error: UE context list is full.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    ue_context_t* new_context = malloc(sizeof(ue_context_t));
    new_context->ue_id = ue_id;
    new_context->mac_layer_stats = mac_layer_stats;
    list_insert(ue_contexts, new_context);

    time_t creation_timestamp = time(NULL);
    ue_context_info_t* context_info = malloc(sizeof(ue_context_info_t));
    context_info->ue_id = ue_id;
    context_info->creation_timestamp = creation_timestamp;
    context_info->last_update_time = creation_timestamp;

    log_add(LOG_UE_CONTEXT, creation_timestamp, &context_info);

    pthread_mutex_unlock(&lock);
    return 0;
}

int remove_ue_context(int ue_id) {
    pthread_mutex_lock(&lock);
    list_node* node = list_find(ue_contexts, ue_id, compare_ue_context);
    if (node == NULL) {
        printf("Error: UE context not found.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    ue_context_t* context = node->data;
    time_t last_update_time = time(NULL);
    context->last_update_time = last_update_time;

    log_add(LOG_UE_CONTEXT, last_update_time, &context);

    list_remove(ue_contexts, node);
    free(node);
    pthread_mutex_unlock(&lock);
    return 0;
}

int update_ue_context(int ue_id) {
    pthread_mutex_lock(&lock);
    list_node* node = list_find(ue_contexts, ue_id, compare_ue_context);
    if (node == NULL) {
        printf("Error: UE context not found.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    ue_context_t* context = node->data;
    time_t last_update_time = time(NULL);
    context->last_update_time = last_update_time;

    log_add(LOG_UE_CONTEXT, last_update_time, &context);

    pthread_mutex_unlock(&lock);
    return 0;
}

int find_ue_context(int ue_id) {
    pthread_mutex_lock(&lock);
    list_node* node = list_find(ue_contexts, ue_id, compare_ue_context);
    if (node == NULL) {
        printf("Error: UE context not found.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

int compare_ue_context(list_node* node, void* data) {
    ue_context_t* context = node->data;
    int ue_id = *((int*)data);

    if (context->ue_id == ue_id) {
        return 0;
    }

    return -1;
}

void cleanup_ue_contexts() {
    pthread_mutex_lock(&lock);
    list_destroy(ue_contexts, free);
    free(ue_contexts);
