#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Structure to store information about each frame
typedef struct {
    int pci;
    int sfn;
    int rbg;
    float rssi;
} frame_info_t;

// Queue for storing frames
struct queue {
    int size;
    frame_info_t *frames[1024];
    pthread_mutex_t mutex;
    semaphore_t sema;
};

void init_queue(struct queue *q) {
    q->size = 0;
    memset(&q->mutex, 0, sizeof(pthread_mutex_t));
    pthread_mutex_init(&q->mutex, NULL);
    semaphore_init(&q->sema, 1, 0);
}

void push_frame(struct queue *q, frame_info_t *f) {
    // Acquire mutex to protect the queue from concurrent access
    pthread_mutex_lock(&q->mutex);

    // Check if the queue is full
    if (q->size == 1024) {
        fprintf(stderr, "Queue is full\n");
        return;
    }

    // Insert the new frame at the end of the queue
    q->frames[q->size++] = f;

    // Signal the semaphore to indicate that a new frame has been added
    semaphore_post(&q->sema);

    // Release mutex
    pthread_mutex_unlock(&q->mutex);
}

frame_info_t *pop_frame(struct queue *q) {
    // Acquire mutex to protect the queue from concurrent access
    pthread_mutex_lock(&q->mutex);

    // Check if the queue is empty
    if (q->size == 0) {
        fprintf(stderr, "Queue is empty\n");
        return NULL;
    }

    // Remove the first frame from the queue and update the size
    frame_info_t *f = q->frames[--q->size];
    semaphore_wait(&q->sema);

    // Release mutex
    pthread_mutex_unlock(&q->mutex);

    return f;
}

// Structure to store information about the network configuration
typedef struct {
    int num_pci;
    int *pcis;
} network_config_t;

// Initialize the network configuration data structure
void init_network_config(network_config_t *cfg) {
    cfg->num_pci = 0;
    cfg->pcis = NULL;
}

// Add a new PCI to the network configuration data structure
void add_pci(network_config_t *cfg, int pci) {
    // Allocate memory for the new PCI
    if (cfg->num_pci == 0) {
        cfg->pcis = malloc(sizeof(int));
    } else {
        cfg->pcis = realloc(cfg->pcis, sizeof(int) * (cfg->num_pci + 1));
    }

    // Store the new PCI
    cfg->pcis[cfg->num_pci++] = pci;
}

// Remove an existing PCI from the network configuration data structure
void remove_pci(network_config_t *cfg, int pci) {
    // Find the index of the PCI to be removed
    int idx = -1;
    for (int i = 0; i < cfg->num_pci; i++) {
        if (cfg->pcis[i] == pci) {
            idx = i;
            break;
        }
    }

    // Check if the PCI was found in the configuration
    if (idx >= 0) {
        // Shift all remaining PCIs to the left of the removed PCI
        for (int i = idx; i < cfg->num_pci - 1; i++) {
            cfg->pcis[i] = cfg->pcis[i + 1];
        }

        // Update the size of the configuration
        cfg->num_pci--;
    } else {
        fprintf(stderr, "PCI not found in network configuration\n");
    }
}

// Structure to store information about the cellular base station
typedef struct {
    int pci;
    float rssi;
} base_station_t;

// Initialize the cellular base station structure
void init_base_station(base_station_t *bs) {
    bs->pci = -1;
    bs->rssi = -128.0f;
}

// Process a downlink frame and extract relevant information
frame_info_t process_frame(DL_FRAME_T *frame, network_config_t *cfg) {
    // Initialize the frame information structure
    frame_info_t info = { -1, -1, -1, -128.0f };

    // Check if the PCI is in the network configuration
    for (int i = 0; i < cfg->num_pci; i++) {
        if (cfg->pcis[i] == frame->pci) {
            info.pci = frame->pci;
            break;
        }
    }

    // Check if the PCI was found in the configuration
    if (info.pci == -1) {
        fprintf(stderr, "PCI not found in network configuration\n");
        return info;
    }

    // Update the frame information structure with the RSSI value from the base station
    for (int i = 0; i < cfg->num_pci; i++) {
        if (cfg->pcis[i] == frame->pci) {
            info.rssi = frame->base_stations[i].rssi;
            break;
        }
    }

    return info;
}

// Check if the RSSI value is within a certain threshold from the minimum and maximum values
int check_rssi(float rssi, float min_rssi, float max_rssi) {
    return (rssi >= min_rssi && rssi <= max_rssi);
}

// Main function for the program
int main() {
    // Initialize the network configuration data structure
    network_config_t cfg;
    init_network_config(&cfg);

    // Add some PCIs to the network configuration
    add_pci(&cfg, 100);
    add_pci(&cfg, 200);

    // Initialize the cellular base station structure
    base_station_t bs;
    init_base_station(&bs);

    // Process some downlink frames and extract relevant information
    for (int i = 0; i < 10; i++) {
        DL_FRAME_T frame;
        process_frame(&frame, &cfg);

        if (check_rssi(frame.base_stations[0].rssi, -128.0f, -96.0f)) {
            // Add the base station to the network configuration if it has a valid RSSI value
            add_pci(&cfg, frame.pci);
        }
    }

    return 0;
}
