// Define the linked list node for the structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the global variable for the head of the linked list
Node* head = NULL;

// Function to dynamically generate and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void generateList(int N) {
    // Create a new node for each structure
    Node* current = (Node*)malloc(sizeof(Node));
    head = current;

    // Generate unique RNTI values for each structure
    uint16_t rnti = 0;
    while (rnti < N) {
        current->data.RX_UE_INFORMATION_TAG = rnti;
        current->data.RNTI = rnti;
        current->data.CRCFLAG = rand() % 256; // Generate a random CRCFLAG value

        // Ensure no consecutive structures have the same RNTI value
        if (rnti > 0) {
            while (current->data.RNTI == head->data.RNTI) {
                current->data.RNTI = rand() % N;
            }
        }

        // Add the new node to the end of the linked list
        if (head->next != NULL) {
            current->next = head->next;
            head->next = current;
        } else {
            head->next = current;
        }

        rnti++;
    }
}

// Function to validate that all RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG fields are properly initialized before adding them to the list
