}

// Function to manage memory efficiently for the linked list, considering both time and space complexity
void freeList() {
    // Free each node in the linked list
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

// Function to ensure thread safety and prevent race conditions when calling the function from multiple threads within a high-performance communication system
void generateListThreadSafe(int N) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);
    generateList(N);
    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}
