    }

    // Update the environment variable with the path to the logging directory
    const char *log_dir_path = "/var/log/nfapi_crc_indication";
    setenv("NFAPI_CRC_INDICATION_LOG_DIR", log_dir_path, 1);

    // Create a new directory if it doesn't exist
    mkdir(log_dir_path, 0755);

    // Open the logging file and write the PDUs to it
    FILE *log_file = fopen(log_dir_path "/crc_indication.log", "w+");
    for (int i = 0; i < num_pdu; i++) {
        fprintf(log_file, "%d,%d,%d\n", pdu[i].rx_ue_information_tag, pdu[i].rnti, pdu[i].crc_indication_rel8_tag);
