    uint8_t *derived_iv = malloc(iv_len);

    // Derive the key and IV using PBKDF2-HMAC-SHA256 with OpenSSL's PKCS5_PBKDF2_HMAC function
    PKCS5_PBKDF2_HMAC(password, strlen((char *) password), pbkdf2_salt, 32, pbkdf2_iterations, EVP_sha256(), key_len, derived_key);
    PKCS5_PBKDF2_HMAC(password, strlen((char *) password), pbkdf2_salt, 32, pbkdf2_iterations, EVP_sha256(), iv_len, derived_iv);

    // Set the derived key and IV for the cipher context using OpenSSL's EVP_CIPHER_CTX_set_key_and_iv function
    EVP_EncryptInit_ex(cipher_ctx, NULL, NULL, derived_key, derived_iv);
}

