            int result = EVP_DecryptUpdate(cipher_ctx, decrypted_data, &decrypted_data_len, data + 16, data_len - 16);
            if (result != Z_OK) {
                printf("Error: %d\n", result);
            } else {
                // Use the decrypted data for processing
            }
        }
    } else {
        // The data is not compressed or encrypted, use it as is for processing
    }
}

// Function to process the data using the AES-256-GCM cipher
void process_data(uint8_t *data, size_t data_len) {
    // Initialize the AES-256-GCM cipher context using OpenSSL's EVP_EncryptInit_ex function
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(cipher_ctx, NULL, NULL, derived_key, derived_iv);

