    int result = EVP_EncryptUpdate(cipher_ctx, data, &data_len, data, data_len);
    if (result != Z_OK) {
        printf("Error: %d\n", result);
    } else {
        // Use the processed data for further processing
    }
}

// Function to clean up memory and resources
void cleanup() {
    free(derived_key);
    free(derived_iv);
    EVP_CIPHER_CTX_free(cipher_ctx);
}

int main() {
    // Initialize the AES-256-GCM cipher context using OpenSSL's EVP_EncryptInit_ex function
    init_cipher();

    // Derive a key and IV from a password using PBKDF2-HMAC with OpenSSL's PKCS5_PBKDF2_HMAC function
    derive_key_and_iv("password");

