#define SEQUENCE_NUMBER_MAX 65535
#define TRANSPORT_FORMAT_INFO_MIN 1
#define TRANSPORT_FORMAT_INFO_MAX 254
#define PHYSICAL_LAYER_CELL_ID_MIN 0
#define PHYSICAL_LAYER_CELL_ID_MAX 63
#define RECEPTION_QUALITY_WEIGHTS (struct { float signal; float noise; }){{0.7, 0.3}}
#define NFAPI_RRC_MESSAGE_T struct { int sequenceNumber; int transportFormatInfo; int physicalLayerCellId; float receptionQuality; }

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    NFAPI_RRC_MESSAGE_T* messages[MAX_MESSAGES];
    int numMessages;
} messageBuffer_t;

// Initializes a new message buffer
void messageBufferInit(messageBuffer_t* buffer) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&buffer->mutex, &attr);
    pthread_cond_init(&buffer->cond, NULL);
    buffer->numMessages = 0;
}

// Adds a new message to the buffer
void messageBufferAdd(messageBuffer_t* buffer, NFAPI_RRC_MESSAGE_T* msg) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->numMessages >= MAX_MESSAGES) {
        // Buffer is full, discard oldest message
        free(buffer->messages[0]);
        memmove(buffer->messages, buffer->messages + 1, sizeof(NFAPI_RRC_MESSAGE_T*) * (MAX_MESSAGES - 1));
        --buffer->numMessages;
    }
    buffer->messages[buffer->numMessages] = msg;
    ++buffer->numMessages;
    pthread_mutex_unlock(&buffer->mutex);
}

// Removes the oldest message from the buffer and returns it
NFAPI_RRC_MESSAGE_T* messageBufferRemove(messageBuffer_t* buffer) {
    NFAPI_RRC_MESSAGE_T* msg;
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->numMessages == 0) {
        // Buffer is empty, return NULL
        msg = NULL;
    } else {
        msg = buffer->messages[0];
        memmove(buffer->messages, buffer->messages + 1, sizeof(NFAPI_RRC_MESSAGE_T*) * (buffer->numMessages - 1));
        --buffer->numMessages;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return msg;
}

// Updates the reception quality of a message in the buffer
void messageBufferUpdate(messageBuffer_t* buffer, NFAPI_RRC_MESSAGE_T* msg) {
    pthread_mutex_lock(&buffer->mutex);
    for (int i = 0; i < buffer->numMessages; ++i) {
        if (msg == buffer->messages[i]) {
            // Found message, update reception quality and break
            msg->receptionQuality = calculateReceptionQuality(msg);
            break;
        }
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Calculates the reception quality of a message using weighted average of signal strength and noise level readings
float calculateReceptionQuality(NFAPI_RRC_MESSAGE_T* msg) {
    float signal = msg->signalStrength;
    float noise = msg->noiseLevel;
    return (RECEPTION_QUALITY_WEIGHTS.signal * signal + RECEPTION_QUALITY_WEIGHTS.noise * noise) / (RECEPTION_QUALITY_WEIGHTS.signal + RECEPTION_QUALITY_WEIGHTS.noise);
}

// Verifies the integrity of an allocated memory block and returns 1 if it is valid, 0 otherwise
int verifyIntegrity(void* mem) {
    // TODO: Implement a more robust verification method, such as checking for buffer overflows or underflows
    return (mem != NULL);
}
