    // Create a condition variable for waiting on the log entry list
    pthread_cond_t log_entry_cv = PTHREAD_COND_INITIALIZER;

    // Initialize the number of log entries written and failed writes
    int num_log_entries_written = 0;
    int num_failed_writes = 0;

    // Loop until all log entries have been written or a maximum number of retries has been reached
    while (num_log_entries_written < num_entries && num_failed_writes <= MAX_NUM_RETRIES) {
        // Lock the mutex for accessing the log entry list
        pthread_mutex_lock(&log_entry_lock);

        // Check if there are any log entries available to write
        while (num_log_entries_written < num_entries && log_entry_list[num_log_entries_written].message == NULL) {
            // Wait on the condition variable for a log entry to become available
            pthread_cond_wait(&log_entry_cv, &log_entry_lock);
        }

        // If there are any log entries available to write, write them to the log file
        if (num_log_entries_written < num_entries) {
            struct LogEntry* entry = &log_entry_list[num_log_entries_written];

            // Write the log entry to the log file
            write_log(entry);

            // Increment the number of log entries written and signal any waiting threads
            num_log_entries_written++;
            pthread_cond_signal(&log_entry_cv);
        }

        // Unlock the mutex for accessing the log entry list
        pthread_mutex_unlock(&log_entry_lock);
    }
