void addToList(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Element* element = createElement(data);
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) { // List is empty
        list->head = element;
        list->tail = element;
    } else {
        list->tail->next = element;
        list->tail = element;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove the first element from the list
Element* removeFirstFromList(List* list) {
    Element* element = NULL;
    pthread_mutex_lock(&list->mutex);
    if (list->head != NULL) { // List is not empty
        element = list->head;
        list->head = element->next;
        if (list->tail == element) {
            list->tail = NULL;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return element;
}

