}

// Function to check if the list has a maximum of 10 unique RNTI values
static inline bool isUniqueRNTI(List* list, Element* element) {
    for (Element* e = list->head; e != NULL && !isSameRNTI(e, element); e = e->next) {}
    return (e == NULL || isSameRNTI(e, element));
}

// Function to limit the total number of unique RNTI values to 10
static inline void limitUniqueRNTIs(List* list) {
    while (list->head != NULL && !isUniqueRNTI(list, list->head)) {
        Element* element = removeFirstFromList(list);
        free(element);
    }
}

