            printf("Structure %d: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u\n", i + 1, structures[i].rx_ue_information_tag, structures[i].rnti, structures[i].crc_indication_rel8_tag);
        }
