#include "3gpp_phy_indication.h"
#include "log.h"

#define MAX_PHY_INDICATIONS 1024
#define CELL_ID_INVALID 0xffffffff
#define PHICH_FLAG_INVALID 0xff

// List node structure for LTEPHYCHINDICATION_T structures
typedef struct list_node {
    LTEPHYCHINDICATION_T *data;
    struct list_node *next;
} ListNode;

// Linked list to store LTEPHYCHINDICATION_T structures
static ListNode *phy_indication_list = NULL;

// Mutex for protecting the phy_indication_list
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Semaphore for signaling when there are new phy indications available
static sem_t *sem = NULL;

// Thread pool for handling incoming phy indications asynchronously
static pthread_t thread_pool[MAX_PHY_INDICATIONS];
static int num_threads = 0;

// Caching strategy for storing LTEPHYCHINDICATION_T structures by CELL_ID
static ListNode *cell_id_cache[MAX_CELL_ID] = {NULL};

void init_phy_indication_list() {
    // Initialize the linked list
    phy_indication_list = NULL;
}

// Add a new LTEPHYCHINDICATION_T structure to the list, ensuring no duplicates
static void add_phy_indication(LTEPHYCHINDICATION_T *phy_indication) {
    // Check if the cell ID is already present in the cache
    ListNode *cache = get_cell_id_cache(phy_indication->CELL_ID);
    if (cache != NULL) {
        // If so, update the existing structure with the new PHICH_FLAG
        cache->data->PHICH_FLAG = phy_indication->PHICH_FLAG;
        return;
    }

    // Add a new node to the linked list
    ListNode *new_node = malloc(sizeof(ListNode));
    new_node->data = phy_indication;
    new_node->next = NULL;

    // Check if there is already a head node
    if (phy_indication_list == NULL) {
        phy_indication_list = new_node;
    } else {
        ListNode *curr = phy_indication_list;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
}

// Get the cache node for a given CELL_ID
static ListNode *get_cell_id_cache(uint32_t cell_id) {
    if (cell_id < MAX_CELL_ID && cell_id_cache[cell_id] != NULL) {
        return cell_id_cache[cell_id];
    } else {
        // If the cache does not contain the CELL_ID, search the linked list
        ListNode *curr = phy_indication_list;
        while (curr != NULL) {
            if (curr->data->CELL_ID == cell_id) {
                return curr;
            }
            curr = curr->next;
        }
    }
    return NULL;
}

// Populate the cache with new LTEPHYCHINDICATION_T structures
static void populate_cache() {
    ListNode *curr = phy_indication_list;
    while (curr != NULL) {
        // Add the node to the cache
        if (get_cell_id_cache(curr->data->CELL_ID) == NULL) {
            cell_id_cache[curr->data->CELL_ID] = curr;
        }
        curr = curr->next;
    }
}

// Handle a single LTEPHYCHINDICATION_T structure asynchronously
void handle_phy_indication(LTEPHYCHINDICATION_T *phy_indication) {
    // Add the phy indication to the linked list and cache
    add_phy_indication(phy_indication);
    populate_cache();

    // Log the received phy indication
    log_phy_indication(phy_indication);
}

// Handle a batch of LTEPHYCHINDICATION_T structures asynchronously
void handle_phy_indications(LTEPHYCHINDICATION_T *phy_indications, int num) {
    // Add the phy indications to the linked list and cache
    for (int i = 0; i < num; i++) {
        add_phy_indication(&phy_indications[i]);
    }
    populate_cache();

    // Log all received phy indications
    for (int i = 0; i < num; i++) {
        log_phy_indication(&phy_indications[i]);
    }
}

// Handle an incoming LTEPHYCHINDICATION_T structure synchronously
void handle_phy_indication_sync(LTEPHYCHINDICATION_T *phy_indication) {
    // Add the phy indication to the linked list and cache
    add_phy_indication(phy_indication);
    populate_cache();

    // Log the received phy indication
    log_phy_indication(phy_indication);
}

// Handle a batch of incoming LTEPHYCHINDICATION_T structures synchronously
void handle_phy_indications_sync(LTEPHYCHINDICATION_T *phy_indications, int num) {
    // Add the phy indications to the linked list and cache
    for (int i = 0; i < num; i++) {
        add_phy_indication(&phy_indications[i]);
    }
    populate_cache();

    // Log all received phy indications
    for (int i = 0; i < num; i++) {
        log_phy_indication(&phy_indications[i]);
    }
}

// Thread pool worker function to handle incoming phy indications asynchronously
void *handle_phy_indications_async(void *arg) {
    // Initialize the thread-local cache
    ListNode *cache = malloc(sizeof(ListNode));
    cache->data = NULL;
    cache->next = NULL;

    while (1) {
        sem_wait(sem);

        // Get the current head node
        ListNode *curr = phy_indication_list;

        // Handle each phy indication in the batch
        while (curr != NULL && cache->data == NULL) {
            LTEPHYCHINDICATION_T *phy_indication = curr->data;
            handle_phy_indication(phy_indication);
            curr = curr->next;
        }

        // Clear the cache and free the memory
        if (cache->data != NULL) {
            ListNode *prev = cache;
            while (prev->next != NULL) {
                prev = prev->next;
                free(prev->next);
            }
            curr = cache;
            free(curr);
        }
    }
}

// Initialize the thread pool and synchronization variables
void init_thread_pool() {
    // Create a semaphore to synchronize the threads
    sem = malloc(sizeof(sem_t));
    sem_init(sem, 0, 0);

    // Create the thread pool
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
    int ret = pthread_create(&thread, &attr, handle_phy_indications_async, NULL);
    if (ret != 0) {
        perror("pthread_create");
    }
    pthread_attr_destroy(&attr);
}

// Handle an incoming LTEPHYCHINDICATION_T structure asynchronously
void handle_phy_indication(LTEPHYCHINDICATION_T *phy_indication) {
    sem_post(sem);
}

// Handle a batch of incoming LTEPHYCHINDICATION_T structures asynchronously
void handle_phy_indications(LTEPHYCHINDICATION_T *phy_indications, int num) {
    // Increase the semaphore value by the number of phy indications
    for (int i = 0; i < num; i++) {
        sem_post(sem);
    }
}']

['package com.example.batchprocessing;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class TransactionLog {
    private final long transactionId;
    private final LocalDateTime timestamp;
    private final double amount;
    private final Status status;

    public TransactionLog(long transactionId, LocalDateTime timestamp, double amount, Status status) {
        this.transactionId = transactionId;
        this.timestamp = timestamp;
        this.amount = amount;
        this.status = status;
    }

    public long getTransactionId() {
        return transactionId;
    }

    public LocalDateTime getTimestamp() {
        return timestamp;
    }

    public double getAmount() {
        return amount;
    }

    public Status getStatus() {
        return status;
    }
}

public enum Status {
    SUCCESS, FAILURE
}

class TransactionLogManager {
    private final Map<Long, TransactionLog> transactionLogs = new ConcurrentHashMap<>();

    public void addTransactionLog(long transactionId, LocalDateTime timestamp, double amount, Status status) {
        transactionLogs.put(transactionId, new TransactionLog(transactionId, timestamp, amount, status));
    }

    public List<TransactionLog> getTransactionLogs() {
        return List.copyOf(transactionLogs.values());
    }

    public void cleanupOldTransactionLogs(int threshold) {
        transactionLogs.entrySet().removeIf(entry -> entry.getValue().getStatus() == Status.SUCCESS && entry.getValue().getTimestamp().isBefore(LocalDateTime.now().minusDays(threshold)));
    }
}

class BatchProcessor {
    private final TransactionLogManager transactionLogManager;
    private final List<TransactionLog> transactionLogs;

    public BatchProcessor(List<TransactionLog> transactionLogs) {
        this.transactionLogs = transactionLogs;
        this.transactionLogManager = new TransactionLogManager();
    }

    public void processBatch() {
        for (TransactionLog transactionLog : transactionLogs) {
            transactionLogManager.addTransactionLog(transactionLog.getTransactionId(), transactionLog.getTimestamp(), transactionLog.getAmount(), transactionLog.getStatus());
        }

        // Aggregate the transactions based on their statuses
        Map<Status, List<Long>> aggregatedTransactions = new ConcurrentHashMap<>();
        for (TransactionLog transactionLog : transactionLogManager.getTransactionLogs()) {
            Status status = transactionLog.getStatus();
            if (!aggregatedTransactions.containsKey(status)) {
                aggregatedTransactions.put(status, new ArrayList<>());
            }
            List<Long> transactions = aggregatedTransactions.get(status);
            transactions.add(transactionLog.getTransactionId());
        }

        // Filter the transactions based on certain criteria
        Map<Status, List<Long>> filteredTransactions = new ConcurrentHashMap<>();
        for (Map.Entry<Status, List<Long>> entry : aggregatedTransactions.entrySet()) {
            Status status = entry.getKey();
            List<Long> transactions = entry.getValue();
            if (transactions.size() > 10) {
                filteredTransactions.put(status, transactions);
            }
        }

        // Transform the transactions based on certain criteria
        Map<Status, List<Double>> transformedTransactions = new ConcurrentHashMap<>();
        for (Map.Entry<Status, List<Long>> entry : filteredTransactions.entrySet()) {
            Status status = entry.getKey();
            List<Long> transactions = entry.getValue();
            double totalAmount = 0;
            for (Long transactionId : transactions) {
                TransactionLog transactionLog = transactionLogManager.getTransactionLogs().stream()
                        .filter(log -> log.getTransactionId() == transactionId)
                        .findFirst()
                        .orElseThrow();
                totalAmount += transactionLog.getAmount();
            }
            transformedTransactions.put(status, Collections.singletonList(totalAmount));
        }
    }
}

class TransactionLogCleaner {
    private final TransactionLogManager transactionLogManager;
    private final int threshold;

    public TransactionLogCleaner(TransactionLogManager transactionLogManager, int threshold) {
        this.transactionLogManager = transactionLogManager;
        this.threshold = threshold;
    }

    public void cleanup() {
        transactionLogManager.cleanupOldTransactionLogs(threshold);
    }
}

class BatchProcessingFramework {
    private final List<BatchProcessor> batchProcessors;
    private final TransactionLogCleaner transactionLogCleaner;

    public BatchProcessingFramework() {
        this.batchProcessors = new ArrayList<>();
        this.transactionLogCleaner = new TransactionLogCleaner(new TransactionLogManager(), 30);
    }

    public void addBatchProcessor(List<TransactionLog> transactionLogs) {
        BatchProcessor batchProcessor = new BatchProcessor(transactionLogs);
        this.batchProcessors.add(batchProcessor);
        // Run the cleanup task in a separate thread to ensure it runs asynchronously
        new Thread(() -> transactionLogCleaner.cleanup()).start();
    }

    public void processBatches() {
        for (BatchProcessor batchProcessor : this.batchProcessors) {
            batchProcessor.processBatch();
        }
    }
}']

