// Macro for defining the maximum number of elements in the list
#define MAX_NUM_ELEMENTS 10000

// Structure to hold the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    // Array of pointers to NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T **elements;
    // Number of elements in the list
    int num_elements;
    // Mutex for synchronizing access to the list
    pthread_mutex_t mutex;
} CrcIndicationList;

// Function to add a new element to the list
int addElement(CrcIndicationList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);
    // Check if there is enough space in the list to add a new element
    if (list->num_elements == MAX_NUM_ELEMENTS) {
        // Release the lock and return an error code
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    // Add the new element to the list
    list->elements[list->num_elements++] = element;
    // Release the lock
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to remove an element from the list
int removeElement(CrcIndicationList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);
    // Search for the element to be removed in the list
    int index = -1;
    for (int i = 0; i < list->num_elements; i++) {
        if (list->elements[i] == element) {
            index = i;
            break;
        }
    }
    // Check if the element was found in the list
    if (index == -1) {
        // Release the lock and return an error code
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    // Remove the element from the list
    int num_elements = list->num_elements - 1;
    for (int i = index; i < num_elements; i++) {
        list->elements[i] = list->elements[i + 1];
    }
    // Decrement the number of elements in the list
    list->num_elements--;
    // Release the lock
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to retrieve an element from the list by its index
NFAPI_CRC_INDICATION_PDU_T *getElement(CrcIndicationList *list, int index) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&list->mutex);
    // Check if the index is valid
    if (index < 0 || index >= list->num_elements) {
        // Release the lock and return nullptr
        pthread_mutex_unlock(&list->mutex);
        return nullptr;
    }
    // Return the element at the specified index
    NFAPI_CRC_INDICATION_PDU_T *element = list->elements[index];
    // Release the lock
    pthread_mutex_unlock(&list->mutex);
    return element;
