  int size;
  int capacity;
  NFAPI_CRC_INDICATION_PDU_T* elements;
} ThreadSafeArray;

// Create a new thread-safe array with the given initial capacity
ThreadSafeArray* create_array(int capacity) {
  ThreadSafeArray* array = (ThreadSafeArray*)malloc(sizeof(ThreadSafeArray));
  if (!array) {
    return NULL;
  }
  array->mutex = PTHREAD_MUTEX_INITIALIZER;
  array->size = 0;
  array->capacity = capacity;
  array->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
  if (!array->elements) {
    free(array);
    return NULL;
  }
  return array;
}

// Add a new element to the thread-safe array, growing the array if necessary
void add_element(ThreadSafeArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
  pthread_mutex_lock(&array->mutex);
  // Grow the array if it's full
  if (array->size == array->capacity) {
    int new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_elements) {
      pthread_mutex_unlock(&array->mutex);
      return;
    }
    array->elements = new_elements;
    array->capacity = new_capacity;
  }
  // Add the element to the array
  array->elements[array->size++] = element;
  pthread_mutex_unlock(&array->mutex);
}

// Retrieve an element from the thread-safe array by index
NFAPI_CRC_INDICATION_PDU_T get_element(ThreadSafeArray* array, int index) {
  if (index < 0 || index >= array->size) {
    return NULL;
  }
  pthread_mutex_lock(&array->mutex);
  NFAPI_CRC_INDICATION_PDU_T element = array->elements[index];
  pthread_mutex_unlock(&array->mutex);
  return element;
}

// Check if a RNTI value is already present in the thread-safe array
