  bool found = false;
  for (int i = 0; i < array->size && !found; ++i) {
    if (array->elements[i].RNTI == RNTI) {
      found = true;
    }
  }
  pthread_mutex_unlock(&array->mutex);
  return found;
}

// Release all allocated resources when the array is no longer needed
void release_array(ThreadSafeArray* array) {
  free(array->elements);
  free(array);
