    data_record_count++;
}

// Define a function to read a DataRecord from the buffer
struct DataRecord* readDataRecord(uint64_t timestamp) {
    struct DataRecord *record = NULL;

    for (size_t i = 0; i < data_record_count; i++) {
        if (data_records[i].timestamp == timestamp) {
            record = &data_records[i];
            break;
        }
    }

    return record;
}

// Define a function to update a DataRecord in the buffer
void updateDataRecord(uint64_t timestamp, char* event_type, char* event_details) {
    struct DataRecord *record = readDataRecord(timestamp);
    if (!record) {
        // Record not found, add it to the buffer
        writeDataRecord(timestamp, event_type, event_details);
    } else {
        // Record found, update its details
        strcpy(record->event_type, event_type);
        strcpy(record->event_details, event_details);
    }
}

// Define a function to retrieve the last DataRecord in the buffer
struct DataRecord* getLastDataRecord(void) {
    return &data_records[data_record_count - 1];
}

// Implement the expandDynamicDataStore function to handle dynamic memory allocation for an array of DataRecords
int expandDynamicDataStore(uint64_t timestamp, char* event_type, char* event_details) {
    // Check if the buffer is full
    if (data_record_count == DATA_RECORD_BUFFER_SIZE) {
        // The buffer is full, expand it to make space for new records
        expandDataRecordBuffer();
    }

    // Add the new record to the buffer
    writeDataRecord(timestamp, event_type, event_details);

    return 0;
}
```
