typedef struct network_stack_config {
  int num_ccch_msgs;
  NFAPI_CCCH_MSG1_T *ccch_msgs[num_ccch_msgs];
} network_stack_config_t;

void initializeNetworkStackConfig(network_stack_config_t *config) {
  // Fetch UE IDs and sequence numbers from external database
  int num_uids = get_num_uids();
  int num_seqs = get_num_seqs();
  config->num_ccch_msgs = num_uids * num_seqs;

  // Allocate memory for CCCH messages
  for (int i = 0; i < num_uids; i++) {
    for (int j = 0; j < num_seqs; j++) {
      NFAPI_CCCH_MSG1_T *msg = malloc(sizeof(NFAPI_CCCH_MSG1_T));
      msg->ccch_msg1_tag = get_ccch_msg1_tag();
      msg->ue_id = i;
      msg->sequence_number = j;
      config->ccch_msgs[i * num_seqs + j] = msg;
    }
  }
}

void send_messages(network_stack_config_t *config) {
  for (int i = 0; i < config->num_ccch_msgs; i++) {
    NFAPI_CCCH_MSG1_T *msg = config->ccch_msgs[i];
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
      perror("socket");
      continue;
    }
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(NFAPI_CCCH_MSG1_PORT);
    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);
    sendto(sockfd, msg, sizeof(NFAPI_CCCH_MSG1_T), 0, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
    close(sockfd);
  }
}

void free_messages(network_stack_config_t *config) {
  for (int i = 0; i < config->num_ccch_msgs; i++) {
    NFAPI_CCCH_MSG1_T *msg = config->ccch_msgs[i];
    free(msg);
  }
}
```
