// TrafficEvent array data structure
struct TrafficEventArray {
    TrafficEvent *events;
    size_t capacity;
    size_t count;
};

TrafficEventArray* create_traffic_event_array() {
    // Allocate memory for the array structure
    TrafficEventArray* array = (TrafficEventArray*)malloc(sizeof(TrafficEventArray));
    if (!array) {
        return NULL;
    }

    // Initialize the capacity and count of the array
    array->capacity = 1024;
    array->count = 0;

    // Allocate memory for the event array
    array->events = (TrafficEvent*)malloc(sizeof(TrafficEvent) * array->capacity);
    if (!array->events) {
        free(array);
        return NULL;
    }

    return array;
}

int add_traffic_event(TrafficEventArray* array, TrafficEvent event) {
    // Check for overflow
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TrafficEvent* new_events = (TrafficEvent*)realloc(array->events, sizeof(TrafficEvent) * new_capacity);
        if (!new_events) {
            return -1;
        }
        array->events = new_events;
        array->capacity = new_capacity;
    }

    // Add the event to the array
    array->events[array->count] = event;
    array->count++;

    return 0;
}

TrafficEvent* get_traffic_event(TrafficEventArray* array, size_t index) {
    // Check for out-of-bounds access
    if (index >= array->count) {
        return NULL;
    }

    return &array->events[index];
}

void clear_traffic_event_array(TrafficEventArray* array) {
    // Clear the event array and reset the count
    array->count = 0;
}

void free_traffic_event_array(TrafficEventArray* array) {
    // Free the event array and the array structure
    if (array->events) {
        free(array->events);
    }
    free(array);
}
