        struct NFAPI_CRC_INDICATION_PDU_T *data = createNFAPI_CRC_INDICATION_PDU_T(123456, 1, true); // use some dummy values for testing purposes
        if (data) {
            insert(data);
        } else {
            perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T from downstream module");
        }
    }
}

// Function to handle the connection with the downstream module
void downstreamConnectionHandler() {
    struct NFAPI_CRC_INDICATION_PDU_T *data;
    while ((data = readFromDownstream())) { // read from the downstream module until there is no more data
        if (cacheFull()) {
            // cache is full, try to resize it based on memory pressure
            int newSize = CACHE_SIZE * 2;
            resizeCache(newSize);
        }
        addToCache(data);
    }
}

// Function to handle the connection with the upstream module
void upstreamConnectionHandler() {
    while (true) { // loop indefinitely
        processMessage(); // process the NFAPI message
    }
}

int main() {
    downstreamConnectionHandler(); // handle the connection with the downstream module
    upstreamConnectionHandler(); // handle the connection with the upstream module
    return 0;
}
