#### Multi-threaded implementation using queues

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/select.h>

// define the NFAPI message structure
struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcfailure_flag;
};

// define the connection parameters
#define DOWNSTREAM_IP "127.0.0.1"
#define DOWNSTREAM_PORT 12345
#define UPSTREAM_IP "127.0.0.1"
#define UPSTREAM_PORT 6789

// define the message queue parameters
#define QUEUE_SIZE 1000
#define MSG_BUFFER_SIZE 10000
#define SEM_VALUE_MAX 255

// define the thread functions
void *downstreamConnectionHandler(void *arg);
void *upstreamConnectionHandler(void *arg);
void *messageQueueHandler(void *arg);

// define the message queue and semaphore
sem_t sem;
struct NFAPI_CRC_INDICATION_PDU_T msg_queue[QUEUE_SIZE];
int msg_front, msg_back;

// main function
int main() {
    // initialize the message queue and semaphore
    sem = sem_open("sem", O_CREAT, 0644, SEM_VALUE_MAX);
    msg_front = msg_back = 0;

    // create the thread for handling the downstream connection
    pthread_t downstream_thread;
    if (pthread_create(&downstream_thread, NULL, downstreamConnectionHandler, NULL)) {
        perror("Failed to create downstream thread");
        exit(1);
    }

    // create the thread for handling the upstream connection
    pthread_t upstream_thread;
    if (pthread_create(&upstream_thread, NULL, upstreamConnectionHandler, NULL)) {
        perror("Failed to create upstream thread");
        exit(1);
    }

    // wait for the threads to finish
    pthread_join(downstream_thread, NULL);
    pthread_join(upstream_thread, NULL);

    return 0;
}

// function to handle the connection with the downstream module
void *downstreamConnectionHandler(void *arg) {
    // open a socket for the downstream connection
    int sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock < 0) {
        perror("Failed to create socket");
        exit(1);
    }

    // connect to the downstream server
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(DOWNSTREAM_PORT);
    if (inet_pton(AF_INET, DOWNSTREAM_IP, &servaddr.sin_addr) <= 0) {
        perror("Failed to set server address");
        exit(1);
    }
    if (connect(sock, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Failed to connect");
        exit(1);
    }

    // send a message to the downstream module
    char msg[] = "Hello from the downstream module!";
    send(sock, msg, strlen(msg), 0);

    // receive a message from the downstream module
    char buffer[MSG_BUFFER_SIZE];
    recv(sock, buffer, MSG_BUFFER_SIZE, 0);
    printf("Received message: %s\n", buffer);

    // close the socket and exit
    close(sock);
    return NULL;
}

// function to handle the connection with the upstream module
void *upstreamConnectionHandler(void *arg) {
    // open a socket for the upstream connection
    int sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock < 0) {
        perror("Failed to create socket");
        exit(1);
    }

    // connect to the upstream server
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(UPSTREAM_PORT);
    if (inet_pton(AF_INET, UPSTREAM_IP, &servaddr.sin_addr) <= 0) {
        perror("Failed to set server address");
        exit(1);
    }
    if (connect(sock, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Failed to connect");
        exit(1);
    }

    // send a message to the upstream module
    char msg[] = "Hello from the upstream module!";
    send(sock, msg, strlen(msg), 0);

    // receive a message from the upstream module
    char buffer[MSG_BUFFER_SIZE];
    recv(sock, buffer, MSG_BUFFER_SIZE, 0);
    printf("Received message: %s\n", buffer);

    // close the socket and exit
    close(sock);
    return NULL;
}

// function to handle the message queue
void *messageQueueHandler(void *arg) {
    while (1) {
        // wait for a semaphore signal
        sem_wait(&sem);

        // check if there is a message in the queue
        if (msg_front == msg_back) continue;

        // handle the message
        struct NFAPI_CRC_INDICATION *msg = &msg_queue[msg_front];
        printf("Received message: %s\n", msg->message);

        // update the front index and signal a semaphore
        msg_front = (msg_front + 1) % QUEUE_SIZE;
        sem_post(&sem);
    }
}']

