        event->eventType = eventType;
        event->metadata = metadata;

        // Add the event to the array
        events[i] = event;
    }
}

// Function to expand the array if new events exceed its current capacity
void expandEvents(int numEvents) {
    // Check if the array has been initialized
    if (!events) {
        fprintf(stderr, "Event array not initialized\n");
        return;
    }

    // Calculate the number of entries to add to the array
    int numEntriesToAdd = numEvents - (sizeof(TrafficEvent*) * events);
    if (numEntriesToAdd <= 0) {
        fprintf(stderr, "No need to expand event array\n");
        return;
    }

    // Allocate memory for the additional entries in the array
    TrafficEvent** newEvents = (TrafficEvent**)malloc(sizeof(TrafficEvent*) * numEntriesToAdd);
    if (!newEvents) {
        fprintf(stderr, "Failed to allocate memory for additional event entries\n");
        return;
    }

    // Initialize each entry in the new array with NULL
    for (int i = 0; i < numEntriesToAdd; i++) {
        newEvents[i] = NULL;
    }

    // Copy the contents of the old array to the new one, and then free the old array
    memcpy(newEvents, events, sizeof(TrafficEvent*) * (sizeof(events) - 1));
    free(events);

    // Update the pointer to point to the new array
    events = newEvents;
}

// Function to release memory allocated for the array of events
void destroyEvents() {
    // Check if the array has been initialized
    if (!events) {
        fprintf(stderr, "Event array not initialized\n");
        return;
    }

    // Free each event structure in the array
    for (int i = 0; i < sizeof(TrafficEvent*) * events; i++) {
        free(events[i]);
    }

    // Free the memory allocated for the array itself
    free(events);
}
