#define MAX_UE_COUNT 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char configId[32];
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} UE_CONFIG_DATA;

void initializeUECrcIndications(int numUe, UE_CONFIG_DATA *ueConfigData) {
    // Check if the number of UE instances is valid
    if (numUe <= 0 || numUe > MAX_UE_COUNT) {
        fprintf(stderr, "Invalid number of UE instances: %d\n", numUe);
        return;
    }

    // Allocate memory for the NFAPI CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T *crcIndications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numUe);
    if (crcIndications == NULL) {
        fprintf(stderr, "Failed to allocate memory for CRC indication PDUs\n");
        return;
    }

    // Initialize the NFAPI CRC indication PDUs
    for (int i = 0; i < numUe; i++) {
        crcIndications[i].RX_UE_INFORMATION_TAG = ueConfigData[i].RNTI;
        crcIndications[i].crcIndicationRel8Tag.crcFlag = rand() % 2 ? true : false;
    }

    // Compute the MD5 hash of the unique configuration ID string for each UE instance
    char md5Hash[33];
    for (int i = 0; i < numUe; i++) {
        sprintf(md5Hash, "%s%d", ueConfigData[i].configId, i);
        MD5_CTX ctx;
        MD5Init(&ctx);
        MD5Update(&ctx, md5Hash, strlen(md5Hash));
        MD5Final(crcIndications[i].crcIndicationRel8Tag.crcIndicatorContainer.crcIndicator, &ctx);
    }

    // Release the memory allocated for the NFAPI CRC indication PDUs
    free(crcIndications);
}
