        node->CRCFLAG = rand() % 100;
        node->next = head;
        head = node;
    }

    // Sort the linked list based on the RNTI values in ascending order
    NFAPI_CRC_INDICATION_PDU* current = head;
    while (current != NULL) {
        if (current->next != NULL && current->RNTI > current->next->RNTI) {
            // Swap the current node with its next node
            NFAPI_CRC_INDICATION_PDU* temp = current->next;
            current->next = temp->next;
