    // Initialize the set
    rntiSet->numElements = 0;
    rntiSet->maxElements = 100;
    rntiSet->elements = (int *)malloc(sizeof(int) * rntiSet->maxElements);
    if (rntiSet->elements == NULL) {
        // Handle allocation failure gracefully
        printf("Memory allocation failed\n");
        return;
    }

    // Iterate over the linked list and validate the RNTIs
    struct NFAPI_CRC_INDICATION_PDU_T *pdu = head;
    while (pdu != NULL) {
        // Check if the RNTI is already in the set
        int *rntiPtr = rntiSet->elements;
        for (int i = 0; i < rntiSet->numElements; i++) {
            if (*rntiPtr == pdu->RNTI) {
                // If the RNTI is already in the set, recompute the CRC flags until uniqueness is achieved
                do {
                    pdu->CRCFLAG = !pdu->CRCFLAG;
                } while (*rntiPtr == pdu->RNTI);
            } else {
                // If the RNTI is not in the set, add it to the set and move on to the next PDU
                *rntiPtr = pdu->RNTI;
                rntiPtr++;
                if (rntiSet->numElements < rntiSet->maxElements) {
                    rntiSet->numElements++;
                } else {
                    // If the set is full, resize it and recompute the CRC flags for all PDUs
                    struct NFAPI_CRC_INDICATION_PDU_T *oldHead = head;
                    int newSize = rntiSet->maxElements * 2;
