## Go

```go
package main

import "fmt"

type DynamicArray struct {
	data  []interface{}
	size  int
	cap   int
}

func (d *DynamicArray) Add(v interface{}) bool {
	if d.size == d.cap {
		return false
	}
	d.data = append(d.data, v)
	d.size++
	return true
}

func (d *DynamicArray) Remove() interface{} {
	if d.size == 0 {
		return nil
	}
	d.size--
	v := d.data[d.size]
	d.data = append(d.data[:d.size], d.data[d.size+1:]...)
	return v
}

func (d *DynamicArray) Get(i int) interface{} {
	if i < 0 || i >= d.size {
		return nil
	}
	return d.data[i]
}

func (d *DynamicArray) Set(i int, v interface{}) bool {
	if i < 0 || i >= d.size {
		return false
	}
	d.data[i] = v
	return true
}

func (d *DynamicArray) Print() {
	for _, e := range d.data {
		fmt.Println(e)
	}
}

func main() {
	d := DynamicArray{data: make([]interface{}, 5), size: 0, cap: 5}
	d.Add("a")
	d.Add("b")
	d.Add("c")
	fmt.Println(d.Get(1)) // Output: b
	d.Set(1, "x")
	d.Print()            // Output: a x c
}
