int encrypt(uint8_t *plaintext, int plaintext_len, uint8_t *key, EVP_CIPHER *evp_cipher) {
    int ciphertext_len = 0;
    uint8_t *ciphertext = NULL;

    if (plaintext_len <= 0) {
        return -1;
    }

    // allocate memory for the ciphertext
    ciphertext = malloc(plaintext_len);
    if (!ciphertext) {
        return -1;
