    int update_len = 0;
    while (update_len < plaintext_len) {
        int chunk_size = plaintext_len - update_len;
        if (chunk_size > EVP_CIPHER_block_size(evp_cipher)) {
            chunk_size = EVP_CIPHER_block_size(evp_cipher);
        }
        EVP_EncryptUpdate(evp_cipher, ciphertext + update_len, &chunk_size, plaintext + update_len, chunk_size);
        update_len += chunk_size;
    }

    // get the finalized ciphertext length
    EVP_EncryptFinal_ex(evp_cipher, ciphertext + update_len, &ciphertext_len);

    return ciphertext_len;
}

