    addElement(array, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG);
}

// Function to retrieve an element from the array by RNTI value
NFAPI_CRC_INDICATION_PDU_T *getElementByRNTI(NFAPI_CRC_INDICATION_ARRAY_T *array, int RNTI) {
    // Check if the RNTI value is found in the array
    for (int i = 0; i < array->count; i++) {
        if (array->elements[i].RNTI == RNTI) {
            return &(array->elements[i]);
        }
    }

    // If the RNTI value is not found, return NULL
    return NULL;
}

// Function to resize the array when new configurations are added
void resizeArray(NFAPI_CRC_INDICATION_ARRAY_T *array) {
    // Double the size of the array
    int newSize = array->count * 2;

    // Create a new array with the doubled size
    NFAPI_CRC_INDICATION_PDU_T *newElements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize);

    // Copy the elements from the old array to the new array
    for (int i = 0; i < array->count; i++) {
        newElements[i] = array->elements[i];
    }

    // Free the memory used by the old array
    free(array->elements);

    // Set the elements field of the array to point to the new array
    array->elements = newElements;

    // Update the count field to reflect the new size
    array->count = newSize;
}

// Function to serialize the configuration array to a binary file
void serializeArray(NFAPI_CRC_INDICATION_ARRAY_T *array, FILE *file) {
    fwrite(&(array->count), sizeof(int), 1, file); // Write the number of elements in the array
    for (int i = 0; i < array->count; i++) {
        fwrite(&(array->elements[i].RNTI), sizeof(int), 1, file); // Write the RNTI value
        fwrite(&(array->elements[i].CRC_INDICATION_REL8_TAG), sizeof(int), 1, file); // Write the CRC indication tag
        fwrite(&(array->elements[i].CRCFLAG), sizeof(bool), 1, file); // Write the CRCFLAG value
    }
}

// Function to deserialize the configuration array from a binary file
void deserializeArray(NFAPI_CRC_INDICATION_ARRAY_T *array, FILE *file) {
    int numElements;
    fread(&numElements, sizeof(int), 1, file); // Read the number of elements in the array
    array->count = numElements;
    array->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numElements);
    for (int i = 0; i < numElements; i++) {
        fread(&(array->elements[i].RNTI), sizeof(int), 1, file); // Read the RNTI value
        fread(&(array->elements[i].CRC_INDICATION_REL8_TAG), sizeof(int), 1, file); // Read the CRC indication tag
        fread(&(array->elements[i].CRCFLAG), sizeof(bool), 1, file); // Read the CRCFLAG value
    }
}

