    int num_threads = 2;
    pthread_t threads[num_threads];

    // Create a thread to consume a batch of CRC indications and process them concurrently in multiple threads
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, consume_crc_indications, (void *)num_threads);
    }

    // Add a batch of CRC indications to the array and signal the consumers
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
    for (int i = 0; i < MAX_CRC_INDICATIONS_PER_THREAD; i++) {
        // Initialize a new CRC indication here
        add_crc_indication(&crc_indication);
    }

    pthread_cond_signal(&crc_sem);

    // Wait for the threads to finish before exiting
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
