    long throughput_bytes; // Throughput in bytes per second for this interface
};

// Function to initialize and populate an array of NetworkInterfaceStats structures
void init_network_interface_stats(struct NetworkInterfaceStats *stats, int num_interfaces) {
    // Initialize the network interface statistics array
    for (int i = 0; i < num_interfaces; i++) {
        stats[i].interface_id = i;
        stats[i].packet_count = 0;
        stats[i].error_rate = 0.0f;
        stats[i].throughput_bytes = 0;
    }
}

// Function to update the network interface statistics array with new data
void update_network_interface_stats(struct NetworkInterfaceStats *stats, int num_interfaces, struct PacketData *packets, int num_packets) {
    // Loop through each packet and update the corresponding interface statistics
    for (int i = 0; i < num_packets; i++) {
        int interface_id = packets[i].interface_id;
        stats[interface_id].packet_count++;
        stats[interface_id].error_rate += packets[i].error_rate;
        stats[interface_id].throughput_bytes += packets[i].throughput_bytes;
    }
}

// Function to validate the incoming data from external sources
void validate_data(struct PacketData *packets, int num_packets) {
    // Loop through each packet and check if the values are within acceptable ranges
    for (int i = 0; i < num_packets; i++) {
        struct PacketData packet = packets[i];
        if (packet.interface_id < 0 || packet.interface_id >= num_interfaces) {
            // Invalid interface ID, ignore the packet
            continue;
        }
        if (packet.error_rate > 1.0f || packet.error_rate < 0.0f) {
            // Error rate is not within acceptable range, ignore the packet
            continue;
        }
        if (packet.throughput_bytes < 0) {
            // Negative throughput value, ignore the packet
            continue;
        }
    }
}

// Function to handle errors or incomplete data packets without affecting other parts of the system
void handle_errors(struct PacketData *packets, int num_packets) {
    // Loop through each packet and check for errors
    for (int i = 0; i < num_packets; i++) {
        struct PacketData packet = packets[i];
        if (packet.error_rate > 0.5f || packet.throughput_bytes <= 0) {
            // Error detected, ignore the packet and continue with the next one
            continue;
        }
    }
}

// Function to integrate new data with existing data in the system
void integrate_data(struct NetworkInterfaceStats *stats, int num_interfaces, struct PacketData *packets, int num_packets) {
    // Loop through each interface and update the statistics with the new data
    for (int i = 0; i < num_interfaces; i++) {
        stats[i].packet_count += packets[i].packet_count;
        stats[i].error_rate += packets[i].error_rate;
        stats[i].throughput_bytes += packets[i].throughput_bytes;
    }
}
