typedef struct {
  LTE_RRC_MessageType_T message;
  NR_UE_CTX_t ctx;
  RRC_ConnectionState_t state;
} Message;

struct MessageList {
  Message* messages;
  size_t count;
  pthread_mutex_t mutex;
};

void initializeMessageList(struct MessageList* list) {
  if (list == NULL) return;
  list->messages = calloc(10, sizeof(Message));
  list->count = 0;
  pthread_mutex_init(&list->mutex, NULL);
}

void addMessage(struct MessageList* list, LTE_RRC_MessageType_T message, NR_UE_CTX_t ctx, RRC_ConnectionState_t state) {
  if (list == NULL || message == NULL) return;
  pthread_mutex_lock(&list->mutex);
  size_t i = list->count++;
  list->messages[i].message = message;
  list->messages[i].ctx = ctx;
  list->messages[i].state = state;
  pthread_mutex_unlock(&list->mutex);
}

void deleteMessage(struct MessageList* list, size_t index) {
  if (list == NULL || index >= list->count) return;
  pthread_mutex_lock(&list->mutex);
  size_t i = index + 1;
  while (i < list->count - 1) {
    list->messages[i].message = list->messages[i + 1].message;
    list->messages[i].ctx = list->messages[i + 1].ctx;
    list->messages[i].state = list->messages[i + 1].state;
    i++;
  }
  list->count--;
  pthread_mutex_unlock(&list->mutex);
}

void updateMessage(struct MessageList* list, size_t index, LTE_RRC_MessageType_T message, NR_UE_CTX_t ctx, RRC_ConnectionState_t state) {
  if (list == NULL || index >= list->count) return;
  pthread_mutex_lock(&list->mutex);
  list->messages[index].message = message;
  list->messages[index].ctx = ctx;
  list->messages[index].state = state;
  pthread_mutex_unlock(&list->mutex);
}

void clearMessageList(struct MessageList* list) {
  if (list == NULL) return;
  pthread_mutex_lock(&list->mutex);
  list->count = 0;
  pthread_mutex_unlock(&list->mutex);
}
