    crc_indications[num_crc_indications].rnti = rnti;
    crc_indications[num_crc_indications].crc_indication_rel8_tag = crc_indication_rel8_tag;
    num_crc_indications++;

    // Release the lock
    pthread_mutex_unlock(&lock);
}

void rotate_log_file() {
    // Acquire the semaphore to manage log file rotation
    if (sem_wait(semaphore) == 0) {
        // Close the current log file
        fclose(current_log_file);

        // Create a new log file
        char *new_log_file = "log_file_" + to_string(num_rotations++);
        FILE *new_log_file = fopen(new_log_file, "w");

        // Write the current log entries and CRC indications to the new file
        for (int i = 0; i < num_entries; i++) {
            ModemLogEntry entry = log_entries[i];
            fprintf(new_log_file, "Timestamp: %ld RNTI: %d Log Level: %d\n",
                    entry.timestamp, entry.rnti, entry.log_level);
        }
        for (int i = 0; i < num_crc_indications; i++) {
            NFAPI_CRC_INDICATION_PDU_T crc_indication = crc_indications[i];
            fprintf(new_log_file, "RX UE Information Tag: %s RNTI: %d CRC Indication Rel8 Tag: %s\n",
                    crc_indication.rx_ue_information_tag, crc_indication.rnti, crc_indication.crc_indication_rel8_tag);
        }

        // Release the semaphore to manage log file rotation
        if (sem_post(semaphore) == 0) {
            // Update the current log file and entries count
            current_log_file = new_log_file;
            num_entries = 0;
            num_crc_indications = 0;
        }
    }
}

void set_logging_config(struct LoggingConfig config) {
    // Update the logging configuration
    this->config = config;
}

void log(int rnti, int log_level, const char *format, ...) {
    // Check if the log level is within the configured range
    if (log_level < config.log_levels[0] || log_level > config.log_levels[2]) {
        return;
    }

    // Acquire the lock for concurrent access
    pthread_mutex_lock(&lock);

    // Get the current timestamp
    long timestamp = get_timestamp();

    // Add the new log entry to the list
    add_modem_log_entry(timestamp, rnti, log_level);

    // Release the lock
    pthread_mutex_unlock(&lock);
}
