// Dynamic array of NFAPI CRC indication PDUs
struct nfapi_crc_indication_pdu_array {
  struct nfapi_crc_indication_pdu** data;
  size_t capacity;
  size_t size;
  pthread_mutex_t mutex;
};

// Initialize a dynamic array of NFAPI CRC indication PDUs
static void nfapi_crc_indication_pdu_array_init(struct nfapi_crc_indication_pdu_array* arr) {
  arr->data = NULL;
  arr->capacity = 0;
  arr->size = 0;
  pthread_mutex_init(&arr->mutex, NULL);
}

// Destroy a dynamic array of NFAPI CRC indication PDUs
static void nfapi_crc_indication_pdu_array_destroy(struct nfapi_crc_indication_pdu_array* arr) {
  for (size_t i = 0; i < arr->capacity; ++i) {
    free(arr->data[i]);
  }
  pthread_mutex_destroy(&arr->mutex);
}

// Insert a new NFAPI CRC indication PDU into the array
static void nfapi_crc_indication_pdu_array_insert(struct nfapi_crc_indication_pdu_array* arr, struct nfapi_crc_indication_pdu* pdu) {
  pthread_mutex_lock(&arr->mutex);
  if (arr->capacity == arr->size) {
    // Grow the array by 10%
    size_t new_cap = (arr->capacity * 11) / 10;
    arr->data = realloc(arr->data, sizeof(*arr->data) * new_cap);
    if (!arr->data) {
      pthread_mutex_unlock(&arr->mutex);
      // Handle memory allocation failure
      return;
    }
    arr->capacity = new_cap;
  }
  arr->data[arr->size++] = pdu;
  pthread_mutex_unlock(&arr->mutex);
}

// Delete an NFAPI CRC indication PDU from the array
static void nfapi_crc_indication_pdu_array_delete(struct nfapi_crc_indication_pdu_array* arr, size_t index) {
  pthread_mutex_lock(&arr->mutex);
  if (index < arr->size) {
    struct nfapi_crc_indication_pdu* deleted = arr->data[index];
    for (size_t i = index; i < arr->size - 1; ++i) {
      arr->data[i] = arr->data[i + 1];
    }
    --arr->size;
    free(deleted);
  }
  pthread_mutex_unlock(&arr->mutex);
}

// Serialize the array of NFAPI CRC indication PDUs to a binary format
static void nfapi_crc_indication_pdu_array_serialize(struct nfapi_crc_indication_pdu_array* arr, uint8_t* buffer, size_t buffer_size) {
  pthread_mutex_lock(&arr->mutex);
