    memcpy(buffer, &pdu->rnti, sizeof(uint16_t));
    buffer += sizeof(uint16_t);
    memcpy(buffer, &pdu->crc_indication_rel8_tag, sizeof(uint8_t));
    buffer += sizeof(uint8_t);
    memcpy(buffer, &pdu->crcflag, sizeof(bool));
    buffer += sizeof(bool);
  }
  pthread_mutex_unlock(&arr->mutex);
