// Deserialize the array of NFAPI CRC indication PDUs from a binary format
static void nfapi_crc_indication_pdu_array_deserialize(struct nfapi_crc_indication_pdu_array* arr, uint8_t* buffer, size_t buffer_size) {
  pthread_mutex_lock(&arr->mutex);
  // Ensure that the buffer is large enough to hold all PDUs
  if (buffer_size < sizeof(struct nfapi_crc_indication_pdu*) * arr->capacity) {
    pthread_mutex_unlock(&arr->mutex);
    return;
