    memcpy(&pdu->rnti, buffer, sizeof(uint16_t));
    buffer += sizeof(uint16_t);
    memcpy(&pdu->crc_indication_rel8_tag, buffer, sizeof(uint8_t));
    buffer += sizeof(uint8_t);
    memcpy(&pdu->crcflag, buffer, sizeof(bool));
    buffer += sizeof(bool);
    arr->data[i] = pdu;
  }
  pthread_mutex_unlock(&arr->mutex);
}
