#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_LIST {
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *entries[];
} NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T *nfapi_crc_indication_list_create(size_t capacity) {
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void nfapi_crc_indication_list_destroy(NFAPI_CRC_INDICATION_LIST_T *list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->entries[i]);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->mutex);
    if (list->size < list->capacity) {
        list->entries[list->size++] = entry;
    } else {
        // If the list is full, allocate a new buffer and copy the entries to it.
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * new_capacity);
        memcpy(new_entries, list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * list->size);
        free(list->entries);
        list->entries = new_entries;
        list->capacity = new_capacity;
        list->entries[list->size++] = entry;
    }
    pthread_mutex_unlock(&list->mutex);
}

void nfapi_crc_indication_list_clear(NFAPI_CRC_INDICATION_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        free(list->entries[i]);
    }
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
}
