// Define a structure to represent an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t valid; // Indicates whether the structure is valid or not
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint32_t crcflag; // Unique identifier for the CRCFLAG value
} nfapi_crc_indication_pdu_t;

// Define a list to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    size_t size; // Number of elements in the list
    size_t capacity; // Maximum number of elements the list can hold
    nfapi_crc_indication_pdu_t* pdu_list; // Array of NFAPI_CRC_INDICATION_PDU_T structures
} crc_indication_list_t;

// Function to dynamically manage the list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indications(crc_indication_list_t* list) {
    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        // Resize the list by a factor of 2
        size_t new_capacity = list->capacity * 2;
        nfapi_crc_indication_pdu_t* new_list = realloc(list->pdu_list, sizeof(nfapi_crc_indication_pdu_t) * new_capacity);
        assert(new_list != NULL); // Ensure the resize was successful
        list->capacity = new_capacity;
        list->pdu_list = new_list;
    }

    // Generate a new CRCFLAG value for the new structure
    uint32_t crcflag = rand();

    // Add the new structure to the list
    nfapi_crc_indication_pdu_t* new_pdu = &list->pdu_list[list->size++];
    new_pdu->valid = 1;
    new_pdu->rx_ue_information_tag = rand();
    new_pdu->rnti = rand();
    new_pdu->crc_indication_rel8_tag = rand();
    new_pdu->crcflag = crcflag;
}

// Function to check the integrity of the generated list
void verify_list(crc_indication_list_t* list) {
    // Iterate over each structure in the list
    for (size_t i = 0; i < list->size; i++) {
        nfapi_crc_indication_pdu_t* pdu = &list->pdu_list[i];

        // Check if the CRCFLAG value is unique
        for (size_t j = 0; j < list->size; j++) {
            nfapi_crc_indication_pdu_t* other_pdu = &list->pdu_list[j];
            if (i != j && pdu->crcflag == other_pdu->crcflag) {
                printf("Duplicate CRCFLAG value found in list\n");
            }
        }
    }
