    *list = malloc(sizeof(struct ListHead));
    if (!*list) {
        return -2;
    }
    (*list)->maxSize = maxSize;
    (*list)->size = 0;
    pthread_mutex_init(&(*list)->lock, NULL);
    semaphore_t mutex;
    struct ListNode *head = malloc(sizeof(struct ListNode));
