import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class Deserializer {
    private Map<String, Class<?>> registeredClasses = new HashMap<>();

    public void registerClass(String className, Class<?> clazz) {
        registeredClasses.put(className, clazz);
    }

    public Object deserialize(byte[] data, String className) throws IOException {
        try (ByteArrayInputStream inputStream = new ByteArrayInputStream(data)) {
            ObjectInputStream objectInputStream = new ObjectInputStream(inputStream);
            Class<?> clazz = registeredClasses.get(className);
            if (clazz == null) {
                throw new IllegalArgumentException("Class not found: " + className);
            }
            return objectInputStream.readObject();
        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Deserialization error: " + e.getMessage());
            return null;
        }
    }
}
