        PacketNode* new_node = malloc(sizeof(PacketNode));
        new_node->packet = packet;
        new_node->next = NULL;

        // Add the new node to the list
        if (*head == NULL) {
            *head = new_node;
        } else {
            PacketNode* current = *head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
