```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Define the packet structure
typedef struct {
    char* source_ip;
    char* destination_ip;
    int payload_size;
} Packet;

// Define the packet buffer data structure
typedef struct {
    int capacity; // maximum number of packets that can be stored in the buffer
    int count; // current number of packets in the buffer
    Packet* packets; // array of pointers to Packet structures
} PacketBuffer;

// Initialize a new packet buffer with a given capacity
PacketBuffer* init_packet_buffer(int capacity) {
    PacketBuffer* buf = malloc(sizeof(PacketBuffer));
    buf->capacity = capacity;
    buf->count = 0;
    buf->packets = calloc(capacity, sizeof(Packet));
    return buf;
}

// Add a new packet to the buffer
void add_packet(PacketBuffer* buf, const char* source_ip, const char* destination_ip, int payload_size) {
    // Check if the buffer is full
    if (buf->count == buf->capacity) {
        fprintf(stderr, "Error: Buffer is full\n");
        return;
    }

    // Allocate memory for the new packet
    Packet* packet = &buf->packets[buf->count];

    // Copy the source and destination IP addresses
    strcpy(packet->source_ip, source_ip);
    strcpy(packet->destination_ip, destination_ip);

    // Set the payload size
    packet->payload_size = payload_size;

    // Increment the count of packets in the buffer
    buf->count++;
}

// Remove a packet from the buffer
void remove_packet(PacketBuffer* buf, int index) {
    if (index < 0 || index >= buf->count) {
        fprintf(stderr, "Error: Invalid index\n");
        return;
    }

    // Shift all packets after the given index down by one
    for (int i = index + 1; i < buf->count; i++) {
        buf->packets[i - 1] = buf->packets[i];
    }

    // Decrement the count of packets in the buffer
    buf->count--;
}

// Look up a packet by its index
Packet* lookup_packet(PacketBuffer* buf, int index) {
    if (index < 0 || index >= buf->count) {
        fprintf(stderr, "Error: Invalid index\n");
        return NULL;
    }

    return &buf->packets[index];
}

// Iterate over all packets in the buffer
void iterate_packets(PacketBuffer* buf, void (*callback)(const Packet* packet)) {
    for (int i = 0; i < buf->count; i++) {
        callback(&buf->packets[i]);
    }
}
```
