public:
    // Constructor and destructor
    Logger(const std::string& name);
    virtual ~Logger();

    // Add log event to the collection
    void addEvent(const LogEvent& event);

    // Remove log event from the collection
    void removeEvent(const unsigned long long id);

    // Retrieve log event from the collection by its identifier
    const LogEvent* getEventById(const unsigned long long id) const;

    // Filter log events based on log level and timestamp ranges
    std::vector<LogEvent> filterEvents(const LogLevel& level, const std::pair<unsigned long long, unsigned long long>& timestampRange) const;

private:
    // Collection of all log events
    std::unordered_map<unsigned long long, LogEvent*> _events;
