```
// Logger.cpp
#include "Logger.h"

Logger::Logger(const std::string& name) {}

Logger::~Logger() {
    // Delete all log events in the collection
    for (auto event : _events) {
        delete event.second;
    }
}

void Logger::addEvent(const LogEvent& event) {
    _events[event.getId()] = new LogEvent(event);
}

void Logger::removeEvent(const unsigned long long id) {
    auto it = _events.find(id);
    if (it != _events.end()) {
        delete it->second;
        _events.erase(it);
    }
}

const LogEvent* Logger::getEventById(const unsigned long long id) const {
    auto it = _events.find(id);
    if (it != _events.end()) {
        return it->second;
    } else {
        return nullptr;
    }
}

std::vector<LogEvent> Logger::filterEvents(const LogLevel& level, const std::pair<unsigned long long, unsigned long long>& timestampRange) const {
    std::vector<LogEvent> filteredEvents;
    for (auto event : _events) {
        if (event.second->getLevel() >= level && event.second->getTimestamp() >= timestampRange.first && event.second->getTimestamp() <= timestampRange.second) {
            filteredEvents.push_back(*(event.second));
        }
    }
    return filteredEvents;
}
