// InMemoryLoggingBackend.cpp
#include "InMemoryLoggingBackend.h"

InMemoryLoggingBackend::InMemoryLoggingBackend(const std::string& name) : LoggingBackend(name) {}

InMemoryLoggingBackend::~InMemoryLoggingBackend() {
    // Delete all log events in the collection
    for (auto event : _events) {
        delete event.second;
    }
}

void InMemoryLoggingBackend::addEvent(const LogEvent& event) {
    _events[event.getId()] = new LogEvent(event);
}

void InMemoryLoggingBackend::removeEvent(const unsigned long long id) {
    auto it = _events.find(id);
    if (it != _events.end()) {
        delete it->second;
        _events.erase(it);
    }
}

const LogEvent* InMemoryLoggingBackend::getEventById(const unsigned long long id) {
    auto it = _events.find(id);
    if (it != _events.end()) {
        return it->second;
    } else {
        return nullptr;
    }
}
