} nfapi_crc_indication_list_t;

// Define a function to initialize and populate the doubly-linked list of NFAPI_CRC_INDICATION_PDU_T elements
int nfapi_crc_indication_list_init(nfapi_crc_indication_list_t *list, size_t initial_capacity) {
