    if (list == NULL || initial_capacity == 0) {
        return -1;
    }

    // Allocate memory for the list elements and initialize the mutex for synchronizing access from multiple threads
    list->elements = malloc(initial_capacity * sizeof(nfapi_crc_indication_pdu_t));
    if (list->elements == NULL) {
        return -1;
    }
    pthread_mutex_init(&list->lock, NULL);

    // Set the initial capacity and number of elements to zero
    list->num_elements = 0;
    list->initial_capacity = initial_capacity;

    return 0;
}

// Define a function to add an element to the doubly-linked list of NFAPI_CRC_INDICATION_PDU_T elements
int nfapi_crc_indication_list_add(nfapi_crc_indication_list_t *list, uint16_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag, bool crcflag) {
    // Check for invalid input parameters
    if (list == NULL || rx_ue_information_tag < 0 || rnti < 0 || crc_indication_rel8_tag < 0 || crcflag < 0) {
        return -1;
    }

    // Acquire the mutex for synchronizing access from multiple threads
    pthread_mutex_lock(&list->lock);

    // Check if the list needs to be resized
    if (list->num_elements == list->initial_capacity) {
        // Double the capacity of the list
        list->initial_capacity *= 2;
        nfapi_crc_indication_pdu_t *new_elements = realloc(list->elements, list->initial_capacity * sizeof(nfapi_crc_indication_pdu_t));
        if (new_elements == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->elements = new_elements;
    }

    // Add the element to the end of the list
    nfapi_crc_indication_pdu_t *element = &list->elements[list->num_elements];
    element->rx_ue_information_tag = rx_ue_information_tag;
    element->rnti = rnti;
    element->crc_indication_rel8_tag = crc_indication_rel8_tag;
    element->crcflag = crcflag;
    list->num_elements++;

    // Release the mutex for synchronizing access from multiple threads
    pthread_mutex_unlock(&list->lock);

