    // Initialize the hash table for unique RNTIs
    UniqueRNTIHashTable* hashTable = (UniqueRNTIHashTable*)malloc(sizeof(UniqueRNTIHashTable));
    hashTable->count = 0;
    hashTable->values = (uint16_t*)malloc(sizeof(uint16_t) * maxCount);

