#define MAX_ELEMENTS 1000 // maximum number of elements in the array
#define MAX_RX_UE_INFORMATION_TAG_LENGTH 64 // maximum length of RX_UE_INFORMATION_TAG
#define MAX_RNTI_LENGTH 8 // maximum length of RNTI
#define MIN_CRCFLAG_VALUE 0 // minimum value for CRCFLAG
#define MAX_CRCFLAG_VALUE 1023 // maximum value for CRCFLAG

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[MAX_RX_UE_INFORMATION_TAG_LENGTH]; // RX_UE_INFORMATION_TAG of the element
    unsigned int RNTI; // RNTI of the element
    unsigned int CRCFLAG; // CRCFLAG of the element
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    pthread_mutex_t mutex; // mutex for synchronization
    NFAPI_CRC_INDICATION_PDU_T *elements; // array of elements
    unsigned int capacity; // current capacity of the array
    unsigned int size; // number of elements in the array
} DynamicArray;

void initDynamicArray(DynamicArray *arr) {
    arr->mutex = PTHREAD_MUTEX_INITIALIZER;
    arr->elements = calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->capacity = MAX_ELEMENTS;
    arr->size = 0;
}

void destroyDynamicArray(DynamicArray *arr) {
    pthread_mutex_destroy(&arr->mutex);
    free(arr->elements);
}

bool addElementToDynamicArray(DynamicArray *arr, const char *RX_UE_INFORMATION_TAG, unsigned int RNTI, unsigned int CRCFLAG) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        // resize the array if it is full
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(arr->elements, 2 * arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_elements == NULL) {
            // out of memory
            pthread_mutex_unlock(&arr->mutex);
            return false;
        } else {
            arr->capacity *= 2;
            arr->elements = new_elements;
        }
    }
    strcpy(arr->elements[arr->size].RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG);
    arr->elements[arr->size].RNTI = RNTI;
    arr->elements[arr->size].CRCFLAG = CRCFLAG;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
    return true;
}

bool removeElementFromDynamicArray(DynamicArray *arr, unsigned int index) {
    pthread_mutex_lock(&arr->mutex);
    if (index >= arr->size) {
        // invalid index
        pthread_mutex_unlock(&arr->mutex);
        return false;
    }
    memmove(arr->elements + index, arr->elements + index + 1, (arr->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->size--;
    pthread_mutex_unlock(&arr->mutex);
    return true;
}

void iterateOverDynamicArray(DynamicArray *arr, void (*callback)(const char *RX_UE_INFORMATION_TAG, unsigned int RNTI, unsigned int CRCFLAG)) {
    pthread_mutex_lock(&arr->mutex);
    for (int i = 0; i < arr->size; i++) {
        callback(arr->elements[i].RX_UE_INFORMATION_TAG, arr->elements[i].RNTI, arr->elements[i].CRCFLAG);
    }
    pthread_mutex_unlock(&arr->mutex);
}

bool validateElementIntegrity(const NFAPI_CRC_INDICATION_PDU_T *element) {
    return element->RX_UE_INFORMATION_TAG[0] != '\0' && element->RNTI != 0 && (element->CRCFLAG >= MIN_CRCFLAG_VALUE && element->CRCFLAG <= MAX_CRCFLAG_VALUE);
}

void validateDynamicArrayIntegrity(DynamicArray *arr) {
    pthread_mutex_lock(&arr->mutex);
    for (int i = 0; i < arr->size; i++) {
        if (!validateElementIntegrity(&arr->elements[i])) {
            printf("Invalid element at index %d in dynamic array\n", i);
            pthread_mutex_unlock(&arr->mutex);
