// Custom data structure for user session logs
struct SessionLog {
    time_t timestamp;
    int session_id;
    char* ip_address;
    char protocol[8];
    int status;
};

// Memory pool for custom data structures
static struct MemoryPool *pool;

// Initialize memory pool with a fixed size of 50,000 elements
int initMemoryPool(size_t size) {
    // Allocate memory for the pool and set its capacity to the specified size
    pool = malloc(sizeof(struct MemoryPool) + sizeof(struct SessionLog) * size);
    if (!pool) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return -1;
    }

    // Initialize the pool's capacity and current size to 0
    pool->capacity = size;
    pool->current_size = 0;

    // Create a mutex for synchronizing access to the pool
    if (pthread_mutex_init(&pool->lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Add a new session log to the memory pool
int addSessionLog(struct SessionLog *log) {
    // Acquire the lock on the pool
    if (pthread_mutex_lock(&pool->lock) != 0) {
        fprintf(stderr, "Failed to acquire mutex: %s\n", strerror(errno));
        return -1;
    }

    // Check if the pool is full
    if (pool->current_size == pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        fprintf(stderr, "Memory pool is full\n");
        return -1;
    }

    // Add the log to the pool
    struct SessionLog *new_log = &pool->logs[pool->current_size++];
    memcpy(new_log, log, sizeof(struct SessionLog));

    // Release the lock on the pool
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

// Get a session log from the memory pool
struct SessionLog *getSessionLog(int index) {
    // Acquire the lock on the pool
    if (pthread_mutex_lock(&pool->lock) != 0) {
        fprintf(stderr, "Failed to acquire mutex: %s\n", strerror(errno));
        return NULL;
    }

    // Check if the index is valid
    if (index < 0 || index >= pool->current_size) {
        pthread_mutex_unlock(&pool->lock);
        fprintf(stderr, "Invalid log index\n");
        return NULL;
    }

    // Return the log at the specified index
    struct SessionLog *log = &pool->logs[index];

    // Release the lock on the pool
    pthread_mutex_unlock(&pool->lock);

    return log;
}

// Free memory allocated by the memory pool
void freeMemoryPool() {
    // Acquire the lock on the pool
    if (pthread_mutex_lock(&pool->lock) != 0) {
        fprintf(stderr, "Failed to acquire mutex: %s\n", strerror(errno));
        return;
    }

    // Free the memory allocated for the pool
    free(pool);

    // Release the lock on the pool
    pthread_mutex_unlock(&pool->lock);
}

// Function to manage memory efficiently for an array of custom data structures representing user session logs
int manageMemoryEfficiently() {
    // Initialize the memory pool with a fixed size of 50,000 elements
    if (initMemoryPool(50000) != 0) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return -1;
    }

    // Add session logs to the pool until it is full
