}

// Add a new NFAPI_CRC_INDICATION_PDU_T structure to the array, growing the capacity if necessary
void nfapi_crc_indication_pdu_array_add(nfapi_crc_indication_pdu_array_t *array, uint16_t rx_ue_information_tag, uint32_t rnti, uint8_t crc_indication_rel8_tag, bool crcflag) {
    if (array->count == array->capacity) {
        // Grow the capacity by a factor of 2 when the array is full
        size_t new_capacity = array->capacity * 2;
        nfapi_crc_indication_pdu_t *new_data = (nfapi_crc_indication_pdu_t *)realloc(array->data, new_capacity * sizeof(nfapi_crc_indication_pdu_t));
        if (new_data == NULL) {
            // Reallocation failed; free the old data and return
            free(array->data);
            array->count = 0;
            array->capacity = 0;
            return;
        } else {
            // Reallocation succeeded; update the capacity and data pointers
            array->capacity = new_capacity;
            array->data = new_data;
        }
    }
    array->data[array->count].rx_ue_information_tag = rx_ue_information_tag;
    array->data[array->count].rnti = rnti;
    array->data[array->count].crc_indication_rel8_tag = crc_indication_rel8_tag;
    array->data[array->count++].crcflag = crcflag;
}

// Update an existing NFAPI_CRC_INDICATION_PDU_T structure in the array, using the RNTI as a lookup key
void nfapi_crc_indication_pdu_array_update(nfapi_crc_indication_pdu_array_t *array, uint32_t rnti, uint16_t rx_ue_information_tag, uint8_t crc_indication_rel8_tag, bool crcflag) {
    for (size_t i = 0; i < array->count; i++) {
        if (array->data[i].rnti == rnti) {
            // Update the structure in place
            array->data[i].rx_ue_information_tag = rx_ue_information_tag;
            array->data[i].crc_indication_rel8_tag = crc_indication_rel8_tag;
            array->data[i].crcflag = crcflag;
