// Video Stream Manager Structure
typedef struct video_stream_manager {
    video_stream_frame **frames; // Array of video stream frames
    int frame_count; // Number of frames in the array
    int allocated_size; // Size of the memory allocation for the frames
    int next_frame_id; // Next unique identifier to use for a new frame
} video_stream_manager;

// Function Prototypes
video_stream_manager *init_video_stream_manager();
void add_video_stream_frame(video_stream_manager *manager, int stream_instance_id, pixel_buffer *pixel_data);
void remove_video_stream_frame(video_stream_manager *manager, int frame_id);
video_stream_frame *get_video_stream_frame(video_stream_manager *manager, int frame_id);
int get_next_video_stream_frame_id(video_stream_manager *manager);
void destroy_video_stream_manager(video_stream_manager *manager);

// Implementation

/**
 * Initialize a new video stream manager.
 */
video_stream_manager *init_video_stream_manager() {
    video_stream_manager *manager = (video_stream_manager *) malloc(sizeof(video_stream_manager));
    if (manager == NULL) {
        return NULL;
    }

    manager->frames = (video_stream_frame **) malloc(sizeof(video_stream_frame *) * INITIAL_FRAMES_ALLOCATION_SIZE);
    if (manager->frames == NULL) {
        free(manager);
        return NULL;
    }

    manager->allocated_size = INITIAL_FRAMES_ALLOCATION_SIZE;
    manager->frame_count = 0;
    manager->next_frame_id = 0;

    return manager;
}

/**
 * Add a new video stream frame to the manager.
 */
void add_video_stream_frame(video_stream_manager *manager, int stream_instance_id, pixel_buffer *pixel_data) {
    if (manager->frame_count == manager->allocated_size) {
        // Reallocate memory for the frames array
        manager->allocated_size += ALLOCATION_INCREMENT;
        manager->frames = realloc(manager->frames, sizeof(video_stream_frame *) * manager->allocated_size);
    }

    video_stream_frame *new_frame = (video_stream_frame *) malloc(sizeof(video_stream_frame));
    if (new_frame == NULL) {
        return;
    }

    new_frame->frame_id = manager->next_frame_id++;
    new_frame->stream_instance_id = stream_instance_id;
    new_frame->pixel_data = pixel_data;

    manager->frames[manager->frame_count++] = new_frame;
}

/**
 * Remove a video stream frame from the manager.
 */
void remove_video_stream_frame(video_stream_manager *manager, int frame_id) {
    for (int i = 0; i < manager->frame_count; ++i) {
        if (manager->frames[i]->frame_id == frame_id) {
            free(manager->frames[i]);
            manager->frames[i] = NULL;
            break;
        }
    }
}

/**
 * Get a video stream frame from the manager.
 */
video_stream_frame *get_video_stream_frame(video_stream_manager *manager, int frame_id) {
    for (int i = 0; i < manager->frame_count; ++i) {
        if (manager->frames[i]->frame_id == frame_id) {
            return manager->frames[i];
        }
    }
    return NULL;
}

/**
 * Get the next unique identifier for a new video stream frame.
 */
int get_next_video_stream_frame_id(video_stream_manager *manager) {
    return manager->next_frame_id++;
}

/**
 * Destroy a video stream manager and free its resources.
 */
void destroy_video_stream_manager(video_stream_manager *manager) {
    for (int i = 0; i < manager->frame_count; ++i) {
        if (manager->frames[i] != NULL) {
            free(manager->frames[i]);
        }
    }
    free(manager->frames);
    free(manager);
}

// Testing

