// Macro to define the maximum number of entries in the CRC indication list
#define MAX_ENTRIES 2048

// Structure to hold the information of a single CRC indication PDU
struct NFAPI_CRC_INDICATION_PDU {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint16_t crc_indication_rel8_tag;
};

// Structure to hold the information of a single CRC indication list entry
struct NFAPI_CRC_INDICATION_LIST {
    struct NFAPI_CRC_INDICATION_PDU *pdu;
    uint64_t timestamp;
    uint32_t unique_id;
};

// Array to store the CRC indication list entries
struct NFAPI_CRC_INDICATION_LIST *crc_indication_list[MAX_ENTRIES];

// Function to dynamically manage the CRC indication list
void crc_indication_list_add(uint16_t rx_ue_information_tag, uint32_t rnti, uint16_t crc_indication_rel8_tag) {
    // Create a new CRC indication PDU structure
    struct NFAPI_CRC_INDICATION_PDU *pdu = (struct NFAPI_CRC_INDICATION_PDU *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU));
    if (!pdu) {
        // Handle memory allocation failure gracefully
        return;
    }

    // Initialize the CRC indication PDU structure
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;

    // Create a new CRC indication list entry structure
    struct NFAPI_CRC_INDICATION_LIST *entry = (struct NFAPI_CRC_INDICATION_LIST *)malloc(sizeof(struct NFAPI_CRC_INDICATION_LIST));
    if (!entry) {
        // Handle memory allocation failure gracefully
        free(pdu);
        return;
    }

    // Initialize the CRC indication list entry structure
    entry->pdu = pdu;
    entry->timestamp = timestamp();
    entry->unique_id = generate_unique_id();

    // Add the new entry to the CRC indication list
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (!crc_indication_list[i]) {
            crc_indication_list[i] = entry;
            break;
        }
    }
}

// Function to compute the CRCFLAG using a rolling checksum algorithm
uint16_t crcflag(int index) {
    // Compute the rolling checksum using the previous 500 PDUs
    uint32_t checksum = 0;
    for (int i = index - 1; i >= index - 500; i--) {
        if (!crc_indication_list[i]) {
            continue;
        }
        struct NFAPI_CRC_INDICATION_PDU *pdu = crc_indication_list[i]->pdu;
        checksum += pdu->rx_ue_information_tag + pdu->rnti + pdu->crc_indication_rel8_tag;
    }
    return (uint16_t)((checksum >> 16) ^ (checksum & 0xFFFF));
}

// Function to integrate with an existing logging framework
void log(struct NFAPI_CRC_INDICATION_PDU *pdu, uint64_t timestamp, uint32_t unique_id) {
    // Log the CRC indication PDU information
    printf("[%llu] CRC Indication: RX Ue Information Tag = %hu, RNTI = %u, CRC Indication Rel8 Tag = %hu\n", timestamp, pdu->rx_ue_information_tag, pdu->rnti, pdu->crc_indication_rel8_tag);
}
