static void populate_crc_indication_list(crc_indication_list_t *list, size_t num_pdus) {
  assert(num_pdus > 0);

  // Ensure the list has enough capacity for the new PDUs.
  if (list->capacity < num_pdus) {
    list->pdu_list = realloc(list->pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);
    if (!list->pdu_list) {
      fprintf(stderr, "Memory allocation failed.\n");
      return;
