    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->pdu_list[i];
    pdu->rx_ue_information_tag = 1;
    pdu->rnti = rand(); // Generate a random RNTI.
    pdu->crc_indication_rel8_tag = 2;
  }

