  for (size_t i = 0; i < num_pdus; i++) {
    list->rolling_checksums[i] = 0;
  }
  for (size_t i = 0; i < num_pdus - 1; i++) {
    list->rolling_checksums[i] =
        (list->rolling_checksums[i + 1] + list->pdu_list[i].crc_indication_rel8_tag) % 0xFFFFFFFF;
  }
}

void create_and_populate_crc_indication_list(size_t num_pdus) {
