void sessionManager(struct Session **sessions, size_t *sessionCount) {
    // Iterate over all active sessions and validate their authentication tokens
    for (size_t i = 0; i < *sessionCount; ++i) {
        struct Session *session = sessions[i];
        char *token = session->token;
        if (!validateToken(token)) {
            // If token is invalid, remove the session from the list and decrement the count
            free(session);
            --(*sessionCount);
            continue;
        }

        // Iterate over all active endpoints in the session and verify their format and uniqueness
        for (size_t j = 0; j < session->endpointCount; ++j) {
            struct Endpoint *endpoint = session->endpoints[j];
            if (!verifyEndpoint(endpoint)) {
                // If endpoint is invalid, remove it from the list and decrement the count
                free(endpoint);
                --session->endpointCount;
                continue;
            }
        }
    }

    // Expire inactive sessions gracefully
    for (size_t i = 0; i < *sessionCount; ++i) {
        struct Session *session = sessions[i];
        if (session->isActive) {
            continue;
        }
        free(session);
        --(*sessionCount);
