        LOG_ERROR("Failed to allocate memory for %d structures", num_structures);
        return NULL;
    }

    // Initialize the structure members and set the CRCFLAG randomly
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)memory;
    for (int i = 0; i < num_structures; i++) {
        structures[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_RANDOM;
        structures[i].rnti = rand() % 65536; // Randomly set the RNTI
        structures[i].crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG_RANDOM;
    }

    return memory;
}

// Function to deallocate an array of NFAPI_CRC_INDICATION_PDU_T structures
