// Function to check the external configuration file for maximum allowable memory usage and number of structures to allocate
void check_external_configuration(MEMORY_TRACKING_T* tracking, uint32_t* max_memory_usage, uint32_t* num_structures) {
    // Check if the external configuration file is present and valid
    if (!is_file_present("external_configuration.conf")) {
        LOG_WARNING("External configuration file not found");
        *max_memory_usage = MAX_MEMORY_USAGE;
        *num_structures = ALLOCATE_STRUCTURES;
    } else if (!is_file_valid("external_configuration.conf")) {
        LOG_WARNING("External configuration file is invalid");
        *max_memory_usage = MAX_MEMORY_USAGE;
        *num_structures = ALLOCATE_STRUCTURES;
    } else {
        // Load the external configuration file and get the maximum allowable memory usage and number of structures to allocate
        FILE* config_file = fopen("external_configuration.conf", "r");
        if (config_file == NULL) {
            LOG_ERROR("Failed to open external configuration file");
            *max_memory_usage = MAX_MEMORY_USAGE;
            *num_structures = ALLOCATE_STRUCTURES;
        } else {
            // Parse the configuration file and get the maximum allowable memory usage and number of structures to allocate
            char line[256];
            while (fgets(line, sizeof(line), config_file)) {
                if (strncmp(line, "max_memory_usage=", 17) == 0) {
                    *max_memory_usage = atoi(line + 17);
                } else if (strncmp(line, "num_structures=", 14) == 0) {
                    *num_structures = atoi(line + 14);
                }
            }
            fclose(config_file);
        }
    }
}

