// Function to allocate an array of NFA states and initialize them with the given input alphabet
NFAState** allocate_nfa_states(uint32_t num_states, uint32_t input_alphabet_size) {
    // Allocate memory for the array of NFA states
    NFAState** nfa_states = malloc(num_states * sizeof(NFAState*));
    if (nfa_states == NULL) {
        LOG_ERROR("Failed to allocate memory for the array of NFA states");
        return NULL;
    }

    // Initialize each state with the input alphabet size and an empty set of transitions
    for (uint32_t i = 0; i < num_states; i++) {
        nfa_states[i] = malloc(sizeof(NFAState));
        if (nfa_states[i] == NULL) {
            LOG_ERROR("Failed to allocate memory for NFA state %d", i);
            return NULL;
        }
        nfa_states[i]->input_alphabet_size = input_alphabet_size;
        nfa_states[i]->transitions = malloc(sizeof(Transition*) * (input_alphabet_size + 1));
        if (nfa_states[i]->transitions == NULL) {
            LOG_ERROR("Failed to allocate memory for the transitions of NFA state %d", i);
            return NULL;
        }
        memset(nfa_states[i]->transitions, 0, sizeof(Transition*) * (input_alphabet_size + 1));
    }

    return nfa_states;
}

// Function to deallocate an array of NFA states
void deallocate_nfa_states(NFAState** nfa_states, uint32_t num_states) {
    // Deallocate the transitions and then the NFA state objects
    for (uint32_t i = 0; i < num_states; i++) {
        free(nfa_states[i]->transitions);
        free(nfa_states[i]);
    }

    // Deallocate the array of NFA states
    free(nfa_states);
}

// Function to print a set of states
void print_set_of_states(StateSet* set) {
    for (uint32_t i = 0; i < set->num_states; i++) {
        printf("%d ", set->states[i]);
    }
}

// Function to print a transition
void print_transition(Transition* t) {
    printf("Input: %c, Output: %s", t->input, t->output);
}

// Function to print an NFA state
void print_nfa_state(NFAState* state) {
    printf("State %d: ", state->id);
    for (uint32_t i = 0; i < state->input_alphabet_size + 1; i++) {
        if (state->transitions[i] == NULL) {
            continue;
        }
        print_transition(state->transitions[i]);
    }
}

// Function to print an NFA
void print_nfa(NFA* nfa) {
    printf("Initial state: %d\n", nfa->initial_state);
    printf("Final states: ");
    for (uint32_t i = 0; i < nfa->num_final_states; i++) {
        printf("%d ", nfa->final_states[i]);
    }
    printf("\n");
    for (uint32_t i = 0; i < nfa->num_states; i++) {
        print_nfa_state(nfa->states[i]);
        printf("\n");
    }
}

// Function to read a set of states from a file
StateSet* read_set_of_states_from_file(FILE* fp) {
    uint32_t num_states;
    if (fscanf(fp, "%d", &num_states) != 1) {
        LOG_ERROR("Failed to read the number of states from the file");
        return NULL;
    }
    StateSet* set = malloc(sizeof(StateSet));
    if (set == NULL) {
        LOG_ERROR("Failed to allocate memory for the state set");
        return NULL;
    }
    set->num_states = num_states;
    set->states = malloc(num_states * sizeof(uint32_t));
    if (set->states == NULL) {
        LOG_ERROR("Failed to allocate memory for the states of the state set");
        return NULL;
    }
    for (uint32_t i = 0; i < num_states; i++) {
        uint32_t state;
        if (fscanf(fp, "%d", &state) != 1) {
            LOG_ERROR("Failed to read the %dth state from the file", i);
            return NULL;
        }
        set->states[i] = state;
    }
    return set;
}

// Function to read a transition from a file
Transition* read_transition_from_file(FILE* fp) {
    uint8_t input;
    char output[10];
    if (fscanf(fp, "%c %s", &input, output) != 2) {
        LOG_ERROR("Failed to read the transition from the file");
        return NULL;
    }
    Transition* t = malloc(sizeof(Transition));
    if (t == NULL) {
        LOG_ERROR("Failed to allocate memory for the transition");
        return NULL;
    }
    t->input = input;
    strcpy(t->output, output);
    return t;
}

// Function to read an NFA state from a file
NFAState* read_nfa_state_from_file(FILE* fp) {
    uint32_t id;
    if (fscanf(fp, "%d", &id) != 1) {
        LOG_ERROR("Failed to read the ID of the NFA state from the file");
        return NULL;
    }
    StateSet* set = read_set_of_states_from_file(fp);
    if (set == NULL) {
        LOG_ERROR("Failed to read the set of states of the NFA state from the file");
        return NULL;
    }
    uint32_t num_transitions;
    if (fscanf(fp, "%d", &num_transitions) != 1) {
        LOG_ERROR("Failed to read the number of transitions of the NFA state from the file");
        return NULL;
    }
    Transition** transitions = malloc(sizeof(Transition*) * (num_transitions + 1));
    if (transitions == NULL) {
        LOG_ERROR("Failed to allocate memory for the transitions of the NFA state");
        return NULL;
    }
    for (uint32_t i = 0; i < num_transitions; i++) {
        Transition* t = read_transition_from_file(fp);
        if (t == NULL) {
            LOG_ERROR("Failed to read the %dth transition of the NFA state from the file", i);
            return NULL;
        }
        transitions[i] = t;
    }
    NFAState* state = malloc(sizeof(NFAState));
    if (state == NULL) {
        LOG_ERROR("Failed to allocate memory for the NFA state");
        return NULL;
    }
    state->id = id;
    state->set = set;
    state->num_transitions = num_transitions;
    state->transitions = transitions;
    return state;
}

// Function to read an NFA from a file
NFA* read_nfa_from_file(const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        LOG_ERROR("Failed to open the NFA file for reading");
        return NULL;
    }
    uint32_t num_states;
    if (fscanf(fp, "%d", &num_states) != 1) {
        LOG_ERROR("Failed to read the number of states from the file");
        fclose(fp);
        return NULL;
    }
    NFA* nfa = malloc(sizeof(NFA));
    if (nfa == NULL) {
        LOG_ERROR("Failed to allocate memory for the NFA");
        fclose(fp);
        return NULL;
    }
    nfa->num_states = num_states;
    nfa->states = malloc(num_states * sizeof(NFAState*));
    if (nfa->states == NULL) {
        LOG_ERROR("Failed to allocate memory for the states of the NFA");
        fclose(fp);
        return NULL;
    }
    for (uint32_t i = 0; i < num_states; i++) {
        NFAState* state = read_nfa_state_from_file(fp);
        if (state == NULL) {
            LOG_ERROR("Failed to read the %dth state of the NFA from the file", i);
            fclose(fp);
            return NULL;
        }
        nfa->states[i] = state;
    }
    uint32_t num_final_states;
    if (fscanf(fp, "%d", &num_final_states) != 1) {
        LOG_ERROR("Failed to read the number of final states from the file");
        fclose(fp);
        return NULL;
    }
    nfa->num_final_states = num_final_states;
    if (nfa->num_final_states > 0) {
        nfa->final_states = malloc(num_final_states * sizeof(uint32_t));
        if (nfa->final_states == NULL) {
            LOG_ERROR("Failed to allocate memory for the final states of the NFA");
            fclose(fp);
            return NULL;
        }
    }
    for (uint32_t i = 0; i < num_final_states; i++) {
        uint32_t state;
        if (fscanf(fp, "%d", &state) != 1) {
            LOG_ERROR("Failed to read the %dth final state of the NFA from the file", i);
            fclose(fp);
            return NULL;
        }
        nfa->final_states[i] = state;
    }
    fclose(fp);
    return nfa;
