// Function to serialize a dynamic array of LTE_RRC_Messages to a file in JSON format
int serialize_lte_rrc_messages(struct LTE_RRC_Message* messages, int num_messages, char* output_file) {
    // Check if input is valid
    if (num_messages <= 0 || messages == NULL || output_file == NULL) {
        return -1;
    }

    // Open the output file in write mode
    FILE* fp = fopen(output_file, "w");
    if (fp == NULL) {
        return -2;
    }

    // Serialize the dynamic array of LTE_RRC_Messages to JSON format
    for (int i = 0; i < num_messages; i++) {
        struct NAS_Message* nas_message = &messages[i].nas_message;

        // Write the NAS_Message ID, MME Identity, and PDN Connection Request to the file in JSON format
        fprintf(fp, "{\"NAS_Message_ID\": %d, \"MME_Identity\": \"%s\", \"PDN_Connection_Request\": \"%s\"}\n",
            nas_message->nas_message_id, nas_message->mme_identity, nas_message->pdn_connection_request);
    }

    // Close the output file
    fclose(fp);

    return 0;
}

int main() {
    // Declare a dynamic array of LTE_RRC_Messages
    struct LTE_RRC_Message* messages = NULL;

    // Initialize and populate the dynamic array of LTE_RRC_Messages
    int result = initialize_lte_rrc_messages(&messages, 10000);
    if (result < 0) {
        printf("Error initializing LTE_RRC_Messages: %d\n", result);
        return -1;
