// C library header file: mac_transmission_buffer.h
#ifndef MAC_TRANSMISSION_BUFFER_H
#define MAC_TRANSMISSION_BUFFER_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <pthread.h>

// Structures for holding transmission buffer entries
struct MAC_Header {
    uint8_t dest_addr[6];
    uint16_t dest_port;
    uint8_t src_addr[6];
    uint16_t src_port;
    uint32_t seq_num;
};

struct MAC_Payload {
    uint8_t* data;
    size_t length;
};

struct TransmissionTimingInfo {
    struct timespec transmission_time;
    bool is_acked;
};

struct MAC_TransmissionBufferEntry {
    struct MAC_Header header;
    struct MAC_Payload payload;
    struct TransmissionTimingInfo timing_info;
};

// API for adding entries to the buffer
bool mac_transmission_buffer_add(struct MAC_TransmissionBufferEntry* entry);

// API for retrieving entries from the buffer
struct MAC_TransmissionBufferEntry* mac_transmission_buffer_get(uint8_t dest_addr[6], uint16_t dest_port, uint8_t src_addr[6], uint16_t src_port);

// API for removing entries from the buffer
bool mac_transmission_buffer_remove(struct MAC_TransmissionBufferEntry* entry);

#endif /* MAC_TRANSMISSION_BUFFER_H */

// C library source file: mac_transmission_buffer.c
#include "mac_transmission_buffer.h"

#define BUFFER_SIZE 1024

static struct MAC_TransmissionBufferEntry buffer[BUFFER_SIZE];
static size_t buffer_index = 0;

// Mutex for synchronizing access to the buffer
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Thread for periodically cleaning up unused entries in the buffer
void* buffer_cleanup_thread(void* args) {
    while (1) {
        // Sleep for a random amount of time between 0 and 3 seconds to prevent the cleanup thread from overwhelming the buffer with requests
        int rand_sleep = (int)(rand() % 3);
        sleep(rand_sleep);

        // Lock the mutex to ensure that only one thread can access the buffer at a time
        pthread_mutex_lock(&buffer_mutex);

        // Iterate over the buffer and remove any unused entries
        for (size_t i = 0; i < BUFFER_SIZE; i++) {
            if (!buffer[i].header.dest_addr[0]) {
                continue;
            }

            if (buffer[i].timing_info.is_acked) {
                // Entry has been acknowledged, so it can be removed from the buffer
                memset(&buffer[i], 0, sizeof(struct MAC_TransmissionBufferEntry));
            }
        }

        pthread_mutex_unlock(&buffer_mutex);
    }
}

bool mac_transmission_buffer_add(struct MAC_TransmissionBufferEntry* entry) {
    // Lock the mutex to ensure that only one thread can access the buffer at a time
    pthread_mutex_lock(&buffer_mutex);

    if (buffer_index >= BUFFER_SIZE) {
        // Buffer is full, so drop the entry and return false
        pthread_mutex_unlock(&buffer_mutex);
        return false;
    }

    buffer[buffer_index++] = *entry;

    pthread_mutex_unlock(&buffer_mutex);
    return true;
}

struct MAC_TransmissionBufferEntry* mac_transmission_buffer_get(uint8_t dest_addr[6], uint16_t dest_port, uint8_t src_addr[6], uint16_t src_port) {
    // Lock the mutex to ensure that only one thread can access the buffer at a time
    pthread_mutex_lock(&buffer_mutex);

    for (size_t i = 0; i < BUFFER_SIZE; i++) {
        if (!buffer[i].header.dest_addr[0]) {
            continue;
        }

        if (memcmp(dest_addr, buffer[i].header.dest_addr, 6) == 0 && dest_port == buffer[i].header.dest_port && memcmp(src_addr, buffer[i].header.src_addr, 6) == 0 && src_port == buffer[i].header.src_port) {
            struct MAC_TransmissionBufferEntry* entry = &buffer[i];
            pthread_mutex_unlock(&buffer_mutex);
            return entry;
        }
    }

    // If no matching entry is found, return NULL
    pthread_mutex_unlock(&buffer_mutex);
    return NULL;
}

bool mac_transmission_buffer_remove(struct MAC_TransmissionBufferEntry* entry) {
    // Lock the mutex to ensure that only one thread can access the buffer at a time
    pthread_mutex_lock(&buffer_mutex);

    for (size_t i = 0; i < BUFFER_SIZE; i++) {
        if (!buffer[i].header.dest_addr[0]) {
            continue;
        }

        if (memcmp(entry->header.dest_addr, buffer[i].header.dest_addr, 6) == 0 && entry->header.dest_port == buffer[i].header.dest_port && memcmp(entry->header.src_addr, buffer[i].header.src_addr, 6) == 0 && entry->header.src_port == buffer[i].header.src_port) {
            // Entry found, so remove it from the buffer
            memset(&buffer[i], 0, sizeof(struct MAC_TransmissionBufferEntry));
            pthread_mutex_unlock(&buffer_mutex);
            return true;
        }
    }

    // If no matching entry is found, return false
    pthread_mutex_unlock(&buffer_mutex);
    return false;
}

// Initialize the buffer and create a background thread for cleaning up unused entries
void mac_transmission_buffer_init() {
    // Lock the mutex to ensure that only one thread can access the buffer at a time
    pthread_mutex_lock(&buffer_mutex);

    memset(buffer, 0, sizeof(struct MAC_TransmissionBufferEntry) * BUFFER_SIZE);

    pthread_t cleanup_thread;
    int result = pthread_create(&cleanup_thread, NULL, buffer_cleanup_thread, NULL);

