#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <json-c/json.h>

#define MAX_USERS 100
#define MAX_NAME_LEN 256
#define MAX_EMAIL_LEN 256
#define MAX_PASSWORD_LEN 256

struct user {
    int id;
    char name[MAX_NAME_LEN];
    char email[MAX_EMAIL_LEN];
    char password[MAX_PASSWORD_LEN];
    enum sub_action sub_action;
};

enum sub_action {
    SUB_ACTION_CREATE,
    SUB_ACTION_UPDATE,
    SUB_ACTION_DELETE
};

struct user_cache {
    int id;
    char name[MAX_NAME_LEN];
    char email[MAX_EMAIL_LEN];
    char password[MAX_PASSWORD_LEN];
    enum sub_action sub_action;
    struct user_cache *next;
};

struct user_cache *user_cache = NULL;

void add_to_cache(struct user *user) {
    if (user_cache == NULL) {
        user_cache = malloc(sizeof(struct user_cache));
        assert(user_cache != NULL);
        memcpy(&user_cache->id, &user->id, sizeof(int));
        strncpy(user_cache->name, user->name, MAX_NAME_LEN);
        strncpy(user_cache->email, user->email, MAX_EMAIL_LEN);
        strncpy(user_cache->password, user->password, MAX_PASSWORD_LEN);
        user_cache->sub_action = user->sub_action;
        user_cache->next = NULL;
    } else {
        struct user_cache *current = user_cache;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(struct user_cache));
        assert(current->next != NULL);
        memcpy(&current->next->id, &user->id, sizeof(int));
        strncpy(current->next->name, user->name, MAX_NAME_LEN);
        strncpy(current->next->email, user->email, MAX_EMAIL_LEN);
        strncpy(current->next->password, user->password, MAX_PASSWORD_LEN);
        current->next->sub_action = user->sub_action;
        current->next->next = NULL;
    }
}

void remove_from_cache(int id) {
    struct user_cache *current = user_cache;
    if (current != NULL && current->id == id) {
        user_cache = current->next;
    } else if (current != NULL && current->next != NULL) {
        while (current->next->id != id && current->next->next != NULL) {
            current = current->next;
        }
        if (current->next->id == id) {
            current->next = current->next->next;
        }
    }
}

struct user *get_user(int id, enum sub_action action) {
    struct user_cache *current = user_cache;
    while (current != NULL && current->id != id) {
        current = current->next;
    }
    if (current == NULL) {
        return NULL;
    } else if (current->sub_action == action || action == SUB_ACTION_CREATE) {
        struct user *user = malloc(sizeof(struct user));
        assert(user != NULL);
        memcpy(&user->id, &current->id, sizeof(int));
        strncpy(user->name, current->name, MAX_NAME_LEN);
        strncpy(user->email, current->email, MAX_EMAIL_LEN);
        strncpy(user->password, current->password, MAX_PASSWORD_LEN);
        user->sub_action = action;
        return user;
    } else {
        return NULL;
    }
}

void handle_user_operation(struct json *json) {
    struct user *user = get_user(json->id, json->sub_action);
    if (user != NULL) {
        switch (user->sub_action) {
            case SUB_ACTION_CREATE:
                add_to_cache(user);
                break;
            case SUB_ACTION_UPDATE:
                remove_from_cache(json->id);
                add_to_cache(user);
                break;
            case SUB_ACTION_DELETE:
                remove_from_cache(json->id);
                break;
        }
    } else {
        printf("Invalid user operation\n");
    }
}

int main() {
    struct json json;
    json.id = 12345;
    json.sub_action = SUB_ACTION_CREATE;
    handle_user_operation(&json);
    return 0;
}
