#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>

struct Session {
    int id;
    char *imsi;
    int session_id;
    NAS_MESSAGE_T nas_message;
    int status;
};

struct SessionList {
    struct Session **sessions;
    int size;
};

void createSession(struct SessionList *session_list, struct Session *new_session) {
    // add new session to the list
    struct Session *tmp = realloc(session_list->sessions, (session_list->size + 1) * sizeof(struct Session *));
    if (!tmp) {
        printf("Error: Out of memory\n");
        return;
    }
    session_list->sessions = tmp;
    session_list->sessions[session_list->size] = new_session;
    session_list->size++;
}

void updateSession(struct SessionList *session_list, struct Session *updated_session) {
    // find the existing session and update its values
    for (int i = 0; i < session_list->size; i++) {
        if (session_list->sessions[i]->id == updated_session->id) {
            session_list->sessions[i] = updated_session;
            break;
        }
    }
}

void deleteSession(struct SessionList *session_list, int id) {
    // find the existing session and remove it from the list
    for (int i = 0; i < session_list->size; i++) {
        if (session_list->sessions[i]->id == id) {
            struct Session *tmp = realloc(session_list->sessions, (session_list->size - 1) * sizeof(struct Session *));
            if (!tmp) {
                printf("Error: Out of memory\n");
                return;
            }
            session_list->sessions = tmp;
            memmove(&session_list->sessions[i], &session_list->sessions[i + 1], (session_list->size - i - 1) * sizeof(struct Session *));
            session_list->size--;
            break;
        }
    }
}

int main() {
    struct SessionList *session_list = malloc(sizeof(struct SessionList));
    session_list->sessions = NULL;
    session_list->size = 0;

    // create a new session
    struct Session *new_session = malloc(sizeof(struct Session));
    new_session->id = 1234;
    new_session->imsi = "123456789";
    new_session->session_id = 0;
    new_session->nas_message = NAS_MESSAGE_T_EAP;
    new_session->status = SESSION_STATUS_ESTABLISHED;
    createSession(session_list, new_session);

    // update the existing session
    struct Session *updated_session = malloc(sizeof(struct Session));
    updated_session->id = 1234;
    updated_session->imsi = "123456789";
    updated_session->session_id = 0;
    updated_session->nas_message = NAS_MESSAGE_T_PPP;
    updated_session->status = SESSION_STATUS_TERMINATED;
    updateSession(session_list, updated_session);

    // delete the existing session
    deleteSession(session_list, 1234);

    free(new_session);
    free(updated_session);
    return 0;
}
