static NFAPI_CRC_INDICATION_PDU_LIST_T* pduList = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage the list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_crc_indication_pdu_list_manage(NFAPI_CRC_INDICATION_PDU_LIST_T* pduList, uint32_t rnti, uint16_t tag) {
    // Check if the RNTI and TAG are valid
    if (!nfapi_crc_indication_pdu_valid(pduList, rnti, tag)) {
        return;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Search for the specified RNTI and TAG in the list
    NFAPI_CRC_INDICATION_PDU_LIST_T* current = pduList;
    while (current != NULL) {
        if (current->rnti == rnti && current->crcFlag == tag) {
            break;
        }
        current = current->next;
    }

    // If the entry is found, remove it from the list
    if (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_LIST_T* previous = current->previous;
        if (previous == NULL) {
            pduList = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }

    // Allocate memory for the new entry
    NFAPI_CRC_INDICATION_PDU_LIST_T* newEntry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST_T));
    if (newEntry == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize the new entry
    newEntry->pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newEntry->pdu == NULL) {
        free(newEntry);
        pthread_mutex_unlock(&mutex);
        return;
    }
    newEntry->crcFlag = tag;
    newEntry->rnti = rnti;
    newEntry->next = current;
    newEntry->previous = previous;

    // Add the new entry to the list
    if (pduList == NULL) {
        pduList = newEntry;
    } else {
        current->previous = newEntry;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to validate a NFAPI_CRC_INDICATION_PDU_T structure
bool nfapi_crc_indication_pdu_valid(NFAPI_CRC_INDICATION_PDU_LIST_T* pduList, uint32_t rnti, uint16_t tag) {
    // Check if the RNTI and TAG are valid
    if (rnti == 0 || tag == 0) {
        return false;
    }

    // Search for the specified RNTI and TAG in the list
    NFAPI_CRC_INDICATION_PDU_LIST_T* current = pduList;
    while (current != NULL) {
        if (current->rnti == rnti && current->crcFlag == tag) {
            return true;
        }
        current = current->next;
    }

    // If the entry is not found, return false
    return false;
}

// Function to serialize the list of NFAPI_CRC_INDICATION_PDU_T structures into a binary format
void nfapi_crc_indication_pdu_list_serialize(NFAPI_CRC_INDICATION_PDU_LIST_T* pduList, uint8_t* buffer) {
    // Initialize the buffer with a header indicating the number of entries in the list
    uint32_t numEntries = 0;
    while (pduList != NULL) {
        numEntries++;
        pduList = pduList->next;
    }
    buffer[0] = numEntries & 0xFF;
    buffer[1] = (numEntries >> 8) & 0xFF;
    buffer[2] = (numEntries >> 16) & 0xFF;
    buffer[3] = (numEntries >> 24) & 0xFF;

    // Serialize each entry in the list and write it to the buffer
    pduList = pduList->next;
    for (uint32_t i = 0; i < numEntries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = pduList->pdu;
        buffer[4 + i * sizeof(NFAPI_CRC_INDICATION_PDU_T)] = pdu->rx_ue_information.rnti & 0xFF;
        buffer[5 + i * sizeof(NFAPI_CRC_INDICATION_PDU_T)] = (pdu->rx_ue_information.rnti >> 8) & 0xFF;
        buffer[6 + i * sizeof(NFAPI_CRC_INDICATION_PDU_T)] = (pdu->rx_ue_information.rnti >> 16) & 0xFF;
        buffer[7 + i * sizeof(NFAPI_CRC_INDICATION_PDU_T)] = (pdu->rx_ue_information.rnti >> 24) & 0xFF;
        buffer[8 + i * sizeof(NFAPI_CRC_INDICATION_PDU_T)] = pdu->crc_indication_rel8.crflag & 0xFF;
