void nfapi_crc_indication_pdu_list_deserialize(NFAPI_CRC_INDICATION_PDU_LIST_T* pduList, uint8_t* buffer) {
    // Get the number of entries in the list from the header
    uint32_t numEntries = buffer[0] | (buffer[1] << 8) | (buffer[2] << 16) | (buffer[3] << 24);

    // Deserialize each entry in the list and write it to the structure
    for (uint32_t i = 0; i < numEntries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
