        reports[i]->UEIdentifier = malloc(sizeof(char) * 16);
        sprintf(reports[i]->UEIdentifier, "UE%d", i + 1);
        reports[i]->numMeasurementResults = 0;
        reports[i]->measurementResults = NULL;
        reports[i]->timestamp = time(NULL);
    }

    // Populate the array of UEStatusReport structures with random signal strength and quality metrics
    for (int i = 0; i < numReports; i++) {
        int numMeasurementResults = rand() % 10 + 1;
        reports[i]->numMeasurementResults = numMeasurementResults;
        reports[i]->measurementResults = malloc(sizeof(MeasurementResult) * numMeasurementResults);
        for (int j = 0; j < numMeasurementResults; j++) {
            reports[i]->measurementResults[j].signalStrength = rand() % 100 + 1;
            reports[i]->measurementResults[j].signalQuality = rand() % 5 + 1;
        }
    }

    // Query the NetworkPerformanceMonitor module periodically to update the signal strength metrics
    while (true) {
        for (int i = 0; i < numReports; i++) {
            int newSignalStrength = rand() % 100 + 1;
            reports[i]->measurementResults[reports[i]->numMeasurementResults - 1].signalStrength = newSignalStrength;
            if (newSignalStrength > thresholdForLogging) {
                printf("UE%d: New signal strength of %d\n", i + 1, newSignalStrength);
            }
        }
        sleep(intervalForQueryingNetworkPerformanceMonitor);
    }
}

// Define the function to free memory allocated for an array of UEStatusReport structures
void freeUEStatusReports(UEStatusReport** reports, int numReports) {
    for (int i = 0; i < numReports; i++) {
        if (reports[i] != NULL) {
            free(reports[i]->UEIdentifier);
            free(reports[i]->measurementResults);
            free(reports[i]);
        }
    }
}
