// Custom data structure for representing a packet
struct Packet {
    struct PacketHeader header;
    size_t numPayloads;
    Payload** payloads;
};

// Custom data structure for representing a payload segment
struct Payload {
    uint16_t checksum;
    uint32_t timestamp;
    uint16_t sequenceNumber;
};

// Function to initialize a doubly linked list of packets
void initPacketList(struct Packet** head) {
    *head = NULL;
}

// Function to add a packet to the end of the doubly linked list
void addPacketToEnd(struct Packet** head, struct Packet* newPacket) {
    if (*head == NULL) {
        *head = newPacket;
        return;
    }

    struct Packet* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }

    current->next = newPacket;
    newPacket->prev = current;
}

// Function to remove a packet from the doubly linked list
void removePacket(struct Packet** head, struct Packet* packet) {
    if (*head == NULL || packet == NULL) return;

    struct Packet* current = *head;
    while (current != NULL && current->next != packet) {
        current = current->next;
    }

    if (current == NULL) return;

    if (packet == *head) {
        *head = (*head)->next;
    }

    struct Packet* nextPacket = packet->next;
    if (nextPacket != NULL) {
        nextPacket->prev = packet->prev;
    }

    struct Packet* prevPacket = packet->prev;
    if (prevPacket != NULL) {
        prevPacket->next = nextPacket;
    }
}

// Function to populate a packet with payload segments
void populatePacket(struct Packet* packet, size_t numPayloads) {
    // Allocate memory for the payload segments
    struct Payload** payloads = malloc(numPayloads * sizeof(struct Payload));
    if (payloads == NULL) return;

    // Initialize each payload segment
    for (size_t i = 0; i < numPayloads; i++) {
        payloads[i] = malloc(sizeof(struct Payload));
        if (payloads[i] == NULL) break;
        payloads[i]->checksum = generateChecksum();
        payloads[i]->timestamp = generateTimestamp();
        payloads[i]->sequenceNumber = i + 1;
    }

    // If any payload segment allocation failed, free the memory and return
    if (i < numPayloads) {
        for (size_t j = 0; j < i; j++) {
            free(payloads[j]);
        }
        free(payloads);
        return;
    }

    // Set the packet's payload segments and number of payloads
    packet->numPayloads = numPayloads;
    packet->payloads = payloads;
}

// Function to generate a random checksum
uint16_t generateChecksum() {
    return (rand() % 0xFFFF) + 1;
}

// Function to generate a timestamp
uint32_t generateTimestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
}

// Function to handle packet loss and retransmission requests
void handlePacketRequests(struct Packet** head, int numRetries) {
    // Check if there are any lost packets
    struct Packet* current = *head;
    while (current != NULL && current->next != NULL) {
        struct Packet* next = current->next;
        uint16_t checksum = calculateChecksum(current);
        if (checksum == 0) {
            // Remove the lost packet from the list
            removePacket(head, current);
            printf("[%lu] Lost packet with sequence number %u\n", current->header.sequenceNumber, next->header.sequenceNumber);
        } else if (checksum != current->header.checksum) {
            // Update the lost packet's checksum and retransmit it
            current->header.checksum = checksum;
            printf("[%lu] Re-transmitting packet with sequence number %u\n", current->header.sequenceNumber, next->header.sequenceNumber);
        } else {
            current = next;
        }
    }

    // Check if there are any retransmission requests
    for (int i = 0; i < numRetries; i++) {
        struct Packet* current = *head;
        while (current != NULL && current->next != NULL) {
            struct Packet* next = current->next;
            uint16_t checksum = calculateChecksum(current);
            if (checksum == 0) {
                // Remove the lost packet from the list
                removePacket(head, current);
                printf("[%lu] Lost packet with sequence number %u\n", current->header.sequenceNumber, next->header.sequenceNumber);
            } else if (checksum != current->header.checksum) {
                // Update the lost packet's checksum and retransmit it
                current->header.checksum = checksum;
                printf("[%lu] Re-transmitting packet with sequence number %u\n", current->header.sequenceNumber, next->header.sequenceNumber);
            } else {
                current = next;
            }
        }
    }
}

// Function to calculate a checksum for a packet
uint16_t calculateChecksum(struct Packet* packet) {
    uint16_t sum = 0;
    for (size_t i = 0; i < packet->numPayloads; i++) {
        sum += packet->payloads[i]->checksum;
    }
    return sum % 0xFFFF;
}

// Function to free the memory allocated for a packet and its payload segments
void freePacket(struct Packet* packet) {
    if (packet == NULL) return;

    struct Payload** payloads = packet->payloads;
    for (size_t i = 0; i < packet->numPayloads; i++) {
        free(payloads[i]);
    }
    free(payloads);
    free(packet);
}

int main() {
    srand((unsigned int) time(NULL));
    struct Packet* head = NULL;
    size_t numPackets = 10;
    for (size_t i = 0; i < numPackets; i++) {
        struct Packet* packet = (struct Packet*) malloc(sizeof(struct Packet));
        packet->header.sequenceNumber = i + 1;
        populatePacketHeader(&packet->header);
        populatePacketPayloads(packet);
        addPacketToQueue(&head, packet);
    }

    int numRetries = 3;
    handlePacketRequests(&head, numRetries);

    struct Packet* current = head;
    while (current != NULL) {
        printf("[%lu] %u\n", current->header.sequenceNumber, calculateChecksum(current));
        current = current->next;
    }

    freePacketList(&head);
    return 0;
}']

