// Structure to store network events
typedef struct {
    time_t timestamp;
    int event_type;
    size_t payload_size;
} NetworkEvent;

// Dynamic array of NetworkEvents
typedef struct {
    // Array of pointers to NetworkEvents
    NetworkEvent** events;
    // Number of elements in the array
    size_t num_events;
    // Capacity of the array (number of slots)
    size_t capacity;
    // Mutex for thread-safe access
    pthread_mutex_t mutex;
} EventArray;

// Initialize an empty event array with a given capacity
EventArray* event_array_init(size_t capacity) {
    EventArray* array = malloc(sizeof(EventArray));
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for event array\n");
        return NULL;
    }
    array->events = calloc(capacity, sizeof(NetworkEvent*));
    if (!array->events) {
        free(array);
        fprintf(stderr, "Failed to allocate memory for event array slots\n");
        return NULL;
    }
    array->num_events = 0;
    array->capacity = capacity;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Add a new event to the array
int event_array_add(EventArray* array, NetworkEvent* event) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&array->mutex);

    // Check if the array is full and needs to be resized
    if (array->num_events == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NetworkEvent** new_events = realloc(array->events, sizeof(NetworkEvent*) * new_capacity);
        if (!new_events) {
            fprintf(stderr, "Failed to resize event array\n");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->events = new_events;
        array->capacity = new_capacity;
    }

    // Add the event to the end of the array
    array->events[array->num_events++] = event;

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Update an existing event in the array
int event_array_update(EventArray* array, size_t index, NetworkEvent* new_event) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&array->mutex);

    // Check if the index is valid
    if (index >= array->num_events) {
        fprintf(stderr, "Invalid index for event update\n");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    // Update the event in the array
    NetworkEvent* old_event = array->events[index];
    *old_event = *new_event;

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Retrieve an event from the array by index
NetworkEvent* event_array_get(EventArray* array, size_t index) {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&array->mutex);

    // Check if the index is valid
    if (index >= array->num_events) {
        fprintf(stderr, "Invalid index for event retrieval\n");
        pthread_mutex_unlock(&array->mutex);
        return NULL;
    }

    // Retrieve the event from the array
    NetworkEvent* event = array->events[index];

    // Unlock the mutex after accessing the array
    pthread_mutex_unlock(&array->mutex);
    return event;
}

// Free the memory allocated for the event array
void event_array_free(EventArray* array) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&array->mutex);

    // Release the memory allocated for the array
    free(array->events);
    free(array);

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(&array->mutex);
}
