    size_t numElements;
    size_t maxSize;
} CRC_INDICATION_LIST_T;

// Function for initializing the CRC indication list
void initCrcIndicationList(CRC_INDICATION_LIST_T *list) {
    list->pduList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10);
    if (!list->pduList) {
        perror("Failed to allocate memory for CRC indication list");
        exit(EXIT_FAILURE);
    }
    list->numElements = 0;
    list->maxSize = 10;
}

// Function for adding a new CRC indication to the list
bool addCrcIndication(CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG *rxUETag, RNTI rnti, CRC_INDICATION_REL8_TAG crcTag) {
    // Check if the list is full
    if (list->numElements == list->maxSize) {
        NFAPI_CRC_INDICATION_PDU_T *tempList = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pduList, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->maxSize * 2);
        if (!tempList) {
            perror("Failed to reallocate memory for CRC indication list");
            exit(EXIT_FAILURE);
        }
        list->pduList = tempList;
        list->maxSize *= 2;
    }

    // Add the new CRC indication to the list
    list->pduList[list->numElements].rxUETag = rxUETag;
    list->pduList[list->numElements].rnti = rnti;
    list->pduList[list->numElements].crcTag = crcTag;
    list->numElements++;

    return true;
}

// Function for querying the list for CRC indications with specific RNTI values
void queryCrcIndicationByRnti(CRC_INDICATION_LIST_T *list, RNTI rnti) {
    // Iterate over the list and filter based on the specified RNTI value
    for (size_t i = 0; i < list->numElements; i++) {
        if (list->pduList[i].rnti == rnti) {
            // Print the matching CRC indication record
            printf("CRC indication record found: RX UETag %p, RNTI %d, CRCFLAG %d\n", list->pduList[i].rxUETag, list->pduList[i].rnti, list->pduList[i].crcTag.crcfFlag);
        }
    }
}

// Function for dynamically resizing the list to accommodate additional structures
void resizeCrcIndicationList(CRC_INDICATION_LIST_T *list) {
    // Reallocate memory for the list with a larger size
    NFAPI_CRC_INDICATION_PDU_T *tempList = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pduList, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->maxSize * 2);
    if (!tempList) {
        perror("Failed to reallocate memory for CRC indication list");
        exit(EXIT_FAILURE);
    }
    list->pduList = tempList;
    list->maxSize *= 2;
}

// Function for archiving old CRC indication records
void archiveCrcIndications(CRC_INDICATION_LIST_T *list) {
    // Iterate over the list and archive any elements that are older than a certain retention period
    time_t currentTime = time(NULL);
    for (size_t i = 0; i < list->numElements; i++) {
        if (difftime(currentTime, list->pduList[i].rxUETag->timestamp) > RETENTION_PERIOD) {
            // Remove the archived element from the list
            memmove(&list->pduList[i], &list->pduList[i + 1], (list->numElements - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->numElements--;
        }
    }
}

// Main function for handling CRC indications and managing the list
int main() {
    // Initialize the list of CRC indications
    CRC_INDICATION_LIST_T list;
    initCrcIndicationList(&list);

    // Handle CRC indications and manage the list as necessary
    while (true) {
        // Get a new CRC indication from the RRU
        RX_UE_TAG *rxUETag = getRxUeTag();
        RNTI rnti = getRnti(rxUETag);
        CRCFLAG crcfFlag = getCrcfFlag(rxUETag);

        // Add the new CRC indication to the list
