// Function to initialize and populate the tree with device session information
void initTree(char **deviceIDs, int numDevices) {
    // Lock the tree for exclusive access
    sem_wait(&treeLock);

    // Create a new root node if it doesn't exist
    if (!root) {
        root = malloc(sizeof(TreeNode));
        root->key = NULL;
        root->value = NULL;
        root->left = NULL;
        root->right = NULL;
    }

    // Populate the tree with device session information
