        sessionInfo->deviceID = strdup(deviceID);
        sessionInfo->log = NULL;
        sessionInfo->activeConnections = 0;

        // Add the device ID to the tree
        TreeNode *node = root;
        while (node) {
            int cmp = strcmp(sessionInfo->deviceID, node->key);
            if (cmp < 0) {
                // Device ID is less than the current key, insert to the left subtree
                if (!node->left) {
                    node->left = malloc(sizeof(TreeNode));
                    node->left->key = strdup(sessionInfo->deviceID);
                    node->left->value = sessionInfo;
                    node->left->left = NULL;
