        logEntry->timestamp = time(NULL);
        logEntry->throughput = 0.0f;
        sessionInfo->log = logEntry;
    }

    // Unlock the tree for other threads to access
    sem_post(&treeLock);
}

// Function to update the network activity log of a device session
void updateNetworkActivityLog(char *deviceID, float throughput) {
    // Lock the tree for exclusive access
    sem_wait(&treeLock);

    // Find the device session information in the tree
    TreeNode *node = root;
    while (node) {
        int cmp = strcmp(deviceID, node->key);
        if (cmp < 0) {
            node = node->left;
        } else if (cmp > 0) {
            node = node->right;
        } else {
            // Device ID is found in the tree, update the network activity log
            DeviceSessionInfo *sessionInfo = node->value;
            sessionInfo->log->throughput += throughput;

            // Unlock the tree for other threads to access
            sem_post(&treeLock);
            return;
        }
    }

    // Device ID is not in the tree, add a new record
