                node->left = malloc(sizeof(TreeNode));
                node->left->key = strdup(sessionInfo->deviceID);
                node->left->value = sessionInfo;
                node->left->left = NULL;
                node->left->right = NULL;
            }
            node = node->left;
        } else if (cmp > 0) {
            // Device ID is greater than the current key, insert to the right subtree
