                node->right = malloc(sizeof(TreeNode));
                node->right->key = strdup(sessionInfo->deviceID);
                node->right->value = sessionInfo;
                node->right->left = NULL;
                node->right->right = NULL;
            }
            node = node->right;
        } else {
            // Device ID is already in the tree, update the existing record
            node->value = sessionInfo;
            break;
        }
    }

    // Add a new network activity log entry to the device session information
    NetworkActivityLog *logEntry = malloc(sizeof(NetworkActivityLog));
    logEntry->timestamp = time(NULL);
    logEntry->throughput = throughput;
    sessionInfo->log = logEntry;

    // Unlock the tree for other threads to access
    sem_post(&treeLock);
}

// Function to remove a device session from the tree
void removeDeviceSession(char *deviceID) {
    // Lock the tree for exclusive access
    sem_wait(&treeLock);

    // Find the device session information in the tree
    TreeNode *node = root;
    while (node) {
        int cmp = strcmp(deviceID, node->key);
        if (cmp < 0) {
            node = node->left;
        } else if (cmp > 0) {
            node = node->right;
        } else {
            // Device ID is found in the tree, remove it from the tree
            if (!node->left && !node->right) {
                free(node);
                root = NULL;
            } else if (node->left && node->right) {
                TreeNode *successor = node->right;
                while (successor->left) {
                    successor = successor->left;
                }
                node->key = strdup(successor->key);
                node->value = successor->value;
                free(successor);
            } else {
                TreeNode *child = node->left ? node->left : node->right;
                free(node);
                root = child;
            }

            // Unlock the tree for other threads to access
            sem_post(&treeLock);
            return;
        }
    }

    // Device ID is not in the tree, do nothing

    // Unlock the tree for other threads to access
    sem_post(&treeLock);
}
