} NFAPI_CRC_INDICATION_PDU_T;

// Memory limit for the function (in MB)
#define MEMORY_LIMIT 100

// Function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_list(int num_entries, uint32_t rnti_min, uint32_t rnti_max) {
    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indication_list == NULL) {
        // Memory allocation failed, log error and return NULL
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize memory usage tracker
    uint32_t total_memory = 0;

    // Loop through each entry in the list of structures
    for (int i = 0; i < num_entries; i++) {
        // Generate a random RNTI value within the specified range
        uint32_t rnti = rand() % (rnti_max - rnti_min + 1) + rnti_min;

        // Set CRCFLAG to a random value
        uint8_t crcflag = rand() % 256;

        // Initialize the structure with the generated RNTI and CRCFLAG values
        crc_indication_list[i].RX_UE_INFORMATION_TAG = i + 1;
        crc_indication_list[i].RNTI = rnti;
        crc_indication_list[i].CRCFLAG = crcflag;
        crc_indication_list[i].CRC_INDICATION_REL8_TAG = 0;

        // Update memory usage tracker
        total_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        // Check if the current memory usage exceeds the specified limit
        if (total_memory > MEMORY_LIMIT * 1024 * 1024) {
            printf("Memory usage exceeded, terminating function\n");
            break;
        }
    }

    // Log successful and failed entries
    int num_successful = i;
    int num_failed = num_entries - i;
    if (num_failed > 0) {
        printf("Failed to generate %d out of %d CRC indication PDUs\n", num_failed, num_entries);
    } else {
        printf("Successfully generated %d CRC indication PDUs\n", num_successful);
    }

    // Return the list of structures
    return crc_indication_list;
}
