// Function to initialize and populate an array of LTE_NAS_Message_T structures with EMM messages
void init_emm_messages(int num_messages, NAS_MESSAGE_TYPE message_type) {
    // Lock the mutex to prevent race conditions in multi-threaded environments
    pthread_mutex_lock(&emm_messages_mutex);

    // Check if the number of messages is valid and within the bounds of the array
    if (num_messages < 0 || num_messages > MAX_EMM_MESSAGES) {
        syslog(LOG_ERR, "Invalid number of EMM messages: %d", num_messages);
        pthread_mutex_unlock(&emm_messages_mutex);
        return;
