    size_t capacity;
    size_t front, rear;
    void **data;
};

// Define the structure to represent the session metrics
struct SessionMetrics {
    uint64_t num_packets;
    uint64_t packet_size;
    uint64_t total_bytes;
    uint64_t latency;
};

// Function to create a new network session state structure
static struct NetworkSessionState *new_session_state(int fd) {
    struct NetworkSessionState *session = malloc(sizeof(*session));
    if (!session) {
        perror("malloc");
        return NULL;
    }

    session->conn_meta = malloc(sizeof(*session->conn_meta));
    if (!session->conn_meta) {
        perror("malloc");
        free(session);
        return NULL;
    }

    session->queue = malloc(sizeof(*session->queue));
    if (!session->queue) {
        perror("malloc");
        free(session->conn_meta);
        free(session);
        return NULL;
    }

    session->metrics.num_packets = 0;
    session->metrics.packet_size = 0;
    session->metrics.total_bytes = 0;
    session->metrics.latency = 0;

    return session;
}

// Function to free a network session state structure
static void free_session_state(struct NetworkSessionState *session) {
    if (session->conn_meta) {
        free(session->conn_meta);
    }
    if (session->queue) {
        free(session->queue->data);
        free(session->queue);
    }
    free(session);
}

// Function to create a new packet queue
static struct PacketQueue *new_packet_queue(size_t capacity) {
    struct PacketQueue *queue = malloc(sizeof(*queue));
    if (!queue) {
        perror("malloc");
        return NULL;
    }

    queue->capacity = capacity;
    queue->front = 0;
    queue->rear = 0;
    queue->data = malloc(sizeof(void *) * queue->capacity);
    if (!queue->data) {
        perror("malloc");
        free(queue);
        return NULL;
    }

    return queue;
}

// Function to free a packet queue
static void free_packet_queue(struct PacketQueue *queue) {
    if (queue->data) {
        free(queue->data);
    }
    free(queue);
}

// Function to enqueue a packet in the packet queue
static bool enqueue_packet(struct NetworkSessionState *session, void *packet) {
    struct PacketQueue *queue = session->queue;
    if (queue->front == 0 && queue->rear == queue->capacity - 1) {
        return false;
    } else if (queue->front == queue->rear + 1) {
        return false;
    }

    queue->data[queue->rear++] = packet;
    return true;
}

// Function to dequeue a packet from the packet queue
static void *dequeue_packet(struct NetworkSessionState *session) {
    struct PacketQueue *queue = session->queue;
    if (queue->front == queue->rear) {
        return NULL;
    }

    void *packet = queue->data[queue->front++];
    return packet;
}

