    if (!session) {
        perror("new_session_state");
        return;
    }

    session->conn_meta->fd = fd;
    memcpy(&session->conn_meta->remote_addr, remote_addr, sizeof(*remote_addr));
    session->conn_meta->is_active = true;

    struct PacketQueue *queue = new_packet_queue(1024);
    if (!queue) {
        perror("new_packet_queue");
        free_session_state(session);
        return;
    }

    session->queue = queue;

    printf("New connection from %s\n", inet_ntop(AF_INET, &remote_addr->sin_addr, buf, sizeof(buf)));
