// Function to initialize the frame list
void init_frame_list(FRAMES_LIST *list) {
    // Initialize the capacity of the list
    list->capacity = 1024;
    list->count = 0;
    list->frames = (NFAPI_RX_FRAME_T *)malloc(sizeof(NFAPI_RX_FRAME_T) * list->capacity);
}

// Function to add a new frame to the list
void add_frame(FRAMES_LIST *list, uint16_t ue_index, NFAPI_RRC_STATE rrc_state, RF_CHAINS *rf_chains) {
    // Check if the list is full and needs to be resized
    if (list->count >= list->capacity) {
        // Increase the capacity of the list by 1024 elements
        size_t new_capacity = list->capacity + 1024;
        NFAPI_RX_FRAME_T *new_frames = (NFAPI_RX_FRAME_T *)realloc(list->frames, sizeof(NFAPI_RX_FRAME_T) * new_capacity);
        if (new_frames == NULL) {
            // Allocation failed, handle error gracefully
            printf("Failed to allocate memory for frame list\n");
            return;
        }
        list->frames = new_frames;
        list->capacity = new_capacity;
    }

    // Add the new frame to the list
    NFAPI_RX_FRAME_T *frame = &list->frames[list->count];
    frame->ue_index = ue_index;
    frame->rrc_state = rrc_state;
    frame->rf_chains = rf_chains;
    list->count++;
}

// Function to update an existing frame in the list based on UE index
void update_frame(FRAMES_LIST *list, uint16_t ue_index, NFAPI_RRC_STATE rrc_state, RF_CHAINS *rf_chains) {
    // Find the frame in the list based on UE index
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->frames[i].ue_index == ue_index) {
            break;
        }
    }
    if (i >= list->count) {
        // Frame not found, handle error gracefully
        printf("Frame with UE index %d not found\n", ue_index);
        return;
    }

    // Update the frame in the list
    NFAPI_RX_FRAME_T *frame = &list->frames[i];
    frame->rrc_state = rrc_state;
    frame->rf_chains = rf_chains;
}

// Function to retrieve a frame from the list based on RRC state
NFAPI_RX_FRAME_T *get_frame(FRAMES_LIST *list, NFAPI_RRC_STATE rrc_state) {
    // Find the first frame in the list with the specified RRC state
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->frames[i].rrc_state == rrc_state) {
            break;
        }
    }
    if (i >= list->count) {
        // Frame not found, handle error gracefully
        printf("Frame with RRC state %d not found\n", rrc_state);
        return NULL;
    }

    // Return the frame from the list
    return &list->frames[i];
}

// Function to serialize the list to a file for later restoration
void serialize_frame_list(FRAMES_LIST *list, FILE *file) {
    // Write the number of frames in the list to the file
    fwrite(&list->count, sizeof(size_t), 1, file);

    // Write each frame in the list to the file
    size_t i;
    for (i = 0; i < list->count; i++) {
        NFAPI_RX_FRAME_T *frame = &list->frames[i];
        fwrite(&frame->ue_index, sizeof(uint16_t), 1, file);
        fwrite(&frame->rrc_state, sizeof(NFAPI_RRC_STATE), 1, file);
        fwrite(&frame->rf_chains, sizeof(RF_CHAINS), 1, file);
    }
}

// Function to deserialize the list from a file
void deserialize_frame_list(FRAMES_LIST *list, FILE *file) {
    // Read the number of frames in the list from the file
    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    // Resize the list to fit the deserialized data
    init_frame_list(list);
    while (list->count < count) {
        add_frame(list, 0, NFAPI_RRC_STATE_INACTIVE, NULL);
    }

    // Read each frame in the list from the file
    size_t i;
    for (i = 0; i < count; i++) {
        uint16_t ue_index;
        fread(&ue_index, sizeof(uint16_t), 1, file);
        NFAPI_RRC_STATE rrc_state;
        fread(&rrc_state, sizeof(NFAPI_RRC_STATE), 1, file);
        RF_CHAINS *rf_chains;
        fread(&rf_chains, sizeof(RF_CHAINS), 1, file);
        update_frame(list, ue_index, rrc_state, rf_chains);
    }
}

int main() {
    FRAMES_LIST list;
    init_frame_list(&list);

    // Add some frames to the list
    add_frame(&list, 10, NFAPI_RRC_STATE_ACTIVE, NULL);
    add_frame(&list, 20, NFAPI_RRC_STATE_INACTIVE, NULL);
    add_frame(&list, 30, NFAPI_RRC_STATE_CONNECTED, NULL);

    // Update a frame in the list based on UE index
    update_frame(&list, 20, NFAPI_RRC_STATE_IDLE, NULL);

    // Retrieve a frame from the list based on RRC state
    NFAPI_RX_FRAME_T *frame = get_frame(&list, NFAPI_RRC_STATE_ACTIVE);
    if (frame != NULL) {
        printf("Found frame with UE index %d and RRC state %d\n", frame->ue_index, frame->rrc_state);
    }

    // Serialize the list to a file for later restoration
    FILE *file = fopen("frame_list.dat", "wb");
    serialize_frame_list(&list, file);
    fclose(file);

    return 0;
}
