#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <limits.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_LIST {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t mutex;
} CRC_INDICATION_LIST_T;

// Initialize a new list with a specified capacity
void crc_indication_list_init(CRC_INDICATION_LIST_T *list, int capacity) {
    list->size = 0;
    list->capacity = capacity;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new element to the list
void crc_indication_list_add(CRC_INDICATION_LIST_T *list, uint16_t rx_ue_information_tag, uint32_t rnti, uint8_t crc_indication_rel8_tag, uint8_t crcflag) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        // resize the list if it's full
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        memcpy(new_data, list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->size);
        free(list->data);
        list->data = new_data;
        list->capacity = new_capacity;
    }
    int index = list->size++;
    list->data[index].rx_ue_information_tag = rx_ue_information_tag;
    list->data[index].rnti = rnti;
    list->data[index].crc_indication_rel8_tag = crc_indication_rel8_tag;
    list->data[index].crcflag = crcflag;
    pthread_mutex_unlock(&list->mutex);
}

// Get the total number of elements in the list
int crc_indication_list_size(CRC_INDICATION_LIST_T *list) {
    return list->size;
}

// Check if a specified RNTI is present in the list
bool crc_indication_list_contains(CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    pthread_mutex_lock(&list->mutex);
    bool found = false;
    for (int i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == rnti) {
            found = true;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return found;
}

// Filter the list based on a specified RNTI range
void crc_indication_list_filter(CRC_INDICATION_LIST_T *list, uint32_t rnti_start, uint32_t rnti_end) {
    pthread_mutex_lock(&list->mutex);
    int new_size = 0;
    for (int i = 0; i < list->size; ++i) {
        if (list->data[i].rnti >= rnti_start && list->data[i].rnti <= rnti_end) {
            new_size++;
        }
    }
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size);
    int j = 0;
    for (int i = 0; i < list->size; ++i) {
        if (list->data[i].rnti >= rnti_start && list->data[i].rnti <= rnti_end) {
            new_data[j++] = list->data[i];
        }
    }
    free(list->data);
    list->size = new_size;
    list->data = new_data;
    pthread_mutex_unlock(&list->mutex);
}

// Serialize the list to a file in binary format
void crc_indication_list_serialize(CRC_INDICATION_LIST_T *list, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        return;
    }
    pthread_mutex_lock(&list->mutex);
    int size = list->size;
    fwrite(&size, sizeof(int), 1, fp);
    for (int i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = &list->data[i];
        fwrite(&element->rx_ue_information_tag, sizeof(uint16_t), 1, fp);
        fwrite(&element->rnti, sizeof(uint32_t), 1, fp);
        fwrite(&element->crc_indication_rel8_tag, sizeof(uint8_t), 1, fp);
        fwrite(&element->crcflag, sizeof(uint8_t), 1, fp);
    }
    pthread_mutex_unlock(&list->mutex);
    fclose(fp);
}

// Deserialize the list from a file in binary format
void crc_indication_list_deserialize(CRC_INDICATION_LIST_T *list, const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        return;
    }
    pthread_mutex_lock(&list->mutex);
    int size;
    fread(&size, sizeof(int), 1, fp);
    for (int i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU *element = &list->data[i];
        fread(&element->rx_ue_information_tag, sizeof(uint16_t), 1, fp);
        fread(&element->rnti, sizeof(uint32_t), 1, fp);
        fread(&element->crc_indication_rel8_tag, sizeof(uint8_t), 1, fp);
        fread(&element->crcflag, sizeof(uint8_t), 1, fp);
    }
    list->size = size;
    pthread_mutex_unlock(&list->mutex);
    fclose(fp);
}

// Free the memory allocated to the list
void crc_indication_list_free(CRC_INDICATION_LIST_T *list) {
    free(list->data);
    list->size = 0;
    list->data = NULL;
}

int main() {
    CRC_INDICATION_LIST_T list;
    crc_indication_list_init(&list, 10);
    crc_indication_list_add(&list, 12345, 987654321, 1234, true);
    printf("The list size is %d\n", crc_indication_list_size(&list));
    crc_indication_list_filter(&list, 123000, 123999);
    printf("The filtered list size is %d\n", crc_indication_list_size(&list));
    crc_indication_list_serialize(&list, "crc_indications.bin");
    CRC_INDICATION_LIST_T new_list;
    crc_indication_list_init(&new_list, 10);
    crc_indication_list_deserialize(&new_list, "crc_indications.bin");
    printf("The new list size is %d\n", crc_indication_list_size(&new_list));
    crc_indication_list_free(&list);
    crc_indication_list_free(&new_list);
    return 0;
}
