static size_t num_packets = 0;

// Add a new packet to the collection
int addPacket(uint16_t pid, uint8_t seq, void* data) {
    // Check for existing packet with same PID and sequence number
    for (size_t i = 0; i < num_packets; i++) {
        if (packets[i].pid == pid && packets[i].seq == seq) {
            return -1; // Packet already exists
        }
    }

    // Allocate memory for new packet
    Packet* new_packet = malloc(sizeof(Packet));
    if (new_packet == NULL) {
        return -2; // Memory allocation failed
    }

    // Initialize packet fields and add to collection
    new_packet->pid = pid;
    new_packet->seq = seq;
    new_packet->data = data;
    packets = realloc(packets, (num_packets + 1) * sizeof(Packet));
    if (packets == NULL) {
        free(new_packet); // Memory allocation failed
        return -3;
    }
    packets[num_packets++] = new_packet;

    return 0; // Success
}

// Update an existing packet in the collection
int updatePacket(uint16_t pid, uint8_t seq, void* data) {
    // Check for existing packet with same PID and sequence number
    for (size_t i = 0; i < num_packets; i++) {
