            packets[i].data = data; // Update packet data
            return 0; // Success
        }
    }
    return -1; // Packet not found
}

// Retrieve a packet from the collection by PID and sequence number
Packet* getPacket(uint16_t pid, uint8_t seq) {
    for (size_t i = 0; i < num_packets; i++) {
        if (packets[i].pid == pid && packets[i].seq == seq) {
            return &packets[i]; // Success
        }
    }
    return NULL; // Packet not found
}

// Release memory for all packets in the collection
void releasePackets() {
