// Mutex to protect the global memory pool from concurrent access
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the memory pool for a new thread
void init_memory_pool(size_t capacity) {
  // Allocate memory for the data array
