    // Double the size of the global memory pool and update the data structures
    struct NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(g_memory_pool.data, 2 * sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * g_memory_pool.capacity);
    if (!new_data) {
