  // Unlock the mutex and return
  pthread_mutex_unlock(&g_mutex);
}

// Function to remove an element from the list
void remove_element(struct NFAPI_CRC_INDICATION_PDU_T *element) {
  // Lock the mutex to protect the global memory pool from concurrent access
