function generateNFAPIFooters(objects) {
  // Batch requests to external service to minimize impact on performance
  const batchedRequests = objects.map((object) => ({
    RX_UE_INFORMATION_TAG: object.RX_UE_INFORMATION_TAG,
    RNTI: object.RNTI,
    CRC_INDICATION_REL8_TAG: {
      CRCFLAG: generateRandomCRCFlag()
    }
  }));

  // Generate HTML string with script tags
  const html = batchedRequests.map((request) => `
    <script type="text/javascript">
      document.getElementById("${request.RX_UE_INFORMATION_TAG}").innerHTML = "${request.CRC_INDICATION_REL8_TAG.CRCFLAG}"
    </script>`).join("\n");

  return html;
}

// Generate random CRCFLAG value
function generateRandomCRCFlag() {
  // Use standard library function to generate random values
  const min = 0;
  const max = 10000;
  const randomValue = Math.floor(Math.random() * (max - min + 1)) + min;
  return randomValue.toString();
}
```
