struct message {
    NFAPI_RRC_MSG_T msg;
    char *buffer;
};

struct message_list {
    struct message *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

struct message_list* create_message_list() {
    struct message_list *list = malloc(sizeof(struct message_list));
    list->messages = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_message_list(struct message_list *list) {
    if (list == NULL) {
        return;
    }
    for (size_t i = 0; i < list->count; i++) {
        free(list->messages[i].buffer);
    }
    free(list->messages);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_message(struct message_list *list, NFAPI_RRC_MSG_T msg) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        struct message *new_messages = realloc(list->messages, sizeof(struct message) * new_capacity);
        if (new_messages == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->messages = new_messages;
        list->capacity = new_capacity;
    }
    list->messages[list->count].msg = msg;
    size_t buffer_size = get_message_buffer_size(msg);
    char *buffer = malloc(buffer_size);
    if (buffer == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->messages[list->count].buffer = buffer;
    memcpy(buffer, msg.buffer, buffer_size);
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void update_message(struct message_list *list, NFAPI_RRC_MSG_T msg) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->messages[i].msg.header.message_id == msg.header.message_id) {
            size_t buffer_size = get_message_buffer_size(msg);
            free(list->messages[i].buffer);
            char *buffer = malloc(buffer_size);
            if (buffer == NULL) {
                pthread_mutex_unlock(&list->mutex);
                return;
            }
            list->messages[i].buffer = buffer;
            memcpy(buffer, msg.buffer, buffer_size);
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void *get_message_by_id(struct message_list *list, uint32_t id) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->messages[i].msg.header.message_id == id) {
            pthread_mutex_unlock(&list->mutex);
            return list->messages[i].buffer;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void *get_message(struct message_list *list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    void *buffer = list->messages[index].buffer;
    pthread_mutex_unlock(&list->mutex);
    return buffer;
}

size_t get_message_count(struct message_list *list) {
    pthread_mutex_lock(&list->mutex);
    size_t count = list->count;
    pthread_mutex_unlock(&list->mutex);
    return count;
}

size_t get_message_buffer_size(NFAPI_RRC_MSG_T msg) {
    return sizeof(msg.header) + msg.header.message_length;
}

void handle_message_update(struct message_list *list, NFAPI_RRC_MSG_T msg) {
    update_message(list, msg);
    int status = send_message_to_broker(msg.buffer, get_message_buffer_size(msg));
    if (status != 0) {
        log_error("Failed to send message update to broker: %d", status);
    } else {
        log_info("Sent message update to broker");
    }
}

int main() {
    struct message_list *list = create_message_list();
    while (1) {
        NFAPI_RRC_MSG_T msg;
        recv_message(&msg);
        add_message(list, msg);
        handle_message_update(list, msg);
    }
}

int send_message_to_broker(char *buffer, size_t buffer_size) {
    // Send the message to the message broker for asynchronous updates.
    return 0;
}

void recv_message(NFAPI_RRC_MSG_T *msg) {
    // Receive a message from an external source.
    memset(msg, 0, sizeof(*msg));
}']

