int pool_head = 0;

// Function to allocate memory dynamically for the list and each structure, ensuring proper memory management to prevent leaks. Consider using a pool allocator for efficient reuse of memory blocks.
void allocate_memory(size_t size) {
    if (crc_indications == NULL) {
        crc_indications = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE);
        if (crc_indications == NULL) {
            fprintf(stderr, "Failed to allocate memory for the list of CRC indication PDUs\n");
            return;
        }
    } else {
        // Check if there is enough space in the pool allocator
        size_t available_space = POOL_SIZE - (pool_head + 1);
        if (available_space < size) {
            fprintf(stderr, "Not enough space in the pool allocator to allocate %lu bytes\n", size);
            return;
        }

        // Allocate memory from the pool allocator
        void* ptr = pool + pool_head++;
        memset(ptr, 0, size);
        return ptr;
    }
}

