// Structure to hold bearer statistics for each session
typedef struct BearerStats {
    int bytes_sent;
    int bytes_received;
    double uplink_bitrate;
    double downlink_bitrate;
} BearerStats;

// Function to initialize user sessions
int initializeUserSessions(int max_sessions, int *session_ids) {
    // Check if input parameters are valid
    if (max_sessions <= 0 || session_ids == NULL) {
        return -1;
    }

    // Allocate memory for the user sessions
    UserSessionInfo **user_sessions = malloc(sizeof(UserSessionInfo *) * max_sessions);
    if (user_sessions == NULL) {
        return -2;
    }

    // Initialize each session with a randomly generated bearer statistics structure
    for (int i = 0; i < max_sessions; i++) {
        UserSessionInfo *session = malloc(sizeof(UserSessionInfo));
        if (session == NULL) {
            return -3;
        }
        session->ue_id = rand();
        session->bearer_id = rand();
        session->session_state = rand();
        BearerStats *stats = malloc(sizeof(BearerStats));
        if (stats == NULL) {
            return -4;
        }
        stats->bytes_sent = rand();
        stats->bytes_received = rand();
        stats->uplink_bitrate = rand() / 10.0;
        stats->downlink_bitrate = rand() / 10.0;
        session->bearer_stats = stats;
        user_sessions[i] = session;
    }

    // Store the session IDs in the input array
    for (int i = 0; i < max_sessions; i++) {
        session_ids[i] = user_sessions[i]->ue_id;
    }

    // Clean up memory
    free(user_sessions);

    return 0;
}
