// Structure representing a network packet header
typedef struct {
    char ipAddress[16]; // IP address of the sender
    uint8_t protocolType; // Type of protocol used for transport (e.g., TCP, UDP)
    uint32_t checksum; // Checksum calculated for the packet header
} PacketHeader;

// Dynamic list of network packet headers
typedef struct {
    PacketHeader *headers; // Array of packet headers
    size_t capacity; // Capacity of the array (number of elements)
    size_t count; // Number of valid elements in the array
} HeaderList;

// Initialize an empty header list with a given capacity
void initHeaderList(HeaderList *list, size_t capacity) {
    list->headers = malloc(capacity * sizeof(PacketHeader));
    memset(list->headers, 0, capacity * sizeof(PacketHeader));
    list->capacity = capacity;
    list->count = 0;
}

// Add a packet header to the list
void addHeaderToList(HeaderList *list, PacketHeader header) {
    if (list->count == list->capacity) {
        // Expand the array if necessary
        list->headers = realloc(list->headers, 2 * list->capacity * sizeof(PacketHeader));
        memset(list->headers + list->count, 0, list->capacity * sizeof(PacketHeader));
        list->capacity *= 2;
    }
    list->headers[list->count++] = header;
}

// Search for a packet header in the list by IP address
bool searchForHeader(HeaderList *list, char ipAddress[]) {
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->headers[i].ipAddress, ipAddress) == 0) {
            return true;
        }
    }
    return false;
}

// Search for a packet header in the list by protocol type
bool searchForProtocolType(HeaderList *list, uint8_t protocolType) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->headers[i].protocolType == protocolType) {
            return true;
        }
    }
    return false;
}

// Periodically validate all packet headers against a provided checksum function
void validateHeaders(HeaderList *list, uint32_t (*checksumFunc)(PacketHeader)) {
    for (size_t i = 0; i < list->count; i++) {
        if (!checksumFunc(list->headers[i])) {
            // Remove the invalid header from the list
            memmove(&list->headers[i], &list->headers[i + 1], (list->count - i) * sizeof(PacketHeader));
            list->count--;
        }
    }
}

// Clean up the header list and free any allocated memory
void cleanupHeaderList(HeaderList *list) {
    free(list->headers);
}
