    // Loop until all the RNTI values have been processed
    while (count < N) {
        // Get a batch of up to 5,000 RNTI values from an external data source
        int batchSize = MIN(N - count, 5000);
        for (int i = 0; i < batchSize; i++) {
            // Populate the NFAPI_CRC_INDICATION_PDU_T structure with a random RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
            arr[i].RX_UE_INFORMATION_TAG = rand() % 1000;
