            arr[i].CRC_INDICATION_REL8_TAG = rand() % 256;
            arr[i].CRCFLAG = (rand() % 2 == 0) ? true : false;
        }

        // Increment the number of RNTI values processed so far
        count += batchSize;

        // Check if any duplicate RNTIs were detected during processing
        bool duplicatesDetected = false;
        for (int i = 0; i < batchSize; i++) {
            for (int j = i + 1; j < batchSize; j++) {
                if (arr[i].RNTI == arr[j].RNTI) {
