LTE_ENB_CONFIG_LIST* create_list() {
  LTE_ENB_CONFIG_LIST* list = (LTE_ENB_CONFIG_LIST*)malloc(sizeof(LTE_ENB_CONFIG_LIST));
  if (!list) {
    fprintf(stderr, "Error: Failed to allocate memory for the list\n");
    return NULL;
  }
  list->count = 0;
  list->data = NULL;
  pthread_mutex_init(&list->lock, NULL); // Initialize a mutex to protect the list from concurrent access
  return list;
}

// Function to add a new LTE_ENB_CONFIG_API_DATA structure to the list
int add_config(LTE_ENB_CONFIG_LIST* list, LTE_ENB_CONFIG_API_DATA config) {
  pthread_mutex_lock(&list->lock); // Acquire a lock on the list before modifying it
  if (list->count >= MAX_CONFIGS) { // Check if the list is full
    fprintf(stderr, "Error: Maximum number of configurations reached\n");
    pthread_mutex_unlock(&list->lock); // Release the lock on the list
    return -1;
  }
  LTE_ENB_CONFIG_API_DATA* new_config = (LTE_ENB_CONFIG_API_DATA*)malloc(sizeof(LTE_ENB_CONFIG_API_DATA)); // Allocate memory for the new configuration
  if (!new_config) {
    fprintf(stderr, "Error: Failed to allocate memory for the new configuration\n");
    pthread_mutex_unlock(&list->lock); // Release the lock on the list
    return -1;
  }
  *new_config = config; // Copy the configuration data into the new structure
  list->data = realloc(list->data, (list->count + 1) * sizeof(LTE_ENB_CONFIG_API_DATA)); // Reallocate memory for the list to accommodate the new structure
  if (!list->data) {
    fprintf(stderr, "Error: Failed to reallocate memory for the list\n");
    pthread_mutex_unlock(&list->lock); // Release the lock on the list
    free(new_config); // Free the memory allocated for the new structure
    return -1;
  }
  list->data[list->count] = *new_config; // Add the new structure to the end of the list
  list->count++;
  pthread_mutex_unlock(&list->lock); // Release the lock on the list
  return 0;
}

// Function to update an existing LTE_ENB_CONFIG_API_DATA structure in the list
int update_config(LTE_ENB_CONFIG_LIST* list, LTE_ENB_CONFIG_API_DATA config) {
  pthread_mutex_lock(&list->lock); // Acquire a lock on the list before modifying it
  for (int i = 0; i < list->count; i++) { // Search for the structure with the same cell identity as the new configuration
    if (list->data[i].ci == config.ci) {
      list->data[i] = config; // Update the existing structure with the new configuration data
      pthread_mutex_unlock(&list->lock); // Release the lock on the list
      return 0;
    }
  }
  fprintf(stderr, "Error: Could not find configuration to update\n");
  pthread_mutex_unlock(&list->lock); // Release the lock on the list
  return -1;
}

