// Rolling checksum for RNTI values in the list
static uint32_t rnti_checksum = 0;

// Sliding window size for detecting duplicate RNTI usage
#define M 10

// List of NFAPI_CRC_INDICATION_PDU_T structures
struct nfapi_crc_indication_pdu *list = NULL;

// Add a new structure to the list and update the checksum
void add_structure(struct nfapi_crc_indication_pdu *new) {
    // Check for duplicate RNTI usage in the last M structures
    uint32_t rnti = new->rx_ue_information_tag.rnti;
    if (rnti_checksum & (1 << rnti)) {
        printf("Duplicate RNTI detected: %u\n", rnti);
        return;
    }

    // Add the new structure to the list and update the checksum
    struct nfapi_crc_indication_pdu *prev = list;
    while (prev && prev->next) {
        prev = prev->next;
    }
    if (!prev || !prev->next) {
        printf("Error: memory allocation failed\n");
        return;
    }
    prev->next = new;
    list = new;
    rnti_checksum |= (1 << rnti);
}

// Remove a structure from the list and update the checksum
void remove_structure(struct nfapi_crc_indication_pdu *old) {
    // Find the structure in the list and remove it
    struct nfapi_crc_indication_pdu *prev = list;
    while (prev && prev->next != old) {
        prev = prev->next;
    }
    if (!prev || !prev->next) {
        printf("Error: structure not found\n");
        return;
    }
    prev->next = old->next;
    list = old->next;
    rnti_checksum &= ~(1 << old->rx_ue_information_tag.rnti);
}

// Handle a new RX_UE_INFORMATION_TAG received from the signaling processor
void handle_rx_ue_information_tag(struct nfapi_rx_ue_information_tag *new) {
    // Create a new structure and add it to the list
    struct nfapi_crc_indication_pdu *new_pdu = malloc(sizeof(*new_pdu));
    if (!new_pdu) {
        printf("Error: memory allocation failed\n");
        return;
    }
    new_pdu->rx_ue_information_tag = *new;
    add_structure(new_pdu);
}

// Handle a CRC_INDICATION_REL8_TAG received from the network interface module
void handle_crc_indication_rel8_tag(struct nfapi_crc_indication_rel8_tag *new) {
    // Find the corresponding structure in the list and update its CRCFLAG field
    struct nfapi_crc_indication_pdu *old = find_structure(new->rnti);
    if (!old) {
        printf("Error: structure not found\n");
        return;
    }
    old->crc_indication_rel8_tag.crcflag = new->crcflag;
}

// Find a structure in the list by its RNTI value
struct nfapi_crc_indication_pdu *find_structure(uint32_t rnti) {
    struct nfapi_crc_indication_pdu *prev = list;
    while (prev && prev->rx_ue_information_tag.rnti != rnti) {
        prev = prev->next;
    }
    return prev;
}
