    array->entries = (UEContext*) calloc(N, sizeof(UEContext));
    if (!array->entries) {
        printf("Failed to allocate memory for UE context entries\n");
        free(array);
        exit(1);
    }

    array->count = N;

    // Initialize entries with random values for rsrp and rsrq, and set pci based on modulo operation
    for (size_t i = 0; i < N; ++i) {
        UEContext* entry = &array->entries[i];
        entry->imsi = rand() % MAX_IMSI;
        entry->rnti = rand() % MAX_RNTI;
        entry->report.pci = rand() % MAX_PCI;
        entry->report.rsrp = rand() % 100;
        entry->report.rsrq = rand() % 25;
    }

    return array;
}

void free_ue_context_array(UEContextArray* array) {
    if (array) {
        free(array->entries);
        free(array);
    }
}

void sort_ue_context_array(UEContextArray* array) {
    qsort(array->entries, array->count, sizeof(UEContext), compare_ue_contexts_by_rsrp);
}

int compare_ue_contexts_by_rsrp(const void *a, const void *b) {
    UEContext* ue1 = (UEContext*) a;
    UEContext* ue2 = (UEContext*) b;
    return ue1->report.rsrp - ue2->report.rsrp;
}

void filter_ue_contexts_by_imsi(UEContextArray* array, long imsi) {
    size_t count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        UEContext* entry = &array->entries[i];
        if (entry->imsi == imsi) {
            count++;
        }
    }

    UEContext** filtered_entries = malloc(sizeof(UEContext*) * count);
    if (!filtered_entries) {
        printf("Failed to allocate memory for filtered UE context entries\n");
        exit(1);
    }

    size_t j = 0;
    for (size_t i = 0; i < array->count; ++i) {
        UEContext* entry = &array->entries[i];
        if (entry->imsi == imsi) {
            filtered_entries[j] = malloc(sizeof(UEContext));
            memcpy(filtered_entries[j], entry, sizeof(UEContext));
            j++;
        }
    }

    free(array->entries);
    array->entries = filtered_entries;
    array->count = count;
}

void filter_ue_contexts_by_rnti(UEContextArray* array, int rnti) {
    size_t count = 0;
    for (size_t i = 0; i < array->count; ++i) {
        UEContext* entry = &array->entries[i];
        if (entry->rnti == rnti) {
            count++;
        }
    }

    UEContext** filtered_entries = malloc(sizeof(UEContext*) * count);
    if (!filtered_entries) {
        printf("Failed to allocate memory for filtered UE context entries\n");
        exit(1);
    }

    size_t j = 0;
    for (size_t i = 0; i < array->count; ++i) {
        UEContext* entry = &array->entries[i];
        if (entry->rnti == rnti) {
            filtered_entries[j] = malloc(sizeof(UEContext));
            memcpy(filtered_entries[j], entry, sizeof(UEContext));
            j++;
        }
    }

    free(array->entries);
    array->entries = filtered_entries;
    array->count = count;
}

void update_ue_contexts(UEContextArray* array) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < array->count; ++i) {
        UEContext* entry = &array->entries[i];
        entry->report.rsrp = rand() % 100;
        entry->report.rsrq = rand() % 25;
    }

    pthread_mutex_unlock(&mutex);
}

void* update_thread(void* args) {
    UEContextArray* array = (UEContextArray*) args;

    while (1) {
        update_ue_contexts(array);
        sleep(0.5); // 500 milliseconds
    }
}
```
