#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Structure to hold network interface configuration details
typedef struct {
    int index;
    uint32_t ip_addr;
    uint32_t subnet_mask;
    uint32_t gateway;
} netif_config_t;

// Function to initialize and populate the network interface configuration array
int init_netif_config(netif_config_t **config, int num_interfaces) {
    // Allocate memory for the configuration array
    *config = (netif_config_t *)malloc(sizeof(netif_config_t) * num_interfaces);
    if (*config == NULL) {
        return -1;  // Memory allocation failed
    }

    // Iterate through each interface and populate the configuration array
    for (int i = 0; i < num_interfaces; i++) {
        // Get the index of the current interface
        int index = get_interface_index(i);
        if (index == -1) {
            return -2;  // Interface not found
        }

        // Get the IP address, subnet mask, and gateway for the current interface
        uint32_t ip_addr = get_ip_address(index);
        uint32_t subnet_mask = get_subnet_mask(index);
        uint32_t gateway = get_gateway(index);
        if (ip_addr == 0 || subnet_mask == 0 || gateway == 0) {
            return -3;  // Invalid interface configuration
        }

        // Validate the IP address and subnet mask for correctness
        if (!validate_ip_address(ip_addr) || !validate_subnet_mask(subnet_mask)) {
            return -4;  // Invalid IP address or subnet mask
        }

        // Add the current interface configuration to the array
        (*config)[i].index = index;
        (*config)[i].ip_addr = ip_addr;
        (*config)[i].subnet_mask = subnet_mask;
        (*config)[i].gateway = gateway;
    }

    return 0;  // Configuration initialized successfully
}

// Function to get the index of a network interface
int get_interface_index(int num) {
    // Retrieve the list of all available network interfaces
    struct ifaddrs *ifaddrs = NULL;
    if (getifaddrs(&ifaddrs) == -1) {
        return -1;  // Failed to retrieve interface list
    }

    // Iterate through each interface and check for the specified number
    struct ifaddrs *ifa = ifaddrs;
    while (num > 0 && ifa != NULL) {
        num--;
        ifa = ifa->ifa_next;
    }

    // Return the index of the requested interface or -1 if not found
    if (ifa == NULL || ifa->ifa_addr == NULL) {
        return -1;  // Interface not found
    }
    return if_nametoindex(ifa->ifa_name);
}

// Function to get the IP address of a network interface
uint32_t get_ip_address(int index) {
    struct in_addr ip_addr;
    ip_addr.s_addr = INADDR_ANY;
    if (getifaddrs(&ip_addr) == -1) {
        return 0;  // Failed to retrieve interface IP address
    }
    return ntohl(ip_addr.s_addr);
}

// Function to get the subnet mask of a network interface
uint32_t get_subnet_mask(int index) {
    struct in_addr subnet_mask;
    subnet_mask.s_addr = INADDR_ANY;
    if (getifaddrs(&subnet_mask) == -1) {
        return 0;  // Failed to retrieve interface subnet mask
    }
    return ntohl(subnet_mask.s_addr);
}

// Function to get the gateway of a network interface
uint32_t get_gateway(int index) {
    struct in_addr gateway;
    gateway.s_addr = INADDR_ANY;
    if (getifaddrs(&gateway) == -1) {
        return 0;  // Failed to retrieve interface gateway
    }
    return ntohl(gateway.s_addr);
}

// Function to validate an IP address for correctness
bool validate_ip_address(uint32_t ip_addr) {
    if (ip_addr == 0) {
        return false;  // Invalid IP address
    }
    uint8_t octets[4];
    memcpy(octets, &ip_addr, 4);
    for (int i = 0; i < 4; i++) {
        if (octets[i] > 255) {
            return false;  // Invalid IP address octet
        }
    }
    return true;  // Valid IP address
}

// Function to validate a subnet mask for correctness
bool validate_subnet_mask(uint32_t subnet_mask) {
    if (subnet_mask == 0) {
        return false;  // Invalid subnet mask
    }
    uint8_t octets[4];
    memcpy(octets, &subnet_mask, 4);
    for (int i = 0; i < 3; i++) {
        if (octets[i] != 255) {
            return false;  // Invalid subnet mask octet
        }
    }
    return true;  // Valid subnet mask
}
```
