void initialize_crc_array(size_t size) {
    // Allocate memory for the array of structures
    crc_array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);

    // Initialize each structure with a random CRCFLAG value
    for (int i = 0; i < size; i++) {
        crc_array[i].rx_ue_information_tag = rand() % 100;
        crc_array[i].rnti = rand() % 1000;
        crc_array[i].crc_indication_rel8_tag = rand() % 256;
    }
}

void populate_crc_array(size_t size) {
    // Lock the mutex to ensure thread safety during population
    pthread_mutex_lock(&mutex);

