#define NFAPI_CRC_INDICATION_PDU_T struct { \
    uint16_t rx_ue_information_tag; \
    uint16_t rnti; \
    uint8_t crc_indication_rel8_tag; \
}

struct nfapi_rx_indication_pdu {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t count;
};

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static struct nfapi_rx_indication_pdu list;

void update_crc_indication(uint16_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag) {
    // Validate RNTI values
    if (rnti < 0x0001 || rnti > 0x3FFF) {
        fprintf(stderr, "Invalid RNTI value: %u\n", rnti);
        return;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the structure already exists in the list
    bool found = false;
    for (size_t i = 0; i < list.count; i++) {
        if (list.pdu[i].rx_ue_information_tag == rx_ue_information_tag) {
            found = true;
            break;
        }
    }

    // Create a new structure if it doesn't exist
    if (!found) {
        list.count++;
        list.pdu = realloc(list.pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list.count);
        memset(&list.pdu[list.count - 1], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Update the structure with the new values
    list.pdu[found ? i : (list.count - 1)].rx_ue_information_tag = rx_ue_information_tag;
    list.pdu[found ? i : (list.count - 1)].rnti = rnti;
    list.pdu[found ? i : (list.count - 1)].crc_indication_rel8_tag = crc_indication_rel8_tag;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void print_crc_indications() {
    printf("Current CRC indications:\n");
    for (size_t i = 0; i < list.count; i++) {
        printf("%u: RX UE information tag %u, RNTI %u, CRCFLAG %u\n", i + 1,
               list.pdu[i].rx_ue_information_tag, list.pdu[i].rnti, list.pdu[i].crc_indication_rel8_tag);
    }
}

void cleanup() {
    pthread_mutex_destroy(&mutex);
    free(list.pdu);
}
