// Function to retrieve external configuration parameters from an external service
int getExternalConfigurationParameters() {
    // Check for cache expiry and update local variables accordingly
    time_t currentTime = time(NULL);
    if (PARAMETER_CACHE_EXPIRY_SECONDS > 0 && currentTime - PARAMETER_CACHE_EXPIRY_SECONDS < PARAMETER_CACHE_LAST_UPDATED) {
        // Use cached parameters
        return 1;
    } else {
        // Retrieve new parameters from external service
        struct url url = {};
        url.scheme = "http";
        url.host = EXTERNAL_CONFIGURATION_SERVICE_HOST;
        url.port = EXTERNAL_CONFIGURATION_SERVICE_PORT;
        url.path = "/configuration";
