            json_value* root = json_parse(response.body);
            json_object* obj = json_value_get_object(root);
            NUM_ENTRIES = json_object_get_number(obj, "numEntries");
            CRCFLAG_DISTRIBUTION[0] = json_object_get_number(obj, "crcFlagDistribution")[0];
            CRCFLAG_DISTRIBUTION[1] = json_object_get_number(obj, "crcFlagDistribution")[1];
            CRCFLAG_DISTRIBUTION[2] = json_object_get_number(obj, "crcFlagDistribution")[2];
            RNTI_RANGE_MIN = json_object_get_number(obj, "rntiRangeMin");
            RNTI_RANGE_MAX = json_object_get_number(obj, "rntiRangeMax");
        } else {
            // Handle error response from external service
            return 0;
        }
    }
}

// Function to generate a random boolean value with the given distribution
bool crcFlagDistribution() {
    float randVal = (float)rand() / (float)RAND_MAX;
    for (int i = 0; i < sizeof(CRCFLAG_DISTRIBUTION); i++) {
        if (randVal <= CRCFLAG_DISTRIBUTION[i]) {
            return (bool)(i % 2 == 0);
        }
    }
}
