pthread_cond_t cv = PTHREAD_COND_INITIALIZER;

// Define function for allocating memory for a new CRC indication structure
nfapi_crc_indication_t *allocate_new_crc_indication(void) {
    nfapi_crc_indication_t *ptr = (nfapi_crc_indication_t *)malloc(sizeof(nfapi_crc_indication_t));
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory for new CRC indication structure\n");
        return NULL;
    }
    return ptr;
}

// Define function for freeing memory of a CRC indication structure
void free_crc_indication(nfapi_crc_indication_t *ptr) {
    if (!ptr) {
        return;
    }
    free(ptr);
}

// Define function for adding a new CRC indication to the list of structures
bool add_new_crc_indication(nfapi_crc_indication_t *ptr) {
    if (!ptr) {
        return false;
    }
    pthread_mutex_lock(&lock);
    // Check if there is enough space to store the new structure
    if (MAX_CONCURRENT_STRUCTS <= num_crc_indications) {
        fprintf(stderr, "Maximum number of CRC indications reached\n");
        pthread_mutex_unlock(&lock);
        return false;
    }
    // Copy the new structure to the list
    crc_indications[num_crc_indications++] = *ptr;
    pthread_cond_signal(&cv);
    pthread_mutex_unlock(&lock);
    return true;
}

// Define function for removing a CRC indication from the list of structures
void remove_crc_indication(nfapi_crc_indication_t *ptr) {
    if (!ptr) {
        return;
    }
    pthread_mutex_lock(&lock);
    // Find the index of the structure to be removed
    int i = 0;
    for (i = 0; i < num_crc_indications; i++) {
        if (crc_indications[i] == *ptr) {
            break;
        }
    }
    // Remove the structure from the list
