        memmove(&(crc_indications[i]), &(crc_indications[i+1]), sizeof(nfapi_crc_indication_t) * (num_crc_indications - i));
    }
    // Decrement the number of stored structures
    num_crc_indications--;
    pthread_cond_signal(&cv);
    pthread_mutex_unlock(&lock);
}

// Define function for processing a CRC indication structure
void process_crc_indication(nfapi_crc_indication_t *ptr) {
