#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define a structure to store information about each packet
typedef struct Packet {
    uint32_t srcIP;
    uint32_t dstIP;
    size_t payloadSize;
    NFAPI_CRC_INDICATION_PDU_T crcIndication;
} Packet;

// Define a hashtable to map IP addresses to packet structures
typedef struct HashTable {
    uint32_t* keys;
    Packet** values;
    size_t capacity;
    size_t count;
} HashTable;

// Implement hash function for IP address
static inline uint32_t hashIP(uint32_t ip) {
    return (ip >> 16) ^ (ip & 0xFFFF);
}

// Create a new hashtable with given capacity
HashTable* createHashTable(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->keys = calloc(capacity, sizeof(uint32_t));
    table->values = calloc(capacity, sizeof(Packet*));
    if (!table->keys || !table->values) {
        free(table);
        return NULL;
    }

    table->count = 0;
    table->capacity = capacity;
    return table;
}

// Insert a new packet into the hashtable
int insertPacket(HashTable* table, uint32_t srcIP, uint32_t dstIP, size_t payloadSize, NFAPI_CRC_INDICATION_PDU_T crcIndication) {
    if (!table || table->count >= table->capacity) return -1;

    // Calculate hash value for IP addresses
    uint32_t hashSrcIP = hashIP(srcIP);
    uint32_t hashDstIP = hashIP(dstIP);

    // Check if a packet with the same source and destination IP already exists
    size_t index;
    for (index = 0; index < table->count; index++) {
        uint32_t keySrcIP = table->keys[index];
        uint32_t keyDstIP = table->values[index]->dstIP;
        if ((keySrcIP == srcIP && keyDstIP == dstIP) || (keySrcIP == dstIP && keyDstIP == srcIP)) {
            // Packet with the same source and destination IP already exists, update it
            table->values[index]->srcIP = srcIP;
            table->values[index]->dstIP = dstIP;
            table->values[index]->payloadSize = payloadSize;
            table->values[index]->crcIndication = crcIndication;
            return 0;
        }
    }

    // Allocate a new packet structure and store it in the hashtable
    Packet* packet = malloc(sizeof(Packet));
    if (!packet) return -1;

    packet->srcIP = srcIP;
    packet->dstIP = dstIP;
    packet->payloadSize = payloadSize;
    packet->crcIndication = crcIndication;

    table->keys[table->count] = hashSrcIP;
    table->values[table->count++] = packet;
    return 0;
}

// Look up a packet in the hashtable by source IP address
Packet* lookupPacketBySrcIP(HashTable* table, uint32_t srcIP) {
    if (!table || table->count == 0) return NULL;

    // Calculate hash value for source IP address
    uint32_t hash = hashIP(srcIP);

    // Search the hashtable for a matching packet
    size_t index;
    for (index = 0; index < table->count; index++) {
        if (table->keys[index] == hash) {
            return table->values[index];
        }
    }

    return NULL;
}

// Look up a packet in the hashtable by destination IP address
Packet* lookupPacketByDstIP(HashTable* table, uint32_t dstIP) {
    if (!table || table->count == 0) return NULL;

    // Calculate hash value for destination IP address
    uint32_t hash = hashIP(dstIP);

    // Search the hashtable for a matching packet
    size_t index;
    for (index = 0; index < table->count; index++) {
        if (table->values[index]->dstIP == dstIP) {
            return table->values[index];
        }
    }

    return NULL;
}

// Remove a packet from the hashtable by source IP address
int removePacketBySrcIP(HashTable* table, uint32_t srcIP) {
    if (!table || table->count == 0) return -1;

    // Calculate hash value for source IP address
    uint32_t hash = hashIP(srcIP);

    // Search the hashtable for a matching packet and remove it if found
    size_t index;
    for (index = 0; index < table->count; index++) {
        if (table->keys[index] == hash) {
            free(table->values[index]);
            table->count--;
            memmove(&table->keys[index], &table->keys[index + 1], sizeof(uint32_t) * (table->count - index));
            memmove(&table->values[index], &table->values[index + 1], sizeof(Packet*) * (table->count - index));
            return 0;
        }
    }

    return -1;
}

// Remove a packet from the hashtable by destination IP address
int removePacketByDstIP(HashTable* table, uint32_t dstIP) {
    if (!table || table->count == 0) return -1;

    // Calculate hash value for destination IP address
    uint32_t hash = hashIP(dstIP);

    // Search the hashtable for a matching packet and remove it if found
    size_t index;
    for (index = 0; index < table->count; index++) {
        if (table->values[index]->dstIP == dstIP) {
            free(table->values[index]);
            table->count--;
            memmove(&table->keys[index], &table->keys[index + 1], sizeof(uint32_t) * (table->count - index));
            memmove(&table->values[index], &table->values[index + 1], sizeof(Packet*) * (table->count - index));
            return 0;
        }
    }

    return -1;
}

// Free the memory allocated to a hashtable
void freeHashTable(HashTable* table) {
    size_t index;
    for (index = 0; index < table->count; index++) {
        free(table->values[index]);
    }
    free(table->keys);
    free(table->values);
    free(table);
}
