// Function to create a new list with the specified capacity
NFAPITagsList* nfapiTagsListCreate(int capacity) {
    if (capacity <= 0) {
        return NULL;
    }

    NFAPITagsList* list = malloc(sizeof(NFAPITagsList));
    if (!list) {
        return NULL;
    }

    list->count = 0;
    list->capacity = capacity;
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * capacity);
    if (!list->elements) {
        free(list);
        return NULL;
    }

    return list;
}

// Function to add a new element to the list, validating that all RX_UE_INFORMATION_TAG fields are properly initialized before adding it
int nfapiTagsListAdd(NFAPITagsList* list, NFAPI_CRC_INDICATION_PDU_T* element) {
