        return -1;
    }

    // Validate that the RX_UE_INFORMATION_TAG fields are properly initialized before adding the element to the list
    if (element->RX_UE_INFORMATION.RNTI == 0 || element->RX_UE_INFORMATION.CRC_INDICATION_REL8_TAG == NULL) {
        return -1;
    }

    // Check if the list is full, and if so, double its capacity to accommodate more elements
    if (list->count >= list->capacity) {
        int newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** newElements = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * newCapacity);
        if (!newElements) {
            return -1;
        }
        list->capacity = newCapacity;
        list->elements = newElements;
    }

    // Add the element to the end of the list
    list->elements[list->count++] = element;

    return 0;
}

// Function to retrieve a copy of the list elements, thread-safe to allow concurrent access by multiple threads
NFAPI_CRC_INDICATION_PDU_T** nfapiTagsListGet(NFAPITagsList* list) {
    if (!list) {
        return NULL;
    }

    // Lock the list to prevent concurrent modification while copying the elements
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T** copy = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * list->count);
    if (!copy) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    memcpy(copy, list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * list->count);
    pthread_mutex_unlock(&list->mutex);

    return copy;
}

// Function to destroy the list and free its memory
void nfapiTagsListDestroy(NFAPITagsList* list) {
    if (!list) {
        return;
    }

    // Lock the list to prevent concurrent modification while destroying it
    pthread_mutex_lock(&list->mutex);
    free(list->elements);
    free(list);
    pthread_mutex_unlock(&list->mutex);
}
