// Structure to store a network interface configuration
typedef struct {
    char id[16]; // Unique identifier for the interface (e.g., eth0)
    int supported_protocols; // Bitmask of supported protocols (e.g., IPv4, IPv6, Ethernet, etc.)
    int default_mode; // Default configuration mode (e.g., DHCP, static, etc.)
} config_t;

// Global array to store all network interface configurations
config_t *configs = NULL;
size_t num_configs = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for synchronizing access to configs

// Add a new configuration to the array
int add_config(const char *id, int supported_protocols, int default_mode) {
    pthread_mutex_lock(&mutex);

    // Check if the identifier is already in use
    for (size_t i = 0; i < num_configs; i++) {
        if (!strcmp(configs[i].id, id)) {
            printf("Identifier %s is already in use.\n", id);
            pthread_mutex_unlock(&mutex);
            return -1; // Error: Identifier already in use
        }
    }

    // Allocate memory for the new configuration
    config_t *new_config = malloc(sizeof(config_t));
    if (!new_config) {
        printf("Out of memory!\n");
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Out of memory
    }

    // Initialize the new configuration
    strcpy(new_config->id, id);
    new_config->supported_protocols = supported_protocols;
    new_config->default_mode = default_mode;

    // Add the new configuration to the array
    configs = realloc(configs, (num_configs + 1) * sizeof(config_t));
    if (!configs) {
        printf("Out of memory!\n");
        free(new_config);
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Out of memory
    }
    configs[num_configs++] = *new_config;

    // Log the new configuration (optional)
    // log_configuration(new_config);

    pthread_mutex_unlock(&mutex);
    return 0; // Success: Configuration added successfully
}

// Update an existing configuration in the array
int update_config(const char *id, int supported_protocols, int default_mode) {
    pthread_mutex_lock(&mutex);

    // Find the configuration with the given identifier
    for (size_t i = 0; i < num_configs; i++) {
        if (!strcmp(configs[i].id, id)) {
            configs[i].supported_protocols = supported_protocols;
            configs[i].default_mode = default_mode;
            break; // Found the configuration
        }
    }

    // Log the updated configuration (optional)
    // log_configuration(configs[i]);

    pthread_mutex_unlock(&mutex);
    return 0; // Success: Configuration updated successfully
}

// Retrieve a configuration from the array by identifier
int get_config(const char *id, config_t **config) {
    pthread_mutex_lock(&mutex);

    // Find the configuration with the given identifier
    for (size_t i = 0; i < num_configs; i++) {
        if (!strcmp(configs[i].id, id)) {
            *config = &configs[i];
            break; // Found the configuration
        }
    }

    pthread_mutex_unlock(&mutex);
    return (*config) ? 0 : -1; // Success: Configuration retrieved successfully (or not found, indicated by NULL pointer)
}

// Free memory allocated for a configuration
void free_config(config_t *config) {
    free(config);
}
