// Function to initialize and populate a list of LTE UE measurement reports
void init_and_populate_reports(struct MeasurementReport *reports, int num_reports, char *data_source) {
    // Initialize the report structure
    struct MeasurementReport *report = (struct MeasurementReport *)malloc(sizeof(struct MeasurementReport));
    if (!report) {
        printf("Error: Out of memory\n");
        return;
    }

    int i, j;
    for (i = 0; i < num_reports; i++) {
        report->measurement_id = i + 1; // Set measurement ID

        // Get reported cell measurements from external data source
        char *cell_data = read_cell_data(report->measurement_id, data_source);
        if (!cell_data) {
            printf("Error: Failed to retrieve cell data for report %d\n", report->measurement_id);
            continue; // Skip this report
        }

        // Parse the reported cell measurements from the data source
        int num_cells = parse_cell_data(cell_data, report->cell_measurements);
        if (num_cells < 0) {
            printf("Error: Failed to parse cell data for report %d\n", report->measurement_id);
            continue; // Skip this report
        }

        // Set the network mode indicator based on the number of reported cells
        if (num_cells > 0) {
            report->network_mode = 'a'; // Assume network mode A for now
        } else {
            report->network_mode = 'b'; // Assume network mode B for now
        }
    }

    // Free the memory allocated for the report structure
    free(report);
}

// Read cell data from an external data source (e.g., a file or database)
char *read_cell_data(int measurement_id, char *data_source) {
    // Simulate reading cell data from a file
    if (!strcmp(data_source, "file")) {
        return read_cell_data_from_file(measurement_id);
    } else if (!strcmp(data_source, "database")) {
        return read_cell_data_from_database(measurement_id);
    }
    return NULL; // Return NULL if data source is not recognized
}

// Read cell data from a file
char *read_cell_data_from_file(int measurement_id) {
    char filename[256];
    snprintf(filename, 256, "measurements/%d.txt", measurement_id);
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error: Failed to open file %s\n", filename);
        return NULL;
    }

    char *cell_data = (char *)malloc(2048); // Allocate 2 KB of memory for cell data
    if (!cell_data) {
        printf("Error: Out of memory\n");
        fclose(file);
        return NULL;
    }

    size_t num_read = fread(cell_data, 1, 2048, file);
    if (num_read < 2048) {
        printf("Error: Failed to read cell data from file %s\n", filename);
        free(cell_data);
        fclose(file);
        return NULL;
    }

    // Close the file and return the cell data
    fclose(file);
    return cell_data;
}

// Read cell data from a database
char *read_cell_data_from_database(int measurement_id) {
    // Simulate reading cell data from a database using a hardcoded ID
    if (measurement_id == 1234) {
        char *cell_data = "10,11,12,13\n20,21,22,23";
        return cell_data; // Return the cell data as a string
    }
    return NULL; // Return NULL if no data found for the given measurement ID
}

// Parse the reported cell measurements from the cell data
int parse_cell_data(char *cell_data, struct CellMeasurements *cell_measurements) {
    char *token = strtok(cell_data, ","); // Tokenize the cell data using "," as a delimiter
    int i = 0;
    while (token != NULL && i < 16) { // Read up to 16 measurements per report
        cell_measurements[i].signal_strength = atof(token); // Convert token to float and store in the structure
        i++;
        token = strtok(NULL, ","); // Get the next token
    }
    return i; // Return the number of measurements read
}']

