#include <errno.h>

// Structure to hold the CRC indication information
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to read the list of integers from the shared data source
void *read_integers(void *args) {
    // Declare variables
    int *data, i;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    struct timespec timeout;

    // Get the shared data source and validation range from the arguments
    char **shared_data_source = (char **)args;
    int validation_range[2] = {-1000, 1000};

    // Allocate memory for the array of integers
    data = malloc(sizeof(int) * (*shared_data_source));
    if (!data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Initialize the mutex and condition variable
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Read the list of integers from the shared data source
    for (i = 0; i < *shared_data_source; ++i) {
        // Check if the integer is within the validation range
        int integer = atoi(shared_data_source[i]);
        if (integer >= validation_range[0] && integer <= validation_range[1]) {
            data[i] = integer;
        } else {
            fprintf(stderr, "Invalid integer: %d\n", integer);
            // If an invalid integer is encountered, free the allocated memory and exit
            free(data);
            pthread_mutex_destroy(&mutex);
            pthread_cond_destroy(&cond);
            exit(EXIT_FAILURE);
        }
    }

    // Signal to the main thread that the data has been read successfully
    pthread_mutex_lock(&mutex);
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);

    // Wait for the main thread to signal to proceed
    pthread_mutex_lock(&mutex);
    while (pthread_cond_wait(&cond, &mutex)) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted\n");
            // If an interruption occurs, free the allocated memory and exit
            free(data);
            pthread_mutex_destroy(&mutex);
            pthread_cond_destroy(&cond);
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&mutex);

    // Return the array of integers to the main thread
    return data;
}

// Function to find and print the largest integer in the array
void *find_largest(void *args) {
    // Declare variables
    int *data = (int *)args, i, largest = INT_MIN;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Iterate through the array of integers and find the largest one
    for (i = 0; i < sizeof(data) / sizeof(*data); ++i) {
        if (data[i] > largest) {
            largest = data[i];
        }
    }

    // Print the largest integer to the console
    printf("Largest integer: %d\n", largest);

    // Signal to the main thread that the comparison has been completed successfully
    pthread_mutex_lock(&mutex);
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);

    // Wait for the main thread to signal to proceed
    pthread_mutex_lock(&mutex);
    while (pthread_cond_wait(&cond, &mutex)) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted\n");
            // If an interruption occurs, free the allocated memory and exit
            free(data);
            pthread_mutex_destroy(&mutex);
            pthread_cond_destroy(&cond);
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&mutex);
