// Define function for removing a specific session information
void removeSession(int index) {
    // Check if the specified index is valid
    if (index < 0 || index >= num_sessions) {
        return;
    }

    // Lock the sessions mutex to prevent race conditions
    pthread_mutex_lock(&sessions_mutex);

    // Remove the session information from the list of sessions
    NFAPI_CRC_INDICATION_PDU_T *removed_session = sessions[index];
    for (int i = index; i < num_sessions - 1; i++) {
        sessions[i] = sessions[i + 1];
