        if (buffer_capacity < MAX_BUFFER_CAPACITY) {
            buffer = realloc(buffer, 2 * buffer_capacity);
            buffer_capacity *= 2;
        } else {
            // If the buffer is already at maximum capacity, discard the oldest data
            memmove(buffer, buffer + buffer_size / 4, buffer_size - buffer_size / 4);
            buffer_size -= buffer_size / 4;
