// Define structure for network management events
typedef struct {
    uint8_t eventType;
    time_t timestamp;
    union {
        char* configUpdate;
        char* statusReport;
    } payload;
} Event;

// Function to initialize and populate an array of structures representing network management events
int initAndPopulateEvents(Event** events, size_t maxSize) {
    // Allocate memory for the array of events
    *events = (Event*) malloc(sizeof(Event) * maxSize);
    if (*events == NULL) {
        return -1;
    }

    // Initialize each event structure with a payload type and size
    for (size_t i = 0; i < maxSize; ++i) {
        Event* event = &(*events)[i];
        event->eventType = EVENT_TYPE_UNKNOWN;
        event->timestamp = 0;
        event->payload.configUpdate = NULL;
        event->payload.statusReport = NULL;
    }

    return 0;
}

// Function to add a new event to the array of structures representing network management events
int addEvent(Event** events, size_t maxSize, uint8_t eventType, time_t timestamp, char* payload) {
    // Check if there is enough memory available for the new event
    if (*events == NULL || *events + (sizeof(Event) * (maxSize - 1)) > (Event*) malloc(sizeof(Event) * maxSize)) {
        return -1;
    }

    // Allocate memory for the payload of the new event
    size_t payloadSize = strlen(payload) + 1;
    char* payloadMemory = (char*) malloc(payloadSize);
    if (payloadMemory == NULL) {
        return -1;
    }

    // Copy the payload into the allocated memory
    memcpy(payloadMemory, payload, payloadSize);

    // Add the new event to the array of events
    Event* newEvent = &(*events)[maxSize - 1];
    newEvent->eventType = eventType;
    newEvent->timestamp = timestamp;
    newEvent->payload.configUpdate = payloadMemory;

    return 0;
}

// Function to deallocate memory for the array of structures representing network management events
void freeEvents(Event** events) {
    // Deallocate each event structure
    for (size_t i = 0; i < maxSize; ++i) {
        Event* event = &(*events)[i];
        if (event->payload.configUpdate != NULL) {
            free(event->payload.configUpdate);
        }
        if (event->payload.statusReport != NULL) {
            free(event->payload.statusReport);
        }
    }

    // Deallocate the memory for the array of events
    free(*events);
}
