#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include "nfapi_types.h"

/* Command-line argument for predefined threshold for memory fragmentation compaction */
#define MEMORY_FRAGMENTATION_THRESHOLD 50

/* Structure to hold allocated CRC indications */
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t size;
} crc_indication_alloc_t;

void allocate_crc_indications(int n, int seed) {
    /* Check for negative input values */
    if (n < 0) {
        fprintf(stderr, "Error: Invalid input value for 'N' - %d\n", n);
        return;
    }

    /* Allocate memory for the array of CRC indications */
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Error: Memory allocation failed for CRC indications\n");
        return;
    }

    /* Initialize the random number generator */
    srand(seed);

    /* Allocate memory for each structure and initialize its fields */
    crc_indication_alloc_t *allocs = malloc(n * sizeof(crc_indication_alloc_t));
    if (!allocs) {
        fprintf(stderr, "Error: Memory allocation failed for CRC indications\n");
        free(pdu);
        return;
    }
    for (int i = 0; i < n; i++) {
        allocs[i].pdu = &pdu[i];
        allocs[i].size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pdu[i].rx_ue_information_tag = rand() % 256;
        pdu[i].rnti = rand() % 65536;
        pdu[i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }

    /* Compact the allocated memory pool periodically if fragmentation exceeds threshold */
    size_t memory_fragmentation = 0;
    for (int i = 0; i < n; i++) {
        memory_fragmentation += allocs[i].size;
        if (memory_fragmentation > MEMORY_FRAGMENTATION_THRESHOLD) {
            compact_allocated_memory(allocs, n);
            memory_fragmentation = 0;
        }
    }

    /* Log the number of successful and failed allocations */
    log_allocation_results(n, seed);

    /* Return the allocated array of CRC indications */
    return pdu;
}

/* Compacts the allocated memory pool by releasing unused memory */
void compact_allocated_memory(crc_indication_alloc_t *allocs, int n) {
    /* Calculate the total size of the allocated memory */
    size_t total_size = 0;
    for (int i = 0; i < n; i++) {
        total_size += allocs[i].size;
    }

    /* Release unused memory and update the allocation table */
    size_t released_memory = 0;
    for (int i = 0; i < n; i++) {
        if (!allocs[i].pdu) {
