    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Iterate over all elements in the list until the RNTI value is found or the end of the list is reached
    size_t index = 0;
    while (index < list->size && list->pdu[index].rnti != rnti) {
        index++;
    }

    // Release the mutex and return the index of the found element or -1 if not found
    pthread_mutex_unlock(&list->mutex);
    return (index < list->size) ? index : -1;
}

// Iterate over all elements in the list
void nfapi_crc_indication_list_foreach(LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *pdu)) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Iterate over all elements in the list and call the callback function for each one
    size_t index = 0;
    while (index < list->size) {
        callback(list->pdu + index);
        index++;
    }

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Destroy the list and free its memory
void nfapi_crc_indication_list_destroy(LIST_T *list) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Free the list structure and all elements in it
    free(list->pdu);
    memset(list, 0, sizeof(*list));

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);
}
