    // Initialize the batch with random RNTI and RX_UE_INFORMATION_TAG values
    for (int i = 0; i < N; i++) {
        batch[i] = malloc(sizeof(nfapi_crc_indication_pdu_t));
        batch[i]->rnti = rand() % UINT16_MAX;
        batch[i]->rx_ue_information_tag = rand() % UINT8_MAX;
        batch[i]->crc_indication_rel8_tag = rand() % UINT8_MAX;
    }

    // Detect disjoint pairs within the batch
    int disjoint_pairs = 0;
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (batch[i]->rnti != batch[j]->rnti && batch[i]->rx_ue_information_tag != batch[j]->rx_ue_information_tag) {
                disjoint_pairs++;
            }
        }
    }

    // Log the number of disjoint pairs detected and the elapsed time for each check
    clock_t start = clock();
    int count = 0;
    while (count < N) {
        if (batch[count]->rnti != batch[N - 1 - count]->rnti || batch[count]->rx_ue_information_tag != batch[N - 1 - count]->rx_ue_information_tag) {
            disjoint_pairs++;
        }
        count++;
    }
    clock_t end = clock();
    float elapsed = (float)(end - start) / CLOCKS_PER_SEC;
    printf("Disjoint pairs detected: %d\n", disjoint_pairs);
    printf("Elapsed time: %.3f seconds\n", elapsed);

    // Return the number of disjoint pairs detected and the elapsed time for each check
    return disjoint_pairs;
}
