// Macros for network protocols and system calls
#define ETH_ALEN 6
#define IPPROTO_TCP 6
#define SOL_SOCKET 1
#define SO_REUSEADDR 2
#define AF_INET 2
#define AF_INET6 10
#define INADDR_ANY 0x00000000
#define INADDR_BROADCAST 0xffffffff

// Structures for network interface configuration and IPv4/IPv6 addresses
typedef struct {
    unsigned char mac[ETH_ALEN];
    int family;
    union {
        struct in_addr ipv4;
        struct in6_addr ipv6;
    };
    uint16_t port;
} nic_config;

// Function to validate MAC addresses and ensure they are unique across the array
int validate_mac(const unsigned char *mac, const size_t mac_len) {
    if (mac_len != ETH_ALEN) {
        return 0; // Invalid MAC length
    }
    for (size_t i = 0; i < ETH_ALEN; ++i) {
        if (!isxdigit(mac[i])) {
            return 0; // Non-hexadecimal character in MAC address
        }
    }
    return 1; // Valid MAC address
}

// Function to initialize and populate an array of NIC settings structures
int init_nic_configs(nic_config *nic_conf, size_t nic_count) {
    if (!nic_conf || !nic_count) {
        return 0; // Invalid input parameters
    }
    for (size_t i = 0; i < nic_count; ++i) {
        // Generate random MAC addresses and IPv4/IPv6 addresses
        unsigned char mac[ETH_ALEN];
        inet_pton(AF_INET, "192.168.0.1", &nic_conf[i].ipv4);
        inet_pton(AF_INET6, "fe80::1", &nic_conf[i].ipv6);
        memcpy(mac, nic_conf[i].mac, ETH_ALEN);

        // Validate MAC addresses and ensure they are unique across the array
        if (!validate_mac(mac, ETH_ALEN)) {
            return 0; // Invalid MAC address
        }
        for (size_t j = 0; j < i; ++j) {
            if (memcmp(nic_conf[i].mac, nic_conf[j].mac, ETH_ALEN) == 0) {
                return 0; // Duplicate MAC address
            }
        }

        // Validate IPv4/IPv6 addresses and ensure they are within a valid range
        if (!inet_pton(AF_INET, "192.168.0.1", &nic_conf[i].ipv4)) {
            return 0; // Invalid IPv4 address
        }
        if (!inet_pton(AF_INET6, "fe80::1", &nic_conf[i].ipv6)) {
            return 0; // Invalid IPv6 address
        }

        // Validate port mappings and ensure they do not conflict with existing system ports
        if (nic_conf[i].port < 1 || nic_conf[i].port > 65535) {
            return 0; // Invalid port number
        }
        for (size_t j = 0; j < i; ++j) {
            if (nic_conf[i].port == nic_conf[j].port) {
                return 0; // Port mapping conflict
            }
        }
    }
    return 1; // Valid NIC configuration
}
```
