// Structures
struct NFAPI_UL_TRACE_RECORD_T {
  uint32_t trace_tag;
  void* uplink_data;
};

// Global variables
size_t max_memory_usage = 1024 * 1024 * 1024; // 1GB
size_t current_memory_usage = 0;
bool memory_exhausted = false;

// Function to initialize and populate an array of NFAPI_UL_TRACE_RECORD_T structures
void init_ul_trace_records(struct NFAPI_UL_TRACE_RECORD_T* ul_trace_records, size_t num_records) {
  // Initialize the array of UL trace records
  for (size_t i = 0; i < num_records; i++) {
    ul_trace_records[i].trace_tag = 0;
    ul_trace_records[i].uplink_data = NULL;
  }

  // Allocate memory for each uplink data sequence dynamically
  size_t current_sequence_size = 0;
  for (size_t i = 0; i < num_records; i++) {
    // Randomly generate the length of the next uplink data sequence
    current_sequence_size = rand() % 1024 + 1; // random value between 1 and 1024

    // Check if memory allocation would exceed the maximum usage limit
    size_t new_memory_usage = current_memory_usage + current_sequence_size;
    if (new_memory_usage > max_memory_usage) {
      printf("Memory exhausted! Cannot allocate %d bytes of uplink data for record %lu.\n", current_sequence_size, i);
      memory_exhausted = true;
      break;
    } else {
      // Allocate memory for the uplink data sequence
      ul_trace_records[i].uplink_data = malloc(current_sequence_size);
      if (ul_trace_records[i].uplink_data == NULL) {
        printf("Error allocating memory for uplink data in record %lu!\n", i);
        break;
      }

      // Initialize the allocated memory
      memset(ul_trace_records[i].uplink_data, 0, current_sequence_size);

      // Update the memory usage counter
      current_memory_usage = new_memory_usage;
    }
  }
}

// Function to free an array of NFAPI_UL_TRACE_RECORD_T structures
void free_ul_trace_records(struct NFAPI_UL_TRACE_RECORD_T* ul_trace_records, size_t num_records) {
  // Free memory for each uplink data sequence
  for (size_t i = 0; i < num_records; i++) {
    if (ul_trace_records[i].uplink_data != NULL) {
      free(ul_trace_records[i].uplink_data);
      ul_trace_records[i].uplink_data = NULL;
    }
  }
}

// Function to update the UL trace records with new data
void update_ul_trace_records(struct NFAPI_UL_TRACE_RECORD_T* ul_trace_records, size_t num_records) {
  // Update each UL trace record with new data
  for (size_t i = 0; i < num_records; i++) {
    if (ul_trace_records[i].uplink_data != NULL) {
      // Randomly generate the length of the next uplink data sequence
      size_t current_sequence_size = rand() % 1024 + 1; // random value between 1 and 1024

      // Check if memory allocation would exceed the maximum usage limit
      size_t new_memory_usage = current_memory_usage + current_sequence_size;
      if (new_memory_usage > max_memory_usage) {
        printf("Memory exhausted! Cannot allocate %d bytes of uplink data for record %lu.\n", current_sequence_size, i);
        memory_exhausted = true;
        break;
      } else {
        // Reallocate memory for the uplink data sequence
        ul_trace_records[i].uplink_data = realloc(ul_trace_records[i].uplink_data, current_sequence_size);
        if (ul_trace_records[i].uplink_data == NULL) {
          printf("Error reallocating memory for uplink data in record %lu!\n", i);
          break;
        }

        // Initialize the allocated memory
        memset(ul_trace_records[i].uplink_data, 0, current_sequence_size);

        // Update the memory usage counter
        current_memory_usage = new_memory_usage;
      }
    }
  }
}

// Function to log the number of records created and any memory usage issues encountered during the process
void log_ul_trace_records(struct NFAPI_UL_TRACE_RECORD_T* ul_trace_records, size_t num_records) {
  // Log the number of records created
  printf("Created %lu UL trace records.\n", num_records);

  // Log any memory usage issues encountered during the process
  if (memory_exhausted) {
    printf("Memory exhausted! Not all UL trace records could be initialized.\n");
  } else {
    printf("Successfully initialized all %lu UL trace records.\n", num_records);
  }
}
```
