void init_gtp_tunnel(GTP_C_Tunnel_T *tunnel) {
  // Populate GTP-C header fields
  tunnel->header.version = 0x01;
  tunnel->header.ptype = 0xff;
  tunnel->header.seq = 0;

  // Generate unique TEID and GTP Command for each tunnel
  tunnel->teid = generate_unique_teid();
  tunnel->command = generate_gtp_c_command(tunnel->teid);

  // Initialize UE association structure
  init_ue_association(&tunnel->ue_assoc);

  // Dynamically allocate memory for GTP-C tunnel parameters
  tunnel->params.mtu = DEFAULT_GTP_MTU;
  tunnel->params.ipv4_src = INADDR_ANY;
  tunnel->params.ipv4_dst = INADDR_ANY;
}

// Generate unique TEID for each GTP-C tunnel
uint32_t generate_unique_teid() {
  static uint32_t teid = 0;
  return ++teid;
}

// Generate GTP-C command for each tunnel based on its TEID
uint8_t generate_gtp_c_command(uint32_t teid) {
  switch (teid % 4) {
    case 0: return GTP_CREATE;
    case 1: return GTP_MODIFY;
    case 2: return GTP_DELETE;
    default: return GTP_RESERVED;
  }
}

// Initialize UE association structure for each tunnel
void init_ue_association(GTP_C_UE_Association *assoc) {
  // Set initial values for fields in UE association structure
  assoc->seq = 0;
  assoc->timeout = DEFAULT_GTP_TIMEOUT;
  assoc->ipv4_src = INADDR_ANY;
  assoc->ipv4_dst = INADDR_ANY;
}
