 * Each structure contains a valid NAS_MESSAGE_TYPE and NAS_MESSAGE, where the NAS_MESSAGE includes a dynamically generated EPS Attach Accept message.
 * The function must also ensure that the EPS_ATTACH_ACCEPT message contains a valid EPS Attach Identifier and EPS Attach Type.
 */
void init_nas_pdu_array(LTE_NAS_PDU_T* nas_pdu, int num_elements) {
    // Initialize the NAS message type
    for (int i = 0; i < num_elements; i++) {
        nas_pdu[i].nas_message_type = LTE_NAS_MESSAGE_TYPE_EPS_ATTACH_ACCEPT;
    }

    // Populate the NAS message with an EPS Attach Accept message
    for (int i = 0; i < num_elements; i++) {
        EPS_Attach_Accept* attach_accept = malloc(sizeof(EPS_Attach_Accept));
        if (!attach_accept) {
            printf("Failed to allocate memory for EPS Attach Accept message\n");
            return;
        }

        // Initialize the EPS attach identifier and type
        int eps_attach_identifier = i + 1;
        EPS_Attach_Type eps_attach_type = EPS_ATTACH_TYPE_EPS_IMSI;

        // Fill in the EPS Attach Accept message
        fill_eps_attach_accept(attach_accept, eps_attach_identifier, eps_attach_type);

        // Set the NAS message to the EPS Attach Accept message
        nas_pdu[i].nas_message = attach_accept;
    }
}

/**
 * Fills in an EPS Attach Accept message with valid values.
 */
void fill_eps_attach_accept(EPS_Attach_Accept* attach_accept, int eps_attach_identifier, EPS_Attach_Type eps_attach_type) {
    // Initialize the header of the EPS Attach Accept message
    attach_accept->header.extended_protocol_discriminator = 0x01;
    attach_accept->header.spare_half_octet = 0x00;
    attach_accept->header.message_type = 0x2D;
    attach_accept->header.payload_length = 0x12;

    // Initialize the identity response information element
    attach_accept->identity_response_information.extended_protocol_discriminator = 0x01;
    attach_accept->identity_response_information.spare_half_octet = 0x00;
    attach_accept->identity_response_information.message_type = 0x75;
    attach_accept->identity_response_information.payload_length = 0x10;

    // Initialize the EPS attach identifier element
    attach_accept->eps_attach_identifier = eps_attach_identifier;

    // Initialize the EPS attach type element
    attach_accept->eps_attach_type = eps_attach_type;
}

/**
 * Releases the memory allocated for an EPS Attach Accept message.
 */
void release_eps_attach_accept(EPS_Attach_Accept* attach_accept) {
    if (attach_accept) {
        free(attach_accept);
    }
}

/**
 * Releases the memory allocated for an array of LTE_NAS_PDU_T structures.
 */
void release_nas_pdu_array(LTE_NAS_PDU_T* nas_pdu, int num_elements) {
    // Release the EPS Attach Accept messages
    for (int i = 0; i < num_elements; i++) {
        if (nas_pdu[i].nas_message) {
            release_eps_attach_accept(nas_pdu[i].nas_message);
        }
    }

    // Release the array of LTE_NAS_PDU_T structures
    free(nas_pdu);
}']

