// Define the struct for LTE_PHY_RX_FRAME_INFO_T
typedef struct {
    LTE_PHY_RX_CHANNEL_INFO_T channelInfo;
    LTE_PHY_RX_SAMPLE_T *samples;
} LTE_PHY_RX_FRAME_INFO_T;

// Define the struct for LTE_PHY_RX_CHANNEL_INFO_T
typedef struct {
    int channelNumber;
    float signalStrength;
} LTE_PHY_RX_CHANNEL_INFO_T;

// Define the struct for LTE_PHY_RX_SAMPLE_T
