    float sampleValue;
    int sampleNumber;
} LTE_PHY_RX_SAMPLE_T;

// Function to initialize and populate a list of LTE_PHY_RX_FRAME_INFO_T structures
LTE_PHY_RX_FRAME_INFO_T* initAndPopulateLtePhyRxFrames(int frameCount, int channelCount, float signalStrengthThreshold) {
    // Allocate memory for the list of LTE_PHY_RX_FRAME_INFO_T structures
    LTE_PHY_RX_FRAME_INFO_T *frames = (LTE_PHY_RX_FRAME_INFO_T*) malloc(frameCount * sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (frames == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for LTE_PHY_RX_FRAME_INFO_T structures\n");
        return NULL;
    }

    // Initialize each structure in the list with a valid channel info and corresponding sample array
    int frameIndex = 0;
    for (int i = 0; i < frameCount; i++) {
        LTE_PHY_RX_FRAME_INFO_T *frame = &frames[i];
        frame->channelInfo.channelNumber = i;
        frame->samples = (LTE_PHY_RX_SAMPLE_T*) malloc(channelCount * sizeof(LTE_PHY_RX_SAMPLE_T));
        if (frame->samples == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for sample array in LTE_PHY_RX_FRAME_INFO_T structure\n");
            return NULL;
        }
        for (int j = 0; j < channelCount; j++) {
            frame->samples[j].sampleValue = rand() % 100;
            frame->samples[j].sampleNumber = j;
        }
        if (frameIndex == 0 || frame->channelInfo.signalStrength > signalStrengthThreshold) {
            frameIndex++;
        } else {
            free(frame->samples);
            frame->samples = NULL;
        }
    }

    // Filter frames based on signal quality metrics stored within the LTE_PHY_RX_FRAME_INFO_T structure
    for (int i = 0; i < frameCount; i++) {
        LTE_PHY_RX_FRAME_INFO_T *frame = &frames[i];
        if (frame->channelInfo.signalStrength > signalStrengthThreshold) {
            // Calculate the RMS of all samples in the frame
            float rms = 0;
            for (int j = 0; j < channelCount; j++) {
                rms += pow(frame->samples[j].sampleValue, 2);
            }
            rms /= channelCount;
            // If the RMS is less than a certain threshold, discard the frame
            if (rms > 10) {
                free(frame->samples);
                frame->samples = NULL;
            }
        }
    }

    return frames;
}
