    int capacity; // maximum capacity of the hash table
    int *keys; // array of keys (RNTIs) in the hash table
    struct node **nodes; // array of nodes (UEContextInfo structures) in the hash table
};

// Node structure for the hash table
struct node {
    UEContextInfo info; // UEContextInfo structure
    int next; // index of the next node in the same chain
};

// Function to create a new hash table with an initial capacity
struct hash_table* create_hash_table(int initial_capacity) {
    struct hash_table *ht = malloc(sizeof(struct hash_table));
    ht->size = 0;
    ht->capacity = initial_capacity;
    ht->keys = calloc(initial_capacity, sizeof(int));
    ht->nodes = calloc(initial_capacity, sizeof(struct node*));
    return ht;
}

// Function to add a new UEContextInfo structure to the hash table
void add_ue_context_info(struct hash_table *ht, int RNTI, int RxUEInformationTag, int CRCIndicationRel8Tag) {
    // Check if the RNTI already exists in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == RNTI) {
            return; // Do nothing if the RNTI already exists
        }
    }

    // If the RNTI does not exist, add a new node to the hash table
    ht->keys[ht->size] = RNTI;
    struct node *new_node = malloc(sizeof(struct node));
    new_node->info.RNTI = RNTI;
    new_node->info.RxUEInformationTag = RxUEInformationTag;
    new_node->info.CRCIndicationRel8Tag = CRCIndicationRel8Tag;
    ht->nodes[ht->size] = new_node;
    ht->size++;
}

// Function to update an existing UEContextInfo structure in the hash table
void update_ue_context_info(struct hash_table *ht, int RNTI, int RxUEInformationTag, int CRCIndicationRel8Tag) {
    // Check if the RNTI exists in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == RNTI) {
            ht->nodes[i]->info.RxUEInformationTag = RxUEInformationTag;
            ht->nodes[i]->info.CRCIndicationRel8Tag = CRCIndicationRel8Tag;
            return; // Update the existing node if it exists
        }
    }
}

// Function to retrieve an UEContextInfo structure from the hash table by RNTI
struct node* get_ue_context_info(struct hash_table *ht, int RNTI) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == RNTI) {
            return ht->nodes[i]; // Return the existing node if it exists
        }
    }
    return NULL; // Return NULL if the RNTI does not exist in the hash table
}

// Function to remove an UEContextInfo structure from the hash table by RNTI
void remove_ue_context_info(struct hash_table *ht, int RNTI) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == RNTI) {
            free(ht->nodes[i]); // Free the memory of the existing node
            ht->nodes[i] = NULL;
            ht->size--; // Decrease the size of the hash table by 1
            return; // Stop the loop if a match is found
        }
    }
}

// Function to resize the hash table when it reaches a certain threshold
void resize_hash_table(struct hash_table *ht) {
    int new_capacity = ht->capacity * 2; // Double the capacity of the hash table
    struct hash_table *new_ht = create_hash_table(new_capacity); // Create a new hash table with the new capacity
    for (int i = 0; i < ht->size; i++) {
