        size_t new_capacity = array->capacity + (array->capacity >> 1);
        lte_ue_context_t *new_contexts = realloc(array->contexts, sizeof(lte_ue_context_t) * new_capacity);
        if (!new_contexts) {
            // Handle allocation failure gracefully
        }
        array->contexts = new_contexts;
        array->capacity = new_capacity;
    }
    // Add the new context to the end of the array
    array->contexts[array->count].tci = tci;
    array->contexts[array->count].mac_pdu = mac_pdu;
    ++array->count;
}

// Update an existing LTE UE context in the dynamic array, if it exists
static bool update_lte_ue_context(lte_ue_context_array_t *array, uint32_t tci, void *mac_pdu) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i].tci == tci) {
            // Update the existing context with the new MAC PDU and Transport Channel Identifier (TCI)
            array->contexts[i].mac_pdu = mac_pdu;
            return true;
        }
    }
    // The TCI was not found in the array, add a new context instead
    add_lte_ue_context(array, tci, mac_pdu);
    return false;
}

// Retrieve an LTE UE context from the dynamic array by Transport Channel Identifier (TCI)
static lte_ue_context_t *get_lte_ue_context(lte_ue_context_array_t *array, uint32_t tci) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i].tci == tci) {
            return &array->contexts[i];
        }
    }
    return NULL;
}

// Free the memory allocated for the dynamic array of LTE UE contexts
static void free_lte_ue_context_array(lte_ue_context_array_t *array) {
    if (!array) return;
    free(array->contexts);
}

// Function to handle incoming LTE UE contexts and update/add them to the dynamic array
static void handle_incoming_lte_ue_contexts(lte_ue_context_array_t *array, void **mac_pdus, size_t num_pdus) {
    if (!array || !mac_pdus || num_pdus == 0) return;
    // Iterate over the incoming MAC PDUs and update/add them to the dynamic array
    for (size_t i = 0; i < num_pdus; ++i) {
        uint32_t tci = get_mac_pdu_tci(mac_pdus[i]); // Get the Transport Channel Identifier (TCI) from the MAC PDU
        void *mac_pdu = mac_pdus[i]; // Store a pointer to the MAC PDU for later use
        if (update_lte_ue_context(array, tci, mac_pdu)) {
            // The context was updated successfully
        } else {
            // Add the new context to the array
            add_lte_ue_context(array, tci, mac_pdu);
        }
    }
}
