};

// Define data structure for the dynamic array of contexts
struct context_array {
    size_t capacity;
    size_t size;
    struct context *data;
    pthread_mutex_t lock;
};

// Define functions for managing the dynamic array of contexts
void init_context_array(struct context_array *arr) {
    arr->capacity = 1024;
    arr->size = 0;
    arr->data = malloc(sizeof(struct context *) * arr->capacity);
    pthread_mutex_init(&arr->lock, NULL);
}

void destroy_context_array(struct context_array *arr) {
    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->data[i]);
    }
    pthread_mutex_destroy(&arr->lock);
}

void add_context(struct context_array *arr, struct context *ctx) {
    // Check if the array is full and needs to be resized
    if (arr->size == arr->capacity) {
        // Resize the array by 2 times its current capacity
        arr->capacity *= 2;
        arr->data = realloc(arr->data, sizeof(struct context *) * arr->capacity);
    }

    // Add the new context to the end of the array
    arr->data[arr->size++] = ctx;
}

void remove_context(struct context_array *arr, struct context *ctx) {
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i] == ctx) {
            // Remove the matching context from the array
            memmove(&arr->data[i], &arr->data[i + 1], sizeof(struct context *) * (arr->size - i));
            --arr->size;
        }
    }
}

void update_context(struct context_array *arr, struct context *ctx) {
    // Check if the array is full and needs to be resized
    if (arr->size == arr->capacity) {
        // Resize the array by 2 times its current capacity
        arr->capacity *= 2;
        arr->data = realloc(arr->data, sizeof(struct context *) * arr->capacity);
    }

    // Update the existing context in the array
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i] == ctx) {
            arr->data[i] = ctx;
            return;
        }
    }

    // Add the new context to the end of the array
    arr->data[arr->size++] = ctx;
}

struct context *get_context(struct context_array *arr, unsigned int tci) {
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i]->tci == tci) {
            return arr->data[i];
        }
    }

    // Return NULL if the context is not found
    return NULL;
}

struct context *get_context_qos(struct context_array *arr, unsigned int qos_class) {
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i]->qos_class == qos_class) {
            return arr->data[i];
        }
    }

    // Return NULL if the context is not found
    return NULL;
}

// Define functions for managing timeouts and expired contexts
void handle_timeout(struct context_array *arr, struct timeout *t) {
    // Check if the context has expired based on its timeout period
    if (t->ctx->valid && t->timeout <= 0) {
        remove_context(arr, t->ctx);
        free(t->ctx);
    }
}

void handle_expiration(struct context_array *arr) {
    // Check all the contexts in the array for expired timeout periods
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i]->valid && arr->data[i]->timeout <= 0) {
            remove_context(arr, arr->data[i]);
            free(arr->data[i]);
        }
    }
}
