// Define a struct to represent an NFAPI CRC indication PDU with a valid RX UE information tag and CRC indication status
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a function to dynamically allocate an array of NFAPI CRC indication PDUs with unique RNTIs and validate the data
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu_array(size_t n) {
    // Validate the input parameter
    if (n == 0) {
        return NULL;
    }

    // Allocate memory for the array of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (pdu_array == NULL) {
        return NULL;
    }

    // Initialize each structure with a unique RNTI value and set the CRCFLAG based on the CRC indication status
    for (size_t i = 0; i < n; ++i) {
        pdu_array[i].rx_ue_information_tag = 1; // Use a fixed value for the RX UE information tag
        pdu_array[i].rnti = i + 1; // Generate a unique RNTI value starting from 1
        pdu_array[i].crc_indication_rel8_tag = 0; // Set the CRCFLAG to 0 for all PDUs
    }

    // Validate that all RNTIs are within a specified valid range and no duplicates exist in the array
    uint32_t rnti_range_start = 1; // Start the RNTI range from 1
    uint32_t rnti_range_end = n + 1; // End the RNTI range at the number of PDUs plus 1
    for (size_t i = 0; i < n; ++i) {
        if (pdu_array[i].rnti < rnti_range_start || pdu_array[i].rnti >= rnti_range_end) {
            free(pdu_array); // Free the allocated memory if an RNTI value is out of range
            return NULL;
        }
    }
    for (size_t i = 0; i < n - 1; ++i) {
        for (size_t j = i + 1; j < n; ++j) {
            if (pdu_array[i].rnti == pdu_array[j].rnti) { // Check for duplicate RNTIs
                free(pdu_array); // Free the allocated memory if a duplicate RNTI is found
                return NULL;
            }
        }
    }

    return pdu_array; // Return the initialized array of CRC indication PDUs
}
