// Function to modify the filename extension
void modify_filename(char* filename, char* new_extension) {
    int file_length = strlen(filename);
    char* dot_position = strrchr(filename, '.');
    if (dot_position != NULL) {
        *dot_position = '\0';
    } else {
        filename[file_length] = '\0';
    }
    strcat(filename, new_extension);
}

// Function to handle concurrent file operations in a thread-safe manner
void safe_fopen(char* filename, char* mode) {
    int fd;
    do {
        fd = open(filename, O_CREAT | O_TRUNC | O_WRONLY, 0644);
        if (fd < 0) {
            sleep(1);
        }
    } while (fd < 0);
}

// Function to log detailed information about file operations
void log_file_operation(char* filename, int status, char* new_filename) {
    FILE* log_file = fopen(LOGGING_FILENAME, "a");
    if (log_file == NULL) {
        perror("Failed to open logging file");
        return;
