void flush_crc_indication_list(NFAPI_CRC_INDICATION_PDU_LIST_T *list) {
    // Start at the head of the list and iterate through each structure until the tail is reached
    NFAPI_CRC_INDICATION_PDU_T *pdu = list->head;
    while (pdu != NULL && pdu != list->tail) {
        // Free the memory allocated for the structure
        free(pdu);

        // Update the head and tail pointers
        list->head = list->head->next;
        list->tail = list->tail->prev;
    }

    // If the head pointer is not NULL, free its memory as well
    if (list->head != NULL) {
        free(list->head);
    }

    // Reset the list pointers to NULL
    list->head = NULL;
    list->tail = NULL;
