        }
    }
}

void validateCRC(NFAPI_CRC_INDICATION_PDU_T *pdu, uint8_t *packet, int len) {
    // Calculate the CRC of the packet
    uint32_t crc = 0;
    for (int i = 0; i < len; i++) {
        crc += packet[i] << (i % NFAPI_CRCFLAG_LEN);
    }
    // Validate the CRCFLAG against the calculated CRC
    bool validCrcFlag = true;
    for (int j = 0; j < NFAPI_CRCFLAG_LEN; j++) {
        if (pdu->rx_ue_information->crcIndicationRel8Tag[j] != crc % 256) {
            validCrcFlag = false;
            break;
        }
    }
