}

// Function to perform garbage collection on the hash table
void htable_gc(HTManager *manager) {
    pthread_mutex_lock(manager->lock); // acquire lock on the hash table
    int count = 0; // number of contexts collected
    for (int i = 0; i < manager->htable->capacity; i++) { // iterate over all slots in the hash table
        if (manager->htable->slots[i] != NULL) { // if a slot is occupied, check its usage status
            if (manager->htable->slots[i]->usage_status == 0) { // if the context is not in use, mark it for deletion
                free(manager->htable->slots[i]);
                manager->htable->slots[i] = NULL;
                count++; // increment the number of collected contexts
            }
        }
    }
    if (count > 0) { // if any contexts were collected, rehash the hash table to remove empty slots
        int new_capacity = manager->htable->capacity - count;
        UEContextInfo **new_slots = malloc(sizeof(UEContextInfo*) * new_capacity);
        for (int i = 0; i < new_capacity; i++) {
            new_slots[i] = manager->htable->slots[i];
        }
        free(manager->htable->slots);
        manager->htable->slots = new_slots;
        manager->htable->capacity = new_capacity;
    }
    pthread_mutex_unlock(manager->lock); // release lock on the hash table
}

// Function to perform periodic maintenance tasks on the hash table, such as garbage collection
void htable_maintain(HTManager *manager) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long cur_time = tv.tv_sec * 1000 + tv.tv_usec / 1000; // current time in milliseconds
    if (cur_time - manager->last_gc > manager->gc_interval) { // check if it's time to perform garbage collection
        htable_gc(manager);
        manager->last_gc = cur_time;
    }
}

