        manager->htable.slots[i] = NULL;
    }
    manager->lock = malloc(sizeof(pthread_mutex_t));
    if (manager->lock == NULL) { // check if memory allocation was successful
        free(manager->htable.slots);
        free(manager);
        return NULL;
    }
    pthread_mutex_init(manager->lock, NULL);
    manager->gc_interval = GC_INTERVAL; // default interval for garbage collection is 10 seconds
    manager->last_gc = 0; // last time garbage collection was performed is initially set to 0 (never)
    return manager;
}

// Function to destroy the hash table and its associated data structures, such as the lock and the GC interval
void htable_destroy(HTManager *manager) {
    pthread_mutex_destroy(manager->lock);
    free(manager->lock);
    for (int i = 0; i < manager->htable.capacity; i++) {
        if (manager->htable.slots[i] != NULL) {
            free(manager->htable.slots[i]);
        }
    }
    free(manager->htable.slots);
    free(manager);
}
