#define MAX_FILENAME_LENGTH 256
#define MAX_DIRNAME_LENGTH 64
#define RETRY_COUNT 3
#define CRC_INDICATION_REL8_TAG 0x01

// Structure to store NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    uint32_t rx_ue_information_tag;
    uint32_t rnti;
