void construct_nfapi_crc_indication_pdu_list(const char* filename, char** dirnames) {
    // Open file with read permissions
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open file");
        return;
    }

    // Get the file size
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Failed to get file size");
        close(fd);
        return;
    }
    long filesize = sb.st_size;

    // Initialize buffer for reading file contents
    char* buf = (char*)malloc(filesize + 1);
    if (!buf) {
        perror("Failed to allocate memory");
        close(fd);
        return;
    }

    // Read file contents into the buffer
    ssize_t read_bytes = read(fd, buf, filesize);
    if (read_bytes < 0) {
        perror("Failed to read from file");
        free(buf);
        close(fd);
        return;
    }

    // Close the file
    close(fd);

    // Initialize variables for tracking processed files and CRC flags
    long total_size = 0;
    int crc_flags[RETRY_COUNT] = {0};

    // Iterate over each line in the buffer
    char* token;
    for (token = strtok(buf, "\n"); token; token = strtok(NULL, "\n")) {
        // Skip empty lines
        if (!strlen(token)) continue;

        // Parse filename from the current line
        char* file_name = strtok(token, " ");

        // Check if the filename is valid and not longer than 256 characters
        if (!file_name || strlen(file_name) > MAX_FILENAME_LENGTH) continue;

        // Initialize variables for handling each file
        char* dirname = NULL;
        int fd = -1;
        struct stat sb;
        long size = 0;
        uint32_t crc_flag = 0;

        // Try to open the file with read permissions
        for (int i = 0; i < RETRY_COUNT; ++i) {
            fd = open(file_name, O_RDONLY);
            if (fd >= 0) break;
            sleep(1); // Wait before retrying
        }

        // If opening the file failed, skip it and move on to the next line
        if (fd < 0) {
            perror("Failed to open file");
            continue;
        }

        // Get the file size
        if (fstat(fd, &sb) == -1) {
            perror("Failed to get file size");
            close(fd);
            continue;
        }
        size = sb.st_size;

        // Allocate a buffer for reading the file contents
        char* file_buf = (char*)malloc(size + 1);
        if (!file_buf) {
            perror("Failed to allocate memory");
            close(fd);
            continue;
        }

        // Read the file contents into the buffer
        ssize_t read_bytes = read(fd, file_buf, size);
        if (read_bytes < 0) {
            perror("Failed to read from file");
            free(file_buf);
            close(fd);
            continue;
        }

        // Close the file
        close(fd);

        // Compute a SHA-256 hash of the file contents and compare it against the expected value
        unsigned char* digest = (unsigned char*)malloc(SHA256_DIGEST_LENGTH);
        SHA256((const unsigned char*)file_buf, size, digest);
        free(file_buf);

        // Check if the hash matches the expected value
        if (!memcmp(digest, "expected_hash", SHA256_DIGEST_LENGTH)) {
            crc_flag = CRC_INDICATION_REL8_TAG;
        } else {
            perror("CRC flag mismatch");
            free(digest);
            continue;
        }

        // Allocate a buffer for storing the file contents with the CRC flag set
        char* new_buf = (char*)malloc(size + 1);
        if (!new_buf) {
            perror("Failed to allocate memory");
            free(digest);
            continue;
        }

        // Copy the file contents and append the CRC flag
        memcpy(new_buf, digest, SHA256_DIGEST_LENGTH);
        new_buf[SHA256_DIGEST_LENGTH] = crc_flag;
        memcpy(new_buf + SHA256_DIGEST_LENGTH + 1, file_buf + SHA256_DIGEST_LENGTH, size - SHA256_DIGEST_LENGTH);

        // Free the original buffer and set it to NULL
        free(file_buf);
        file_buf = NULL;

        // Get the directory name from the filename
        dirname = strtok(file_name, "/");

        // Check if the directory exists and create it if necessary
        if (!dirname || strlen(dirname) > MAX_FILENAME_LENGTH) continue;
        int err = mkdir(dirname, 0755);
        if (err && errno != EEXIST) {
            perror("Failed to create directory");
            free(new_buf);
            continue;
        }

        // Open the file in the directory with write permissions
        fd = open(file_name, O_WRONLY | O_TRUNC | O_CREAT, 0644);
        if (fd < 0) {
            perror("Failed to open file");
            free(new_buf);
            continue;
        }

        // Write the contents of the new buffer to the file
        ssize_t write_bytes = write(fd, new_buf, size + 1);
        if (write_bytes < 0) {
            perror("Failed to write to file");
            close(fd);
            free(new_buf);
            continue;
        }

        // Close the file
        close(fd);

        // Free the new buffer and set it to NULL
        free(new_buf);
        new_buf = NULL;

        // Update variables for tracking processed files and CRC flags
        total_size += size + 1;
        crc_flags[i] = crc_flag;
    }

    // Print the total number of bytes processed and the CRC flags used
    printf("Total size: %ld\n", total_size);
    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (crc_flags[i]) {
            printf("CRC flag set on attempt %d\n", i + 1);
        }
    }

    // Free the buffer and return
    free(buf);
    return;
}
