// Structure to store a CRC indication PDU
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage a dynamically allocated array of CRC indication PDUs
void manage_crc_indications(NFAPI_CRC_INDICATION_PDU_T **pdu, unsigned int n) {
    // Allocate memory for the array of CRC indication PDUs
    *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdu == NULL) {
        // Handle allocation failure gracefully
        printf("Error: Failed to allocate memory for CRC indication PDUs\n");
        return;
    }

    // Initialize the array with random values
    srand(time(NULL));
    for (unsigned int i = 0; i < n; i++) {
        (*pdu)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*pdu)[i].RNTI = rand() % 65535;
        (*pdu)[i].CRCFLAG = rand() % 2 ? 1 : 0;
    }

    // Set the CRC flag for each element based on a provided probability p
    float p = 0.01f; // Probability of setting CRC flag
    for (unsigned int i = 0; i < n; i++) {
        if (rand() % 1000000 <= p * 1000000) {
            (*pdu)[i].CRCFLAG = 1;
        }
    }
}

// Function to validate a CRC indication PDU structure
int validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check that the RX_UE_INFORMATION_TAG and RNTI fields are valid
    if (pdu->RX_UE_INFORMATION_TAG == 0 || pdu->RNTI == 0) {
        return 0;
    }

    // Check that the CRCFLAG field is set correctly
    if (pdu->CRCFLAG != 1 && pdu->CRCFLAG != 0) {
        return 0;
    }

    // All checks passed, CRC indication PDU structure is valid
    return 1;
}

// Function to correct errors in a CRC indication PDU structure
void correct_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Set the CRCFLAG field for one randomly selected element with an incorrect CRC flag
    int random_index = rand() % n;
    while (pdu[random_index].CRCFLAG == 1) {
        random_index = rand() % n;
    }
    pdu[random_index].CRCFLAG = 0;
}

// Function to free the memory allocated for a dynamically allocated array of CRC indication PDUs
void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T **pdu) {
    if (*pdu != NULL) {
        free(*pdu);
    }
}
