// Define constants for NAS message types and MME identity regex pattern
#define NAS_MESSAGE_TYPE_PDN_CONNECTIVITY_REQUEST 0x1
#define NAS_MESSAGE_TYPE_PDN_DISCONNECT_REQUEST  0x2
#define NAS_MESSAGE_TYPE_PDN_CONNECTION_UPDATE   0x3
#define MME_IDENTITY_REGEX_PATTERN "^[a-zA-Z0-9]{5,15}$"

// Define a structure for the doubly linked list of LTE uplink NAS messages
typedef struct {
    unsigned char nas_message_type;
    char* mme_identity;
    unsigned char* nas_message;
    size_t nas_message_len;
} LTE_Uplink_NAS_Message;

// Define a function to initialize and populate the doubly linked list of LTE uplink NAS messages
void initialize_uplink_nas_messages(LTE_Uplink_NAS_Message** head) {
    // Check if the input parameter is null
    if (head == NULL) {
        printf("ERROR: Input parameter 'head' cannot be null\n");
        return;
    }

    // Initialize the doubly linked list to an empty state
    *head = NULL;

    // Read external data sources for NAS message types and MME identities
    unsigned char nas_message_type = 0x1;
    char* mme_identity = "mme-identity";

    // Validate the NAS message type and MME identity using regular expressions
    if (!regex_match(nas_message_type, NAS_MESSAGE_TYPE_PDN_CONNECTIVITY_REQUEST) && !regex_match(mme_identity, MME_IDENTITY_REGEX_PATTERN)) {
        printf("ERROR: Invalid NAS message type or MME identity\n");
        return;
    }

    // Dynamically allocate memory for the NAS message payload
    unsigned char* nas_message = malloc(sizeof(unsigned char) * 100);
    if (nas_message == NULL) {
        printf("ERROR: Failed to allocate memory for NAS message\n");
        return;
    }

    // Initialize the LTE uplink NAS message structure
    LTE_Uplink_NAS_Message* new_node = malloc(sizeof(LTE_Uplink_NAS_Message));
    if (new_node == NULL) {
        printf("ERROR: Failed to allocate memory for LTE uplink NAS message\n");
        free(nas_message);
        return;
    }

    // Set the NAS message type, MME identity, and NAS message payload
    new_node->nas_message_type = nas_message_type;
    new_node->mme_identity = mme_identity;
    new_node->nas_message = nas_message;
    new_node->nas_message_len = 100;

    // Insert the LTE uplink NAS message into the doubly linked list
    if (*head == NULL) {
        *head = new_node;
    } else {
        LTE_Uplink_NAS_Message* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
    }
}

// Define an iterator interface for traversing the doubly linked list in both forward and backward directions
void* iterate_uplink_nas_messages(LTE_Uplink_NAS_Message* node, int direction) {
    // Check if the input parameter is null or if the direction is invalid
    if (node == NULL || direction != 1 && direction != -1) {
        printf("ERROR: Invalid iteration direction\n");
        return NULL;
    }

    // Iterate through the doubly linked list in the specified direction
    while (node != NULL) {
        void* data = node->nas_message;
        if (direction == 1) {
            node = node->next;
        } else {
            node = node->prev;
        }
        return data;
    }
}

// Define a function to free the memory allocated for the LTE uplink NAS messages in the doubly linked list
void free_uplink_nas_messages(LTE_Uplink_NAS_Message* head) {
    // Check if the input parameter is null
    if (head == NULL) {
        printf("ERROR: Input parameter 'head' cannot be null\n");
        return;
    }

    // Free the memory allocated for each LTE uplink NAS message in the doubly linked list
    while (head != NULL) {
        LTE_Uplink_NAS_Message* current = head->next;
        free(head->nas_message);
        free(head);
        head = current;
    }
}
