/* Function to check if an environment variable for the directory path is already set. If so, use the existing value; otherwise, create a new directory with the provided name and set the environment variable to the path of the newly created directory. */
int create_directory_and_set_env_var(const char *dir_name) {
    /* Check if the environment variable for the directory path is already set */
    const char *env_val = getenv("DIRECTORY_PATH");
    if (env_val != NULL) {
        printf("Using existing DIRECTORY_PATH: %s\n", env_val);
        return 0;
    }

    /* Create a new directory with the provided name and set the environment variable to the path of the newly created directory */
    char *dir_path = malloc(strlen(dir_name) + 1);
    if (dir_path == NULL) {
        printf("Error: Failed to allocate memory for DIRECTORY_PATH\n");
        return -1;
    }
    strcpy(dir_path, dir_name);

    /* Create the directory with mode 0755 */
    if (mkdir(dir_path, 0755) != 0) {
        printf("Error: Failed to create DIRECTORY_PATH %s\n", dir_path);
        free(dir_path);
        return -1;
    }

    /* Set the environment variable for the directory path */
    if (setenv("DIRECTORY_PATH", dir_path, 1) != 0) {
        printf("Error: Failed to set DIRECTORY_PATH\n");
        free(dir_path);
        return -1;
    }

    /* Clean up */
    free(dir_path);

    return 0;
}

/* Function to initialize and populate a linked list of LTE Uplink NAS Messages within a network management system. */
int initialize_and_populate_linked_list() {
    /* Check if the environment variable for the directory path is already set */
    const char *env_val = getenv("DIRECTORY_PATH");
    if (env_val == NULL) {
        printf("Error: DIRECTORY_PATH not set\n");
        return -1;
    }

    /* Create a new directory for the linked list */
    char *dir_path = malloc(strlen(env_val) + 1);
    if (dir_path == NULL) {
        printf("Error: Failed to allocate memory for DIRECTORY_PATH\n");
        return -1;
    }
    strcpy(dir_path, env_val);

    /* Create the directory with mode 0755 */
    if (mkdir(dir_path, 0755) != 0) {
        printf("Error: Failed to create DIRECTORY_PATH %s\n", dir_path);
        free(dir_path);
        return -1;
    }

    /* Initialize the linked list */
    LTE_Uplink_NAS_Message *head = NULL, *tail = NULL;

    /* Read messages from external data sources and add them to the linked list */
    FILE *fp = fopen(dir_path, "r");
    if (fp == NULL) {
        printf("Error: Failed to open DIRECTORY_PATH %s\n", dir_path);
        free(dir_path);
        return -1;
    }
    while (!feof(fp)) {
        /* Read the message from the file */
        LTE_Uplink_NAS_Message *msg = malloc(sizeof(LTE_Uplink_NAS_Message));
        if (msg == NULL) {
            printf("Error: Failed to allocate memory for message\n");
            fclose(fp);
            free(dir_path);
            return -1;
        }
        /* Initialize the message structure */
        msg->nas_message_type = 0;
        msg->mme_identity = 0;
        msg->nas_message = NULL;
        /* Deserialize the message from the file */
        if (fread(&msg->nas_message_type, sizeof(uint8_t), 1, fp) != 1 ||
            fread(&msg->mme_identity, sizeof(uint32_t), 1, fp) != 1 ||
            fread(&msg->nas_message_length, sizeof(uint32_t), 1, fp) != 1 ||
            msg->nas_message = malloc(msg->nas_message_length)) == NULL) {
                printf("Error: Failed to read message from file\n");
                free(msg);
                fclose(fp);
                free(dir_path);
                return -1;
        }
        /* Add the message to the linked list */
        if (head == NULL) {
            head = tail = msg;
        } else {
            tail->next = msg;
            tail = msg;
        }
    }
    fclose(fp);

    /* Clean up */
    free(dir_path);

    return 0;
}
