// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void initList(NFAPI_CRC_INDICATION_PDU_T **list, size_t n) {
    // Allocate memory for the list
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize each structure in the list with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < n; i++) {
        (*list)[i].tag = RX_UE_INFORMATION_TAG;
        (*list)[i].rnti = rand() % 65536; // Randomly generate a valid RNTI value between 0 and 65535
        (*list)[i].crcFlag = CRCFLAG_REL8; // Set the CRC flag to REL8
    }
}

// Function to read floating-point numbers from standard input, validate each number to ensure it falls within the range of -1e308 to 1e308, and add them to a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void readInput(NFAPI_CRC_INDICATION_PDU_T **list, size_t *n) {
    // Read floating-point numbers from standard input until an empty line is encountered or EOF is reached
    while (1) {
        double num;
        if (scanf("%lf", &num) != 1) break;
        if (!(-1e308 <= num && num <= 1e308)) continue; // Ignore invalid numbers that fall outside the range of -1e308 to 1e308
        NFAPI_CRC_INDICATION_PDU_T *newEntry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newEntry == NULL) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        newEntry->tag = RX_UE_INFORMATION_TAG;
        newEntry->rnti = rand() % 65536; // Randomly generate a valid RNTI value between 0 and 65535
        newEntry->crcFlag = CRCFLAG_REL8; // Set the CRC flag to REL8
        *list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*list, (*n + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*list == NULL) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        (*list)[*n] = *newEntry;
        (*n)++;
    }
}

// Function to free the memory allocated for a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void freeList(NFAPI_CRC_INDICATION_PDU_T **list, size_t n) {
    for (size_t i = 0; i < n; i++) {
        free((*list)[i].tag);
        free((*list)[i].rnti);
        free((*list)[i].crcFlag);
    }
    free(*list);
}

int main() {
    // Define a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures and its size variable
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t n = 0;

    // Initialize the list with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values
    initList(&list, n);

    // Read floating-point numbers from standard input until an empty line is encountered or EOF is reached, validate each number to ensure it falls within the range of -1e308 to 1e308, and add them to the list
    readInput(&list, &n);

    // Print the contents of the list
    printf("List size: %zu\n", n);
    for (size_t i = 0; i < n; i++) {
        printf("%d | %u | %d\n", list[i].tag, list[i].rnti, list[i].crcFlag);
    }

    // Free the memory allocated for the list
    freeList(&list, n);
    return 0;
}
