```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <math.h>

// Macro for calculating the SNR based on noise figure and transmission power
#define SNR(noise_figure, transmission_power) \
    (pow(10, ((transmission_power - noise_figure)/10)))

typedef struct MAC_TransmissionParameters {
    uint8_t logical_channel_id;
    uint8_t transmission_mode;
    int8_t transmission_power;
} MAC_TransmissionParameters;

// Structure for storing the dynamic array of transmission parameters
struct TransmissionParameterArray {
    MAC_TransmissionParameters *transmission_parameters;
    size_t capacity;
    size_t count;
};

// Function to add a new transmission parameter to the dynamic array
void add_transmission_parameter(struct TransmissionParameterArray *array,
                                uint8_t logical_channel_id, uint8_t transmission_mode,
                                int8_t transmission_power) {
    // Check if the array is full and needs to be resized
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_TransmissionParameters *new_transmission_parameters =
            realloc(array->transmission_parameters, new_capacity);
        // Check for memory allocation failure
        if (new_transmission_parameters == NULL) {
            perror("Memory allocation failed");
            return;
        }
        array->transmission_parameters = new_transmission_parameters;
        array->capacity = new_capacity;
    }

    // Add the new transmission parameter to the end of the array
    array->transmission_parameters[array->count].logical_channel_id = logical_channel_id;
    array->transmission_parameters[array->count].transmission_mode = transmission_mode;
    array->transmission_parameters[array->count].transmission_power = transmission_power;
    array->count++;
}

// Function to update a transmission parameter in the dynamic array
void update_transmission_parameter(struct TransmissionParameterArray *array,
                                   uint8_t logical_channel_id, uint8_t transmission_mode,
                                   int8_t transmission_power) {
    // Find the index of the transmission parameter to be updated
    size_t index = find_transmission_parameter(array, logical_channel_id);

    // Check if the parameter was found and update it
    if (index != SIZE_MAX) {
        array->transmission_parameters[index].transmission_mode = transmission_mode;
        array->transmission_parameters[index].transmission_power = transmission_power;
    } else {
        // If the parameter was not found, add it to the end of the array
        add_transmission_parameter(array, logical_channel_id, transmission_mode, transmission_power);
    }
}

// Function to find a transmission parameter in the dynamic array
size_t find_transmission_parameter(struct TransmissionParameterArray *array, uint8_t logical_channel_id) {
    for (size_t i = 0; i < array->count; i++) {
        if (array->transmission_parameters[i].logical_channel_id == logical_channel_id) {
            return i;
        }
    }
    return SIZE_MAX;
}

// Function to calculate the expected SNR for a transmission parameter
int8_t calculate_expected_snr(struct TransmissionParameterArray *array, uint8_t logical_channel_id) {
    // Find the index of the transmission parameter to be updated
    size_t index = find_transmission_parameter(array, logical_channel_id);

    // Check if the parameter was found and calculate its expected SNR
    if (index != SIZE_MAX) {
        return SNR(10.0f, array->transmission_parameters[index].transmission_power);
    } else {
        // If the parameter was not found, return 0
        return 0;
    }
}

// Function to remove a transmission parameter from the dynamic array
void remove_transmission_parameter(struct TransmissionParameterArray *array, uint8_t logical_channel_id) {
    // Find the index of the transmission parameter to be removed
    size_t index = find_transmission_parameter(array, logical_channel_id);

    // Check if the parameter was found and remove it from the array
    if (index != SIZE_MAX) {
        // Shift all elements after the removed element to the left by one position
        for (size_t i = index; i < array->count - 1; i++) {
            array->transmission_parameters[i] = array->transmission_parameters[i + 1];
        }
        array->count--;
    }
}

// Function to get the number of transmission parameters in the dynamic array
size_t get_num_transmission_parameters(struct TransmissionParameterArray *array) {
    return array->count;
