// Structure to hold CRC indication PDU data
typedef struct {
    unsigned int crc;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage an array of NFAPI_CRC_INDICATION_PDU_T structures
void manageNfapiCrcIndicationArray(NFAPI_CRC_INDICATION_PDU_T **array, int num_elements) {
    // Initialize mutex for synchronizing access to the array
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Set predefined threshold for dynamic resizing of the array
    int resize_threshold = 100;

    // Allocate memory for the array
    *array = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
    if (*array == NULL) {
        printf("Error: Failed to allocate memory for CRC indication array\n");
        exit(1);
    }

    // Initialize all elements of the array to zero
    memset(*array, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);

    // Create a condition variable for signaling when the resize threshold is reached
    pthread_cond_t resize_condition = PTHREAD_COND_INITIALIZER;

    // Set initial size of the array
    int current_size = num_elements;

    // Lock mutex before accessing the array
    pthread_mutex_lock(&mutex);

    while (1) {
        // Check if the resize threshold is reached and the array needs to be resized
        if (current_size >= resize_threshold) {
            // Double the size of the array
            current_size *= 2;

            // Reallocate memory for the new array
            NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *) realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_size);
            if (new_array == NULL) {
                printf("Error: Failed to resize CRC indication array\n");
                exit(1);
            }

            // Update the pointer to the new array
            *array = new_array;
        }

        // Add a new element to the array
        (*array)[current_size - 1].crc = 0;

        // Unlock mutex before accessing the array
        pthread_mutex_unlock(&mutex);

        // Signal condition variable to notify other threads that the resize threshold has been reached
        pthread_cond_signal(&resize_condition);

        // Wait for a signal on the condition variable
        pthread_cond_wait(&resize_condition, &mutex);
    }

    // Clean up resources
    free(*array);
    *array = NULL;
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&resize_condition);
}
