    // Find the element with the matching RNTI in the list
    size_t index = crc_indication_list_find(list, RNTI);
    if (index == SIZE_MAX) {
        printf("Could not find element with RNTI %u\n", RNTI);
        return;
    }

    // Remove the element from the list
    pthread_mutex_lock(&list->mutex);
    list->data[index] = list->data[--list->count];
    pthread_mutex_unlock(&list->mutex);
