#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <fcntl.h>

// Structure for CRC indication PDU
typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure for CRC indication REL8 tag
typedef struct {
    uint32_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_REL8_TAG;

// List node structure
typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct list_node *next;
} LIST_NODE;

// List head structure
typedef struct {
    LIST_NODE *head;
    LIST_NODE *tail;
} LIST;

// File descriptor for exporting the list to a file
int fd = 0;

// Function to initialize the list
void init_list() {
    // Initialize the head and tail pointers to NULL
    head = NULL;
    tail = NULL;
}

// Function to add an element to the list
bool add_element(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the list is empty
    if (head == NULL) {
        // Initialize the head and tail pointers
        head = malloc(sizeof(LIST_NODE));
        tail = head;
    } else {
        // Allocate memory for a new node
        LIST_NODE *new_node = malloc(sizeof(LIST_NODE));
        if (new_node == NULL) {
            printf("Memory allocation failed\n");
            return false;
        }
        tail->next = new_node;
        tail = new_node;
    }
    // Set the next pointer of the new node to NULL
    tail->next = NULL;
    // Copy the PDU data into the new node
    memcpy(tail->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return true;
}

// Function to remove an element from the list
bool remove_element(uint16_t rnti) {
    // Check if the list is empty
    if (head == NULL) {
        printf("List is empty\n");
        return false;
    }
    // Traverse the list until we find the node with the matching RNTI
    LIST_NODE *prev = head, *curr = head->next;
    while (curr != NULL) {
        if (curr->pdu->rnti == rnti) {
            // Found the node to remove
            prev->next = curr->next;
            free(curr);
            return true;
        }
        prev = curr;
        curr = curr->next;
    }
    printf("Node with RNTI %d not found\n", rnti);
    return false;
}

// Function to validate the integrity of a CRC_INDICATION_REL8_TAG
bool validate_crc(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Calculate the expected CRC value based on the RX_UE_INFORMATION_TAG and RNTI
    uint32_t crc = pdu->rx_ue_information_tag ^ pdu->rnti;
    // Check if the CRCFLAG matches the expected value
    return (pdu->crcflag == (crc & 0xFF));
}

// Function to add a CRC_INDICATION_REL8_TAG to the list
bool add_crc(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Validate the CRCFLAG before adding the PDU to the list
    if (!validate_crc(pdu)) {
        printf("CRCFLAG validation failed\n");
        return false;
    }
    // Add the PDU to the list
    return add_element(pdu);
}

// Function to export the list to a file in JSON format
void export_list() {
    // Open the file for writing
    fd = open("list.json", O_RDWR | O_CREAT, 0644);
    if (fd == -1) {
        printf("File opening failed\n");
        return;
    }
    // Write the JSON data to the file
    for (LIST_NODE *curr = head; curr != NULL; curr = curr->next) {
        char buffer[256];
        sprintf(buffer, "{\"rx_ue_information_tag\": %d, \"rnti\": %d, \"crcflag\": %d}\n",
            curr->pdu->rx_ue_information_tag, curr->pdu->rnti, curr->pdu->crcflag);
        write(fd, buffer, strlen(buffer));
    }
}

// Function to import the list from a file in JSON format
void import_list() {
    // Open the file for reading
    fd = open("list.json", O_RDONLY);
    if (fd == -1) {
        printf("File opening failed\n");
        return;
    }
    // Read the JSON data from the file
    char buffer[256];
    while (read(fd, buffer, 256) > 0) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        sscanf(buffer, "{\"rx_ue_information_tag\": %d, \"rnti\": %d, \"crcflag\": %d}",
            &pdu.rx_ue_information_tag, &pdu.rnti, &pdu.crcflag);
        // Add the PDU to the list
        add_element(&pdu);
    }
}

// Function to initialize the list and import data from a file
void init() {
    // Import data from a file in JSON format
    import_list();
}

// Function to deinitialize the list and export data to a file
void deinit() {
    // Export data to a file in JSON format
    export_list();
}

// Main function
int main() {
    init();
    deinit();
    return 0;
}
```

The `init` and `deinit` functions are used to initialize and deinitialize the list, respectively. The `add_element`, `remove_element`, and `validate_crc` functions are used to add a new element to the list, remove an element from the list, and validate the integrity of a CRC_INDICATION_REL8_TAG, respectively. The `export_list` function is used to export the list data to a file in JSON format, and the `import_list` function is used to import the list data from a file in JSON format. The main function calls the `init` and `deinit` functions to initialize and deinitialize the list, respectively.']

