    list->pdu_list[list->pdu_count++] = *new_entry;

    return list;
}

// Function for removing an entry from the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *remove_entry(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    // Check if the list is empty
    if (list->pdu_count == 0) {
        return NULL;
    }

    // Find the entry to be removed
    for (size_t i = 0; i < list->pdu_count; i++) {
        if (list->pdu_list[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && list->pdu_list[i].RNTI == RNTI && list->pdu_list[i].CRC_INDICATION_REL8_TAG == CRC_INDICATION_REL8_TAG) {
            // Remove the entry from the list
            NFAPI_CRC_INDICATION_PDU_T *removed_entry = &(list->pdu_list[i]);
            memmove(&(list->pdu_list[i]), &(list->pdu_list[i + 1]), sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->pdu_count - i - 1));
            list->pdu_count--;

            return list;
        }
    }

    // If the entry to be removed is not found, return NULL
    return NULL;
}

// Function for iterating over the entries in the list of NFAPI_CRC_INDICATION_PDU_T structures
void iterate_entries(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if the list is empty
    if (list->pdu_count == 0) {
        return;
    }

    for (size_t i = 0; i < list->pdu_count; i++) {
        printf("Entry %zu: RX_UE_INFORMATION_TAG = %hu, RNTI = %hu, CRC_INDICATION_REL8_TAG = %hhu, CRCFLAG = %d\n", i, list->pdu_list[i].RX_UE_INFORMATION_TAG, list->pdu_list[i].RNTI, list->pdu_list[i].CRC_INDICATION_REL8_TAG, list->pdu_list[i].CRCFLAG);
    }
}

// Function for logging the resource usage of the function
void log_resource_usage() {
    // Get the current time in milliseconds since the epoch
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    long current_millis = (long)((double)current_time.tv_sec * 1000 + (double)current_time.tv_nsec / 1000000);

    // Calculate the memory usage of the function
    size_t total_memory_usage = 0;
    for (size_t i = 0; i < list->pdu_count; i++) {
        total_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // Log the resource usage to a file
    FILE *log_file = fopen("resource_usage.log", "a");
    if (log_file == NULL) {
        return;
    }

    fprintf(log_file, "%ldms: Memory usage = %zu bytes\n", current_millis, total_memory_usage);
    fclose(log_file);
}

int main() {
    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->pdu_list = NULL;
    list->pdu_count = 0;

    // Add new entries to the list as necessary
    add_new_entry(list, 1234, 5678, 9012, true);
    remove_entry(list, 1234, 5678, 9012);
    iterate_entries(list);

    // Log the resource usage of the function
    log_resource_usage();

    return 0;
}
