#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <pthread.h>
#include <unistd.h>
#include "nfapi_interface.h"
#include "crc_indication_utils.h"

struct nfapi_crc_indication_pdu *generate_crc_indication_pdus(int num_pdus, int rat) {
  struct nfapi_crc_indication_pdu *pdus;

  // Allocate memory for the CRC indication PDUs
  pdus = (struct nfapi_crc_indication_pdu *)malloc(num_pdus * sizeof(struct nfapi_crc_indication_pdu));
  if (!pdus) {
    fprintf(stderr, "Error: Failed to allocate memory for CRC indication PDUs\n");
    return NULL;
  }

  // Initialize the RX UE information tag and RNTI for each PDU
  for (int i = 0; i < num_pdus; i++) {
    pdus[i].rx_ue_information.tag = NFAPI_RX_UE_INFORMATION_TAG;
    pdus[i].rx_ue_information.rnti = generate_rnti();
  }

  // Generate the CRC indication PDUs for each RNTI
  for (int i = 0; i < num_pdus; i++) {
    pdus[i].crc_indication_rel8.tag = NFAPI_CRC_INDICATION_REL8_TAG;
    pdus[i].crc_indication_rel8.crci = generate_crc(rat);
  }

  return pdus;
}

int generate_rnti() {
  // Generate a random RNTI value between 1 and 65535
  return (rand() % 65535) + 1;
}

int generate_crc(int rat) {
  // Generate a random CRC value based on the radio access technology
  if (rat == NFAPI_RAT_LTE) {
    return (rand() % 65535) + 1;
  } else if (rat == NFAPI_RAT_NR) {
    // Generate a random CRC value for the NR protocol
    return (rand() % 4095) + 1;
  } else {
    fprintf(stderr, "Error: Unsupported radio access technology\n");
    return -1;
  }
}
```
