// Function to manage the list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **list, int M, int L) {
    // Initialize a mutex for thread synchronization
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop until the list size does not exceed the maximum value M
    while (1) {
        // Acquire the mutex lock to prevent race conditions and deadlocks
        pthread_mutex_lock(&mutex);

        // Check if the list size is less than or equal to the maximum value M
        if (list->size <= M) {
            // Generate a new NFAPI_CRC_INDICATION_PDU_T structure with a randomly set CRCFLAG
            NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            new_pdu->RX_UE_INFORMATION_TAG = rand() % 10;
            new_pdu->RNTI = rand() % 10000;
            new_pdu->CRC_INDICATION_REL8_TAG = rand() % 10;
            new_pdu->CRCFLAG = (rand() % 2) == 0;

            // Add the new NFAPI_CRC_INDICATION_PDU_T structure to the list
            list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (list->size + 1));
            list[list->size] = new_pdu;

            // Increment the list size and release the mutex lock
            list->size++;
            pthread_mutex_unlock(&mutex);
        } else {
            // Check if there are any stale entries in the list older than T seconds
            time_t current_time = time(NULL);
            for (int i = 0; i < list->size; i++) {
                NFAPI_CRC_INDICATION_PDU_T *pdu = list[i];
                if (current_time - pdu->timestamp > T) {
                    // Remove the stale entry from the list and release the mutex lock
                    free(list[i]);
                    memmove(&list[i], &list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (list->size - i));
                    list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (list->size - 1));
                    list->size--;
                    pthread_mutex_unlock(&mutex);
                } else {
                    // If there are no stale entries, release the mutex lock and wait for the next iteration
                    pthread_mutex_unlock(&mutex);
                    break;
                }
            }
        }
    }
}
