// Define the caching mechanism for RNTI values
#define RNTI_CACHE_SIZE 1024
static uint32_t rntiCache[RNTI_CACHE_SIZE];
static pthread_mutex_t rntiMutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to generate NFAPI CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_T* generateNFAPackage(uint32_t numEntries) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfaArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numEntries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaArray) {
        printf("Error: failed to allocate memory for NFAPI CRC indication PDUs\n");
        return NULL;
    }

    // Populate the array with valid values for RX UE information, RNTI, and CRC indication REL8 tag
    uint32_t i;
    for (i = 0; i < numEntries; i++) {
        // Generate a random RNTI value using the XorShift algorithm
        unsigned long rntiSeed = 123456789;
        uint32_t rnti;
        do {
            rntiSeed ^= (rntiSeed << 13);
            rntiSeed ^= (rntiSeed >> 17);
            rnti = (unsigned long)((rntiSeed ^ (rntiSeed >> 5)) & 0xFFFFFFFFUL);
        } while (rntiCache[rnti % RNTI_CACHE_SIZE] == rnti);
        rntiCache[rnti % RNTI_CACHE_SIZE] = rnti;

        // Set the RX UE information tag and RNTI value for the current structure
        nfaArray[i].rxUeInfoTag.fieldsPresent = (RX_UE_INFORMATION_TAG__RNTI & 0xFF);
        nfaArray[i].rnti = rnti;

        // Set a randomly generated CRC indication REL8 tag with a CRCFlag value
        unsigned long crcFlagSeed = 123456789;
        do {
            crcFlagSeed ^= (crcFlagSeed << 13);
            crcFlagSeed ^= (crcFlagSeed >> 17);
            nfaArray[i].crcIndRel8.CRCFlag = (unsigned long)((crcFlagSeed ^ (crcFlagSeed >> 5)) & 0xFFFFFFFFUL);
        } while (nfaArray[i].crcIndRel8.CRCFlag == 0);
    }

    return nfaArray;
}

// Define the function to free memory allocated for NFAPI CRC indication PDUs
void freeNFAPackage(NFAPI_CRC_INDICATION_PDU_T* nfaArray) {
    // Release the memory allocated for the array of NFAPI_CRC_INDICATION_PDU_T structures
    if (nfaArray) {
        free(nfaArray);
    }
}
