// Structure for keeping track of a UE's RRC state and slice context configuration
typedef struct {
    uint32_t ue_id; // Unique identifier for the UE
    NFAPI_RX_INDICATION_PDU_T rx_indication; // Struct containing RX indication data
    SliceContextConfig *slice_context; // Dynamic allocation of slice context configuration
} UEContext;

// Function to initialize and configure a list of NFAPI_RX_INDICATION_PDU_T structures for a given number of UEs
int nfapi_rx_indication_init(int num_ues, int *ue_ids) {
    int i, j; // Loop counters
    UEContext *ue_context = (UEContext *)malloc(num_ues * sizeof(UEContext));
    if (!ue_context) {
        fprintf(stderr, "Failed to allocate memory for UE context list\n");
        return -1;
    }
    memset(ue_context, 0, num_ues * sizeof(UEContext));

    // Iterate over the given UEs and initialize their RX indication structures
    for (i = 0; i < num_ues; i++) {
        UEContext *ue = &ue_context[i];
        ue->ue_id = ue_ids[i];
        nfapi_rx_indication_init(&ue->rx_indication); // Initialize RX indication structure for this UE
    }

    return 0;
}

// Function to update the slice context configuration for a given UE
int nfapi_slice_context_update(uint32_t ue_id, SliceContextConfig *slice_context) {
    UEContext *ue = NULL; // Pointer to UE context structure
    int i; // Loop counter

    // Find the UE with the given ID in the UE context list
    for (i = 0; i < num_ues; i++) {
        if (ue_context[i].ue_id == ue_id) {
            ue = &ue_context[i];
            break;
        }
    }
    if (!ue) { // Check for errors
        fprintf(stderr, "UE with ID %u not found\n", ue_id);
        return -1;
    }

    // Free the previous slice context configuration (if any)
    if (ue->slice_context) {
        nfapi_slice_context_free(ue->slice_context);
    }

    // Copy the new slice context configuration
    ue->slice_context = slice_context;

    return 0;
}

// Function to free the memory allocated for a given UE's slice context configuration
int nfapi_slice_context_free(SliceContextConfig *slice_context) {
    if (!slice_context) {
        fprintf(stderr, "Invalid argument: slice_context is NULL\n");
        return -1;
    }
    free(slice_context); // Free the memory allocated for the slice context configuration
    return 0;
}

// Function to deallocate memory for a given list of NFAPI_RX_INDICATION_PDU_T structures
int nfapi_rx_indication_dealloc(int num_ues, NFAPI_RX_INDICATION_PDU_T **ue_rx_indications) {
    int i; // Loop counter

    if (!ue_rx_indications) {
        fprintf(stderr, "Invalid argument: ue_rx_indications is NULL\n");
        return -1;
    }

    // Iterate over the given UE RX indication structures and free their memory
    for (i = 0; i < num_ues; i++) {
        NFAPI_RX_INDICATION_PDU_T *rx_indication = ue_rx_indications[i];
        if (!rx_indication) continue; // Skip NULL pointers
        nfapi_slice_context_free(rx_indication->slice_context); // Free the slice context configuration for this UE
        free(rx_indication); // Free the memory allocated for the RX indication structure
    }

    return 0;
}
