void init_interface_pool(interface_pool_t* pool) {
    pool->num_configs = 0;
}

// Function to add a new network interface configuration to the pool
bool add_interface_config(interface_pool_t* pool, uint32_t id, char* ip_address, void* link_layer_settings) {
    // Check if the pool is full
    if (pool->num_configs >= POOL_SIZE) {
        return false;
    }

    // Add a new interface configuration to the pool
    pool->configs[pool->num_configs].id = id;
    strcpy(pool->configs[pool->num_configs].ip_address, ip_address);
    pool->configs[pool->num_configs].link_layer_settings = link_layer_settings;

    // Increment the number of interface configurations in the pool
    pool->num_configs++;

    return true;
}

// Function to remove a network interface configuration from the pool
bool remove_interface_config(interface_pool_t* pool, uint32_t id) {
    // Check if the pool is empty
    if (pool->num_configs == 0) {
        return false;
    }

    // Find the index of the interface configuration to remove
    size_t i;
    for (i = 0; i < pool->num_configs; i++) {
        if (pool->configs[i].id == id) {
            break;
        }
    }

    // Check if the interface configuration was found
    if (i == pool->num_configs) {
        return false;
    }

    // Remove the interface configuration from the pool
    for (size_t j = i; j < pool->num_configs - 1; j++) {
        pool->configs[j] = pool->configs[j + 1];
    }

    // Decrement the number of interface configurations in the pool
    pool->num_configs--;

    return true;
}

// Function to update a network interface configuration in the pool
bool update_interface_config(interface_pool_t* pool, uint32_t id, char* ip_address, void* link_layer_settings) {
    // Find the index of the interface configuration to update
    size_t i;
    for (i = 0; i < pool->num_configs; i++) {
        if (pool->configs[i].id == id) {
            break;
        }
    }

    // Check if the interface configuration was found
    if (i == pool->num_configs) {
        return false;
    }

    // Update the IP address and link layer settings of the interface configuration
    strcpy(pool->configs[i].ip_address, ip_address);
    pool->configs[i].link_layer_settings = link_layer_settings;

    return true;
}

// Function to retrieve a network interface configuration from the pool by ID
interface_config_t* get_interface_config(interface_pool_t* pool, uint32_t id) {
    // Find the index of the interface configuration to retrieve
    size_t i;
    for (i = 0; i < pool->num_configs; i++) {
        if (pool->configs[i].id == id) {
            break;
        }
    }

    // Check if the interface configuration was found
    if (i == pool->num_configs) {
        return NULL;
    }

    return &pool->configs[i];
}
