tcp_connection_stats* init_tcp_conn_stat(const char* src_ip, const char* dst_ip) {
    tcp_connection_stats* stats = (tcp_connection_stats*) malloc(sizeof(tcp_connection_stats));
    if (!stats) {
        perror("malloc");
        return NULL;
    }
    memset(stats, 0, sizeof(tcp_connection_stats));
    strncpy(stats->src_ip, src_ip, 15);
    strncpy(stats->dst_ip, dst_ip, 15);
    return stats;
