    free(stats_list[i].src_ip);
    free(stats_list[i].dst_ip);
    memmove(stats_list + i, stats_list + i + 1, (num_connections - i - 1) * sizeof(tcp_connection_stats));
    num_connections--;
    pthread_mutex_unlock(&mutex);
    return 0;
}

