int generateNFAPICRCIndications(OAuthRequest* request, NFAPI_CRC_INDICATION_PDU_T** pduList) {
    // Initialize a list to store the PDUs
    *pduList = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    json_t* jsonResponse;
    char* privateKey;
    char* cert;
    int nPdus = 0;

