    pthread_t validatorThread;
    if (pthread_create(&validatorThread, NULL, validateAndDecryptCert, privateKey)) {
        return -1;
    }

    // Populate the PDU list with the data from the validated certificates
    json_t* certificates = json_object_get(jsonResponse, "certificates");
