        pdu.crcIndicationRel8Tag = crcIndicationRel8Tag;
        (*pduList)[nPdus] = pdu;
        nPdus++;
    }

    // Join the validator thread to ensure that the certificates are properly validated and decrypted before returning
    void* status;
    if (pthread_join(validatorThread, &status)) {
        return -1;
    }

    // Clean up the json response and certificate data
