        // Check if the event's timestamp falls within the specified time interval
        if (event->eventTime >= minTime && event->eventTime <= maxTime) {
            filterCount++; // Increment count of filtered events
            continue; // Skip to next event if event is in time interval
        }

        // Check if the IP address matches the specified pattern
        if (strcmp(event->sourceIP, ipPattern) != 0 && strcmp(event->destinationIP, ipPattern) != 0) {
            continue; // Skip to next event if IP address does not match pattern
        }

        // If wildcard pattern is used, check if the IP address matches the pattern without wildcards
        if (ipMatch) {
            char* ip = strstr(event->sourceIP, "*");
            if (ip == NULL || strcmp(ip + 1, ipPattern + strlen(ip)) != 0) {
