        list->head = node;
        list->tail = node;
        return 0;
    }
    else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
        return 1;
    }
}

int remove_from_crc_list(struct NFAPI_CRC_INDICATION_LIST* list, struct NFAPI_CRC_INDICATION_PDU* node) {
    if (node->prev == NULL) {
        return 0;
    }
    else {
        node->prev->next = node->next;
        if (node->next != NULL) {
            node->next->prev = node->prev;
        }
        else {
            list->tail = node->prev;
        }
        return 1;
    }
}

void process_crc_list(struct NFAPI_CRC_INDICATION_LIST* list) {
