        // Remove the node from the list after processing it
        remove_from_crc_list(list, node);
    }
}

void free_crc_list(struct NFAPI_CRC_INDICATION_LIST* list) {
    struct NFAPI_CRC_INDICATION_PDU* node = list->head;
    while (node != NULL) {
