// Structure to store CRC indication information
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t sequence_number; // Unique sequence number for each structure
    uint16_t RX_UE_INFORMATION_TAG; // Tag of the UE that provided the CRC information
    uint16_t RNTI; // RNTI of the UE that provided the CRC information
    uint8_t CRCFLAG; // Flag to indicate if CRC is present or not
    uint32_t CRC_INDICATION_REL8_TAG; // Relative timing indicator for CRC information
} NFAPI_CRC_INDICATION_PDU_T;

// List data structure to store the dynamically allocated structures
typedef struct {
    int count; // Number of elements in the list
    int size; // Size of the list (in terms of number of elements)
    NFAPI_CRC_INDICATION_PDU_T **data; // Pointer to the first element in the list
} NFAPI_CRC_INDICATION_LIST_T;

// Initialize a new list with a specified size
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_init(int size) {
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->count = 0;
    list->size = size;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * size);
    return list;
}

// Add a new element to the list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (list->count == list->size) {
        // List is full, reallocate memory to double the size
        int new_size = list->size * 2;
        list->data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_size);
        list->size = new_size;
    }
    list->data[list->count++] = element;
}

// Remove an element from the list by its sequence number
void nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t sequence_number) {
    // Find the index of the element to be removed
    int i;
    for (i = 0; i < list->count; i++) {
        if (list->data[i]->sequence_number == sequence_number) {
            break;
        }
    }
    // Check if the element was found
    if (i < list->count) {
        // Remove the element by shifting all elements after it to the left
        for (int j = i; j < list->count - 1; j++) {
            list->data[j] = list->data[j + 1];
        }
        list->count--;
    }
}

// Compact the list by reclaiming unused memory and reducing the size of the data structure
void nfapi_crc_indication_list_compact(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Reallocate memory to a smaller size if possible
    int new_size = list->count;
    if (new_size == 0) {
        free(list->data);
        list->data = NULL;
        list->size = 0;
    } else {
        list->data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_size);
        list->size = new_size;
    }
}

// Monitor the performance of the system under high load and adjust memory allocation dynamically to optimize resource usage and prevent fragmentation
void nfapi_crc_indication_list_monitor(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if the system is under high load (e.g., more than 80% of maximum capacity)
    if (list->count >= list->size * 0.8) {
        // Adjust memory allocation to reduce fragmentation and optimize resource usage
        nfapi_crc_indication_list_compact(list);
    }
}

// Periodically flush the list to a file at a user-specified interval to ensure data persistence and facilitate external retrieval
void nfapi_crc_indication_list_flush(NFAPI_CRC_INDICATION_LIST_T *list, char* filename) {
    // Write the list to a file in a binary format
    FILE *file = fopen(filename, "wb");
    fwrite(&list->count, sizeof(int), 1, file);
    for (int i = 0; i < list->count; i++) {
        fwrite(list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

// Thread-safe method to populate the list with a new element, ensuring integrity and thread safety
void nfapi_crc_indication_list_populate(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire a lock to prevent concurrent modifications
    pthread_mutex_lock(&list->lock);
    // Add the new element to the list and release the lock
    nfapi_crc_indication_list_add(list, element);
    pthread_mutex_unlock(&list->lock);
}

// Thread-safe method to remove an element from the list by its sequence number, ensuring integrity and thread safety
void nfapi_crc_indication_list_remove_by_sequence_number(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t sequence_number) {
    // Acquire a lock to prevent concurrent modifications
    pthread_mutex_lock(&list->lock);
    // Remove the element from the list and release the lock
    nfapi_crc_indication_list_remove(list, sequence_number);
    pthread_mutex_unlock(&list->lock);
