// Linked list node to store elements of the linked list
typedef struct LIST_NODE {
  NFAPI_CRC_INDICATION_PDU data;
  struct LIST_NODE *next;
} LIST_NODE;

// Global variable to keep track of the head node of the linked list
LIST_NODE* head = NULL;

// Global variable to keep track of the tail node of the linked list
LIST_NODE* tail = NULL;

// Global variable to keep track of the number of elements in the linked list
int numElements = 0;

// Global variable to keep track of the maximum number of elements that can be stored in the linked list
const int MAX_ELEMENTS = 10000;

// Global mutex to protect the linked list from concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

/**
 * Initializes the linked list by creating a head node and setting it as the tail node.
 */
void initLinkedList() {
  // Create a new head node
  LIST_NODE* newHead = (LIST_NODE*) malloc(sizeof(LIST_NODE));
  if (newHead == NULL) {
    printf("Error: Failed to allocate memory for the linked list\n");
    return;
  }

  // Set the head node as the tail node
  head = newHead;
  tail = newHead;
}

/**
 * Adds a new element to the end of the linked list.
 */
void addElement(RX_UE_INFORMATION_TAG tag, RNTI rnti, CRC_INDICATION_REL8_TAG crcIndRel8Tag) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&mutex);

  // Create a new node and set its data fields
  LIST_NODE* newNode = (LIST_NODE*) malloc(sizeof(LIST_NODE));
  if (newNode == NULL) {
    printf("Error: Failed to allocate memory for the linked list\n");
    return;
  }
  newNode->data.tag = tag;
  newNode->data.rnti = rnti;
  newNode->data.crcIndRel8Tag = crcIndRel8Tag;

  // Generate a random value for the CRCFlag field
  unsigned short randVal = (unsigned short) (rand() % 1000);
  newNode->data.crcFlag = randVal;

  // Add the new node to the end of the linked list
  tail->next = newNode;
  tail = newNode;

  // Increment the number of elements in the linked list
  numElements++;

  // Unlock the mutex
  pthread_mutex_unlock(&mutex);
}

/**
 * Removes the first element from the linked list.
 */
void removeFirstElement() {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&mutex);

  // Check if there are any elements in the linked list
  if (numElements == 0) {
    printf("Error: The linked list is empty\n");
    return;
  }

  // Set the head node to the next node in the linked list
  LIST_NODE* temp = head->next;

  // Free the memory of the first element
  free(head);

  // Update the head and tail nodes
  head = temp;
  if (temp == NULL) {
    tail = NULL;
  }

  // Decrement the number of elements in the linked list
  numElements--;

  // Unlock the mutex
  pthread_mutex_unlock(&mutex);
}

/**
 * Returns the first element from the linked list.
 */
NFAPI_CRC_INDICATION_PDU getFirstElement() {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&mutex);

  // Check if there are any elements in the linked list
  if (numElements == 0) {
    printf("Error: The linked list is empty\n");
    return;
  }

  // Return the data field of the first element
  NFAPI_CRC_INDICATION_PDU data = head->data;

  // Unlock the mutex
  pthread_mutex_unlock(&mutex);

  return data;
}

/**
 * Destroys the linked list by freeing all memory allocated to it.
 */
void destroyLinkedList() {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&mutex);

  // Check if there are any elements in the linked list
  if (numElements > 0) {
    printf("Error: The linked list is not empty\n");
    return;
  }

  // Free all memory allocated to the nodes of the linked list
  LIST_NODE* temp = head;
  while (temp != NULL) {
    free(temp);
    temp = temp->next;
  }

  // Set the head and tail nodes to null
  head = NULL;
  tail = NULL;

  // Unlock the mutex
  pthread_mutex_unlock(&mutex);
}
