    int size; // Current number of elements in the array
    log_entry_t *entries; // Array of log entries
} log_array_t;

// Initialize and manage a dynamic array of custom message structures
void init_log_array(log_array_t **arr) {
    // Allocate memory for the array structure
    *arr = (log_array_t *)malloc(sizeof(log_array_t));

    // Initialize the capacity and size to 0
    (*arr)->capacity = 0;
    (*arr)->size = 0;

    // Allocate memory for the array of log entries
    (*arr)->entries = (log_entry_t *)malloc(sizeof(log_entry_t) * (*arr)->capacity);
}

// Add a new entry to the dynamic array
void add_log_entry(log_array_t *arr, long timestamp, int type, char *source_id, void *metadata) {
    // Check if the array is full
    if ((*arr)->size == (*arr)->capacity) {
        // Double the capacity of the array
        (*arr)->capacity = 2 * (*arr)->capacity;
        (*arr)->entries = (log_entry_t *)realloc((*arr)->entries, sizeof(log_entry_t) * (*arr)->capacity);
    }

    // Add the new entry to the array
    (*arr)->entries[(*arr)->size].timestamp = timestamp;
    (*arr)->entries[(*arr)->size].type = type;
    (*arr)->entries[(*arr)->size].source_id = source_id;
    (*arr)->entries[(*arr)->size].metadata = metadata;
    (*arr)->size++;
}

// Retrieve log entries by source identifier
void get_log_entries(log_array_t *arr, char *source_id) {
    // Initialize an empty array to hold the retrieved entries
    int retrieved_entries = 0;
    log_entry_t *retrieved_entry = (log_entry_t *)malloc(sizeof(log_entry_t));

    // Iterate over the array of log entries and retrieve those with the specified source identifier
    for (int i = 0; i < (*arr)->size; i++) {
        if (strcmp((*arr)->entries[i].source_id, source_id) == 0) {
            retrieved_entry[retrieved_entries] = (*arr)->entries[i];
            retrieved_entries++;
        }
    }

    // Return the array of retrieved entries
    return retrieved_entry;
}

// Filter log entries based on a specified time range
void filter_log_entries(log_array_t *arr, long min_timestamp, long max_timestamp) {
    // Initialize an empty array to hold the filtered entries
    int filtered_entries = 0;
    log_entry_t *filtered_entry = (log_entry_t *)malloc(sizeof(log_entry_t));

    // Iterate over the array of log entries and filter those within the specified time range
    for (int i = 0; i < (*arr)->size; i++) {
        if ((*arr)->entries[i].timestamp >= min_timestamp && (*arr)->entries[i].timestamp <= max_timestamp) {
            filtered_entry[filtered_entries] = (*arr)->entries[i];
            filtered_entries++;
        }
    }

    // Return the array of filtered entries
    return filtered_entry;
}

// Interface with an external logging service for asynchronous error reporting
void report_error(log_array_t *arr, char *message) {
