    printf("Error: %s\n", message);
}

// Ensure compatibility with a third-party analytics platform for performance metrics
void measure_performance(log_array_t *arr) {
    // Measure the performance of the log array by calculating the time taken to add and retrieve entries
    long start = clock();
    for (int i = 0; i < (*arr)->size; i++) {
        get_log_entry(arr, i);
    }
