// Function to generate a unique GUTI value based on a provided seed
char* generate_guti(unsigned long seed) {
    char guti[32];
    sprintf(guti, "%08lx%08lx", seed, seed + 1);
    return strdup(guti);
}

// Function to generate a unique IMSI value based on a provided seed
char* generate_imsi(unsigned long seed) {
    char imsi[16];
    sprintf(imsi, "%08lx%08lx", seed, seed + 1);
    return strdup(imsi);
}

// Function to add a new event log entry to the list
void add_event_log(unsigned long timestamp, char *event_type, char *source_identifier, void* metadata) {
    // Acquire lock on the list of event logs
    pthread_mutex_lock(&log_lock);

    // Create a new event log structure and populate it with the provided data
    event_log_t* new_event = malloc(sizeof(event_log_t));
    new_event->timestamp = timestamp;
    strcpy(new_event->event_type, event_type);
    strcpy(new_event->source_identifier, source_identifier);
    new_event->metadata = metadata;

    // Add the new event log to the end of the list
    if (event_logs == NULL) {
        event_logs = malloc(sizeof(list_t));
        event_logs->head = new_event;
        event_logs->tail = new_event;
    } else {
        event_logs->tail->next = new_event;
        event_logs->tail = new_event;
    }

    // Release lock on the list of event logs
    pthread_mutex_unlock(&log_lock);
}

// Function to add a new UE context entry to the list
void add_ue_context(char *imsi, char *guti) {
    // Acquire lock on the list of UE contexts
    pthread_mutex_lock(&log_lock);

    // Create a new UE context structure and populate it with the provided data
    ue_context_t* new_ue = malloc(sizeof(ue_context_t));
    strcpy(new_ue->imsi, imsi);
    strcpy(new_ue->guti, guti);

    // Add the new UE context to the end of the list
    if (ue_contexts == NULL) {
        ue_contexts = malloc(sizeof(list_t));
        ue_contexts->head = new_ue;
        ue_contexts->tail = new_ue;
    } else {
        ue_contexts->tail->next = new_ue;
        ue_contexts->tail = new_ue;
    }

    // Release lock on the list of UE contexts
    pthread_mutex_unlock(&log_lock);
}

// Function to generate unique GUTI and IMSI values based on a provided seed
void generate_unique_identifiers(unsigned long seed) {
    // Acquire lock on the list of event logs
    pthread_mutex_lock(&log_lock);

    // Loop through all event logs in the list to find a suitable GUTI value
    list_node_t* current = event_logs->head;
    while (current != NULL) {
        if (strncmp(current->data.guti, generate_guti(seed), 32) == 0) {
            // Increment the seed and try again
            seed++;
            generate_unique_identifiers(seed);
        } else {
            // Use the generated GUTI value as the new IMSI value
            strcpy(current->data.imsi, generate_guti(seed));
            break;
        }
    }

    // Loop through all UE contexts in the list to find a suitable IMSI value
    current = ue_contexts->head;
    while (current != NULL) {
        if (strncmp(current->data.imsi, generate_imsi(seed), 16) == 0) {
            // Increment the seed and try again
            seed++;
            generate_unique_identifiers(seed);
        } else {
            // Use the generated IMSI value as the new GUTI value
            strcpy(current->data.guti, generate_imsi(seed));
            break;
        }
    }

    // Release lock on the list of event logs
    pthread_mutex_unlock(&log_lock);
}
