#include <string.h>

// Define the structure for a NICP message
typedef struct NicpMsg {
    int interfaceId;
    int portNum;
    char* deviceTags[10]; // Maximum of 10 device tags per message
} NicpMsg;

// Define the function to initialize the dynamic array of NICP messages
NicpMsg** initNicpMessages(int numMessages) {
    // Allocate memory for the dynamic array of NICP messages
    NicpMsg** nicpMessages = (NicpMsg**)malloc(numMessages * sizeof(NicpMsg*));
    if (!nicpMessages) {
        fprintf(stderr, "Error: Failed to allocate memory for NICP messages\n");
        return NULL;
    }

    // Initialize each NICP message structure with a valid interface identifier and port number
    for (int i = 0; i < numMessages; ++i) {
        nicpMessages[i] = (NicpMsg*)malloc(sizeof(NicpMsg));
        if (!nicpMessages[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for NICP message %d\n", i);
            continue;
        }
        nicpMessages[i]->interfaceId = i;
        nicpMessages[i]->portNum = 0; // Initialize the port number to 0
    }

    return nicpMessages;
}

// Define the function to add a device tag to a NICP message
int addDeviceTag(NicpMsg* msg, char* tag) {
    // Check if the message is null or if there are no more slots available for device tags
    if (!msg || (msg->interfaceId == 0 && msg->portNum == 0)) {
        return -1;
    }

    // Check if the device tag is already in use by another message
    for (int i = 0; i < msg->interfaceId; ++i) {
        if (strcmp(msg->deviceTags[i], tag) == 0) {
            return -2;
        }
    }

    // Add the device tag to the message and increment the port number by 1
    strcpy(msg->deviceTags[msg->interfaceId], tag);
    msg->portNum++;

    return 0;
}

// Define the function to remove a device tag from a NICP message
int removeDeviceTag(NicpMsg* msg, char* tag) {
    // Check if the message is null or if there are no more slots available for device tags
    if (!msg || (msg->interfaceId == 0 && msg->portNum == 0)) {
        return -1;
    }

    // Check if the device tag is already in use by another message
    for (int i = 0; i < msg->interfaceId; ++i) {
        if (strcmp(msg->deviceTags[i], tag) == 0) {
            memmove(&msg->deviceTags[i], &msg->deviceTags[i + 1], sizeof(char*) * (msg->interfaceId - i));
            msg->portNum--;
            return 0;
        }
    }

    // If the device tag is not found, return an error code
    return -2;
}

// Define the function to validate the integrity of a NICP message
int validateNicpMessage(NicpMsg* msg) {
    if (!msg) {
        return -1;
    }
    // Check if the interface identifier and port number are valid
    if (msg->interfaceId < 0 || msg->portNum < 0) {
        return -2;
    }
    // Check if all device tags in the message are valid
    for (int i = 0; i < msg->interfaceId; ++i) {
        if (!msg->deviceTags[i]) {
            return -3;
        }
    }

    return 0;
}

// Define the function to update a NICP message from an external data source
int updateNicpMessage(NicpMsg* msg, char* newData) {
    // Check if the message is null or if there are no more slots available for device tags
    if (!msg || (msg->interfaceId == 0 && msg->portNum == 0)) {
        return -1;
    }

    // Update the NICP message with the new data
    strcpy(msg, newData);

    return 0;
}

// Define the function to free a NICP message and its device tags
void freeNicpMessage(NicpMsg* msg) {
    if (!msg) {
        return;
    }
    for (int i = 0; i < msg->interfaceId; ++i) {
        free(msg->deviceTags[i]);
    }
    free(msg);
}
