// Define the data structure to hold the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
  NFAPI_CRC_INDICATION_PDU_T* data;
  size_t capacity; // Maximum number of elements in the list
  size_t count; // Current number of elements in the list
} CRC_INDICATION_LIST;

// Define the function to create a new list with the given maximum size
CRC_INDICATION_LIST* crc_indication_list_create(size_t max_size) {
  // Allocate memory for the list and its data
  CRC_INDICATION_LIST* list = malloc(sizeof(CRC_INDICATION_LIST));
  list->data = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  list->capacity = max_size;
  list->count = 0;

  // Initialize the mutex for thread safety
  pthread_mutex_init(&list->mutex, NULL);

  return list;
}

// Define the function to add an element to the list
bool crc_indication_list_add(CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
  // Check if the list is full
  if (list->count == list->capacity) {
    return false;
  }

  // Verify the integrity of the input data
  if (!verify_crc_indication(pdu)) {
    return false;
  }

  // Lock the mutex for thread safety
  pthread_mutex_lock(&list->mutex);

  // Add the element to the list
  list->data[list->count++] = *pdu;

  // Unlock the mutex
  pthread_mutex_unlock(&list->mutex);

  return true;
}

// Define the function to remove an element from the list
bool crc_indication_list_remove(CRC_INDICATION_LIST* list, size_t index) {
  // Check if the index is valid
  if (index >= list->count) {
    return false;
  }

  // Lock the mutex for thread safety
  pthread_mutex_lock(&list->mutex);

  // Shift the elements after the removed element to fill the gap
  memmove(&list->data[index], &list->data[index + 1], (list->count - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  list->count--;

  // Unlock the mutex
  pthread_mutex_unlock(&list->mutex);

  return true;
}

// Define the function to retrieve an element from the list by index
NFAPI_CRC_INDICATION_PDU_T* crc_indication_list_get(CRC_INDICATION_LIST* list, size_t index) {
  // Check if the index is valid
  if (index >= list->count) {
    return NULL;
  }

  return &list->data[index];
}

// Define the function to release the list and its memory
void crc_indication_list_release(CRC_INDICATION_LIST* list) {
  // Release the mutex for thread safety
  pthread_mutex_destroy(&list->mutex);

  // Free the memory allocated for the list and its data
  free(list->data);
  free(list);
}
