    NFAPI_CRC_INDICATION_PDU_T pdu;
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
};

struct crc_indications {
    struct crc_indication *indications;
    size_t count;
};

struct crc_indications populate_crc_indications(size_t n) {
    // Initialize the indications structure with a null pointer and zero count
    struct crc_indications indications = {NULL, 0};

    // Validate the input value of N is within a predefined range
    if (n <= 0 || n > 10000) {
        printf("Invalid value for N: %zu\n", n);
        return indications;
    }

    // Allocate memory for the array of CRC indications
    struct crc_indication *ind = malloc(sizeof(*ind) * n);
    if (!ind) {
        printf("Failed to allocate memory for CRC indications\n");
        return indications;
    }

    // Populate the array of CRC indications with random values
    size_t i;
    for (i = 0; i < n; ++i) {
        ind[i].rx_ue_information_tag = rand() % 1000;
        ind[i].rnti = rand() % 65536;
        while (crc_indications_contains(indications, ind[i].rnti)) {
            ind[i].rnti = rand() % 65536;
        }
        ind[i].crc_indication_rel8_tag = rand() % 256;
    }

    // Store the indications in the structure and return it
    indications.indications = ind;
    indications.count = n;
    return indications;
}

bool crc_indications_contains(struct crc_indications *indications, uint16_t rnti) {
    // Search for the RNTI in the array of CRC indications
    size_t i;
    for (i = 0; i < indications->count; ++i) {
        if (indications->indications[i].rnti == rnti) {
            return true;
        }
    }
    return false;
}

void crc_indications_free(struct crc_indications *indications) {
    // Free the memory allocated for the array of CRC indications
    free(indications->indications);
    indications->count = 0;
    indications->indications = NULL;
}
